class CedarDatabaseTestAccess {
 public:
  static WorkExecutionService* work_execution_service(
      CedarDatabase* database) {
    return database == nullptr ? nullptr
                               : database->work_execution_service_.get();
  }
  static std::shared_ptr<DatabaseLifecycle> lifecycle(
      CedarDatabase* database) {
    return database == nullptr ? nullptr : database->lifecycle_;
  }
  static std::shared_ptr<RuntimeFeedbackStore> runtime_feedback(
      CedarDatabase* database) {
    return database == nullptr ? nullptr : database->runtime_feedback_;
  }
  static void SetShutdownExecutionHook(
      CedarDatabase* database, std::function<void()> hook) {
    database->shutdown_execution_hook_ = std::move(hook);
  }
  static void SetVersionSetFaultInjector(
      CedarDatabase* database,
      std::function<Status(VersionSetFaultPoint)> injector) {
    database->coordinator_.SetVersionSetFaultInjectorForTesting(
        std::move(injector));
  }
  static void SetDecisionInstallHook(
      CedarDatabase* database,
      std::function<void(uint64_t, bool)> hook) {
    database->coordinator_.SetDecisionInstallHookForTesting(std::move(hook));
  }
  static void SetRecoveryExecutionHook(
      CedarDatabase* database, std::function<void()> hook) {
    database->coordinator_.SetRecoveryExecutionHookForTesting(std::move(hook));
  }
  static void SetMaintenanceCancellationObserver(
      CedarDatabase* database,
      WorkCancellation::CheckpointObserverForTesting observer) {
    database->coordinator_.SetMaintenanceCancellationObserverForTesting(
        std::move(observer));
  }
  static void UseSingleWorkerExecutionService(CedarDatabase* database) {
    database->work_execution_service_ =
        std::make_shared<WorkExecutionService>(database->work_scheduler_, 1);
  }
};

