struct BlockingCancellationState {
  std::mutex mutex;
  std::condition_variable changed;
  bool entered = false;
};

class BlockingUntilCancelledResultStream final : public QueryResultStream {
 public:
  BlockingUntilCancelledResultStream(
      std::shared_ptr<QueryCancellation> cancellation,
      std::shared_ptr<BlockingCancellationState> state)
      : cancellation_(std::move(cancellation)), state_(std::move(state)) {}

  Status Next(ResultBatch*) override {
    {
      std::lock_guard<std::mutex> lock(state_->mutex);
      state_->entered = true;
    }
    state_->changed.notify_all();
    std::unique_lock<std::mutex> lock(state_->mutex);
    state_->changed.wait(lock, [this] {
      return cancellation_->IsCancelled();
    });
    return Status::QueryCancelled("test stream", "cancelled at yield boundary");
  }

  Status terminal_status() const override { return Status::OK(); }

 private:
  std::shared_ptr<QueryCancellation> cancellation_;
  std::shared_ptr<BlockingCancellationState> state_;
};

TEST(StatusTest, ShutdownInProgressIsTypedAndStable) {
  const Status status = Status::ShutdownInProgress(
      "database lifecycle", "database is closing");
  EXPECT_TRUE(status.IsShutdownInProgress());
  EXPECT_EQ(status.ToString(),
            "ShutdownInProgress: database lifecycle: database is closing");
}

TEST(StatusTest, MaintenanceBackoffIsTypedAndStable) {
  const Status status = Status::MaintenanceBackoff(
      "maintenance admission", "optional work yielded under pressure");
  EXPECT_TRUE(status.IsMaintenanceBackoff());
  EXPECT_EQ(status.ToString(),
            "MaintenanceBackoff: maintenance admission: optional work yielded under pressure");
}

TEST(DatabaseLifecycleTest, QuiescingRejectsNewOperationsWithTypedStatus) {
  auto lifecycle = std::make_shared<DatabaseLifecycle>();
  auto admitted = lifecycle->TryEnter(DatabaseOperationClass::kCommit);
  ASSERT_TRUE(admitted.ok()) << admitted.status().ToString();
  EXPECT_EQ(lifecycle->active_operations(DatabaseOperationClass::kCommit), 1U);

  EXPECT_TRUE(lifecycle->BeginClose());
  EXPECT_EQ(lifecycle->phase(), DatabasePhase::kQuiescing);
  const auto rejected = lifecycle->TryEnter(DatabaseOperationClass::kPointRead);
  ASSERT_FALSE(rejected.ok());
  EXPECT_TRUE(rejected.status().IsShutdownInProgress())
      << rejected.status().ToString();

  admitted = DatabaseOperationLease();
  lifecycle->WaitForNoOperations(DatabaseOperationClass::kCommit);
  EXPECT_EQ(lifecycle->active_operations(DatabaseOperationClass::kCommit), 0U);
}

TEST(DatabaseLifecycleTest, OnlyOneConcurrentCloserOwnsTheProtocol) {
  auto lifecycle = std::make_shared<DatabaseLifecycle>();
  EXPECT_TRUE(lifecycle->BeginClose());
  EXPECT_FALSE(lifecycle->BeginClose());
  lifecycle->FinishClose(Status::IOError("checkpoint", "injected"));
  const Status result = lifecycle->WaitForClose();
  EXPECT_TRUE(result.IsIOError()) << result.ToString();
  EXPECT_EQ(lifecycle->phase(), DatabasePhase::kClosed);
}

TEST(DatabaseLifecycleTest, CancelledTrackedQueryNeverEntersItsInnerStream) {
  auto lifecycle = std::make_shared<DatabaseLifecycle>();
  auto cancellation = std::make_shared<QueryCancellation>();
  auto registered = lifecycle->RegisterQuery(cancellation);
  ASSERT_TRUE(registered.ok()) << registered.status().ToString();
  auto inner = std::make_unique<InMemoryResultStream>(
      std::vector<ResultBatch>{}, Status::OK());
  LifecycleTrackedResultStream stream(
      std::move(inner), registered.ConsumeValueOrDie());

  ASSERT_TRUE(lifecycle->BeginClose());
  lifecycle->CancelQueriesAndWaitForCalls();
  EXPECT_TRUE(cancellation->IsCancelled());
  ResultBatch batch;
  const Status next = stream.Next(&batch);
  EXPECT_TRUE(next.IsQueryCancelled()) << next.ToString();
}

TEST(DatabaseLifecycleTest, DrainWaitsUntilTrackedQueryReachesTerminalState) {
  auto lifecycle = std::make_shared<DatabaseLifecycle>();
  auto registered = lifecycle->RegisterQuery(
      std::make_shared<QueryCancellation>());
  ASSERT_TRUE(registered.ok()) << registered.status().ToString();
  auto inner = std::make_unique<InMemoryResultStream>(
      std::vector<ResultBatch>{}, Status::OK());
  LifecycleTrackedResultStream stream(
      std::move(inner), registered.ConsumeValueOrDie());
  ASSERT_TRUE(lifecycle->BeginClose());

  std::atomic<bool> drained{false};
  std::thread waiter([&] {
    lifecycle->WaitForQueriesDrained();
    drained.store(true, std::memory_order_release);
  });
  while (lifecycle->active_query_count() == 0) std::this_thread::yield();
  EXPECT_FALSE(drained.load(std::memory_order_acquire));
  ResultBatch batch;
  EXPECT_TRUE(stream.Next(&batch).IsNotFound());
  EXPECT_TRUE(stream.terminal_status().ok())
      << stream.terminal_status().ToString();
  waiter.join();
  EXPECT_TRUE(drained.load(std::memory_order_acquire));
}

TEST(DatabaseLifecycleTest, CancelWaitsForExecutingQueryCallToLeaveRuntime) {
  auto lifecycle = std::make_shared<DatabaseLifecycle>();
  auto cancellation = std::make_shared<QueryCancellation>();
  auto registered = lifecycle->RegisterQuery(cancellation);
  ASSERT_TRUE(registered.ok()) << registered.status().ToString();
  auto state = std::make_shared<BlockingCancellationState>();
  LifecycleTrackedResultStream stream(
      std::make_unique<BlockingUntilCancelledResultStream>(cancellation, state),
      registered.ConsumeValueOrDie());

  Status next = Status::InvalidArgument("test", "Next did not return");
  std::thread query([&] {
    ResultBatch batch;
    next = stream.Next(&batch);
  });
  {
    std::unique_lock<std::mutex> lock(state->mutex);
    state->changed.wait(lock, [&] { return state->entered; });
  }
  ASSERT_TRUE(lifecycle->BeginClose());
  std::thread closer([&] { lifecycle->CancelQueriesAndWaitForCalls(); });
  while (!cancellation->IsCancelled()) std::this_thread::yield();
  state->changed.notify_all();
  query.join();
  closer.join();
  EXPECT_TRUE(next.IsQueryCancelled()) << next.ToString();
}

class ReserveAtEndResultStream final : public QueryResultStream {
 public:
  ReserveAtEndResultStream(
      ResultBatch batch, std::shared_ptr<QueryMemoryAccount> memory,
      uint64_t terminal_hold_bytes)
      : batch_(std::move(batch)), memory_(std::move(memory)),
        terminal_hold_bytes_(terminal_hold_bytes) {}
  ~ReserveAtEndResultStream() override {
    if (memory_ && held_) memory_->Release(terminal_hold_bytes_);
  }

  Status Next(ResultBatch* batch) override {
    if (!emitted_) {
      if (batch == nullptr) {
        return Status::InvalidArgument("test stream", "missing output");
      }
      *batch = std::move(batch_);
      emitted_ = true;
      return Status::OK();
    }
    if (!held_ && terminal_status_.ok()) {
      terminal_status_ = memory_->Reserve(terminal_hold_bytes_);
      held_ = terminal_status_.ok();
    }
    return Status::NotFound("test stream", "end of stream");
  }

  Status terminal_status() const override { return terminal_status_; }

 private:
  ResultBatch batch_;
  std::shared_ptr<QueryMemoryAccount> memory_;
  uint64_t terminal_hold_bytes_ = 0;
  Status terminal_status_ = Status::OK();
  bool emitted_ = false;
  bool held_ = false;
};

