TEST_F(DurableLogTest, DatabaseExecutesTcypherSessionControlStatements) {
  CedarDatabase db(path_, 2, 11);
  ASSERT_TRUE(db.Open().ok());
  auto session = db.CreateTcypherSession().ConsumeValueOrDie();
  ASSERT_TRUE(session);
  const auto begin = db.ExecuteTcypher(*session, "BEGIN SNAPSHOT;");
  ASSERT_TRUE(begin.ok()) << begin.status().ToString();
  ResultBatch ignored;
  EXPECT_TRUE(begin.ValueOrDie()->Next(&ignored).IsNotFound());
  EXPECT_FALSE(db.ExecuteTcypher(*session, "BEGIN STRICT;").ok());
  const auto rollback = db.ExecuteTcypher(*session, "ROLLBACK;");
  ASSERT_TRUE(rollback.ok()) << rollback.status().ToString();
  EXPECT_TRUE(db.ExecuteTcypher(*session, "BEGIN STRICT;").ok());
  EXPECT_TRUE(db.ExecuteTcypher("BEGIN SNAPSHOT;").status().IsNotSupportedError());
}

