TEST_F(DurableLogTest,
       CloseWaitsForAlreadyEnteredTcypherSessionCommitBeforeCheckpoint) {
  CedarDatabase db(path_, 1, 11);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence",
                         PhysicalType::kBinary, 4096,
                         EncodingPolicy::kAdaptive,
                         CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(db.RegisterColumn(existence, &registered).ok());
  auto session = db.CreateTcypherSession().ConsumeValueOrDie();
  ASSERT_NE(session, nullptr);
  ASSERT_TRUE(session->Begin(TcypherSessionMode::kSnapshot).ok());
  ASSERT_TRUE(session->Stage({PendingEvent::Put(
      LogicalKey::VertexExistence(56), 10, registered.schema_epoch,
      Value::Binary(""))}).ok());

  std::mutex hook_mutex;
  std::condition_variable hook_cv;
  bool entered = false;
  bool release = false;
  CedarDatabaseTestAccess::SetDecisionInstallHook(
      &db, [&](uint64_t, bool) {
        std::unique_lock<std::mutex> lock(hook_mutex);
        entered = true;
        hook_cv.notify_all();
        hook_cv.wait(lock, [&] { return release; });
      });

  uint64_t commit_seq = 0;
  Status commit = Status::InvalidArgument("test", "commit did not run");
  std::thread committer([&] { commit = session->Commit(&commit_seq); });
  {
    std::unique_lock<std::mutex> lock(hook_mutex);
    ASSERT_TRUE(hook_cv.wait_for(lock, std::chrono::seconds(2),
                                 [&] { return entered; }));
  }
  Status closed = Status::InvalidArgument("test", "close did not run");
  std::atomic<bool> close_done{false};
  std::thread closer([&] {
    closed = db.Close();
    close_done.store(true, std::memory_order_release);
  });
  EXPECT_FALSE(close_done.load(std::memory_order_acquire));
  {
    std::lock_guard<std::mutex> lock(hook_mutex);
    release = true;
  }
  hook_cv.notify_all();
  committer.join();
  closer.join();
  ASSERT_TRUE(commit.ok()) << commit.ToString();
  ASSERT_GT(commit_seq, 0U);
  ASSERT_TRUE(closed.ok()) << closed.ToString();

  CedarDatabase reopened(path_, 1, 11);
  ASSERT_TRUE(reopened.Open().ok());
  const auto value = reopened.Get(LogicalKey::VertexExistence(56), 10);
  ASSERT_TRUE(value.ok()) << value.status().ToString();
  EXPECT_TRUE(value.ValueOrDie().has_value());
}

