TEST_F(DurableLogTest, StrictCommitRejectsReadPointWhoseObservedIdentityIsForged) {
  TransactionCoordinator coordinator(path_, 2, 19);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "name", PhysicalType::kString,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  uint64_t snapshot_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexProperty(9, 7), 10,
                        registered.schema_epoch, Value::String("observed")),
  }, &snapshot_seq).ok());
  auto captured = coordinator.CaptureStrictReadPoint(
      LogicalKey::VertexProperty(9, 7), 20, snapshot_seq);
  ASSERT_TRUE(captured.ok()) << captured.status().ToString();
  captured.ValueOrDie().observed_event = TemporalEvent::Put(
      LogicalKey::VertexProperty(9, 7), 10, snapshot_seq,
      registered.schema_epoch, Value::String("forged"));
  const TransactionMeasurementSnapshot before_measurements =
      coordinator.transaction_measurements();

  const CommitResult result = coordinator.CommitStrictWithResult(
      snapshot_seq,
      {PendingEvent::Put(LogicalKey::VertexProperty(10, 7), 10,
                         registered.schema_epoch, Value::String("write"))},
      {captured.ValueOrDie()});

  EXPECT_EQ(result.outcome, CommitOutcome::kAborted);
  EXPECT_TRUE(result.reason.IsConflict()) << result.reason.ToString();
  EXPECT_EQ(coordinator.visible_seq(), snapshot_seq);
  const auto window = BuildTransactionMeasurementWindow(
      before_measurements, coordinator.transaction_measurements());
  ASSERT_TRUE(window.ok()) << window.status().ToString();
  EXPECT_EQ(window.ValueOrDie().aborted, 1U);
  EXPECT_EQ(window.ValueOrDie().conflicts, 1U);
  EXPECT_EQ(window.ValueOrDie().decision_latency.sample_count, 0U);
}

TEST_F(DurableLogTest, StrictTransactionsRejectDeterministicWriteSkew) {
  TransactionCoordinator coordinator(path_, 2, 29);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "state", PhysicalType::kInt64,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  uint64_t snapshot_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 10,
                        registered.schema_epoch, Value::Int64(0)),
      PendingEvent::Put(LogicalKey::VertexProperty(2, 7), 10,
                        registered.schema_epoch, Value::Int64(0)),
  }, &snapshot_seq).ok());

  const auto first_read = coordinator.CaptureStrictReadPoint(
      LogicalKey::VertexProperty(2, 7), 10, snapshot_seq);
  const auto second_read = coordinator.CaptureStrictReadPoint(
      LogicalKey::VertexProperty(1, 7), 10, snapshot_seq);
  ASSERT_TRUE(first_read.ok()) << first_read.status().ToString();
  ASSERT_TRUE(second_read.ok()) << second_read.status().ToString();

  const CommitResult first = coordinator.CommitStrictWithResult(
      snapshot_seq,
      {PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 10,
                         registered.schema_epoch, Value::Int64(1))},
      {first_read.ValueOrDie()});
  const CommitResult second = coordinator.CommitStrictWithResult(
      snapshot_seq,
      {PendingEvent::Put(LogicalKey::VertexProperty(2, 7), 10,
                         registered.schema_epoch, Value::Int64(1))},
      {second_read.ValueOrDie()});

  EXPECT_NE(first.outcome, second.outcome);
  const CommitResult& rejected = first.outcome == CommitOutcome::kAborted ? first : second;
  EXPECT_TRUE(rejected.reason.IsConflict()) << rejected.reason.ToString();
}

TEST_F(DurableLogTest,
       RandomStrictDependencyCyclesNeverCommitEveryParticipant) {
  constexpr uint64_t kSeed = 0xceda7d3e5ULL;
  std::mt19937_64 random(kSeed);
  TransactionCoordinator coordinator(path_, 4, 79);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "state", PhysicalType::kInt64,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  std::vector<LogicalKey> keys;
  for (uint64_t vertex_id = 1; vertex_id <= 6; ++vertex_id) {
    keys.push_back(LogicalKey::VertexProperty(vertex_id, 7));
  }
  uint64_t initial_snapshot = 0;
  std::vector<PendingEvent> initial_events;
  for (const LogicalKey& key : keys) {
    initial_events.push_back(PendingEvent::Put(
        key, 0, registered.schema_epoch, Value::Int64(0)));
  }
  ASSERT_TRUE(coordinator.Commit(0, initial_events, &initial_snapshot).ok());

  constexpr uint32_t kCases = 24;
  for (uint32_t case_index = 0; case_index < kCases; ++case_index) {
    const size_t cycle_size = 2 + random() % 5;
    std::shuffle(keys.begin(), keys.end(), random);
    const uint64_t snapshot = coordinator.visible_seq();
    const uint64_t valid_time = 100 + case_index * 10;
    std::vector<TransactionCoordinator::StrictReadPoint> reads;
    reads.reserve(cycle_size);
    for (size_t index = 0; index < cycle_size; ++index) {
      const auto read = coordinator.CaptureStrictReadPoint(
          keys[index], valid_time, snapshot);
      ASSERT_TRUE(read.ok()) << "seed=" << kSeed << " case=" << case_index
                             << " read=" << index << " "
                             << read.status().ToString();
      reads.push_back(read.ValueOrDie());
    }

    std::mutex start_mutex;
    std::condition_variable start_cv;
    size_t ready = 0;
    bool start = false;
    std::vector<CommitResult> results(cycle_size);
    std::vector<std::thread> workers;
    workers.reserve(cycle_size);
    for (size_t index = 0; index < cycle_size; ++index) {
      workers.emplace_back([&, index]() {
        {
          std::unique_lock<std::mutex> lock(start_mutex);
          ++ready;
          start_cv.notify_all();
          start_cv.wait(lock, [&]() { return start; });
        }
        results[index] = coordinator.CommitStrictWithResult(
            snapshot,
            {PendingEvent::Put(keys[(index + 1) % cycle_size], valid_time,
                               registered.schema_epoch,
                               Value::Int64(case_index + 1))},
            {reads[index]});
      });
    }
    {
      std::unique_lock<std::mutex> lock(start_mutex);
      ASSERT_TRUE(start_cv.wait_for(lock, std::chrono::seconds(2),
                                    [&]() { return ready == cycle_size; }));
      start = true;
    }
    start_cv.notify_all();
    for (std::thread& worker : workers) worker.join();

    SCOPED_TRACE("seed=" + std::to_string(kSeed) +
                 " case=" + std::to_string(case_index) +
                 " cycle_size=" + std::to_string(cycle_size));
    size_t committed = 0;
    for (const CommitResult& result : results) {
      if (result.outcome == CommitOutcome::kCommitted) {
        ++committed;
      } else {
        EXPECT_EQ(result.outcome, CommitOutcome::kAborted);
        EXPECT_TRUE(result.reason.IsConflict()) << result.reason.ToString();
      }
    }
    EXPECT_GT(committed, 0U);
    EXPECT_LT(committed, cycle_size);
  }
}

TEST_F(DurableLogTest, PreparedStrictReadReservationRejectsSnapshotWriter) {
  TransactionCoordinator coordinator(path_, 2, 31);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "state", PhysicalType::kInt64,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  uint64_t snapshot_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 10,
                        registered.schema_epoch, Value::Int64(0)),
      PendingEvent::Put(LogicalKey::VertexProperty(2, 7), 10,
                        registered.schema_epoch, Value::Int64(0)),
  }, &snapshot_seq).ok());
  const auto read = coordinator.CaptureStrictReadPoint(
      LogicalKey::VertexProperty(2, 7), 10, snapshot_seq);
  ASSERT_TRUE(read.ok()) << read.status().ToString();

  std::mutex gate_mutex;
  std::condition_variable gate_cv;
  bool reservation_installed = false;
  bool release_first = false;
  coordinator.SetReservationInstalledHookForTesting([&]() {
    std::unique_lock<std::mutex> lock(gate_mutex);
    reservation_installed = true;
    gate_cv.notify_all();
    gate_cv.wait(lock, [&]() { return release_first; });
  });

  CommitResult first;
  std::thread first_thread([&]() {
    first = coordinator.CommitStrictWithResult(
        snapshot_seq,
        {PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 10,
                           registered.schema_epoch, Value::Int64(1))},
        {read.ValueOrDie()});
  });
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    ASSERT_TRUE(gate_cv.wait_for(lock, std::chrono::seconds(2),
                                 [&]() { return reservation_installed; }));
  }

  const CommitResult second = coordinator.CommitWithResult(
      snapshot_seq,
      {PendingEvent::Put(LogicalKey::VertexProperty(2, 7), 10,
                         registered.schema_epoch, Value::Int64(1))});
  EXPECT_EQ(second.outcome, CommitOutcome::kAborted);
  EXPECT_TRUE(second.reason.IsConflict()) << second.reason.ToString();

  {
    std::lock_guard<std::mutex> lock(gate_mutex);
    release_first = true;
  }
  gate_cv.notify_all();
  first_thread.join();
  EXPECT_EQ(first.outcome, CommitOutcome::kCommitted) << first.reason.ToString();
}

TEST_F(DurableLogTest, AbortedPreparedStrictTransactionReleasesReservation) {
  TransactionCoordinator coordinator(path_, 2, 37);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "state", PhysicalType::kInt64,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  uint64_t snapshot_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 10,
                        registered.schema_epoch, Value::Int64(0)),
      PendingEvent::Put(LogicalKey::VertexProperty(2, 7), 10,
                        registered.schema_epoch, Value::Int64(0)),
  }, &snapshot_seq).ok());
  const auto read = coordinator.CaptureStrictReadPoint(
      LogicalKey::VertexProperty(2, 7), 10, snapshot_seq);
  ASSERT_TRUE(read.ok()) << read.status().ToString();

  std::atomic<uint32_t> prepare_faults{0};
  coordinator.SetCommitFaultInjectorForTesting(
      [&](CommitFaultPoint point) {
        if (point == CommitFaultPoint::kAfterPrepareDurable &&
            prepare_faults.fetch_add(1) == 0) {
          return Status::IOError("test", "abort prepared transaction");
        }
        return Status::OK();
      });
  const CommitResult aborted = coordinator.CommitStrictWithResult(
      snapshot_seq,
      {PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 10,
                         registered.schema_epoch, Value::Int64(1))},
      {read.ValueOrDie()});
  EXPECT_EQ(aborted.outcome, CommitOutcome::kAborted);

  const CommitResult retry = coordinator.CommitWithResult(
      snapshot_seq,
      {PendingEvent::Put(LogicalKey::VertexProperty(2, 7), 10,
                         registered.schema_epoch, Value::Int64(1))});
  EXPECT_EQ(retry.outcome, CommitOutcome::kCommitted) << retry.reason.ToString();
}

TEST_F(DurableLogTest,
       CoordinatorWriteReservationsRespectHalfOpenIntervalMatrix) {
  struct IntervalCase {
    uint64_t contender_valid_from;
    bool expect_conflict;
  };
  const std::array<IntervalCase, 4> cases = {{{49, true},
                                              {75, true},
                                              {100, false},
                                              {150, false}}};
  for (size_t case_index = 0; case_index < cases.size(); ++case_index) {
    SCOPED_TRACE("case=" + std::to_string(case_index) +
                 " contender_valid_from=" +
                 std::to_string(cases[case_index].contender_valid_from));
    const std::string case_path = path_ + "/interval_" +
                                  std::to_string(case_index);
    TransactionCoordinator coordinator(case_path, 2, 83);
    ASSERT_TRUE(coordinator.Open().ok());
    ColumnSchema property{EntityType::Vertex, 7, 0, "state",
                          PhysicalType::kInt64, 4096,
                          EncodingPolicy::kAdaptive,
                          CompressionPolicy::kLz4};
    ColumnSchema registered;
    ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
    const LogicalKey key = LogicalKey::VertexProperty(1, 7);
    uint64_t snapshot = 0;
    ASSERT_TRUE(coordinator.Commit(
        0,
        {PendingEvent::Put(key, 0, registered.schema_epoch, Value::Int64(0)),
         PendingEvent::Put(key, 100, registered.schema_epoch, Value::Int64(1)),
         PendingEvent::Put(key, 200, registered.schema_epoch, Value::Int64(2))},
        &snapshot).ok());

    std::mutex gate_mutex;
    std::condition_variable gate_cv;
    bool installed = false;
    bool release_first = false;
    coordinator.SetReservationInstalledHookForTesting([&]() {
      std::unique_lock<std::mutex> lock(gate_mutex);
      installed = true;
      gate_cv.notify_all();
      gate_cv.wait(lock, [&]() { return release_first; });
    });
    CommitResult first_result;
    std::thread first([&]() {
      first_result = coordinator.CommitWithResult(
          snapshot,
          {PendingEvent::Put(key, 50, registered.schema_epoch,
                             Value::Int64(3))});
    });
    {
      std::unique_lock<std::mutex> lock(gate_mutex);
      ASSERT_TRUE(gate_cv.wait_for(lock, std::chrono::seconds(2),
                                   [&]() { return installed; }));
    }
    coordinator.SetReservationInstalledHookForTesting({});

    const CommitResult contender = coordinator.CommitWithResult(
        snapshot,
        {PendingEvent::Put(key, cases[case_index].contender_valid_from,
                           registered.schema_epoch, Value::Int64(4))});
    if (cases[case_index].expect_conflict) {
      EXPECT_EQ(contender.outcome, CommitOutcome::kAborted);
      EXPECT_TRUE(contender.reason.IsConflict())
          << contender.reason.ToString();
    } else {
      EXPECT_EQ(contender.outcome, CommitOutcome::kCommitted)
          << contender.reason.ToString();
    }

    {
      std::lock_guard<std::mutex> lock(gate_mutex);
      release_first = true;
    }
    gate_cv.notify_all();
    first.join();
    EXPECT_EQ(first_result.outcome, CommitOutcome::kCommitted)
        << first_result.reason.ToString();
  }
}

TEST_F(DurableLogTest, IndependentShardPreparesReachFsyncConcurrently) {
  constexpr uint64_t kHashSeed = 47;
  TransactionCoordinator coordinator(path_, 2, kHashSeed);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "state", PhysicalType::kInt64,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());

  const ShardDirectory directory(2, kHashSeed);
  std::array<std::optional<LogicalKey>, 2> keys;
  for (uint64_t vertex_id = 1; vertex_id < 1000; ++vertex_id) {
    const LogicalKey candidate = LogicalKey::VertexProperty(vertex_id, 7);
    const uint32_t shard = directory.ShardFor(candidate);
    if (!keys[shard].has_value()) keys[shard] = candidate;
    if (keys[0].has_value() && keys[1].has_value()) break;
  }
  ASSERT_TRUE(keys[0].has_value());
  ASSERT_TRUE(keys[1].has_value());

  std::mutex gate_mutex;
  std::condition_variable gate_cv;
  uint32_t fsynced_prepares = 0;
  bool overlap_observed = true;
  const std::thread::id caller_thread = std::this_thread::get_id();
  std::set<std::thread::id> prepare_threads;
  coordinator.SetPrepareLogFaultInjectorForTesting(
      [&](DecisionLogFaultPoint point) {
        if (point != DecisionLogFaultPoint::kAfterRecordFsync) {
          return Status::OK();
        }
        std::unique_lock<std::mutex> lock(gate_mutex);
        prepare_threads.insert(std::this_thread::get_id());
        ++fsynced_prepares;
        gate_cv.notify_all();
        if (!gate_cv.wait_for(lock, std::chrono::seconds(2),
                              [&]() { return fsynced_prepares == 2; })) {
          overlap_observed = false;
        }
        return Status::OK();
      });

  std::array<CommitResult, 2> results;
  std::thread first([&]() {
    results[0] = coordinator.CommitWithResult(
        0, {PendingEvent::Put(*keys[0], 10, registered.schema_epoch,
                              Value::Int64(1))});
  });
  std::thread second([&]() {
    results[1] = coordinator.CommitWithResult(
        0, {PendingEvent::Put(*keys[1], 10, registered.schema_epoch,
                              Value::Int64(2))});
  });
  first.join();
  second.join();

  EXPECT_TRUE(overlap_observed);
  EXPECT_EQ(prepare_threads.size(), 2U);
  EXPECT_EQ(prepare_threads.count(caller_thread), 0U);
  EXPECT_EQ(results[0].outcome, CommitOutcome::kCommitted)
      << results[0].reason.ToString();
  EXPECT_EQ(results[1].outcome, CommitOutcome::kCommitted)
      << results[1].reason.ToString();
}

TEST_F(DurableLogTest, IndependentShardValidationsRunConcurrently) {
  constexpr uint64_t kHashSeed = 61;
  TransactionCoordinator coordinator(path_, 2, kHashSeed);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "state", PhysicalType::kInt64,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  const ShardDirectory directory(2, kHashSeed);
  std::array<std::optional<LogicalKey>, 2> keys;
  for (uint64_t vertex_id = 1; vertex_id < 1000; ++vertex_id) {
    const LogicalKey candidate = LogicalKey::VertexProperty(vertex_id, 7);
    keys[directory.ShardFor(candidate)] = candidate;
    if (keys[0].has_value() && keys[1].has_value()) break;
  }
  ASSERT_TRUE(keys[0].has_value());
  ASSERT_TRUE(keys[1].has_value());

  std::mutex gate_mutex;
  std::condition_variable gate_cv;
  size_t arrivals = 0;
  bool first_observed_overlap = false;
  coordinator.SetValidationStartedHookForTesting([&](uint32_t) {
    std::unique_lock<std::mutex> lock(gate_mutex);
    const bool first = arrivals++ == 0;
    gate_cv.notify_all();
    if (first) {
      first_observed_overlap = gate_cv.wait_for(
          lock, std::chrono::seconds(2), [&]() { return arrivals == 2; });
    }
  });

  std::array<CommitResult, 2> results;
  std::array<std::thread, 2> workers;
  for (uint32_t shard = 0; shard < 2; ++shard) {
    workers[shard] = std::thread([&, shard]() {
      results[shard] = coordinator.CommitWithResult(
          0, {PendingEvent::Put(*keys[shard], 10, registered.schema_epoch,
                                Value::Int64(shard + 1))});
    });
  }
  for (std::thread& worker : workers) worker.join();
  coordinator.SetValidationStartedHookForTesting({});

  EXPECT_TRUE(first_observed_overlap);
  for (const CommitResult& result : results) {
    EXPECT_EQ(result.outcome, CommitOutcome::kCommitted)
        << result.reason.ToString();
  }
}

