TEST_F(DurableLogTest, OpenRunsRecoveryThroughTypedScheduler) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  ASSERT_TRUE(service.Start().ok());
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.SetWorkExecutionService(&service).ok());
  const std::thread::id caller_thread = std::this_thread::get_id();
  std::thread::id recovery_thread;
  coordinator.SetRecoveryExecutionHookForTesting(
      [&] { recovery_thread = std::this_thread::get_id(); });

  ASSERT_TRUE(coordinator.Open().ok());

  EXPECT_NE(recovery_thread, std::thread::id{});
  EXPECT_NE(recovery_thread, caller_thread);
  const WorkExecutionStats stats = service.stats();
  EXPECT_EQ(stats.submitted[1], 1U);
  EXPECT_EQ(stats.admitted[1], 1U);
  EXPECT_EQ(stats.completed[1], 1U);
  EXPECT_TRUE(service.Stop().ok());
}

