TEST_F(DurableLogTest,
       WorkExecutionServiceBindingPropagatesGovernorConfigurationFailure) {
  auto scheduler = std::make_shared<WorkScheduler>();
  WorkExecutionService service(scheduler, 1);
  ASSERT_TRUE(service.Start().ok());
  std::mutex blocker_mutex;
  std::condition_variable blocker_cv;
  bool blocker_entered = false;
  bool release_blocker = false;
  const auto blocker = service.Submit(
      WorkClass::kAnalyticalQuery, [&] {
        std::unique_lock<std::mutex> lock(blocker_mutex);
        blocker_entered = true;
        blocker_cv.notify_all();
        blocker_cv.wait(lock, [&] { return release_blocker; });
        return Status::OK();
      });
  ASSERT_TRUE(blocker.ok()) << blocker.status().ToString();
  {
    std::unique_lock<std::mutex> lock(blocker_mutex);
    ASSERT_TRUE(blocker_cv.wait_for(
        lock, std::chrono::seconds(2), [&] { return blocker_entered; }));
  }

  ResourceGovernor resources(ResourceProfile{0, 0, 0, 0, 1});
  TransactionCoordinator coordinator(path_, 1, 11);
  coordinator.SetResourceGovernor(&resources);
  const Status rejected = coordinator.SetWorkExecutionService(&service);
  EXPECT_TRUE(rejected.IsInvalidArgument()) << rejected.ToString();

  {
    std::lock_guard<std::mutex> lock(blocker_mutex);
    release_blocker = true;
  }
  blocker_cv.notify_all();
  EXPECT_TRUE(blocker.ValueOrDie().Wait().ok());
  EXPECT_TRUE(coordinator.SetWorkExecutionService(&service).ok());
  EXPECT_TRUE(service.Stop().ok());
}

