TEST(SchemaRegistryTest, ConcurrentManifestCasPublishesOneSchemaIdentity) {
  const std::string path = "/tmp/cedar_schema_registry_manifest_cas";
  std::filesystem::remove_all(path);
  VersionSet versions(path + "/manifest/MANIFEST");
  ASSERT_TRUE(versions.Open().ok());
  const uint64_t generation = versions.Snapshot()->generation;
  ColumnSchema first{EntityType::Vertex, 7, 1, "name",
                     PhysicalType::kString, 4096,
                     EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema second = first;
  second.blob_threshold = 8192;
  std::array<Status, 2> statuses{
      Status::InvalidArgument("test", "not run"),
      Status::InvalidArgument("test", "not run")};
  std::thread left([&] {
    VersionEdit edit;
    edit.schema_adds.push_back(first);
    edit.expected_generation = generation;
    statuses[0] = versions.ApplyEdit(edit);
  });
  std::thread right([&] {
    VersionEdit edit;
    edit.schema_adds.push_back(second);
    edit.expected_generation = generation;
    statuses[1] = versions.ApplyEdit(edit);
  });
  left.join();
  right.join();
  EXPECT_EQ(static_cast<int>(statuses[0].ok()) +
                static_cast<int>(statuses[1].ok()),
            1);
  EXPECT_EQ(static_cast<int>(statuses[0].IsConflict()) +
                static_cast<int>(statuses[1].IsConflict()),
            1);
  ASSERT_EQ(versions.Snapshot()->schemas.size(), 1U);
  EXPECT_EQ(versions.Snapshot()->schemas[0].schema_epoch, 1U);
  std::filesystem::remove_all(path);
}

TEST_F(DurableLogTest,
       ConcurrentCoordinatorSchemaRegistrationIsIdempotentAndContiguous) {
  TransactionCoordinator coordinator(path_, 1, 19);
  ASSERT_TRUE(coordinator.Open().ok());
  const auto run_pair = [&](const ColumnSchema& first,
                            const ColumnSchema& second,
                            std::array<Status, 2>* statuses,
                            std::array<ColumnSchema, 2>* registered) {
    std::atomic<uint32_t> ready{0};
    std::atomic<bool> start{false};
    std::thread left([&] {
      ready.fetch_add(1, std::memory_order_release);
      while (!start.load(std::memory_order_acquire)) std::this_thread::yield();
      (*statuses)[0] = coordinator.RegisterColumn(first, &(*registered)[0]);
    });
    std::thread right([&] {
      ready.fetch_add(1, std::memory_order_release);
      while (!start.load(std::memory_order_acquire)) std::this_thread::yield();
      (*statuses)[1] = coordinator.RegisterColumn(second, &(*registered)[1]);
    });
    while (ready.load(std::memory_order_acquire) != 2) {
      std::this_thread::yield();
    }
    start.store(true, std::memory_order_release);
    left.join();
    right.join();
  };

  const ColumnSchema same{
      EntityType::Vertex, 7, 0, "name", PhysicalType::kString, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  std::array<Status, 2> same_statuses;
  std::array<ColumnSchema, 2> same_registered;
  run_pair(same, same, &same_statuses, &same_registered);
  ASSERT_TRUE(same_statuses[0].ok()) << same_statuses[0].ToString();
  ASSERT_TRUE(same_statuses[1].ok()) << same_statuses[1].ToString();
  EXPECT_EQ(same_registered[0].schema_epoch, 1U);
  EXPECT_EQ(same_registered[1].schema_epoch, 1U);
  EXPECT_EQ(std::count_if(
                coordinator.version_snapshot()->schemas.begin(),
                coordinator.version_snapshot()->schemas.end(),
                [](const ColumnSchema& schema) {
                  return schema.entity_type == EntityType::Vertex &&
                      schema.column_id == 7;
                }),
            1);

  ColumnSchema first = same;
  first.column_id = 8;
  first.logical_type = "payload";
  ColumnSchema second = first;
  second.blob_threshold = 8192;
  std::array<Status, 2> different_statuses;
  std::array<ColumnSchema, 2> different_registered;
  run_pair(first, second, &different_statuses, &different_registered);
  ASSERT_TRUE(different_statuses[0].ok())
      << different_statuses[0].ToString();
  ASSERT_TRUE(different_statuses[1].ok())
      << different_statuses[1].ToString();
  std::array<uint32_t, 2> epochs{
      different_registered[0].schema_epoch,
      different_registered[1].schema_epoch};
  std::sort(epochs.begin(), epochs.end());
  EXPECT_EQ(epochs, (std::array<uint32_t, 2>{1, 2}));
  EXPECT_TRUE(SameColumnSchemaDefinition(different_registered[0], first));
  EXPECT_TRUE(SameColumnSchemaDefinition(different_registered[1], second));
  EXPECT_EQ(std::count_if(
                coordinator.version_snapshot()->schemas.begin(),
                coordinator.version_snapshot()->schemas.end(),
                [](const ColumnSchema& schema) {
                  return schema.entity_type == EntityType::Vertex &&
                      schema.column_id == 8;
                }),
            2);
}

