  const DecisionAppendResult append = decisions.AppendCommitWithResult(
      7, {PrepareReference{0, 0, 1}}, SystemHlc{1, 0});
  EXPECT_TRUE(append.status.IsIOError()) << append.status.ToString();
  EXPECT_TRUE(append.may_be_durable);
