TEST_F(DurableLogTest, PartialDecisionWriteRequiresReopenWithoutAmbiguousOutcome) {
  const std::string decision_path = path_ + "/decision/DECISION";
  DecisionLog decisions(decision_path);
  ASSERT_TRUE(decisions.Open().ok());
  decisions.SetFaultInjectorForTesting([](DecisionLogFaultPoint point) {
    return point == DecisionLogFaultPoint::kAfterPartialRecordWrite
        ? Status::IOError("test", "partial decision write")
        : Status::OK();
  });

  const DecisionAppendResult partial = decisions.AppendCommitWithResult(
      7, {PrepareReference{0, 0, 1}}, SystemHlc{1, 0});
  EXPECT_TRUE(partial.status.IsIOError()) << partial.status.ToString();
  EXPECT_FALSE(partial.may_be_durable);
  EXPECT_TRUE(partial.requires_reopen);
  EXPECT_EQ(partial.commit_seq, 1U);

  const DecisionAppendResult blocked = decisions.AppendCommitWithResult(
      8, {PrepareReference{0, 0, 2}}, SystemHlc{2, 0});
  EXPECT_TRUE(blocked.status.IsRecoveryRequired()) << blocked.status.ToString();
  EXPECT_FALSE(blocked.may_be_durable);
  EXPECT_TRUE(blocked.requires_reopen);

  decisions.SetFaultInjectorForTesting({});
  ASSERT_TRUE(decisions.Open().ok());
  EXPECT_TRUE(decisions.commits().empty());
  const DecisionAppendResult clean = decisions.AppendCommitWithResult(
      8, {PrepareReference{0, 0, 2}}, SystemHlc{2, 0});
  ASSERT_TRUE(clean.status.ok()) << clean.status.ToString();
  EXPECT_EQ(clean.commit_seq, 1U);
}

