TEST_F(DurableLogTest, AmbiguousDecisionAppendRequiresRecoveryAndResolvesOnReopen) {
  ColumnSchema registered;
  uint64_t indeterminate_txn_id = 0;
  {
    TransactionCoordinator coordinator(path_, 1, 41);
    ASSERT_TRUE(coordinator.Open().ok());
    ColumnSchema schema{EntityType::Vertex, 3, 0, "name", PhysicalType::kString,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
    ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
    coordinator.SetDecisionLogFaultInjectorForTesting(
        [](DecisionLogFaultPoint point) {
          return point == DecisionLogFaultPoint::kAfterRecordWrite
              ? Status::IOError("test", "decision append failed after full write")
              : Status::OK();
        });

    const CommitResult result = coordinator.CommitWithResult(
        0, {PendingEvent::Put(LogicalKey::VertexProperty(9, 3), 10,
                              registered.schema_epoch,
                              Value::String("recover durable append"))});
    EXPECT_EQ(result.outcome, CommitOutcome::kIndeterminate);
    EXPECT_TRUE(result.reason.IsIOError()) << result.reason.ToString();
    EXPECT_NE(result.txn_id, 0U);
    indeterminate_txn_id = result.txn_id;
    EXPECT_TRUE(coordinator.GetChecked(
        LogicalKey::VertexProperty(9, 3), 10).status().IsRecoveryRequired());
  }

  TransactionCoordinator recovered(path_, 1, 41);
  ASSERT_TRUE(recovered.Open().ok());
  EXPECT_EQ(recovered.Get(LogicalKey::VertexProperty(9, 3), 10),
            std::optional<Value>(Value::String("recover durable append")));
  const auto outcome = recovered.ResolveTransaction(indeterminate_txn_id);
  ASSERT_TRUE(outcome.ok()) << outcome.status().ToString();
  EXPECT_EQ(outcome.ValueOrDie(), std::optional<uint64_t>(1));
  const CommitResult replacement = recovered.CommitWithResult(
      1, {PendingEvent::Put(LogicalKey::VertexProperty(9, 3), 10,
                            registered.schema_epoch,
                            Value::String("replacement"))});
  EXPECT_EQ(replacement.outcome, CommitOutcome::kCommitted)
      << replacement.reason.ToString();
  EXPECT_EQ(replacement.commit_seq, 2U);
  EXPECT_EQ(recovered.Get(LogicalKey::VertexProperty(9, 3), 10),
            std::optional<Value>(Value::String("replacement")));
}

TEST_F(DurableLogTest, DurableDecisionPublicationFailureIsIndeterminateUntilRecovery) {
  ColumnSchema registered;
  uint64_t indeterminate_txn_id = 0;
  {
    TransactionCoordinator coordinator(path_, 1, 41);
    ASSERT_TRUE(coordinator.Open().ok());
    ColumnSchema schema{EntityType::Vertex, 1, 0, "name", PhysicalType::kString,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
    ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
    coordinator.SetCommitFaultInjectorForTesting([](CommitFaultPoint point) {
      return point == CommitFaultPoint::kAfterDecisionDurable
          ? Status::IOError("test", "decision publication failed")
          : Status::OK();
    });

    const CommitResult result = coordinator.CommitWithResult(
        0, {PendingEvent::Put(LogicalKey::VertexProperty(9, 1), 10,
                              registered.schema_epoch, Value::String("durable"))});
    EXPECT_EQ(result.outcome, CommitOutcome::kIndeterminate);
    EXPECT_EQ(result.commit_seq, 0U);
    ASSERT_NE(result.txn_id, 0U);
    indeterminate_txn_id = result.txn_id;
    EXPECT_TRUE(coordinator.recovery_required());

    const auto durable_outcome = coordinator.ResolveTransaction(result.txn_id);
    ASSERT_TRUE(durable_outcome.ok()) << durable_outcome.status().ToString();
    EXPECT_TRUE(durable_outcome.ValueOrDie().has_value());
    const auto blocked_read = coordinator.GetChecked(
        LogicalKey::VertexProperty(9, 1), 10);
    EXPECT_TRUE(blocked_read.status().IsRecoveryRequired())
        << blocked_read.status().ToString();
    const CommitResult blocked_commit = coordinator.CommitWithResult(
        0, {PendingEvent::Put(LogicalKey::VertexProperty(10, 1), 10,
                              registered.schema_epoch, Value::String("blocked"))});
    EXPECT_EQ(blocked_commit.outcome, CommitOutcome::kAborted);
    EXPECT_TRUE(blocked_commit.reason.IsRecoveryRequired())
        << blocked_commit.reason.ToString();
  }

  TransactionCoordinator recovered(path_, 1, 41);
  ASSERT_TRUE(recovered.Open().ok());
  const auto value = recovered.GetChecked(LogicalKey::VertexProperty(9, 1), 10);
  ASSERT_TRUE(value.ok()) << value.status().ToString();
  EXPECT_EQ(value.ValueOrDie(), std::optional<Value>(Value::String("durable")));
  const auto outcome = recovered.ResolveTransaction(indeterminate_txn_id);
  ASSERT_TRUE(outcome.ok()) << outcome.status().ToString();
  EXPECT_EQ(outcome.ValueOrDie(), std::optional<uint64_t>(1));
}

TEST_F(DurableLogTest, PublicEdgeGetIntersectsEndpointsAndSharesDirectionalIdentity) {
  CedarDatabase db(path_, 2, 43);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema vertex_existence{EntityType::Vertex, 0, 0, "vertex_existence",
                                PhysicalType::kBinary, 4096,
                                EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema edge_existence{EntityType::EdgeOut, 7, 0, "KNOWS",
                              PhysicalType::kBinary, 4096,
                              EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_vertex;
  ColumnSchema registered_edge;
  ASSERT_TRUE(db.RegisterColumn(vertex_existence, &registered_vertex).ok());
  ASSERT_TRUE(db.RegisterColumn(edge_existence, &registered_edge).ok());

  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(1), 10,
                     registered_vertex.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(2), 10,
                     registered_vertex.schema_epoch, Value::Binary("")).ok());
  const LogicalKey edge_out = LogicalKey::EdgeExistence(
      1, 2, 7, 99, EntityType::EdgeOut);
  const LogicalKey edge_in = LogicalKey::EdgeExistence(
      1, 2, 7, 99, EntityType::EdgeIn);
  ASSERT_TRUE(db.Put(edge_out, 15, registered_edge.schema_epoch,
                     Value::Binary("edge")).ok());
  const uint64_t visible_edge_snapshot = db.visible_seq().ValueOrDie();

  ASSERT_EQ(db.Get(edge_out, 15).ValueOrDie(),
            std::optional<Value>(Value::Binary("edge")));
  ASSERT_EQ(db.Get(edge_in, 15).ValueOrDie(),
            std::optional<Value>(Value::Binary("edge")));

  ASSERT_TRUE(db.Delete(LogicalKey::VertexExistence(2), 20,
                        registered_vertex.schema_epoch).ok());
  EXPECT_FALSE(db.Get(edge_out, 25).ValueOrDie().has_value());
  EXPECT_FALSE(db.Get(edge_in, 25).ValueOrDie().has_value());
  EXPECT_EQ(db.Get(edge_out, 25, visible_edge_snapshot).ValueOrDie(),
            std::optional<Value>(Value::Binary("edge")));

  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(2), 30,
                     registered_vertex.schema_epoch, Value::Binary("")).ok());
  EXPECT_EQ(db.Get(edge_out, 35).ValueOrDie(),
            std::optional<Value>(Value::Binary("edge")));
  EXPECT_EQ(db.Get(edge_in, 35).ValueOrDie(),
            std::optional<Value>(Value::Binary("edge")));
}

