TEST_F(DurableLogTest,
       LaterDecisionCanInstallAheadButWaitsForTheVisiblePrefix) {
  constexpr uint64_t kHashSeed = 67;
  TransactionCoordinator coordinator(path_, 2, kHashSeed);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "state", PhysicalType::kInt64,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  const ShardDirectory directory(2, kHashSeed);
  std::array<std::optional<LogicalKey>, 2> keys;
  for (uint64_t vertex_id = 1; vertex_id < 1000; ++vertex_id) {
    const LogicalKey candidate = LogicalKey::VertexProperty(vertex_id, 7);
    keys[directory.ShardFor(candidate)] = candidate;
    if (keys[0].has_value() && keys[1].has_value()) break;
  }
  ASSERT_TRUE(keys[0].has_value());
  ASSERT_TRUE(keys[1].has_value());

  std::mutex gate_mutex;
  std::condition_variable gate_cv;
  bool first_waiting_to_install = false;
  bool release_first = false;
  bool second_installed = false;
  uint64_t visible_after_second_install = UINT64_MAX;
  coordinator.SetDecisionInstallHookForTesting(
      [&](uint64_t commit_seq, bool before_install) {
        std::unique_lock<std::mutex> lock(gate_mutex);
        if (commit_seq == 1 && before_install) {
          first_waiting_to_install = true;
          gate_cv.notify_all();
          gate_cv.wait(lock, [&]() { return release_first; });
        } else if (commit_seq == 2 && !before_install) {
          visible_after_second_install = coordinator.visible_seq();
          second_installed = true;
          gate_cv.notify_all();
        }
      });

  CommitResult first_result;
  CommitResult second_result;
  std::thread first([&]() {
    first_result = coordinator.CommitWithResult(
        0, {PendingEvent::Put(*keys[0], 10, registered.schema_epoch,
                              Value::Int64(1))});
  });
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    ASSERT_TRUE(gate_cv.wait_for(
        lock, std::chrono::seconds(2),
        [&]() { return first_waiting_to_install; }));
  }
  std::thread second([&]() {
    second_result = coordinator.CommitWithResult(
        0, {PendingEvent::Put(*keys[1], 10, registered.schema_epoch,
                              Value::Int64(2))});
  });
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    EXPECT_TRUE(gate_cv.wait_for(
        lock, std::chrono::seconds(2), [&]() { return second_installed; }));
    release_first = true;
  }
  gate_cv.notify_all();
  first.join();
  second.join();
  coordinator.SetDecisionInstallHookForTesting({});

  EXPECT_EQ(visible_after_second_install, 0U);
  EXPECT_EQ(first_result.outcome, CommitOutcome::kCommitted)
      << first_result.reason.ToString();
  EXPECT_EQ(first_result.commit_seq, 1U);
  EXPECT_EQ(second_result.outcome, CommitOutcome::kCommitted)
      << second_result.reason.ToString();
  EXPECT_EQ(second_result.commit_seq, 2U);
  EXPECT_EQ(coordinator.visible_seq(), 2U);
}

TEST_F(DurableLogTest,
       EarlierInstallFailureWakesAheadOfPrefixCommitAsIndeterminate) {
  constexpr uint64_t kHashSeed = 73;
  TransactionCoordinator coordinator(path_, 2, kHashSeed);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "state", PhysicalType::kInt64,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  const ShardDirectory directory(2, kHashSeed);
  std::array<std::optional<LogicalKey>, 2> keys;
  for (uint64_t vertex_id = 1; vertex_id < 1000; ++vertex_id) {
    const LogicalKey candidate = LogicalKey::VertexProperty(vertex_id, 7);
    keys[directory.ShardFor(candidate)] = candidate;
    if (keys[0].has_value() && keys[1].has_value()) break;
  }
  ASSERT_TRUE(keys[0].has_value());
  ASSERT_TRUE(keys[1].has_value());

  std::mutex gate_mutex;
  std::condition_variable gate_cv;
  bool first_waiting_to_install = false;
  bool release_first = false;
  bool second_installed = false;
  coordinator.SetDecisionInstallHookForTesting(
      [&](uint64_t commit_seq, bool before_install) {
        std::unique_lock<std::mutex> lock(gate_mutex);
        if (commit_seq == 1 && before_install) {
          first_waiting_to_install = true;
          gate_cv.notify_all();
          gate_cv.wait(lock, [&]() { return release_first; });
        } else if (commit_seq == 2 && !before_install) {
          second_installed = true;
          gate_cv.notify_all();
        }
      });
  coordinator.SetDecisionInstallFaultInjectorForTesting(
      [](uint64_t commit_seq) {
        return commit_seq == 1
                   ? Status::IOError("test", "fail visible-prefix predecessor")
                   : Status::OK();
      });

  CommitResult first_result;
  CommitResult second_result;
  std::thread first([&]() {
    first_result = coordinator.CommitWithResult(
        0, {PendingEvent::Put(*keys[0], 10, registered.schema_epoch,
                              Value::Int64(1))});
  });
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    ASSERT_TRUE(gate_cv.wait_for(
        lock, std::chrono::seconds(2),
        [&]() { return first_waiting_to_install; }));
  }
  std::thread second([&]() {
    second_result = coordinator.CommitWithResult(
        0, {PendingEvent::Put(*keys[1], 10, registered.schema_epoch,
                              Value::Int64(2))});
  });
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    ASSERT_TRUE(gate_cv.wait_for(
        lock, std::chrono::seconds(2), [&]() { return second_installed; }));
    release_first = true;
  }
  gate_cv.notify_all();
  first.join();
  second.join();
  coordinator.SetDecisionInstallHookForTesting({});
  coordinator.SetDecisionInstallFaultInjectorForTesting({});

  EXPECT_EQ(first_result.outcome, CommitOutcome::kIndeterminate);
  EXPECT_EQ(second_result.outcome, CommitOutcome::kIndeterminate);
  EXPECT_TRUE(coordinator.recovery_required());
  EXPECT_EQ(coordinator.visible_seq(), 0U);
}

TEST(StorageShardTest, InstallsCommittedEventsIdempotently) {
  StorageShard shard(3);
  const LogicalKey key = LogicalKey::VertexProperty(88, 5);
  const std::vector<PendingEvent> events = {
      PendingEvent::Put(key, 100, 1, Value::String("first")),
  };

  ASSERT_TRUE(shard.InstallCommitted(17, 1, events).ok());
  ASSERT_TRUE(shard.InstallCommitted(17, 1, events).ok());
  EXPECT_EQ(shard.event_count(), 1U);

  const auto value = shard.Get(key, 100, 1);
  ASSERT_TRUE(value.has_value());
  EXPECT_EQ(*value, Value::String("first"));
}

TEST(StorageShardTest, RejectsContradictoryReplayForInstalledEventSlot) {
  StorageShard shard(3);
  const LogicalKey key = LogicalKey::VertexProperty(88, 5);
  const std::vector<PendingEvent> original = {
      PendingEvent::Put(key, 100, 1, Value::String("first")),
  };

  ASSERT_TRUE(shard.InstallCommitted(17, 1, original).ok());

  const Status changed_sequence = shard.InstallCommitted(17, 2, original);
  EXPECT_TRUE(changed_sequence.IsCorruption()) << changed_sequence.ToString();

  const std::vector<PendingEvent> changed_content = {
      PendingEvent::Put(key, 100, 1, Value::String("different")),
  };
  const Status content_status = shard.InstallCommitted(17, 1, changed_content);
  EXPECT_TRUE(content_status.IsCorruption()) << content_status.ToString();
  EXPECT_EQ(shard.event_count(), 1U);
}

TEST_F(DurableLogTest, CoordinatorCommitsAcrossShardsAndRecoversVisibleState) {
  const LogicalKey first = LogicalKey::VertexProperty(1, 1);
  const LogicalKey second = LogicalKey::VertexProperty(2, 1);
  TransactionCoordinator coordinator(path_, 2, 7);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 1, 0, "name", PhysicalType::kString,
                      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());

  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(first, 10, registered.schema_epoch, Value::String("one")),
      PendingEvent::Put(second, 10, registered.schema_epoch, Value::String("two")),
  }, &commit_seq).ok());
  EXPECT_EQ(commit_seq, 1U);
  EXPECT_EQ(coordinator.visible_seq(), 1U);
  EXPECT_EQ(coordinator.Get(first, 10).value(), Value::String("one"));
  EXPECT_EQ(coordinator.Get(second, 10).value(), Value::String("two"));

  uint64_t rejected_commit = 0;
  const Status mismatch = coordinator.Commit(1, {
      PendingEvent::Put(first, 20, registered.schema_epoch, Value::Int32(7)),
  }, &rejected_commit);
  EXPECT_TRUE(mismatch.IsSchemaMismatch()) << mismatch.ToString();
  EXPECT_EQ(coordinator.visible_seq(), 1U);

  TransactionCoordinator reopened(path_, 2, 7);
  ASSERT_TRUE(reopened.Open().ok());
  EXPECT_EQ(reopened.visible_seq(), 1U);
  EXPECT_EQ(reopened.Get(first, 10).value(), Value::String("one"));
  EXPECT_EQ(reopened.Get(second, 10).value(), Value::String("two"));

  ASSERT_TRUE(coordinator.Flush().ok());
  EXPECT_FALSE(coordinator.version_snapshot()->files.empty());
}

TEST_F(DurableLogTest, CheckpointRetainsCommittedOutcomesAfterDecisionPrefixReclamation) {
  const LogicalKey key = LogicalKey::VertexProperty(7, 1);
  TransactionCoordinator coordinator(path_, 1, 17);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 1, 0, "name", PhysicalType::kString,
                      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());

  uint64_t first_commit = 0;
  uint64_t second_commit = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(key, 10, registered.schema_epoch, Value::String("first")),
  }, &first_commit).ok());
  ASSERT_TRUE(coordinator.Commit(first_commit, {
      PendingEvent::Put(key, 20, registered.schema_epoch, Value::String("second")),
  }, &second_commit).ok());
  ASSERT_EQ(first_commit, 1U);
  ASSERT_EQ(second_commit, 2U);
  ASSERT_TRUE(coordinator.Flush().ok());
  ASSERT_TRUE(coordinator.CheckpointDurableLogs().ok());
  ASSERT_TRUE(std::filesystem::exists(path_ + "/checkpoints/TXN-OUTCOMES-2.toi"));
  const auto first_outcome = coordinator.ResolveTransaction(first_commit);
  ASSERT_TRUE(first_outcome.ok()) << first_outcome.status().ToString();
  ASSERT_TRUE(first_outcome.ValueOrDie().has_value());
  EXPECT_EQ(*first_outcome.ValueOrDie(), first_commit);

  TransactionCoordinator reopened(path_, 1, 17);
  ASSERT_TRUE(reopened.Open().ok());
  EXPECT_EQ(reopened.visible_seq(), second_commit);
  EXPECT_EQ(reopened.Get(key, 10).value(), Value::String("first"));
  EXPECT_EQ(reopened.Get(key, 20).value(), Value::String("second"));
  const auto second_outcome = reopened.ResolveTransaction(second_commit);
  ASSERT_TRUE(second_outcome.ok()) << second_outcome.status().ToString();
  ASSERT_TRUE(second_outcome.ValueOrDie().has_value());
  EXPECT_EQ(*second_outcome.ValueOrDie(), second_commit);

  uint64_t third_commit = 0;
  ASSERT_TRUE(reopened.Commit(second_commit, {
      PendingEvent::Put(key, 30, registered.schema_epoch, Value::String("third")),
  }, &third_commit).ok());
  EXPECT_EQ(third_commit, 3U);
}

TEST_F(DurableLogTest, ManifestRewriteEstimateMatchesPersistedFramedBytes) {
  const std::string manifest_path = path_ + "/manifest/MANIFEST";
  VersionSet versions(manifest_path);
  ASSERT_TRUE(versions.Open().ok());
  const auto one_rewrite = versions.EstimateManifestRewriteBytes(1, 0);
  const auto three_rewrites = versions.EstimateManifestRewriteBytes(3, 0);
  ASSERT_TRUE(one_rewrite.ok()) << one_rewrite.status().ToString();
  ASSERT_TRUE(three_rewrites.ok()) << three_rewrites.status().ToString();
  EXPECT_EQ(three_rewrites.ValueOrDie(), 3 * one_rewrite.ValueOrDie());

  ASSERT_TRUE(versions.ApplyEdit(VersionEdit{}).ok());
  ASSERT_TRUE(std::filesystem::exists(manifest_path));
  EXPECT_EQ(one_rewrite.ValueOrDie(), std::filesystem::file_size(manifest_path));
}

TEST_F(DurableLogTest, ManifestEditEstimateIncludesIndexFragmentRecord) {
  const std::string manifest_path = path_ + "/manifest/MANIFEST";
  const std::string sst_path = path_ + "/shards/0/sst/1.sst";
  ASSERT_TRUE(std::filesystem::create_directories(
      std::filesystem::path(sst_path).parent_path()));
  const BlockPartition partition{EntityType::Vertex, 3, 1,
                                 PhysicalType::kInt64};
  SstFile written;
  ASSERT_TRUE(WriteSstFile(
      sst_path, partition,
      {TemporalEvent::Put(LogicalKey::VertexProperty(1, 3), 10, 1, 1,
                          Value::Int64(7))},
      &written).ok());

  VersionSet versions(manifest_path);
  ASSERT_TRUE(versions.Open().ok());
  IndexDefinition definition;
  definition.index_id = 1;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 3;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kBuilding;
  definition.generation = 1;
  VersionEdit seed;
  seed.schema_adds.push_back(ColumnSchema{
      EntityType::Vertex, 3, 1, "score", PhysicalType::kInt64, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4});
  seed.adds.push_back(SstFileMeta{
      1, "shards/0/sst/1.sst", partition,
      std::filesystem::file_size(sst_path), written.blob_refs,
      written.metadata.format, written.metadata.identity,
      written.metadata.statistics, written.metadata.statistics_crc32c});
  seed.index_adds.push_back(definition);
  ASSERT_TRUE(versions.ApplyEdit(seed).ok());

  VersionEdit no_fragment;
  no_fragment.expected_generation = versions.Snapshot()->generation;
  const auto baseline =
      versions.EstimateManifestEditRewriteBytes(no_fragment);
  VersionEdit with_fragment = no_fragment;
  with_fragment.index_fragment_adds.push_back(IndexFragment{
      1, 1, "indexes/1/1.idx", 1, 1,
      versions.Snapshot()->generation + 1, 1, true, {}});
  const auto projected =
      versions.EstimateManifestEditRewriteBytes(with_fragment);
  ASSERT_TRUE(baseline.ok()) << baseline.status().ToString();
  ASSERT_TRUE(projected.ok()) << projected.status().ToString();
  EXPECT_GT(projected.ValueOrDie(), baseline.ValueOrDie());
}

TEST_F(DurableLogTest,
       SchemaRegistrationAdmissionUsesExactProjectedManifestRewrite) {
  const ColumnSchema first{
      EntityType::Vertex, 6, 0, "first", PhysicalType::kString, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  const ColumnSchema second{
      EntityType::Vertex, 7, 0, "second-column-with-current-catalog",
      PhysicalType::kString, 8192, EncodingPolicy::kAdaptive,
      CompressionPolicy::kLz4};

  const auto prepare = [&](const std::string& root,
                           std::unique_ptr<TransactionCoordinator>* coordinator,
                           uint64_t* estimate) {
    coordinator->reset(new TransactionCoordinator(root, 1, 29));
    ASSERT_TRUE((*coordinator)->Open().ok());
    ColumnSchema registered;
    ASSERT_TRUE((*coordinator)->RegisterColumn(first, &registered).ok());
    VersionSet estimator(root + "/manifest/MANIFEST");
    ASSERT_TRUE(estimator.Open().ok());
    ColumnSchema projected = second;
    projected.schema_epoch = 1;
    const auto projected_bytes =
        estimator.EstimateSchemaEditRewriteBytes(projected);
    ASSERT_TRUE(projected_bytes.ok()) << projected_bytes.status().ToString();
    *estimate = projected_bytes.ValueOrDie();
  };

  {
    const std::string root = path_ + "/resource-under";
    std::unique_ptr<TransactionCoordinator> coordinator;
    uint64_t estimate = 0;
    prepare(root, &coordinator, &estimate);
    const uint64_t generation = coordinator->version_snapshot()->generation;
    const uint64_t manifest_bytes =
        std::filesystem::file_size(root + "/manifest/MANIFEST");
    ResourceGovernor resources(ResourceProfile{
        0, 0, 1, 0, 0, 0, 0, estimate - 1, 1});
    coordinator->SetResourceGovernor(&resources);
    ColumnSchema registered;
    const Status status = coordinator->RegisterColumn(second, &registered);
    EXPECT_TRUE(status.IsQueryMemoryLimit()) << status.ToString();
    EXPECT_EQ(coordinator->version_snapshot()->generation, generation);
    EXPECT_EQ(std::filesystem::file_size(root + "/manifest/MANIFEST"),
              manifest_bytes);
    EXPECT_EQ(resources.used().descriptors, 0U);
    EXPECT_EQ(resources.used().write_bytes, 0U);
    EXPECT_EQ(resources.used().metadata_ops, 0U);
  }

  {
    const std::string root = path_ + "/io-under";
    std::unique_ptr<TransactionCoordinator> coordinator;
    uint64_t estimate = 0;
    prepare(root, &coordinator, &estimate);
    const uint64_t generation = coordinator->version_snapshot()->generation;
    ResourceGovernor resources(ResourceProfile{
        0, 0, 1, 0, 0, 0, 0, estimate, 1});
    IoGovernor io(IoGovernorLimits{
        IoTokenBudget{0, 0}, IoTokenBudget{0, 0},
        IoTokenBudget{estimate - 1, 0}, IoTokenBudget{1, 0}});
    coordinator->SetResourceGovernor(&resources);
    coordinator->SetIoGovernor(&io);
    ColumnSchema registered;
    const Status status = coordinator->RegisterColumn(second, &registered);
    EXPECT_TRUE(status.IsQueryMemoryLimit()) << status.ToString();
    EXPECT_EQ(coordinator->version_snapshot()->generation, generation);
    EXPECT_EQ(resources.used().descriptors, 0U);
  }

  {
    const std::string root = path_ + "/critical-reserve";
    std::unique_ptr<TransactionCoordinator> coordinator;
    uint64_t estimate = 0;
    prepare(root, &coordinator, &estimate);
    const uint64_t generation = coordinator->version_snapshot()->generation;
    const ResourceProfile exact_resources{
        0, 0, 1, 0, 0, 0, 0, estimate, 1};
    ResourceGovernor resources(exact_resources, exact_resources);
    IoGovernor io(IoGovernorLimits{
        IoTokenBudget{0, 0}, IoTokenBudget{0, 0},
        IoTokenBudget{estimate, 0}, IoTokenBudget{1, 0}},
        IoTokenSnapshot{0, 0, estimate, 1});
    coordinator->SetResourceGovernor(&resources);
    coordinator->SetIoGovernor(&io);
    ColumnSchema registered;
    const Status status = coordinator->RegisterColumn(second, &registered);
    EXPECT_TRUE(status.IsQueryMemoryLimit()) << status.ToString();
    EXPECT_EQ(coordinator->version_snapshot()->generation, generation);
    EXPECT_EQ(resources.used().descriptors, 0U);
    EXPECT_EQ(resources.used().write_bytes, 0U);
    EXPECT_EQ(resources.used().metadata_ops, 0U);
    EXPECT_EQ(io.available(true).write_bytes, estimate);
    EXPECT_EQ(io.available(true).metadata_ops, 1U);
  }

  {
    const std::string root = path_ + "/exact";
    std::unique_ptr<TransactionCoordinator> coordinator;
    uint64_t estimate = 0;
    prepare(root, &coordinator, &estimate);
    const ResourceProfile exact_resources{
        0, 0, 1, 0, 0, 0, 0, estimate, 1};
    ResourceGovernor resources(exact_resources);
    IoGovernor io(IoGovernorLimits{
        IoTokenBudget{0, 0}, IoTokenBudget{0, 0},
        IoTokenBudget{estimate, 0}, IoTokenBudget{1, 0}});
    coordinator->SetResourceGovernor(&resources);
    coordinator->SetIoGovernor(&io);
    ColumnSchema registered;
    const Status status = coordinator->RegisterColumn(second, &registered);
    ASSERT_TRUE(status.ok()) << status.ToString();
    EXPECT_EQ(registered.schema_epoch, 1U);
    EXPECT_EQ(std::filesystem::file_size(root + "/manifest/MANIFEST"),
              estimate);
    EXPECT_EQ(resources.used().descriptors, 0U);
    EXPECT_EQ(resources.used().write_bytes, 0U);
    EXPECT_EQ(resources.used().metadata_ops, 0U);
    EXPECT_EQ(io.available(true).write_bytes, 0U);
    EXPECT_EQ(io.available(true).metadata_ops, 0U);
  }
}

