TEST_F(DurableLogTest, PublicationFaultMatrixCleansUnmanifestedSstAndSidecarOutputs) {
  {
    TransactionCoordinator coordinator(path_, 1, 11);
    ASSERT_TRUE(coordinator.Open().ok());
  }
  const BlockPartition partition{
      EntityType::Vertex, 7, 1, PhysicalType::kString};
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 10, 1, 1,
                         Value::String("fault")),
  };
  const std::vector<SstPublicationFaultPoint> sst_points = {
      SstPublicationFaultPoint::kAfterFileFsync,
      SstPublicationFaultPoint::kAfterRename,
      SstPublicationFaultPoint::kAfterDirectoryFsync,
  };
  for (size_t index = 0; index < sst_points.size(); ++index) {
    const std::string output = path_ + "/shards/0/sst/" +
        std::to_string(100 + index) + ".sst";
    const SstPublicationFaultPoint selected = sst_points[index];
    const Status written = WriteSstFile(
        output, partition, events, nullptr,
        [selected](SstPublicationFaultPoint point) {
          return point == selected
              ? Status::IOError("sst fault matrix", "injected")
              : Status::OK();
        });
    EXPECT_FALSE(written.ok());
    if (selected == SstPublicationFaultPoint::kAfterFileFsync) {
      EXPECT_TRUE(std::filesystem::exists(output + ".tmp"));
      EXPECT_FALSE(std::filesystem::exists(output));
    } else {
      EXPECT_TRUE(written.IsIndeterminate()) << written.ToString();
      EXPECT_TRUE(std::filesystem::exists(output));
    }
  }

  IndexDefinition definition;
  definition.index_id = 1;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncodingSortedDelta;
  const std::vector<IndexPosting> postings = {
      IndexPosting{EncodeIndexCanonicalValue(Value::String("fault")).ValueOrDie(),
                   0, 10, 1},
  };
  const std::vector<IndexSidecarPublicationFaultPoint> sidecar_points = {
      IndexSidecarPublicationFaultPoint::kAfterFileFsync,
      IndexSidecarPublicationFaultPoint::kAfterRename,
      IndexSidecarPublicationFaultPoint::kAfterDirectoryFsync,
  };
  for (size_t index = 0; index < sidecar_points.size(); ++index) {
    const std::string output = path_ + "/indexes/1/" +
        std::to_string(100 + index) + ".idx";
    const IndexSidecarPublicationFaultPoint selected = sidecar_points[index];
    const Status written = WriteIndexSidecarFile(
        output, definition, 100 + index, postings,
        [selected](IndexSidecarPublicationFaultPoint point) {
          return point == selected
              ? Status::IOError("sidecar fault matrix", "injected")
              : Status::OK();
        });
    EXPECT_FALSE(written.ok());
    if (selected == IndexSidecarPublicationFaultPoint::kAfterFileFsync) {
      EXPECT_TRUE(std::filesystem::exists(output + ".tmp"));
      EXPECT_FALSE(std::filesystem::exists(output));
    } else {
      EXPECT_TRUE(written.IsIndeterminate()) << written.ToString();
      EXPECT_TRUE(std::filesystem::exists(output));
    }
  }

  TransactionCoordinator reopened(path_, 1, 11);
  ASSERT_TRUE(reopened.Open().ok());
  for (size_t index = 0; index < 3; ++index) {
    EXPECT_FALSE(std::filesystem::exists(
        path_ + "/shards/0/sst/" + std::to_string(100 + index) + ".sst"));
    EXPECT_FALSE(std::filesystem::exists(
        path_ + "/shards/0/sst/" + std::to_string(100 + index) + ".sst.tmp"));
    EXPECT_FALSE(std::filesystem::exists(
        path_ + "/indexes/1/" + std::to_string(100 + index) + ".idx"));
    EXPECT_FALSE(std::filesystem::exists(
        path_ + "/indexes/1/" + std::to_string(100 + index) + ".idx.tmp"));
  }
}

