TEST_F(DurableLogTest, CloseRunsTheRealProtocolAsTypedShutdownWork) {
  CedarDatabase db(path_, 1, 11);
  ASSERT_TRUE(db.Open().ok());
  WorkExecutionService* service =
      CedarDatabaseTestAccess::work_execution_service(&db);
  ASSERT_NE(service, nullptr);
  const std::thread::id caller_thread = std::this_thread::get_id();
  std::atomic<bool> ran_on_worker{false};
  CedarDatabaseTestAccess::SetShutdownExecutionHook(&db, [&] {
    ran_on_worker.store(std::this_thread::get_id() != caller_thread,
                        std::memory_order_release);
  });
  const WorkExecutionStats before = service->stats();

  const Status closed = db.Close(ClosePolicy::kCancelQueries);
  ASSERT_TRUE(closed.ok()) << closed.ToString();
  const WorkExecutionStats after = service->stats();
  EXPECT_EQ(after.submitted[2] - before.submitted[2], 1U);
  EXPECT_EQ(after.admitted[2] - before.admitted[2], 1U);
  EXPECT_EQ(after.completed[2] - before.completed[2], 1U);
  EXPECT_TRUE(ran_on_worker.load(std::memory_order_acquire));
  const std::string metrics = db.ExportMetricsJson();
  EXPECT_NE(metrics.find("cedar_database_lifecycle_phase"), std::string::npos);
  EXPECT_NE(metrics.find("cedar_database_active_queries"), std::string::npos);

  const Status rejected = db.Flush();
  EXPECT_TRUE(rejected.IsShutdownInProgress()) << rejected.ToString();
  EXPECT_TRUE(db.Close().ok());
}

