TEST_F(DurableLogTest, ConcurrentCloseCallersObserveOneProtocolResult) {
  CedarDatabase db(path_, 1, 11);
  ASSERT_TRUE(db.Open().ok());
  std::mutex hook_mutex;
  std::condition_variable hook_cv;
  bool entered = false;
  bool release = false;
  CedarDatabaseTestAccess::SetShutdownExecutionHook(&db, [&] {
    std::unique_lock<std::mutex> lock(hook_mutex);
    entered = true;
    hook_cv.notify_all();
    hook_cv.wait(lock, [&] { return release; });
  });

  Status first = Status::InvalidArgument("test", "first not closed");
  Status second = Status::InvalidArgument("test", "second not closed");
  std::atomic<bool> second_done{false};
  std::thread first_closer([&] { first = db.Close(); });
  {
    std::unique_lock<std::mutex> lock(hook_mutex);
    hook_cv.wait(lock, [&] { return entered; });
  }
  std::thread second_closer([&] {
    second = db.Close();
    second_done.store(true, std::memory_order_release);
  });
  EXPECT_FALSE(second_done.load(std::memory_order_acquire));
  {
    std::lock_guard<std::mutex> lock(hook_mutex);
    release = true;
  }
  hook_cv.notify_all();
  first_closer.join();
  second_closer.join();
  EXPECT_EQ(first.ToString(), second.ToString());
  EXPECT_TRUE(first.ok()) << first.ToString();
}

