TEST_F(DurableLogTest, RetainedSpillingQueryStreamDoesNotCreateSpillAfterDestruction) {
  static_assert(std::is_same<
      decltype(TcypherQueryOptions{}.spill_resource_extensions),
      std::shared_ptr<ResourceGovernorExtension>>::value,
      "lazy spill must retain shared resource-extension ownership");
  const std::string spill_directory = path_ + "/outliving-query-spill";
  std::unique_ptr<QueryResultStream> stream;
  {
    CedarDatabase db(path_, 1, 11);
    ASSERT_TRUE(db.Open().ok());
    ColumnSchema existence{EntityType::Vertex, 0, 0, "existence",
                           PhysicalType::kBinary, 4096,
                           EncodingPolicy::kAdaptive,
                           CompressionPolicy::kLz4};
    ColumnSchema name{EntityType::Vertex, 7, 0, "name",
                      PhysicalType::kString, 4096,
                      EncodingPolicy::kAdaptive,
                      CompressionPolicy::kLz4};
    ColumnSchema registered_existence;
    ColumnSchema registered_name;
    ASSERT_TRUE(db.RegisterColumn(existence, &registered_existence).ok());
    ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
    for (uint64_t id = 1; id <= 12; ++id) {
      ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(id), 10,
                         registered_existence.schema_epoch,
                         Value::Binary("")).ok());
      ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(id, 7), 10,
                         registered_name.schema_epoch,
                         Value::String(std::string(96, 'a' + id))).ok());
    }
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.batch_capacity = 3;
    options.memory_account =
        std::make_shared<QueryMemoryAccount>(400, 64U << 10);
    options.spill_directory = spill_directory;
    auto opened = db.ExecuteTcypher(
        "MATCH (n) RETURN n.name ORDER BY n.name;", options);
    ASSERT_TRUE(opened.ok()) << opened.status().ToString();
    stream = opened.ConsumeValueOrDie();
  }

  ResultBatch result;
  const Status first = stream->Next(&result);
  EXPECT_TRUE(first.IsQueryCancelled()) << first.ToString();
  EXPECT_TRUE(!std::filesystem::exists(spill_directory) ||
              std::filesystem::is_empty(spill_directory));
  stream.reset();
  EXPECT_TRUE(!std::filesystem::exists(spill_directory) ||
              std::filesystem::is_empty(spill_directory));
}

