TEST(TcypherExecutorTest,
     ScheduledStreamIsTheOnlyQueryOwnerOfExecutionService) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_scheduled_stream_service_owner_timeline");
  auto scheduler = std::make_shared<WorkScheduler>();
  auto service = std::make_shared<WorkExecutionService>(scheduler, 1);
  ASSERT_TRUE(service->Start().ok());
  {
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    TcypherExecutionContext context{
        timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
        {TemporalEvent::Put(LogicalKey::VertexExistence(7), 10, 1, 1,
                            Value::Binary(""))}};
    context.work_execution_service = service;
    auto stream = OpenPhysicalRootForTest("MATCH (n) RETURN n;",
                                          std::move(context));
    ASSERT_TRUE(stream.ok()) << stream.status().ToString();
    EXPECT_EQ(service.use_count(), 2L);
  }
  EXPECT_EQ(service.use_count(), 1L);
  EXPECT_TRUE(service->Stop().ok());
}

