TEST_F(DurableLogTest,
       IndexedTargetPredicateFiltersExpandTargetsInsteadOfRootSources) {
  CedarDatabase db(path_, 2, 11);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema vertex_existence{
      EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema city{
      EntityType::Vertex, 8, 0, "city", PhysicalType::kString, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema edge_existence{
      EntityType::EdgeOut, 9, 0, "KNOWS", PhysicalType::kBinary, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_vertex;
  ColumnSchema registered_city;
  ColumnSchema registered_edge;
  ASSERT_TRUE(db.RegisterColumn(vertex_existence, &registered_vertex).ok());
  ASSERT_TRUE(db.RegisterColumn(city, &registered_city).ok());
  ASSERT_TRUE(db.RegisterColumn(edge_existence, &registered_edge).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(1), 10,
                     registered_vertex.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(2), 10,
                     registered_vertex.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(3), 10,
                     registered_vertex.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(
      LogicalKey::EdgeExistence(1, 2, registered_edge.column_id, 99,
                                EntityType::EdgeOut),
      10, registered_edge.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(
      LogicalKey::EdgeExistence(1, 3, registered_edge.column_id, 100,
                                EntityType::EdgeOut),
      10, registered_edge.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(2, registered_city.column_id),
                     10, registered_city.schema_epoch,
                     Value::String("Paris")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(3, registered_city.column_id),
                     10, registered_city.schema_epoch,
                     Value::String("London")).ok());
  ASSERT_TRUE(db.Flush().ok());
  IndexDefinition definition;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = registered_city.column_id;
  definition.schema_epoch = registered_city.schema_epoch;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  uint64_t index_id = 0;
  ASSERT_TRUE(db.RegisterIndex(definition, &index_id).ok());
  ASSERT_TRUE(db.SetIndexState(index_id, IndexState::kBuilding).ok());
  ASSERT_TRUE(db.SetIndexState(index_id, IndexState::kActive).ok());

  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.execution_stats = stats;
  auto stream = db.ExecuteTcypher(
      "MATCH (a)-[r:KNOWS]->(b) WHERE b.city = 'Paris' RETURN b;",
      options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  const Status next = stream.ValueOrDie()->Next(&result);
  ASSERT_TRUE(next.ok()) << next.ToString();
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(2));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
  EXPECT_EQ(stats->index_dynamic_filter_input_rows, 2U);
  EXPECT_EQ(stats->index_dynamic_filter_rejected_rows, 1U);
  EXPECT_EQ(stats->index_dynamic_filter_output_rows, 1U);
  EXPECT_FALSE(stats->has_selected_access_path);
  EXPECT_FALSE(stats->has_executed_access_path);

  auto explain_stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions explain_options;
  explain_options.statement_start_valid_time = 10;
  explain_options.execution_stats = explain_stats;
  auto explained = db.ExecuteTcypher(
      "EXPLAIN ANALYZE MATCH (a)-[r:KNOWS]->(b) "
      "WHERE b.city = 'Paris' RETURN b;",
      explain_options);
  ASSERT_TRUE(explained.ok()) << explained.status().ToString();
  ASSERT_TRUE(explained.ValueOrDie()->Next(&result).ok());
  const auto profile = result.batch().ValueAt(0, 0);
  ASSERT_TRUE(profile.has_value());
  ASSERT_EQ(profile->type(), PhysicalType::kString);
  const std::string& profile_text = std::get<std::string>(profile->data());
  EXPECT_NE(profile_text.find("\"dynamic_filter_input_rows\":2"),
            std::string::npos);
  EXPECT_NE(profile_text.find("\"dynamic_filter_rejected_rows\":1"),
            std::string::npos);
  EXPECT_NE(profile_text.find("\"dynamic_filter_output_rows\":1"),
            std::string::npos);
  EXPECT_TRUE(explained.ValueOrDie()->Next(&result).IsNotFound());
}

TEST_F(DurableLogTest, RepairsCorruptIndexSidecarWhileQueriesRemainCorrect) {
  auto db = std::make_unique<CedarDatabase>(path_, 1, 31);
  ASSERT_TRUE(db->Open().ok());
  ColumnSchema existence{
      EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{
      EntityType::Vertex, 7, 0, "name", PhysicalType::kString, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ASSERT_TRUE(db->RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(db->RegisterColumn(name, &registered_name).ok());
  for (uint64_t vertex = 1; vertex <= 32; ++vertex) {
    ASSERT_TRUE(db->Put(LogicalKey::VertexExistence(vertex), 10,
                        registered_existence.schema_epoch,
                        Value::Binary("")).ok());
    ASSERT_TRUE(db->Put(LogicalKey::VertexProperty(vertex, 7), 10,
                        registered_name.schema_epoch,
                        Value::String(vertex == 7 ? "target" : "other"))
                    .ok());
  }
  ASSERT_TRUE(db->Flush().ok());
  IndexDefinition definition;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = registered_name.schema_epoch;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncodingBitmap;
  uint64_t index_id = 0;
  ASSERT_TRUE(db->RegisterIndex(definition, &index_id).ok());
  ASSERT_TRUE(db->SetIndexState(index_id, IndexState::kBuilding).ok());
  ASSERT_TRUE(db->SetIndexState(index_id, IndexState::kActive).ok());

  std::filesystem::path sidecar_path;
  for (const auto& entry : std::filesystem::recursive_directory_iterator(
           std::filesystem::path(path_) / "indexes")) {
    if (entry.path().extension() == ".idx") {
      sidecar_path = entry.path();
      break;
    }
  }
  ASSERT_FALSE(sidecar_path.empty());
  std::ifstream original_input(sidecar_path, std::ios::binary);
  const std::string original_sidecar(
      (std::istreambuf_iterator<char>(original_input)),
      std::istreambuf_iterator<char>());
  ASSERT_FALSE(original_sidecar.empty());
  std::ofstream(sidecar_path, std::ios::binary | std::ios::trunc) << "corrupt";

  const auto run_query = [&db](const std::string& query,
                               std::shared_ptr<TcypherExecutionStats> stats) {
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.execution_stats = std::move(stats);
    auto stream = db->ExecuteTcypher(query, options);
    if (!stream.ok()) return StatusOr<uint64_t>(stream.status());
    uint64_t rows = 0;
    ResultBatch batch;
    while (true) {
      const Status next = stream.ValueOrDie()->Next(&batch);
      if (next.IsNotFound()) break;
      if (!next.ok()) return StatusOr<uint64_t>(next);
      rows += batch.batch().row_count();
    }
    return StatusOr<uint64_t>(rows);
  };

  auto fallback_stats = std::make_shared<TcypherExecutionStats>();
  const std::string equality_query =
      "MATCH (n) WHERE n.name = 'target' RETURN n;";
  const auto fallback = run_query(equality_query, fallback_stats);
  ASSERT_TRUE(fallback.ok()) << fallback.status().ToString();
  EXPECT_EQ(fallback.ValueOrDie(), 1U);
  EXPECT_EQ(fallback_stats->index_advisory_fallbacks, 1U);
  const auto health_after_fallback = db->index_health_stats();
  ASSERT_TRUE(health_after_fallback.ok())
      << health_after_fallback.status().ToString();
  EXPECT_EQ(health_after_fallback.ValueOrDie().event_count, 1U);
  EXPECT_EQ(health_after_fallback.ValueOrDie().repair_schedule_count, 1U);
  std::ifstream repaired_input(sidecar_path, std::ios::binary);
  const std::string repaired_sidecar(
      (std::istreambuf_iterator<char>(repaired_input)),
      std::istreambuf_iterator<char>());
  EXPECT_EQ(repaired_sidecar, original_sidecar);

  const auto duplicate_observation = run_query(
      equality_query, std::make_shared<TcypherExecutionStats>());
  ASSERT_TRUE(duplicate_observation.ok())
      << duplicate_observation.status().ToString();
  EXPECT_EQ(duplicate_observation.ValueOrDie(), 1U);
  const auto health_after_duplicate = db->index_health_stats();
  ASSERT_TRUE(health_after_duplicate.ok())
      << health_after_duplicate.status().ToString();
  EXPECT_EQ(health_after_duplicate.ValueOrDie().event_count, 1U);
  EXPECT_EQ(health_after_duplicate.ValueOrDie().repair_schedule_count, 1U);

  db.reset();
  db = std::make_unique<CedarDatabase>(path_, 1, 31);
  ASSERT_TRUE(db->Open().ok());

  auto repaired_stats = std::make_shared<TcypherExecutionStats>();
  const auto repaired = run_query(equality_query, repaired_stats);
  ASSERT_TRUE(repaired.ok()) << repaired.status().ToString();
  EXPECT_EQ(repaired.ValueOrDie(), 1U);
  EXPECT_EQ(repaired_stats->index_advisory_fallbacks, 0U);
}

TEST_F(DurableLogTest,
       IndexedSourceAndTargetPredicatesKeepIndependentCandidateDomains) {
  CedarDatabase db(path_, 2, 11);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema vertex_existence{
      EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{
      EntityType::Vertex, 7, 0, "name", PhysicalType::kString, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema city{
      EntityType::Vertex, 8, 0, "city", PhysicalType::kString, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema edge_existence{
      EntityType::EdgeOut, 9, 0, "KNOWS", PhysicalType::kBinary, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_vertex;
  ColumnSchema registered_name;
  ColumnSchema registered_city;
  ColumnSchema registered_edge;
  ASSERT_TRUE(db.RegisterColumn(vertex_existence, &registered_vertex).ok());
  ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
  ASSERT_TRUE(db.RegisterColumn(city, &registered_city).ok());
  ASSERT_TRUE(db.RegisterColumn(edge_existence, &registered_edge).ok());
  for (uint64_t id : {1U, 2U, 3U, 4U}) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(id), 10,
                       registered_vertex.schema_epoch,
                       Value::Binary("")).ok());
  }
  ASSERT_TRUE(db.Put(
      LogicalKey::EdgeExistence(1, 2, registered_edge.column_id, 99,
                                EntityType::EdgeOut),
      10, registered_edge.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(
      LogicalKey::EdgeExistence(1, 3, registered_edge.column_id, 100,
                                EntityType::EdgeOut),
      10, registered_edge.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(
      LogicalKey::EdgeExistence(4, 2, registered_edge.column_id, 101,
                                EntityType::EdgeOut),
      10, registered_edge.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(1, registered_name.column_id),
                     10, registered_name.schema_epoch,
                     Value::String("Alice")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(4, registered_name.column_id),
                     10, registered_name.schema_epoch,
                     Value::String("Carol")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(2, registered_city.column_id),
                     10, registered_city.schema_epoch,
                     Value::String("Paris")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(3, registered_city.column_id),
                     10, registered_city.schema_epoch,
                     Value::String("London")).ok());
  ASSERT_TRUE(db.Flush().ok());
  for (const ColumnSchema* column : {&registered_name, &registered_city}) {
    IndexDefinition definition;
    definition.entity_type = EntityType::Vertex;
    definition.column_id = column->column_id;
    definition.schema_epoch = column->schema_epoch;
    definition.capabilities = kIndexEquality;
    definition.canonical_encoding_id = kIndexCanonicalEncoding;
    uint64_t index_id = 0;
    ASSERT_TRUE(db.RegisterIndex(definition, &index_id).ok());
    ASSERT_TRUE(db.SetIndexState(index_id, IndexState::kBuilding).ok());
    ASSERT_TRUE(db.SetIndexState(index_id, IndexState::kActive).ok());
  }

  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.execution_stats = stats;
  auto stream = db.ExecuteTcypher(
      "MATCH (a)-[r:KNOWS]->(b) "
      "WHERE a.name = 'Alice' AND b.city = 'Paris' RETURN a, b;",
      options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::Int64(2));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
  EXPECT_EQ(stats->index_dynamic_filter_input_rows, 2U);
  EXPECT_EQ(stats->index_dynamic_filter_rejected_rows, 1U);
  EXPECT_EQ(stats->index_dynamic_filter_output_rows, 1U);
}

