TEST_F(DurableLogTest, ExecuteTcypherCountsFixedRelationshipBindings) {
  CedarDatabase db(path_, 2, 11);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema vertex_existence{EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary,
                                4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema edge_existence{EntityType::EdgeOut, 7, 0, "edge_existence",
                              PhysicalType::kBinary, 4096, EncodingPolicy::kAdaptive,
                              CompressionPolicy::kLz4};
  ColumnSchema registered_vertex;
  ColumnSchema registered_edge;
  ASSERT_TRUE(db.RegisterColumn(vertex_existence, &registered_vertex).ok());
  ASSERT_TRUE(db.RegisterColumn(edge_existence, &registered_edge).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(1), 10, registered_vertex.schema_epoch,
                     Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(2), 10, registered_vertex.schema_epoch,
                     Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::EdgeExistence(1, 2, 7, 99, EntityType::EdgeOut),
                     10, registered_edge.schema_epoch, Value::Binary("")).ok());

  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  auto stats = std::make_shared<TcypherExecutionStats>();
  options.execution_stats = stats;
  const auto stream = db.ExecuteTcypher("MATCH (a)-[r]->(b) RETURN COUNT(a);", options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.column_names(), (std::vector<std::string>{"count(a)"}));
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(1));
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);

  TcypherQueryOptions explain_options;
  explain_options.statement_start_valid_time = 10;
  const auto explained = db.ExecuteTcypher(
      "EXPLAIN MATCH (a)-[r]->(b) RETURN COUNT(a);", explain_options);
  ASSERT_TRUE(explained.ok()) << explained.status().ToString();
  ASSERT_TRUE(explained.ValueOrDie()->Next(&result).ok());
  const auto explain = result.batch().ValueAt(0, 0);
  ASSERT_TRUE(explain.has_value());
  const std::string& explain_text = std::get<std::string>(explain->data());
  EXPECT_NE(explain_text.find("Expand"), std::string::npos) << explain_text;
  EXPECT_NE(explain_text.find("Aggregate"), std::string::npos) << explain_text;
}

TEST_F(DurableLogTest,
       ExecuteTcypherGroupsAggregateByCompleteRelationshipIdentity) {
  CedarDatabase db(path_, 2, 11);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema vertex_existence{
      EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary,
      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema edge_existence{
      EntityType::EdgeOut, 7, 0, "edge_existence", PhysicalType::kBinary,
      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_vertex;
  ColumnSchema registered_edge;
  ASSERT_TRUE(db.RegisterColumn(vertex_existence, &registered_vertex).ok());
  ASSERT_TRUE(db.RegisterColumn(edge_existence, &registered_edge).ok());
  for (uint64_t id : {1U, 2U, 3U}) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(id), 10,
                       registered_vertex.schema_epoch, Value::Binary(""))
                    .ok());
  }
  ASSERT_TRUE(db.Put(
      LogicalKey::EdgeExistence(1, 2, 7, 99, EntityType::EdgeOut),
      10, registered_edge.schema_epoch, Value::Binary(""))
                  .ok());
  ASSERT_TRUE(db.Put(
      LogicalKey::EdgeExistence(1, 3, 7, 100, EntityType::EdgeOut),
      10, registered_edge.schema_epoch, Value::Binary(""))
                  .ok());

  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.execution_stats = stats;
  auto stream = db.ExecuteTcypher(
      "MATCH (a)-[r]->(b) RETURN r, COUNT(a);", options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  std::map<int64_t, int64_t> counts;
  for (;;) {
    ResultBatch result;
    const Status next = stream.ValueOrDie()->Next(&result);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    ASSERT_TRUE(result.batch().IsStructured(0));
    for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
      const auto relationship = result.batch().StructAt(0, row);
      ASSERT_TRUE(relationship.has_value());
      ASSERT_EQ(relationship->fields.size(), 6U);
      counts.emplace(
          std::get<int64_t>(relationship->fields[3].value->data()),
          std::get<int64_t>(result.batch().ValueAt(1, row)->data()));
    }
  }
  EXPECT_EQ(counts, (std::map<int64_t, int64_t>{{99, 1}, {100, 1}}));
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

