TEST_F(DurableLogTest, ExecuteTcypherExpandsMultiHopFixedRelationshipChains) {
  CedarDatabase db(path_, 2, 11);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema vertex_existence{EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary,
                                4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema knows{EntityType::EdgeOut, 7, 0, "KNOWS", PhysicalType::kBinary,
                      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema follows{EntityType::EdgeOut, 8, 0, "FOLLOWS", PhysicalType::kBinary,
                        4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_vertex;
  ColumnSchema registered_knows;
  ColumnSchema registered_follows;
  ASSERT_TRUE(db.RegisterColumn(vertex_existence, &registered_vertex).ok());
  ASSERT_TRUE(db.RegisterColumn(knows, &registered_knows).ok());
  ASSERT_TRUE(db.RegisterColumn(follows, &registered_follows).ok());
  for (uint64_t id : {1U, 2U, 3U, 4U}) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(id), 10, registered_vertex.schema_epoch,
                       Value::Binary("")).ok());
  }
  ASSERT_TRUE(db.Put(LogicalKey::EdgeExistence(1, 2, 7, 100, EntityType::EdgeOut), 10,
                     registered_knows.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::EdgeExistence(2, 3, 8, 101, EntityType::EdgeOut), 10,
                     registered_follows.schema_epoch, Value::Binary("")).ok());
  ASSERT_TRUE(db.Put(LogicalKey::EdgeExistence(2, 4, 7, 102, EntityType::EdgeOut), 10,
                     registered_knows.schema_epoch, Value::Binary("")).ok());

  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  const auto stream = db.ExecuteTcypher(
      "MATCH (a)-[r1:KNOWS]->(b)-[r2:FOLLOWS]->(c) RETURN a, b, c, r1, r2;", options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(result.column_names(), (std::vector<std::string>{"a", "b", "c", "r1", "r2"}));
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::Int64(2));
  EXPECT_EQ(*result.batch().ValueAt(2, 0), Value::Int64(3));
  ASSERT_TRUE(result.batch().IsStructured(3));
  ASSERT_TRUE(result.batch().IsStructured(4));
  EXPECT_EQ(result.batch().StructAt(3, 0)->fields[3].value, Value::Int64(100));
  EXPECT_EQ(result.batch().StructAt(4, 0)->fields[3].value, Value::Int64(101));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
}

TEST(TcypherExecutorTest, IntersectsIntervalsAcrossMultiHopFixedRelationshipChains) {
  CommitTimeline timeline("/tmp/cedar_unused_multi_hop_range_timeline");
  ASSERT_TRUE(timeline.AddDurableCommit(1, SystemHlc{100, 0}).ok());
  auto schemas = std::make_shared<SchemaSnapshot>();
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 0}].push_back(
      ColumnSchema{EntityType::Vertex, 0, 1, "existence", PhysicalType::kBinary,
                   4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4});
  schemas->schemas[{static_cast<uint8_t>(EntityType::EdgeOut), 7}].push_back(
      ColumnSchema{EntityType::EdgeOut, 7, 1, "KNOWS", PhysicalType::kBinary,
                   4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4});
  schemas->schemas[{static_cast<uint8_t>(EntityType::EdgeOut), 8}].push_back(
      ColumnSchema{EntityType::EdgeOut, 8, 1, "FOLLOWS", PhysicalType::kBinary,
                   4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4});
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexExistence(1), 5, 1, 1, Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(2), 10, 1, 1, Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(3), 15, 1, 1, Value::Binary("")),
      TemporalEvent::Put(LogicalKey::EdgeExistence(1, 2, 7, 100, EntityType::EdgeOut),
                         12, 1, 1, Value::Binary("")),
      TemporalEvent::Put(LogicalKey::EdgeExistence(2, 3, 8, 101, EntityType::EdgeOut),
                         18, 1, 1, Value::Binary("")),
  };
  const auto stream = ExecuteTcypher(
      "FOR VALID_TIME BETWEEN 0 AND 50 MATCH (a)-[r1:KNOWS]->(b)-[r2:FOLLOWS]->(c) "
      "RETURN a, b, c, r1, r2, valid_from(r2), valid_to(r2);",
      TcypherExecutionContext{timeline, 1, {}, schemas, events});
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::Int64(2));
  EXPECT_EQ(*result.batch().ValueAt(2, 0), Value::Int64(3));
  ASSERT_TRUE(result.batch().IsStructured(3));
  ASSERT_TRUE(result.batch().IsStructured(4));
  EXPECT_EQ(result.batch().StructAt(4, 0)->fields[3].value, Value::Int64(101));
  EXPECT_EQ(*result.batch().ValueAt(5, 0), Value::Timestamp(18));
  EXPECT_EQ(*result.batch().ValueAt(6, 0), Value::Timestamp(kTemporalInfinity));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
}

