TEST(TcypherExecutorTest,
     PhysicalValidTimeRangeProjectsPinnedSystemTime) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_range_system_time_timeline");
  ASSERT_TRUE(timeline.AddDurableCommit(1, SystemHlc{100, 0}).ok());
  ASSERT_TRUE(timeline.AddDurableCommit(2, SystemHlc{200, 0}).ok());
  ASSERT_TRUE(timeline.AddDurableCommit(3, SystemHlc{300, 0}).ok());
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 30;
  options.batch_capacity = 4;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 3, options, std::make_shared<SchemaSnapshot>(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(7), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Delete(LogicalKey::VertexExistence(7), 20, 2, 1),
       TemporalEvent::Put(LogicalKey::VertexExistence(7), 25, 3, 1,
                          Value::Binary(""))}};
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME BETWEEN 0 AND 30 MATCH (n) "
      "RETURN n, valid_from(n), system_time(n), commit_seq(n);",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  const Status first = stream.ValueOrDie()->Next(&result);
  ASSERT_TRUE(first.ok()) << first.ToString();
  ASSERT_EQ(result.batch().row_count(), 2U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(7));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::Timestamp(0));
  EXPECT_EQ(*result.batch().ValueAt(2, 0), Value::Timestamp(100));
  EXPECT_EQ(*result.batch().ValueAt(3, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(1, 1), Value::Timestamp(25));
  EXPECT_EQ(*result.batch().ValueAt(2, 1), Value::Timestamp(300));
  EXPECT_EQ(*result.batch().ValueAt(3, 1), Value::Int64(3));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

