TEST(TcypherExecutorTest, AggregatesAlignedRangePropertiesAcrossResultBatches) {
  CommitTimeline timeline("/tmp/cedar_unused_range_grouped_aggregate_timeline");
  auto schemas = std::make_shared<SchemaSnapshot>();
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 7}] = {
      ColumnSchema{EntityType::Vertex, 7, 1, "team", PhysicalType::kString,
                   4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4}};
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 8}] = {
      ColumnSchema{EntityType::Vertex, 8, 1, "amount", PhysicalType::kInt64,
                   4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4}};
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 30;
  options.batch_capacity = 1;
  options.execution_stats = stats;
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexExistence(1), 10, 1, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(2), 10, 1, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 10, 1, 1,
                         Value::String("A")),
      TemporalEvent::Put(LogicalKey::VertexProperty(2, 7), 10, 1, 1,
                         Value::String("A")),
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 8), 10, 1, 1,
                         Value::Int64(2)),
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 8), 20, 2, 1,
                         Value::Int64(3)),
      TemporalEvent::Put(LogicalKey::VertexProperty(2, 8), 10, 1, 1,
                         Value::Int64(4)),
  };
  const auto stream = ExecuteTcypher(
      "FOR VALID_TIME BETWEEN 15 AND 30 MATCH (n) "
      "RETURN n.team, COUNT(n), SUM(n.amount), AVG(n.amount), "
      "MIN(n.amount), MAX(n.amount);",
      TcypherExecutionContext{timeline, 2, options, schemas, events});
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  const Status next = stream.ValueOrDie()->Next(&result);
  ASSERT_TRUE(next.ok()) << next.ToString();
  EXPECT_EQ(result.column_names(),
            (std::vector<std::string>{"n.team", "count(n)", "sum(n.amount)",
                                      "avg(n.amount)", "min(n.amount)",
                                      "max(n.amount)"}));
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::String("A"));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::Int64(3));
  EXPECT_EQ(*result.batch().ValueAt(2, 0), Value::Int64(9));
  EXPECT_EQ(*result.batch().ValueAt(3, 0), Value::Float64(3.0));
  EXPECT_EQ(*result.batch().ValueAt(4, 0), Value::Int64(2));
  EXPECT_EQ(*result.batch().ValueAt(5, 0), Value::Int64(4));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

