TEST(TcypherExecutorTest, PhysicalMultiHopRangeExpandUsesPinnedIntervals) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_multi_hop_range_expand_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 30;
  options.batch_capacity = 1;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 4, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(2), 5, 2, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(3), 10, 3, 1,
                          Value::Binary("")),
       TemporalEvent::Delete(LogicalKey::VertexExistence(3), 25, 4, 1),
       TemporalEvent::Put(LogicalKey::EdgeExistence(1, 2, 9, 71, EntityType::EdgeOut),
                          5, 2, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(2, 3, 9, 72, EntityType::EdgeOut),
                          15, 3, 1, Value::Binary(""))}};
  BitemporalOracle oracle;
  for (const TemporalEvent& event : context.committed_events) {
    if (event.is_delete()) {
      oracle.AppendDelete(event.logical_key(), event.valid_from(),
                          event.commit_seq());
    } else {
      oracle.AppendPut(event.logical_key(), event.valid_from(),
                       event.commit_seq(), event.value());
    }
  }
  const auto expected = oracle.ResolveIntersection(
      {LogicalKey::VertexExistence(1), LogicalKey::VertexExistence(2),
       LogicalKey::EdgeExistence(1, 2, 9, 71, EntityType::EdgeOut),
       LogicalKey::VertexExistence(3),
       LogicalKey::EdgeExistence(2, 3, 9, 72, EntityType::EdgeOut)},
      0, 30, 4);
  ASSERT_EQ(expected.size(), 1U);
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME BETWEEN 0 AND 30 MATCH (a)-[r:KNOWS]->(b)-[s:KNOWS]->(c) "
      "RETURN a, b, c, valid_from(s), valid_to(s);",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  const Status next = stream.ValueOrDie()->Next(&result);
  ASSERT_TRUE(next.ok()) << next.ToString() << " terminal="
                         << stream.ValueOrDie()->terminal_status().ToString();
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::Int64(2));
  EXPECT_EQ(*result.batch().ValueAt(2, 0), Value::Int64(3));
  EXPECT_EQ(*result.batch().ValueAt(3, 0),
            Value::Timestamp(expected[0].valid_from));
  EXPECT_EQ(*result.batch().ValueAt(4, 0),
            Value::Timestamp(expected[0].valid_to));
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

