TEST(TcypherExecutorTest, PhysicalVariablePointExpandProjectsCompleteRelationshipPath) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_variable_point_relationship_path_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 4;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(2), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(3), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(1, 2, 9, 71, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(2, 3, 9, 72, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary(""))}};
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a)-[r:KNOWS*2..2]->(b) RETURN r;",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  const Status next = stream.ValueOrDie()->Next(&result);
  ASSERT_TRUE(next.ok()) << next.ToString();
  ASSERT_EQ(result.batch().row_count(), 1U);
  ASSERT_TRUE(result.batch().IsList(0));
  const auto path = result.batch().ListAt(0, 0);
  ASSERT_TRUE(path.has_value());
  EXPECT_TRUE(path->elements.empty());
  ASSERT_EQ(path->structured_elements.size(), 2U);
  ASSERT_EQ(path->structured_elements[0].fields.size(), 6U);
  ASSERT_EQ(path->structured_elements[1].fields.size(), 6U);
  EXPECT_EQ(path->structured_elements[0].fields[0].name, "source_id");
  EXPECT_EQ(path->structured_elements[0].fields[0].value, Value::Int64(1));
  EXPECT_EQ(path->structured_elements[0].fields[1].name, "target_id");
  EXPECT_EQ(path->structured_elements[0].fields[1].value, Value::Int64(2));
  EXPECT_EQ(path->structured_elements[0].fields[3].name, "edge_id");
  EXPECT_EQ(path->structured_elements[0].fields[3].value, Value::Int64(71));
  EXPECT_EQ(path->structured_elements[1].fields[0].value, Value::Int64(2));
  EXPECT_EQ(path->structured_elements[1].fields[1].value, Value::Int64(3));
  EXPECT_EQ(path->structured_elements[1].fields[3].value, Value::Int64(72));
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

TEST(TcypherExecutorTest, PhysicalMixedVariableThenFixedPointProjectsBothBindings) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_mixed_variable_fixed_point_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 4;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 7, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(2), 0, 2, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(3), 0, 3, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(4), 0, 4, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              1, 2, 9, 71, EntityType::EdgeOut),
                          0, 5, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              2, 3, 9, 72, EntityType::EdgeOut),
                          0, 6, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              3, 4, 9, 73, EntityType::EdgeOut),
                          0, 7, 1, Value::Binary(""))}};
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a)-[p:KNOWS*2..2]->(b)-[r:KNOWS]->(c) "
      "RETURN a, p, b, r, c;",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  const Status next = stream.ValueOrDie()->Next(&result);
  ASSERT_TRUE(next.ok()) << next.ToString();
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(result.batch().ValueAt(0, 0), Value::Int64(1));
  ASSERT_TRUE(result.batch().IsList(1));
  const auto path = result.batch().ListAt(1, 0);
  ASSERT_TRUE(path.has_value());
  ASSERT_EQ(path->structured_elements.size(), 2U);
  EXPECT_EQ(path->structured_elements[0].fields[3].value, Value::Int64(71));
  EXPECT_EQ(path->structured_elements[1].fields[3].value, Value::Int64(72));
  EXPECT_EQ(result.batch().ValueAt(2, 0), Value::Int64(3));
  ASSERT_TRUE(result.batch().IsStructured(3));
  EXPECT_EQ(result.batch().StructAt(3, 0)->fields[3].value, Value::Int64(73));
  EXPECT_EQ(result.batch().ValueAt(4, 0), Value::Int64(4));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

