TEST(TcypherExecutorTest, ExplainAnalyzeSupportsMixedExpandOrdersAndRange) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_explain_analyze_mixed_expand_timeline");
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(2), 0, 2, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(3), 0, 3, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(4), 0, 4, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::EdgeExistence(
                              1, 2, 9, 71, EntityType::EdgeOut),
                          0, 5, 1, Value::Binary("")),
      TemporalEvent::Put(LogicalKey::EdgeExistence(
                              2, 3, 9, 72, EntityType::EdgeOut),
                          0, 6, 1, Value::Binary("")),
      TemporalEvent::Put(LogicalKey::EdgeExistence(
                              3, 4, 9, 73, EntityType::EdgeOut),
                          0, 7, 1, Value::Binary(""))};
  const auto profile_for = [&](const std::string& query) {
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.batch_capacity = 1;
    auto stream = ExecuteTcypher(
        query, TcypherExecutionContext{
                   timeline, 7, options, MakeTcypherBinderSchemaSnapshot(),
                   events});
    if (!stream.ok()) {
      ADD_FAILURE() << query << " => " << stream.status().ToString();
      return std::string();
    }
    ResultBatch result;
    EXPECT_TRUE(stream.ValueOrDie()->Next(&result).ok());
    if (result.batch().column_count() == 0) return std::string();
    return std::get<std::string>(result.batch().ValueAt(0, 0)->data());
  };
  for (const std::string& query : {
           "EXPLAIN ANALYZE FOR VALID_TIME AS OF 10 "
           "MATCH (a)-[p:KNOWS*2..2]->(b)-[r:KNOWS]->(c) "
           "RETURN a, p, b, r, c;",
           "EXPLAIN ANALYZE FOR VALID_TIME BETWEEN 0 AND 20 "
           "MATCH (a)-[r:KNOWS]->(b)-[p:KNOWS*2..2]->(c) "
           "RETURN a, r, b, p, c;"}) {
    const std::string profile = profile_for(query);
    ASSERT_FALSE(profile.empty());
    const std::string first = ExplainOperatorCounters(profile, "VectorExpand", 0);
    const std::string second = ExplainOperatorCounters(profile, "VectorExpand", 1);
    EXPECT_NE(first.find("\"input_rows\":"), std::string::npos) << profile;
    EXPECT_NE(first.find("\"output_rows\":"), std::string::npos) << profile;
    EXPECT_NE(second.find("\"input_rows\":"), std::string::npos) << profile;
    EXPECT_NE(second.find("\"output_rows\":"), std::string::npos) << profile;
    EXPECT_NE(profile.find("storage"), std::string::npos) << profile;
    EXPECT_NE(profile.find("memory"), std::string::npos) << profile;
  }
}

