TEST(TcypherExecutorTest,
     PhysicalVariablePointExpandRepartitionsBranchingFrontier) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_variable_point_repartition_timeline");
  const std::vector<TemporalEvent> events = {
       TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(2), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(3), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(4), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexProperty(4, 7), 0, 1, 1,
                          Value::String("z")),
       TemporalEvent::Put(LogicalKey::VertexExistence(5), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(10), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(11), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(12), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(13), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 0, 1, 1,
                          Value::String("root")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              1, 2, 9, 71, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              1, 3, 9, 72, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              1, 4, 9, 73, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              1, 5, 9, 74, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              2, 10, 9, 75, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              3, 11, 9, 76, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              4, 12, 9, 77, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(
                              5, 13, 9, 78, EntityType::EdgeOut),
                          0, 1, 1, Value::Binary(""))};
  const std::string spill_directory =
      "/tmp/cedar_variable_point_frontier_spill";
  std::filesystem::remove_all(spill_directory);
  auto frontier_memory =
      std::make_shared<QueryMemoryAccount>(1, 64U << 10);
  const auto execute = [&](uint32_t batch_capacity,
                           const std::shared_ptr<TcypherExecutionStats>& run_stats,
                           std::vector<int64_t>* terminals) {
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.batch_capacity = batch_capacity;
    options.execution_stats = run_stats;
    if (batch_capacity == 1) {
      options.memory_account = frontier_memory;
      options.spill_directory = spill_directory;
    }
    auto stream = ExecuteTcypher(
        "FOR VALID_TIME AS OF 10 "
        "MATCH (a)-[r:KNOWS*2..2]->(b) "
        "WHERE a.name = 'root' RETURN a, b;",
        TcypherExecutionContext{
            timeline, 1, options, MakeTcypherBinderSchemaSnapshot(), events});
    ASSERT_TRUE(stream.ok()) << stream.status().ToString();
    ResultBatch result;
    for (;;) {
      const Status next = stream.ValueOrDie()->Next(&result);
      if (next.IsNotFound()) break;
      ASSERT_TRUE(next.ok()) << next.ToString();
      for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
        ASSERT_EQ(*result.batch().ValueAt(0, row), Value::Int64(1));
        terminals->push_back(
            std::get<int64_t>(result.batch().ValueAt(1, row)->data()));
      }
    }
  };
  auto baseline_stats = std::make_shared<TcypherExecutionStats>();
  std::vector<int64_t> baseline_terminals;
  execute(8, baseline_stats, &baseline_terminals);
  auto stats = std::make_shared<TcypherExecutionStats>();
  std::vector<int64_t> terminals;
  execute(1, stats, &terminals);
  ASSERT_EQ(terminals.size(), 4U);
  std::sort(terminals.begin(), terminals.end());
  std::sort(baseline_terminals.begin(), baseline_terminals.end());
  EXPECT_EQ(terminals, baseline_terminals);
  EXPECT_EQ(terminals, (std::vector<int64_t>{10, 11, 12, 13}));
  EXPECT_EQ(baseline_stats->path_frontier_repartitions, 0U);
  EXPECT_EQ(stats->path_frontier_hops, 2U);
  EXPECT_EQ(stats->path_frontier_input_states, 5U);
  EXPECT_EQ(stats->path_frontier_output_states, 8U);
  EXPECT_EQ(stats->path_frontier_completed_paths, 4U);
  EXPECT_GE(stats->path_frontier_repartitions, 1U);
  EXPECT_GE(stats->path_frontier_partitions, 4U);
  EXPECT_GE(stats->path_frontier_max_partition_size, 1U);
  EXPECT_GT(stats->path_frontier_spill_starts, 0U);
  EXPECT_GT(stats->path_frontier_spill_bytes, 0U);
  EXPECT_EQ(frontier_memory->used_bytes(), 0U);
  EXPECT_TRUE(std::filesystem::exists(spill_directory));
  EXPECT_TRUE(std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

