TEST(TcypherExecutorTest,
     PhysicalHashJoinReoptimizesNextPipelineFromBoundedPrefix) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_hash_next_pipeline_reoptimization_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 1;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(2), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(3), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 0, 1, 1,
                          Value::String("target")),
       TemporalEvent::Put(LogicalKey::VertexProperty(2, 7), 0, 1, 1,
                          Value::String("other-2")),
       TemporalEvent::Put(LogicalKey::VertexProperty(3, 7), 0, 1, 1,
                          Value::String("other-3"))}};
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a {id: 1}) MATCH (b) "
      "WHERE a.name = b.name RETURN a, b;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 1, 10, {}, context.schema_snapshot});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  PhysicalHashJoinPlanningStats planning;
  planning.statistics_snapshot_id = 1;
  planning.left = PhysicalCardinalityEstimate{100, 1000, false};
  planning.right = PhysicalCardinalityEstimate{10, 1000, false};
  const auto plan = PlanPhysicalHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, planning);
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  EXPECT_EQ(plan.ValueOrDie()->build_side,
            PhysicalHashJoinBuildSide::kRight);
  const auto snapshot = BuildPhysicalQuerySnapshot(bound.ValueOrDie(), context);
  ASSERT_TRUE(snapshot.ok()) << snapshot.status().ToString();
  auto stream = OpenPhysicalHashJoinRuntime(
      plan.ValueOrDie(), snapshot.ValueOrDie(), std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::Int64(1));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
  EXPECT_EQ(stats->pipeline_reoptimization_checks, 1U);
  EXPECT_EQ(stats->pipeline_reoptimizations, 1U);
  EXPECT_EQ(stats->pipeline_reoptimization_sampled_rows, 3U);
  EXPECT_EQ(stats->pipeline_reoptimization_sampled_batches, 3U);
  EXPECT_GT(stats->pipeline_reoptimization_prefix_memory_bytes, 0U);
  EXPECT_EQ(stats->hash_join_build_side_switches, 1U);
  EXPECT_EQ(stats->hash_join_build_side_left, 1U);
}

TEST(TcypherExecutorTest,
     PhysicalHashJoinKeepsPlannedSideWhenPrefixIsInconclusive) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_hash_inconclusive_reoptimization_timeline");
  std::vector<TemporalEvent> events;
  for (uint64_t id = 1; id <= 10; ++id) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(id), 0, 1, 1, Value::Binary("")));
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(id, 7), 0, 1, 1,
        Value::String("key-" + std::to_string(id))));
  }
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 1;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
      std::move(events)};
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) "
      "WHERE a.name = b.name RETURN a, b;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 1, 10, {}, context.schema_snapshot});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  PhysicalHashJoinPlanningStats planning;
  planning.statistics_snapshot_id = 1;
  planning.left = PhysicalCardinalityEstimate{1, 1000, false};
  planning.right = PhysicalCardinalityEstimate{100, 1000, false};
  const auto plan = PlanPhysicalHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, planning);
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  ASSERT_EQ(plan.ValueOrDie()->build_side,
            PhysicalHashJoinBuildSide::kLeft);
  const auto snapshot = BuildPhysicalQuerySnapshot(bound.ValueOrDie(), context);
  ASSERT_TRUE(snapshot.ok()) << snapshot.status().ToString();
  auto stream = OpenPhysicalHashJoinRuntime(
      plan.ValueOrDie(), snapshot.ValueOrDie(), std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  uint64_t rows = 0;
  for (;;) {
    ResultBatch result;
    const Status next = stream.ValueOrDie()->Next(&result);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    rows += result.batch().row_count();
  }
  EXPECT_EQ(rows, 10U);
  EXPECT_EQ(stats->pipeline_reoptimization_checks, 1U);
  EXPECT_EQ(stats->pipeline_reoptimizations, 0U);
  EXPECT_EQ(stats->pipeline_reoptimization_sampled_rows, 4U);
  EXPECT_EQ(stats->pipeline_reoptimization_sampled_batches, 4U);
  EXPECT_EQ(stats->hash_join_build_side_switches, 0U);
  EXPECT_EQ(stats->hash_join_build_side_left, 1U);
}

TEST(TcypherExecutorTest, PhysicalHashJoinSpillsAndPreservesProbeAndBuildOrder) {
  const std::string spill_directory = "/tmp/cedar_physical_hash_join_spill";
  std::filesystem::remove_all(spill_directory);
  CommitTimeline timeline("/tmp/cedar_unused_physical_hash_join_spill_timeline");
  std::vector<TemporalEvent> events;
  for (uint64_t id = 1; id <= 15; ++id) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(id), 0, 1, 1, Value::Binary("")));
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(id, 7), 0, 1, 1,
        Value::String("group-" + std::to_string(id % 3) + std::string(96, 'x'))));
  }
  auto memory = std::make_shared<QueryMemoryAccount>(1536, 32U << 10);
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 2;
  options.memory_account = memory;
  options.spill_directory = spill_directory;
  TcypherExecutionContext context{
      timeline, 1, options, MakeTcypherBinderSchemaSnapshot(), std::move(events)};
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) "
      "WHERE a.name = b.name RETURN a, b;",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();

  std::vector<std::pair<int64_t, int64_t>> actual;
  for (;;) {
    ResultBatch batch;
    const Status next = stream.ValueOrDie()->Next(&batch);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    ASSERT_TRUE(std::filesystem::exists(spill_directory));
    EXPECT_FALSE(std::filesystem::is_empty(spill_directory));
    for (uint32_t row = 0; row < batch.batch().row_count(); ++row) {
      actual.emplace_back(
          std::get<int64_t>(batch.batch().ValueAt(0, row)->data()),
          std::get<int64_t>(batch.batch().ValueAt(1, row)->data()));
    }
  }
  std::vector<std::pair<int64_t, int64_t>> expected;
  for (int64_t a = 1; a <= 15; ++a) {
    for (int64_t b = 1; b <= 15; ++b) {
      if (a % 3 == b % 3) expected.emplace_back(a, b);
    }
  }
  EXPECT_EQ(actual, expected);

  stream = Status::NotFound("test", "release stream");
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

