TEST(TcypherExecutorTest,
     PhysicalDisconnectedCrossJoinSpillsReplaySideAndPreservesRows) {
  const std::string spill_directory =
      "/tmp/cedar_physical_disconnected_cross_join_spill";
  std::filesystem::remove_all(spill_directory);
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_disconnected_cross_join_spill_timeline");
  std::vector<TemporalEvent> events;
  for (uint64_t id = 1; id <= 32; ++id) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(id), 0, 1, 1, Value::Binary("")));
  }
  auto memory = std::make_shared<QueryMemoryAccount>(2U << 10, 1U << 20);
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 7;
  options.memory_account = memory;
  options.spill_directory = spill_directory;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
      std::move(events)};
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) RETURN a, b;",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();

  std::vector<std::string> rows;
  bool observed_spill = false;
  for (;;) {
    ResultBatch batch;
    const Status next = stream.ValueOrDie()->Next(&batch);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    for (uint32_t row = 0; row < batch.batch().row_count(); ++row) {
      rows.push_back(
          std::to_string(std::get<int64_t>(
              batch.batch().ValueAt(0, row)->data())) + ":" +
          std::to_string(std::get<int64_t>(
              batch.batch().ValueAt(1, row)->data())));
    }
    observed_spill = observed_spill ||
        (std::filesystem::exists(spill_directory) &&
         !std::filesystem::is_empty(spill_directory));
  }
  std::vector<std::string> expected;
  for (uint64_t a = 1; a <= 32; ++a) {
    for (uint64_t b = 1; b <= 32; ++b) {
      expected.push_back(std::to_string(a) + ":" + std::to_string(b));
    }
  }
  std::sort(rows.begin(), rows.end());
  std::sort(expected.begin(), expected.end());
  EXPECT_EQ(rows, expected);
  EXPECT_TRUE(observed_spill);
  EXPECT_EQ(stats->physical_cross_join_builds, 1U);
  EXPECT_EQ(stats->cross_join_spill_starts, 1U);
  EXPECT_GT(stats->cross_join_spill_bytes, 0U);

  stream = Status::NotFound("test", "release stream");
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

TEST(TcypherExecutorTest,
     PhysicalDisconnectedCrossJoinCompletesSpillNearHardMemoryLimit) {
  const std::string spill_directory =
      "/tmp/cedar_physical_disconnected_cross_join_near_hard";
  std::filesystem::remove_all(spill_directory);
  std::vector<Value> retained_values;
  std::vector<bool> retained_validity;
  for (uint32_t row = 0; row < 22; ++row) {
    retained_values.push_back(Value::String(
        row == 20 ? std::string(600, 'x') : "build-" + std::to_string(row)));
    retained_validity.push_back(true);
  }
  ColumnBatch retained(22);
  ASSERT_TRUE(retained.AddVector(std::make_shared<FlatVector>(
      std::move(retained_values), std::move(retained_validity))).ok());
  ColumnBatch probe(1);
  ASSERT_TRUE(probe.AddVector(std::make_shared<FlatVector>(
      std::vector<Value>{Value::String("probe")},
      std::vector<bool>{true})).ok());

  auto memory = std::make_shared<QueryMemoryAccount>(3900, 4200);
  auto stats = std::make_shared<TcypherExecutionStats>();
  auto stream = OpenPhysicalCrossJoinForTesting(
      std::make_unique<InMemoryResultStream>(
          std::vector<ResultBatch>{ResultBatch(
              {"build"}, std::move(retained))}, Status::OK()),
      std::make_unique<InMemoryResultStream>(
          std::vector<ResultBatch>{ResultBatch(
              {"probe"}, std::move(probe))}, Status::OK()),
      {{true, 0, PhysicalType::kString, false, "build"},
       {false, 0, PhysicalType::kString, false, "probe"}},
      {PhysicalType::kString}, 1, memory, spill_directory, stats, false);

  std::vector<std::string> rows;
  for (;;) {
    ResultBatch batch;
    const Status next = stream->Next(&batch);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString()
                           << " spill_starts=" << stats->cross_join_spill_starts
                           << " used=" << memory->used_bytes()
                           << " peak=" << memory->peak_bytes();
    for (uint32_t row = 0; row < batch.batch().row_count(); ++row) {
      rows.push_back(std::get<std::string>(
          batch.batch().ValueAt(0, row)->data()));
    }
  }
  std::vector<std::string> expected;
  for (uint32_t row = 0; row < 22; ++row) {
    expected.push_back(
        row == 20 ? std::string(600, 'x') : "build-" + std::to_string(row));
  }
  EXPECT_EQ(rows, expected);
  EXPECT_EQ(stats->cross_join_spill_starts, 1U);
  EXPECT_GT(memory->peak_bytes(), 0U);
  EXPECT_LE(memory->peak_bytes(), memory->hard_limit_bytes());

  stream.reset();
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(!std::filesystem::exists(spill_directory) ||
              std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

