TEST(TcypherExecutorTest,
     PhysicalCrossJoinSpillReplaysStructuredAndListCells) {
  const std::string spill_directory =
      "/tmp/cedar_physical_cross_join_structured_spill";
  std::filesystem::remove_all(spill_directory);
  std::vector<StructValue> structures;
  std::vector<ListValue> lists;
  for (int64_t id = 1; id <= 8; ++id) {
    structures.push_back(StructValue{{
        StructField{"id", Value::Int64(id)},
        StructField{"label", Value::String("node-" + std::to_string(id))}}});
    lists.push_back(ListValue{{Value::String("v-" + std::to_string(id)),
                               std::nullopt, Value::Int64(id * 10)}});
  }
  ColumnBatch retained(8);
  ASSERT_TRUE(retained.AddVector(std::make_shared<StructVector>(
      structures, std::vector<bool>(8, true))).ok());
  ASSERT_TRUE(retained.AddVector(std::make_shared<ListVector>(
      lists, std::vector<bool>(8, true))).ok());
  ColumnBatch probe(1);
  ASSERT_TRUE(probe.AddVector(std::make_shared<FlatVector>(
      std::vector<Value>{Value::String("probe")},
      std::vector<bool>{true})).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(1500, 64U << 10);
  auto stats = std::make_shared<TcypherExecutionStats>();
  auto stream = OpenPhysicalCrossJoinForTesting(
      std::make_unique<InMemoryResultStream>(
          std::vector<ResultBatch>{ResultBatch(
              {"record", "items"}, std::move(retained))}, Status::OK()),
      std::make_unique<InMemoryResultStream>(
          std::vector<ResultBatch>{ResultBatch(
              {"probe"}, std::move(probe))}, Status::OK()),
      {{true, 0, PhysicalType::kBinary, false, "record"},
       {true, 1, PhysicalType::kBinary, false, "items"},
       {false, 0, PhysicalType::kString, false, "probe"}},
      {PhysicalType::kBinary, PhysicalType::kBinary}, 3, memory,
      spill_directory, stats, false);

  uint32_t output_row = 0;
  for (;;) {
    ResultBatch batch;
    const Status next = stream->Next(&batch);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    EXPECT_LE(batch.batch().row_count(), 3U);
    for (uint32_t row = 0; row < batch.batch().row_count(); ++row) {
      ASSERT_LT(output_row, structures.size());
      ASSERT_TRUE(batch.batch().StructAt(0, row).has_value());
      ASSERT_TRUE(batch.batch().ListAt(1, row).has_value());
      EXPECT_EQ(batch.batch().StructAt(0, row)->fields[0].value,
                Value::Int64(output_row + 1));
      EXPECT_EQ(batch.batch().ListAt(1, row)->elements[2],
                Value::Int64((output_row + 1) * 10));
      EXPECT_EQ(batch.batch().ValueAt(2, row), Value::String("probe"));
      ++output_row;
    }
  }
  EXPECT_EQ(output_row, 8U);
  EXPECT_EQ(stats->cross_join_spill_starts, 1U);
  stream.reset();
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(!std::filesystem::exists(spill_directory) ||
              std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

