TEST(TcypherExecutorTest,
     PhysicalCrossJoinRejectsUnchargedFixedWidthOutputPeak) {
  constexpr uint32_t kRows = 64;
  ColumnBatch build(1);
  ASSERT_TRUE(build.AddVector(std::make_shared<FlatVector>(
      std::vector<Value>{Value::Int64(1)}, std::vector<bool>{true})).ok());
  std::vector<Value> probe_values;
  probe_values.reserve(kRows);
  for (uint32_t row = 0; row < kRows; ++row) {
    probe_values.push_back(Value::Int64(row));
  }
  ColumnBatch probe(kRows);
  ASSERT_TRUE(probe.AddVector(std::make_shared<FlatVector>(
      std::move(probe_values), std::vector<bool>(kRows, true))).ok());

  const uint64_t previously_charged_output_bytes =
      sizeof(FlatVector) + sizeof(std::vector<ResultValueCell>) +
      static_cast<uint64_t>(kRows) *
          (sizeof(ResultValueCell) + sizeof(bool));
  auto memory = std::make_shared<QueryMemoryAccount>(
      previously_charged_output_bytes + 512,
      previously_charged_output_bytes + 512);
  auto stream = OpenPhysicalCrossJoinForTesting(
      std::make_unique<InMemoryResultStream>(
          std::vector<ResultBatch>{ResultBatch({"build"}, std::move(build))},
          Status::OK()),
      std::make_unique<InMemoryResultStream>(
          std::vector<ResultBatch>{ResultBatch({"probe"}, std::move(probe))},
          Status::OK()),
      {{false, 0, PhysicalType::kInt64, false, "probe"}},
      {PhysicalType::kInt64}, kRows, memory, "", nullptr, false);

  ResultBatch result;
  const Status limited = stream->Next(&result);
  EXPECT_TRUE(limited.IsQueryMemoryLimit()) << limited.ToString();
  result = ResultBatch{};
  stream.reset();
  EXPECT_EQ(memory->used_bytes(), 0U);
}

