TEST(TcypherExecutorTest,
     DisconnectedCrossJoinExplainAndAnalyzeUseTheSamePhysicalPlan) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_disconnected_cross_join_explain_timeline");
  const auto make_events = [] {
    return std::vector<TemporalEvent>{
        TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1,
                           Value::Binary("")),
        TemporalEvent::Put(LogicalKey::VertexExistence(2), 0, 1, 1,
                           Value::Binary("")),
        TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 0, 1, 1,
                           Value::String("same")),
        TemporalEvent::Put(LogicalKey::VertexProperty(2, 7), 0, 1, 1,
                           Value::String("same"))};
  };

  auto explain_stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions explain_options;
  explain_options.statement_start_valid_time = 10;
  explain_options.execution_stats = explain_stats;
  TcypherExecutionContext explain_context{
      timeline, 1, explain_options, MakeTcypherBinderSchemaSnapshot(),
      make_events()};
  auto explain_stream = ExecuteTcypher(
      "EXPLAIN FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name RETURN a, b, c;",
      std::move(explain_context));
  ASSERT_TRUE(explain_stream.ok()) << explain_stream.status().ToString();
  ResultBatch explain_batch;
  ASSERT_TRUE(explain_stream.ValueOrDie()->Next(&explain_batch).ok());
  const std::string explain = std::get<std::string>(
      explain_batch.batch().ValueAt(0, 0)->data());
  EXPECT_NE(explain.find("PhysicalMultiHashJoinPlan"), std::string::npos)
      << explain;
  EXPECT_NE(explain.find("CrossJoin"), std::string::npos) << explain;
  EXPECT_EQ(explain_stats->physical_cross_join_builds, 0U);

  auto analyze_stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions analyze_options;
  analyze_options.statement_start_valid_time = 10;
  analyze_options.execution_stats = analyze_stats;
  TcypherExecutionContext analyze_context{
      timeline, 1, analyze_options, MakeTcypherBinderSchemaSnapshot(),
      make_events()};
  auto analyze_stream = ExecuteTcypher(
      "EXPLAIN ANALYZE FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name RETURN a, b, c;",
      std::move(analyze_context));
  ASSERT_TRUE(analyze_stream.ok()) << analyze_stream.status().ToString();
  ResultBatch analyze_batch;
  ASSERT_TRUE(analyze_stream.ValueOrDie()->Next(&analyze_batch).ok());
  const std::string profile = std::get<std::string>(
      analyze_batch.batch().ValueAt(0, 0)->data());
  EXPECT_NE(profile.find("PhysicalMultiHashJoinPlan"), std::string::npos)
      << profile;
  EXPECT_NE(profile.find("CrossJoin"), std::string::npos) << profile;
  EXPECT_EQ(analyze_stats->physical_cross_join_builds, 1U);
  EXPECT_EQ(analyze_stats->cross_join_output_rows, 8U);
  EXPECT_NE(analyze_stats->executed_physical_plan_id, 0U);
  EXPECT_EQ(analyze_stats->last_physical_plan_id,
            analyze_stats->executed_physical_plan_id);
}

TEST(TcypherExecutorTest,
     RandomDisconnectedCrossJoinMatchesFixedSeedReferenceOracle) {
  constexpr uint64_t kSeed = 0xceda7c2055ULL;
  std::mt19937_64 random(kSeed);
  for (uint32_t case_index = 0; case_index < 32; ++case_index) {
    SCOPED_TRACE(::testing::Message()
                 << "seed=" << kSeed << " case=" << case_index);
    const uint64_t vertex_count = 1 + random() % 4;
    std::vector<uint64_t> groups(vertex_count + 1);
    std::vector<TemporalEvent> events;
    for (uint64_t id = 1; id <= vertex_count; ++id) {
      groups[id] = random() % 3;
      events.push_back(TemporalEvent::Put(
          LogicalKey::VertexExistence(id), 0, 1, 1, Value::Binary("")));
      events.push_back(TemporalEvent::Put(
          LogicalKey::VertexProperty(id, 7), 0, 1, 1,
          Value::String("group-" + std::to_string(groups[id]))));
    }
    CommitTimeline timeline(
        "/tmp/cedar_unused_random_disconnected_cross_join_" +
        std::to_string(case_index));
    auto stats = std::make_shared<TcypherExecutionStats>();
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.batch_capacity = 3;
    options.execution_stats = stats;
    TcypherExecutionContext context{
        timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
        std::move(events)};
    auto stream = ExecuteTcypher(
        "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) MATCH (c) "
        "WHERE a.name = b.name RETURN a, b, c;",
        std::move(context));
    ASSERT_TRUE(stream.ok()) << stream.status().ToString();
    std::vector<std::string> actual;
    for (;;) {
      ResultBatch batch;
      const Status next = stream.ValueOrDie()->Next(&batch);
      if (next.IsNotFound()) break;
      ASSERT_TRUE(next.ok()) << next.ToString();
      for (uint32_t row = 0; row < batch.batch().row_count(); ++row) {
        actual.push_back(
            std::to_string(std::get<int64_t>(
                batch.batch().ValueAt(0, row)->data())) + ":" +
            std::to_string(std::get<int64_t>(
                batch.batch().ValueAt(1, row)->data())) + ":" +
            std::to_string(std::get<int64_t>(
                batch.batch().ValueAt(2, row)->data())));
      }
    }
    std::vector<std::string> expected;
    for (uint64_t a = 1; a <= vertex_count; ++a) {
      for (uint64_t b = 1; b <= vertex_count; ++b) {
        if (groups[a] != groups[b]) continue;
        for (uint64_t c = 1; c <= vertex_count; ++c) {
          expected.push_back(std::to_string(a) + ":" +
                             std::to_string(b) + ":" +
                             std::to_string(c));
        }
      }
    }
    std::sort(actual.begin(), actual.end());
    std::sort(expected.begin(), expected.end());
    EXPECT_EQ(actual, expected);
    EXPECT_EQ(stats->physical_cross_join_builds, 1U);
  }
}

TEST(TcypherExecutorTest,
     ConnectedThreeRootLocalPredicateUsesPhysicalChildFilter) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_unsupported_multi_root_fallback_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(2), 0, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 0, 1, 1,
                          Value::String("same")),
       TemporalEvent::Put(LogicalKey::VertexProperty(2, 7), 0, 1, 1,
                          Value::String("same")),
       TemporalEvent::Put(LogicalKey::VertexProperty(2, 8), 0, 1, 1,
                          Value::String("terminal"))}};
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name AND a.city = 'terminal' "
      "RETURN a, b, c;",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  uint64_t rows = 0;
  for (;;) {
    ResultBatch result;
    const Status next = stream.ValueOrDie()->Next(&result);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    rows += result.batch().row_count();
  }
  EXPECT_EQ(rows, 4U);
  EXPECT_EQ(stats->physical_multi_join_builds, 1U);
  EXPECT_GT(stats->pipeline_builds, 0U);
  EXPECT_EQ(stats->last_physical_plan_id, stats->executed_physical_plan_id);
}

