TEST_F(DurableLogTest, PhysicalHashJoinExplainUsesPinnedStatsForExactBuildSide) {
  CedarDatabase db(path_, 1, 41);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence",
                         PhysicalType::kBinary, 4096,
                         EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{EntityType::Vertex, 7, 0, "name", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ASSERT_TRUE(db.RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
  for (uint64_t id : {1U, 2U, 3U}) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(id), 10,
                       registered_existence.schema_epoch, Value::Binary("")).ok());
    ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(id, 7), 10,
                       registered_name.schema_epoch, Value::String("same")).ok());
  }
  ASSERT_TRUE(db.Flush().ok());
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  auto stream = db.ExecuteTcypher(
      "EXPLAIN FOR VALID_TIME AS OF 10 MATCH (a {id: 1}) MATCH (b) "
      "WHERE a.name = b.name RETURN a, b;",
      options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  const auto value = result.batch().ValueAt(0, 0);
  ASSERT_TRUE(value.has_value());
  const std::string& explain = std::get<std::string>(value->data());
  EXPECT_NE(explain.find("build=left"), std::string::npos) << explain;
  EXPECT_NE(explain.find("left_rows=1"), std::string::npos) << explain;
  EXPECT_NE(explain.find("right_rows=3"), std::string::npos) << explain;
  EXPECT_EQ(explain.find("statistics=0"), std::string::npos) << explain;
}

TEST_F(DurableLogTest, PhysicalThreeRootExplainUsesPinnedStatsForJoinOrder) {
  CedarDatabase db(path_, 1, 42);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence",
                         PhysicalType::kBinary, 4096,
                         EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{EntityType::Vertex, 7, 0, "name", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ASSERT_TRUE(db.RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
  for (uint64_t id : {1U, 2U, 3U}) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(id), 10,
                       registered_existence.schema_epoch,
                       Value::Binary(""))
                    .ok());
    ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(id, 7), 10,
                       registered_name.schema_epoch, Value::String("same"))
                    .ok());
  }
  ASSERT_TRUE(db.Flush().ok());
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.execution_stats = stats;
  auto stream = db.ExecuteTcypher(
      "EXPLAIN FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b {id: 1}) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name RETURN a, b, c;",
      options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  const auto value = result.batch().ValueAt(0, 0);
  ASSERT_TRUE(value.has_value());
  const std::string& explain = std::get<std::string>(value->data());
  EXPECT_NE(explain.find("PhysicalMultiHashJoinPlan"), std::string::npos)
      << explain;
  EXPECT_EQ(explain.find("statistics=0"), std::string::npos) << explain;
  EXPECT_NE(explain.find("order=2,1,3"), std::string::npos) << explain;
  EXPECT_NE(explain.find("accumulated_rows=1"), std::string::npos)
      << explain;
  EXPECT_NE(explain.find("input_rows=3"), std::string::npos) << explain;
  EXPECT_EQ(stats->physical_multi_join_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 0U);
}

TEST_F(DurableLogTest,
       PhysicalThreeRootExplainUsesPerBindingPinnedPropertyStatistics) {
  CedarDatabase db(path_, 1, 45);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence",
                         PhysicalType::kBinary, 4096,
                         EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{EntityType::Vertex, 7, 0, "name", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema city{EntityType::Vertex, 8, 0, "city", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ColumnSchema registered_city;
  ASSERT_TRUE(db.RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
  ASSERT_TRUE(db.RegisterColumn(city, &registered_city).ok());
  for (uint64_t id = 1; id <= 10; ++id) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(id), 10,
                       registered_existence.schema_epoch, Value::Binary(""))
                    .ok());
    ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(id, 7), 10,
                       registered_name.schema_epoch, Value::String("name"))
                    .ok());
    if (id <= 2) {
      ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(id, 8), 10,
                         registered_city.schema_epoch, Value::String("name"))
                      .ok());
    }
  }
  ASSERT_TRUE(db.Flush().ok());

  const std::string query =
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.city = c.name RETURN a, b, c;";
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.execution_stats = stats;
  auto stream = db.ExecuteTcypher("EXPLAIN " + query, options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  const auto value = result.batch().ValueAt(0, 0);
  ASSERT_TRUE(value.has_value());
  const std::string& explain = std::get<std::string>(value->data());
  EXPECT_EQ(explain.find("statistics=0"), std::string::npos) << explain;
  EXPECT_NE(explain.find("order=2,1,3"), std::string::npos) << explain;
  EXPECT_NE(explain.find("accumulated_rows=2"), std::string::npos)
      << explain;
  EXPECT_NE(explain.find("input_rows=10"), std::string::npos) << explain;
  EXPECT_NE(explain.find("accumulated_confidence=700"), std::string::npos)
      << explain;
  EXPECT_NE(explain.find("accumulated_conservative=0"), std::string::npos)
      << explain;

  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_multi_join_no_stats_order_timeline");
  const auto parsed = ParseTcypher(query);
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 1, 10, {},
                            MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  const auto without_stats = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, {}, 0);
  ASSERT_TRUE(without_stats.ok()) << without_stats.status().ToString();
  EXPECT_EQ(without_stats.ValueOrDie()->join_order,
            (std::vector<uint32_t>{0, 1, 2}));
  EXPECT_NE(without_stats.ValueOrDie()->join_order,
            (std::vector<uint32_t>{1, 0, 2}));
}

TEST_F(DurableLogTest,
       PhysicalThreeRootSessionOverlayUsesConservativePinnedPlanning) {
  CedarDatabase db(path_, 1, 44);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "Person",
                         PhysicalType::kBinary, 4096,
                         EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{EntityType::Vertex, 7, 0, "name", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ASSERT_TRUE(db.RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(7), 10,
                     registered_existence.schema_epoch, Value::Binary(""))
                  .ok());
  ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(7, 7), 10,
                     registered_name.schema_epoch, Value::String("same"))
                  .ok());
  ASSERT_TRUE(db.Flush().ok());

  auto session = db.CreateTcypherSession().ConsumeValueOrDie();
  ASSERT_TRUE(session);
  ASSERT_TRUE(db.ExecuteTcypher(*session, "BEGIN SNAPSHOT;").ok());
  ASSERT_TRUE(db.ExecuteTcypher(
                    *session,
                    "CREATE (n:Person {name: 'same'}) VALID FROM 10;")
                  .ok());

  TcypherQueryOptions explain_options;
  explain_options.statement_start_valid_time = 10;
  explain_options.execution_stats = std::make_shared<TcypherExecutionStats>();
  auto explained = db.ExecuteTcypher(
      *session,
      "EXPLAIN FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name RETURN a, b, c;",
      explain_options);
  ASSERT_TRUE(explained.ok()) << explained.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(explained.ValueOrDie()->Next(&result).ok());
  const auto value = result.batch().ValueAt(0, 0);
  ASSERT_TRUE(value.has_value());
  const std::string& explain = std::get<std::string>(value->data());
  EXPECT_EQ(explain.find("statistics=0"), std::string::npos) << explain;
  EXPECT_NE(explain.find("order=1,2,3"), std::string::npos) << explain;
  EXPECT_NE(explain.find("accumulated_conservative=1"), std::string::npos)
      << explain;
  EXPECT_EQ(explain_options.execution_stats->pipeline_builds, 0U);

  TcypherQueryOptions execute_options;
  execute_options.statement_start_valid_time = 10;
  execute_options.execution_stats = std::make_shared<TcypherExecutionStats>();
  auto executed = db.ExecuteTcypher(
      *session,
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name RETURN a, b, c;",
      execute_options);
  ASSERT_TRUE(executed.ok()) << executed.status().ToString();
  uint64_t rows = 0;
  for (;;) {
    const Status next = executed.ValueOrDie()->Next(&result);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    rows += result.batch().row_count();
  }
  EXPECT_EQ(rows, 8U);
  EXPECT_EQ(execute_options.execution_stats->physical_multi_join_builds, 1U);
  EXPECT_EQ(execute_options.execution_stats->pipeline_builds, 5U);
  EXPECT_TRUE(db.ExecuteTcypher(*session, "ROLLBACK;").ok());
}

TEST_F(DurableLogTest, PhysicalHashJoinRuntimeHonorsPinnedLeftBuildSideWhenSpilling) {
  const std::string spill_directory = path_ + "/hash_join_left_build_spill";
  std::filesystem::remove_all(spill_directory);
  CedarDatabase db(path_, 1, 43);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence",
                         PhysicalType::kBinary, 4096,
                         EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{EntityType::Vertex, 7, 0, "name", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ASSERT_TRUE(db.RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
  for (uint64_t id : {1U, 2U, 3U}) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(id), 10,
                       registered_existence.schema_epoch, Value::Binary("")).ok());
    ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(id, 7), 10,
                       registered_name.schema_epoch, Value::String("same")).ok());
  }
  ASSERT_TRUE(db.Flush().ok());
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  auto memory = std::make_shared<QueryMemoryAccount>(1, 8U << 20);
  options.memory_account = memory;
  options.spill_directory = spill_directory;
  options.execution_stats = std::make_shared<TcypherExecutionStats>();
  auto stream = db.ExecuteTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a {id: 1}) MATCH (b) "
      "WHERE a.name = b.name RETURN a, b;",
      options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  std::vector<std::pair<int64_t, int64_t>> rows;
  for (;;) {
    ResultBatch result;
    const Status next = stream.ValueOrDie()->Next(&result);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    ASSERT_TRUE(std::filesystem::exists(spill_directory));
    EXPECT_FALSE(std::filesystem::is_empty(spill_directory));
    for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
      rows.emplace_back(
          std::get<int64_t>(result.batch().ValueAt(0, row)->data()),
          std::get<int64_t>(result.batch().ValueAt(1, row)->data()));
    }
  }
  std::sort(rows.begin(), rows.end());
  EXPECT_EQ(rows, (std::vector<std::pair<int64_t, int64_t>>{
                      {1, 1}, {1, 2}, {1, 3}}));
  EXPECT_EQ(options.execution_stats->hash_join_build_side_left, 1U);
  EXPECT_EQ(options.execution_stats->hash_join_build_input_rows, 1U);
  EXPECT_EQ(options.execution_stats->hash_join_probe_input_rows, 3U);
  const auto operator_counters =
      options.execution_stats->operator_runtime->Snapshot();
  const auto join = operator_counters.find(
      OperatorRuntimeKey{options.execution_stats->executed_physical_plan_id, 1});
  ASSERT_NE(join, operator_counters.end());
  EXPECT_GT(join->second.spill_starts, 0U);
  EXPECT_GT(join->second.spill_bytes, 0U);
  EXPECT_GT(join->second.memory_peak_bytes, 0U);
  stream = Status::NotFound("test", "release stream");
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

TEST(TcypherExecutorTest, PhysicalHashJoinExplainAnalyzeExecutesTypedPlan) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_hash_join_analyze_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 1;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(1), 0, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 0, 1, 1,
                          Value::String("same"))}};
  auto stream = ExecuteTcypher(
      "EXPLAIN ANALYZE FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) "
      "WHERE a.name = b.name RETURN a, b;",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  const auto profile = result.batch().ValueAt(0, 0);
  ASSERT_TRUE(profile.has_value());
  const std::string& text = std::get<std::string>(profile->data());
  EXPECT_NE(text.find("HashJoin"), std::string::npos);
  EXPECT_NE(text.find("\"pipelines_built\":3"), std::string::npos);
  EXPECT_NE(text.find("\"output_rows\":1"), std::string::npos);
  const size_t join_operator = text.find("\"kind\":\"HashJoin\"");
  ASSERT_NE(join_operator, std::string::npos);
  const size_t join_counters = text.find("\"counters\":{", join_operator);
  ASSERT_NE(join_counters, std::string::npos);
  EXPECT_NE(text.find("\"build_input_rows\":1", join_counters),
            std::string::npos);
  EXPECT_NE(text.find("\"probe_input_rows\":1", join_counters),
            std::string::npos);
  EXPECT_NE(text.find("\"output_rows\":1", join_counters),
            std::string::npos);
  EXPECT_NE(stats->executed_physical_plan_id, 0U);
  EXPECT_EQ(stats->executed_physical_plan_id, stats->last_physical_plan_id);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

TEST(TcypherExecutorTest, PhysicalHashJoinProjectsPropertiesAndProvenance) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_hash_join_projection_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 8;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 2, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(1), 3, 1, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(2), 5, 2, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 3, 1, 1,
                          Value::String("same")),
       TemporalEvent::Put(LogicalKey::VertexProperty(2, 7), 5, 2, 1,
                          Value::String("same"))}};
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) WHERE a.name = b.name "
      "RETURN a.name, b, valid_from(a);",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 4U);
  EXPECT_EQ(result.column_names(),
            (std::vector<std::string>{"a.name", "b", "valid_from(a)"}));
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::String("same"));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(2, 0), Value::Timestamp(3));
  EXPECT_EQ(*result.batch().ValueAt(1, 1), Value::Int64(2));
  EXPECT_EQ(*result.batch().ValueAt(1, 2), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(2, 2), Value::Timestamp(5));
  EXPECT_EQ(*result.batch().ValueAt(1, 3), Value::Int64(2));
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 3U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

