TEST_F(DurableLogTest, TcypherActiveIndexWithoutUsableFragmentUsesBaseScan) {
  CedarDatabase db(path_, 2, 11);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary,
                         4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{EntityType::Vertex, 7, 0, "name", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ASSERT_TRUE(db.RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
  for (uint64_t entity_id = 1; entity_id <= 64; ++entity_id) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(entity_id), 10,
                       registered_existence.schema_epoch, Value::Binary("")).ok());
    ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(entity_id, 7), 10,
                       registered_name.schema_epoch,
                       Value::String(entity_id == 17 ? "target" : "other")).ok());
  }

  IndexDefinition definition;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = registered_name.column_id;
  definition.schema_epoch = registered_name.schema_epoch;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  uint64_t index_id = 0;
  ASSERT_TRUE(db.RegisterIndex(definition, &index_id).ok());
  ASSERT_TRUE(db.SetIndexState(index_id, IndexState::kBuilding).ok());
  ASSERT_TRUE(db.SetIndexState(index_id, IndexState::kActive).ok());

  TcypherQueryOptions options;
  options.statement_start_valid_time = 15;
  auto stream = db.ExecuteTcypher("MATCH (n) WHERE n.name = 'target' RETURN n;", options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(17));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());

  ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(17, 7), 20,
                     registered_name.schema_epoch, Value::String("other")).ok());
  options.statement_start_valid_time = 25;
  stream = db.ExecuteTcypher("MATCH (n) WHERE n.name = 'target' RETURN n;", options);
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
}

TEST_F(DurableLogTest, TcypherUsesRangePrefixAndInPredicatesWithActiveSidecars) {
  CedarDatabase db(path_, 1, 11);
  ASSERT_TRUE(db.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary,
                         4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{EntityType::Vertex, 29, 0, "name", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ASSERT_TRUE(db.RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(db.RegisterColumn(name, &registered_name).ok());
  const std::vector<std::pair<uint64_t, std::string>> rows = {
      {1, "alpha"}, {2, "alpine"}, {3, "bravo"}, {4, "charlie"},
  };
  for (const auto& row : rows) {
    ASSERT_TRUE(db.Put(LogicalKey::VertexExistence(row.first), 10,
                       registered_existence.schema_epoch, Value::Binary("")).ok());
    ASSERT_TRUE(db.Put(LogicalKey::VertexProperty(row.first, 29), 10,
                       registered_name.schema_epoch, Value::String(row.second)).ok());
  }
  ASSERT_TRUE(db.Flush().ok());
  IndexDefinition definition;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = registered_name.column_id;
  definition.schema_epoch = registered_name.schema_epoch;
  definition.capabilities = kIndexEquality | kIndexOrderedRange | kIndexPrefix;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  uint64_t index_id = 0;
  ASSERT_TRUE(db.RegisterIndex(definition, &index_id).ok());
  ASSERT_TRUE(db.SetIndexState(index_id, IndexState::kBuilding).ok());
  ASSERT_TRUE(db.SetIndexState(index_id, IndexState::kActive).ok());

  const auto collect_ids = [&](const std::string& query) {
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    const auto stream = db.ExecuteTcypher(query, options);
    EXPECT_TRUE(stream.ok()) << stream.status().ToString();
    ResultBatch batch;
    std::vector<int64_t> ids;
    while (stream.ok() && stream.ValueOrDie()->Next(&batch).ok()) {
      for (uint32_t row = 0; row < batch.batch().row_count(); ++row) {
        ids.push_back(std::get<int64_t>(batch.batch().ValueAt(0, row)->data()));
      }
    }
    std::sort(ids.begin(), ids.end());
    return ids;
  };
  EXPECT_EQ(collect_ids("MATCH (n) WHERE n.name >= 'bravo' RETURN n;"),
            (std::vector<int64_t>{3, 4}));
  EXPECT_EQ(collect_ids("MATCH (n) WHERE n.name STARTS WITH 'al' RETURN n;"),
            (std::vector<int64_t>{1, 2}));
  EXPECT_EQ(collect_ids("MATCH (n) WHERE n.name IN ['alpha', 'charlie'] RETURN n;"),
            (std::vector<int64_t>{1, 4}));
}

TEST(TcypherExecutorTest, ValidatedIndexCoverageStillResolvesSuccessorDeletes) {
  CommitTimeline timeline("/tmp/cedar_unused_index_coverage_timeline");
  const ColumnSchema name{EntityType::Vertex, 7, 1, "name", PhysicalType::kString,
                          4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  auto schemas = std::make_shared<SchemaSnapshot>();
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 7}].push_back(name);

  std::vector<TemporalEvent> property_events;
  std::vector<TemporalEvent> committed_events;
  for (uint64_t entity_id = 1; entity_id <= 64; ++entity_id) {
    committed_events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(entity_id), 10, 1, 1, Value::Binary("")));
    property_events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(entity_id, 7), 10, 1, 1,
        Value::String(entity_id == 17 ? "target" : "other")));
  }
  property_events.push_back(
      TemporalEvent::Delete(LogicalKey::VertexProperty(17, 7), 20, 2, 1));
  committed_events.insert(committed_events.end(), property_events.begin(), property_events.end());

  IndexDefinition definition;
  definition.index_id = 1;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kActive;
  const auto sidecar = BuildIndexCandidateSidecar(99, definition, property_events);
  ASSERT_TRUE(sidecar.ok()) << sidecar.status().ToString();

  auto versions = std::make_shared<VersionSnapshot>();
  versions->generation = 7;
  versions->files.push_back(SstFileMeta{99, "shards/0/sst/99.sst",
      BlockPartition{EntityType::Vertex, 7, 1, PhysicalType::kString}, 0, {}});
  auto catalog = std::make_shared<IndexCatalogSnapshot>();
  catalog->catalog_generation = 7;
  catalog->definitions.push_back(definition);
  catalog->fragments.push_back(IndexFragment{1, 99, "indexes/1/99.sidecar",
      static_cast<uint64_t>(property_events.size()), 64, 7, 1, true, {}});

  TcypherQueryOptions options;
  options.statement_start_valid_time = 15;
  auto stream = ExecuteTcypher("MATCH (n) WHERE n.name = 'target' RETURN n;",
      TcypherExecutionContext{timeline, 2, options, schemas, committed_events, nullptr, nullptr,
                              catalog, versions,
                              {TcypherIndexSource{1, 99, property_events, sidecar.ValueOrDie()}}});
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(17));

  options.statement_start_valid_time = 25;
  stream = ExecuteTcypher("MATCH (n) WHERE n.name = 'target' RETURN n;",
      TcypherExecutionContext{timeline, 2, options, schemas, committed_events, nullptr, nullptr,
                              catalog, versions,
                              {TcypherIndexSource{1, 99, property_events, sidecar.ValueOrDie()}}});
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
}

TEST(TcypherExecutorTest, HybridIndexCandidatesIncludeUncoveredMemtableMatches) {
  CommitTimeline timeline("/tmp/cedar_unused_hybrid_index_timeline");
  const ColumnSchema name{EntityType::Vertex, 7, 1, "name", PhysicalType::kString,
                          4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  auto schemas = std::make_shared<SchemaSnapshot>();
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 7}].push_back(name);

  std::vector<TemporalEvent> source_events;
  std::vector<TemporalEvent> committed_events;
  constexpr uint64_t kCoveredVertices = 2048;
  for (uint64_t entity_id = 1; entity_id <= kCoveredVertices; ++entity_id) {
    committed_events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(entity_id), 0, 1, 1, Value::Binary("")));
    source_events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(entity_id, 7), 0, 1, 1,
        Value::String(entity_id == 1 ? "target" : "other")));
  }
  committed_events.insert(committed_events.end(), source_events.begin(), source_events.end());
  committed_events.push_back(TemporalEvent::Put(
      LogicalKey::VertexExistence(kCoveredVertices + 1), 0, 2, 1, Value::Binary("")));
  committed_events.push_back(TemporalEvent::Put(
      LogicalKey::VertexProperty(kCoveredVertices + 1, 7), 0, 2, 1, Value::String("target")));

  IndexDefinition definition;
  definition.index_id = 1;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kActive;
  const auto sidecar = BuildIndexCandidateSidecar(99, definition, source_events);
  ASSERT_TRUE(sidecar.ok()) << sidecar.status().ToString();
  auto versions = std::make_shared<VersionSnapshot>();
  versions->generation = 7;
  versions->files.push_back(SstFileMeta{99, "shards/0/sst/99.sst",
      BlockPartition{EntityType::Vertex, 7, 1, PhysicalType::kString}, 0, {}});
  auto catalog = std::make_shared<IndexCatalogSnapshot>();
  catalog->catalog_generation = 7;
  catalog->definitions.push_back(definition);
  catalog->fragments.push_back(IndexFragment{1, 99, "indexes/1/99.sidecar",
      static_cast<uint64_t>(source_events.size()), 1, 7, 1, true, {}});

  TcypherQueryOptions options;
  options.statement_start_valid_time = 0;
  const auto stream = ExecuteTcypher("MATCH (n) WHERE n.name = 'target' RETURN n;",
      TcypherExecutionContext{timeline, 2, options, schemas, committed_events, nullptr, nullptr,
                              catalog, versions,
                              {TcypherIndexSource{1, 99, source_events, sidecar.ValueOrDie()}}});
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 2U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(0, 1), Value::Int64(kCoveredVertices + 1));
}

TEST(TcypherExecutorTest, IncompleteMemtableDeltaFallsBackWithoutFalseNegatives) {
  CommitTimeline timeline("/tmp/cedar_unused_incomplete_memtable_delta_timeline");
  const ColumnSchema name{EntityType::Vertex, 7, 1, "name", PhysicalType::kString,
                          4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  auto schemas = std::make_shared<SchemaSnapshot>();
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 7}].push_back(name);
  std::vector<TemporalEvent> property_events;
  std::vector<TemporalEvent> committed_events;
  constexpr uint64_t kVertexCount = 2048;
  constexpr uint64_t kTargetId = 17;
  for (uint64_t entity_id = 1; entity_id <= kVertexCount; ++entity_id) {
    committed_events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(entity_id), 10, 1, 1,
        Value::Binary("")));
    property_events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(entity_id, 7), 10, 1, 1,
        Value::String(entity_id == kTargetId ? "target" : "other")));
  }
  committed_events.insert(committed_events.end(), property_events.begin(),
                          property_events.end());

  IndexDefinition definition;
  definition.index_id = 1;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kActive;
  auto versions = std::make_shared<VersionSnapshot>();
  versions->generation = 7;
  auto catalog = std::make_shared<IndexCatalogSnapshot>();
  catalog->catalog_generation = 7;
  catalog->definitions.push_back(definition);

  TcypherDeltaIndexSource incomplete;
  incomplete.index_id = 1;
  incomplete.source_generation = 1;
  incomplete.events = property_events;
  ASSERT_TRUE(incomplete.index.Rebuild(
      definition, incomplete.source_generation, {}).ok());
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  const auto stream = ExecuteTcypher(
      "MATCH (n) WHERE n.name = 'target' RETURN n;",
      TcypherExecutionContext{timeline, 1, options, schemas, committed_events,
                              nullptr, nullptr, catalog, versions, {},
                              {std::move(incomplete)}});
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(kTargetId));
}

