TEST(TcypherExecutorTest,
     GroupsCollectedNamesByTypedRelationshipThroughPhysicalRuntime) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_group_collect_relationship_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 1;
  options.execution_stats = stats;
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexExistence(1), 1, 1, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(2), 1, 2, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(3), 1, 3, 1,
                         Value::Binary("")),
      TemporalEvent::Put(
          LogicalKey::EdgeExistence(1, 2, 9, 71, EntityType::EdgeOut),
          5, 4, 1, Value::Binary("")),
      TemporalEvent::Put(
          LogicalKey::EdgeExistence(1, 3, 9, 72, EntityType::EdgeOut),
          7, 5, 1, Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexProperty(2, 7), 1, 6, 1,
                         Value::String("Ada")),
      TemporalEvent::Put(LogicalKey::VertexProperty(3, 7), 1, 7, 1,
                         Value::String("Li")),
  };
  const auto stream = ExecuteTcypher(
      "MATCH (a)-[r:KNOWS]->(b) RETURN r, COLLECT(b.name);",
      TcypherExecutionContext{
          timeline, 7, options, MakeTcypherBinderSchemaSnapshot(), events});
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  for (int64_t expected_edge = 71; expected_edge <= 72; ++expected_edge) {
    ResultBatch result;
    ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
    ASSERT_EQ(result.batch().row_count(), 1U);
    ASSERT_TRUE(result.batch().IsStructured(0));
    ASSERT_TRUE(result.batch().IsList(1));
    const auto relationship = result.batch().StructAt(0, 0);
    ASSERT_TRUE(relationship.has_value());
    ASSERT_EQ(relationship->fields.size(), 6U);
    EXPECT_EQ(relationship->fields[3].value, Value::Int64(expected_edge));
    const auto collected = result.batch().ListAt(1, 0);
    ASSERT_TRUE(collected.has_value());
    ASSERT_EQ(collected->elements.size(), 1U);
    EXPECT_EQ(collected->elements[0],
              Value::String(expected_edge == 71 ? "Ada" : "Li"));
  }
  ResultBatch end;
  EXPECT_TRUE(stream.ValueOrDie()->Next(&end).IsNotFound());
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_GT(stats->pipeline_builds, 0U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

