TEST(TcypherExecutorTest, SortsChangePropertiesAcrossResultBatches) {
  CommitTimeline timeline("/tmp/cedar_unused_change_sort_timeline");
  auto schemas = std::make_shared<SchemaSnapshot>();
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 7}] = {
      ColumnSchema{EntityType::Vertex, 7, 1, "name", PhysicalType::kString,
                   4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4}};
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 1;
  options.execution_stats = stats;
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexExistence(1), 1, 1, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(2), 2, 2, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 1, 1, 1,
                         Value::String("Zoe")),
      TemporalEvent::Put(LogicalKey::VertexProperty(2, 7), 2, 2, 1,
                         Value::String("Ada")),
  };
  const auto stream = ExecuteTcypher(
      "CHANGES FOR VALID_TIME BETWEEN 0 AND 10 MATCH (n) "
      "RETURN n.name ORDER BY n.name;",
      TcypherExecutionContext{timeline, 2, options, schemas, events});
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  std::vector<std::string> names;
  for (;;) {
    ResultBatch result;
    const Status next = stream.ValueOrDie()->Next(&result);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
      names.push_back(std::get<std::string>(
          result.batch().ValueAt(0, row)->data()));
    }
  }
  EXPECT_EQ(names, (std::vector<std::string>{"Ada", "Zoe"}));
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

