TEST(ColumnBatchTest, ExposesStableScalarReferencesAcrossVectorViews) {
  auto parent = std::make_shared<FlatVector>(
      std::vector<Value>{Value::String("alpha"), Value::Binary("beta")},
      std::vector<bool>{true, true});
  DictionaryVector dictionary(parent, {1, 0});
  auto dictionary_parent = std::make_shared<DictionaryVector>(parent,
                                                               std::vector<uint32_t>{1, 0});
  SliceVector slice(dictionary_parent, 1, 1);
  ConstantVector constant(Value::String("constant"), 2);

  ASSERT_NE(parent->ValueRefAt(0), nullptr);
  EXPECT_EQ(parent->ValueRefAt(0), parent->ValueRefAt(0));
  EXPECT_EQ(dictionary.ValueRefAt(0), parent->ValueRefAt(1));
  EXPECT_EQ(slice.ValueRefAt(0), parent->ValueRefAt(0));
  ASSERT_NE(constant.ValueRefAt(1), nullptr);
  EXPECT_EQ(*constant.ValueRefAt(1), Value::String("constant"));
  EXPECT_EQ(parent->ValuePayloadBytesAt(0), 5U);
  EXPECT_EQ(dictionary.ValuePayloadBytesAt(0), 4U);

  StructVector structured(
      {StructValue{{StructField{"id", Value::Int64(1)},
                    StructField{"ok", Value::Bool(true)}}}},
      {true});
  ListVector listed(
      {ListValue{{Value::Int32(7), Value::String("value")}}}, {true});
  EXPECT_EQ(structured.ValueRefAt(0), nullptr);
  EXPECT_EQ(listed.ValueRefAt(0), nullptr);
  EXPECT_EQ(structured.ValuePayloadBytesAt(0),
            2U * sizeof(StructField) + 4U);
  EXPECT_EQ(listed.ValuePayloadBytesAt(0),
            2U * sizeof(std::optional<Value>) + 5U);

  auto structured_parent = std::make_shared<StructVector>(
      std::vector<StructValue>{{{StructField{"name", Value::String("Ada")}}}},
      std::vector<bool>{true});
  auto listed_parent = std::make_shared<ListVector>(
      std::vector<ListValue>{{{Value::String("Ada")}}},
      std::vector<bool>{true});
  auto structured_dictionary = std::make_shared<DictionaryVector>(
      structured_parent, std::vector<uint32_t>{0});
  auto listed_dictionary = std::make_shared<DictionaryVector>(
      listed_parent, std::vector<uint32_t>{0});
  SliceVector structured_slice(structured_dictionary, 0, 1);
  SliceVector listed_slice(listed_dictionary, 0, 1);
  EXPECT_EQ(structured_dictionary->StructRefAt(0),
            structured_parent->StructRefAt(0));
  EXPECT_EQ(listed_dictionary->ListRefAt(0), listed_parent->ListRefAt(0));
  EXPECT_EQ(structured_slice.StructRefAt(0),
            structured_parent->StructRefAt(0));
  EXPECT_EQ(listed_slice.ListRefAt(0), listed_parent->ListRefAt(0));

  ColumnBatch composite_batch(1);
  ASSERT_TRUE(composite_batch.AddVector(structured_dictionary).ok());
  ASSERT_TRUE(composite_batch.AddVector(listed_dictionary).ok());
  EXPECT_EQ(composite_batch.StructRefAt(0, 0),
            structured_parent->StructRefAt(0));
  EXPECT_EQ(composite_batch.ListRefAt(1, 0), listed_parent->ListRefAt(0));

  ColumnBatch batch(2);
  ASSERT_TRUE(batch.AddVector(dictionary_parent).ok());
  ASSERT_TRUE(batch.SetSelection({1}).ok());
  EXPECT_EQ(batch.ValueRefAt(0, 0), parent->ValueRefAt(0));
  EXPECT_EQ(batch.ValuePayloadBytesAt(0, 0), 5U);
}

