TEST(TemporalCoalesceTest, MergesEqualDemandedStatesUnlessProvenanceIsDemanded) {
  const LogicalKey key = LogicalKey::VertexProperty(1, 1);
  const auto first = std::make_shared<TemporalEvent>(
      TemporalEvent::Put(key, 0, 1, 1, Value::String("same")));
  const auto second = std::make_shared<TemporalEvent>(
      TemporalEvent::Put(key, 10, 2, 1, Value::String("same")));
  const std::vector<AlignedTemporalInterval> intervals = {
      {0, 10, {first}},
      {10, 20, {second}},
  };
  const auto coalesced = CoalesceTemporalIntervals(intervals, false);
  ASSERT_TRUE(coalesced.ok()) << coalesced.status().ToString();
  ASSERT_EQ(coalesced.ValueOrDie().size(), 1U);
  EXPECT_EQ(coalesced.ValueOrDie()[0].valid_from, 0U);
  EXPECT_EQ(coalesced.ValueOrDie()[0].valid_to, 20U);
  const auto provenance = CoalesceTemporalIntervals(intervals, true);
  ASSERT_TRUE(provenance.ok()) << provenance.status().ToString();
  EXPECT_EQ(provenance.ValueOrDie().size(), 2U);
}

TEST(TemporalCoalesceTest, MergesOnlyContiguousIntervalsWithEqualDemandAndProvenance) {
  const LogicalKey key = LogicalKey::VertexProperty(1, 1);
  const auto first = std::make_shared<TemporalEvent>(
      TemporalEvent::Put(key, 0, 1, 1, Value::String("same")));
  const auto second = std::make_shared<TemporalEvent>(
      TemporalEvent::Put(key, 20, 2, 1, Value::String("same")));
  const std::vector<AlignedTemporalInterval> input = {
      {5, 10, {first}}, {10, 20, {first}}, {20, 30, {second}},
  };
  const auto coalesced = CoalesceTemporalIntervals(input);
  ASSERT_TRUE(coalesced.ok()) << coalesced.status().ToString();
  ASSERT_EQ(coalesced.ValueOrDie().size(), 2U);
  EXPECT_EQ(coalesced.ValueOrDie()[0].valid_from, 5U);
  EXPECT_EQ(coalesced.ValueOrDie()[0].valid_to, 20U);
  EXPECT_EQ(coalesced.ValueOrDie()[1].valid_from, 20U);
}

TEST(ResultBatchTest, PreservesTypedBatchAndReportsTerminalStreamStatus) {
  ColumnBatch batch(2);
  ASSERT_TRUE(batch.AddVector(std::make_shared<FlatVector>(
      std::vector<Value>{Value::String("cedar")}, std::vector<bool>{true})).ok());
  ResultBatch result({"name"}, batch);
  ASSERT_TRUE(result.Validate().ok());
  EXPECT_EQ(result.column_names()[0], "name");
  ASSERT_TRUE(result.batch().ValueAt(0, 0).has_value());
  EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::String("cedar"));

  InMemoryResultStream stream({result}, Status::Corruption("query", "late page failure"));
  ResultBatch delivered;
  ASSERT_TRUE(stream.Next(&delivered).ok());
  EXPECT_EQ(delivered.column_names()[0], "name");
  EXPECT_TRUE(stream.Next(&delivered).IsNotFound());
  EXPECT_TRUE(stream.terminal_status().IsCorruption());

  ResultBatch wrong_names({"first", "second"}, batch);
  EXPECT_TRUE(wrong_names.Validate().IsInvalidArgument());
}

