TEST(TemporalScanCursorTest, RawChangeScanOrdersLongVersionChainsAcrossMorsels) {
  constexpr uint64_t kVersionsPerKey = 2050;
  TemporalScanSpec spec;
  spec.snapshot_seq = kVersionsPerKey;
  spec.batch_capacity = 64;
  spec.raw_events = true;
  std::vector<TemporalEvent> events;
  events.reserve(2 * kVersionsPerKey);
  for (uint64_t version = 1; version <= kVersionsPerKey; ++version) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(1), version * 10, version, 1, Value::Binary("")));
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(2), version * 10, version, 1, Value::Binary("")));
  }
  auto opened = OpenTemporalScan(
      events, spec);
  ASSERT_TRUE(opened.ok()) << opened.status().ToString();

  uint64_t expected_valid_from = 10;
  uint64_t emitted = 0;
  ColumnBatch batch;
  while (opened.ValueOrDie().NextMorsel(&batch).ok()) {
    for (uint32_t row = 0; row < batch.row_count(); ++row) {
      const auto valid_from = batch.ValueAt(kValidFrom, row);
      const auto entity_id = batch.ValueAt(kEntityId, row);
      ASSERT_TRUE(valid_from.has_value());
      ASSERT_TRUE(entity_id.has_value());
      EXPECT_EQ(*valid_from, Value::Timestamp(expected_valid_from));
      EXPECT_EQ(*entity_id, Value::Int64(emitted % 2 == 0 ? 1 : 2));
      if (emitted % 2 == 1) expected_valid_from += 10;
      ++emitted;
    }
  }
  EXPECT_EQ(emitted, 2 * kVersionsPerKey);
}

