TEST(TcypherExecutorTest,
     RelationshipValidTimeChangesUsePhysicalRawEdgeScan) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_relationship_change_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 20;
  options.batch_capacity = 2;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 5, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(
           LogicalKey::EdgeExistence(1, 2, 9, 77, EntityType::EdgeOut),
           5, 1, 1, Value::Binary("")),
       TemporalEvent::Put(
           LogicalKey::EdgeProperty(1, 2, 9, 77, 10,
                                    EntityType::EdgeOut),
           5, 2, 1, Value::String("close")),
       TemporalEvent::Delete(
           LogicalKey::EdgeExistence(1, 2, 9, 77, EntityType::EdgeOut),
           15, 3, 1),
       TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 0, 4, 1,
                          Value::String("Ada")),
       TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 10, 5, 1,
                          Value::String("Lin"))}};
  auto stream = ExecuteTcypher(
      "CHANGES FOR VALID_TIME BETWEEN 0 AND 20 "
      "MATCH (a)-[r:KNOWS]->(b) "
      "RETURN r, r.weight, a.name, valid_from(a), operation(b), "
      "operation(r), commit_seq(r);",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 2U);
  EXPECT_EQ(result.column_names(),
            (std::vector<std::string>{"r", "r.weight", "a.name",
                                      "valid_from(a)", "operation(b)",
                                      "operation(r)", "commit_seq(r)"}));
  ASSERT_TRUE(result.batch().IsStructured(0));
  EXPECT_EQ(result.batch().StructAt(0, 0)->fields[3].value,
            Value::Int64(77));
  EXPECT_EQ(*result.batch().ValueAt(1, 0), Value::String("close"));
  ASSERT_TRUE(result.batch().ValueAt(2, 0).has_value());
  ASSERT_TRUE(result.batch().ValueAt(2, 1).has_value());
  EXPECT_EQ(result.batch().ValueAt(2, 0)->type(), PhysicalType::kString);
  EXPECT_EQ(result.batch().ValueAt(2, 1)->type(), PhysicalType::kString);
  EXPECT_EQ(*result.batch().ValueAt(2, 0), Value::String("Ada"));
  EXPECT_EQ(*result.batch().ValueAt(2, 1), Value::String("Lin"));
  EXPECT_EQ(*result.batch().ValueAt(3, 0), Value::Timestamp(5));
  EXPECT_EQ(*result.batch().ValueAt(3, 1), Value::Timestamp(15));
  EXPECT_EQ(*result.batch().ValueAt(4, 0), Value::String("PUT"));
  EXPECT_EQ(*result.batch().ValueAt(4, 1), Value::String("DELETE"));
  EXPECT_EQ(*result.batch().ValueAt(5, 0), Value::String("PUT"));
  EXPECT_EQ(*result.batch().ValueAt(5, 1), Value::String("DELETE"));
  EXPECT_EQ(*result.batch().ValueAt(6, 0), Value::Int64(1));
  EXPECT_EQ(*result.batch().ValueAt(6, 1), Value::Int64(3));
  EXPECT_TRUE(stream.ValueOrDie()->Next(&result).IsNotFound());
  EXPECT_EQ(stats->physical_plan_builds, 1U);
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

