TEST(TcypherExecutorTest,
     FixedSeedRelationshipChangesMatchRawEventOracle) {
  constexpr uint64_t kSeed = 0xCE4A'2026'0722ULL;
  std::mt19937_64 random(kSeed);
  for (uint32_t case_index = 0; case_index < 24; ++case_index) {
    SCOPED_TRACE("seed=" + std::to_string(kSeed) +
                 " case=" + std::to_string(case_index));
    struct ExpectedChange {
      LogicalKey key;
      uint64_t valid_from = 0;
      uint64_t commit_seq = 0;
      TemporalOperation operation = TemporalOperation::kPut;
    };
    std::vector<TemporalEvent> events;
    std::vector<ExpectedChange> expected;
    uint64_t commit_seq = 1;
    for (uint64_t edge = 0; edge < 4; ++edge) {
      const LogicalKey key = LogicalKey::EdgeExistence(
          1 + edge % 2, 10 + edge, 9, 100 + edge,
          EntityType::EdgeOut);
      const uint32_t versions = 1 + static_cast<uint32_t>(random() % 4);
      for (uint32_t version = 0; version < versions; ++version) {
        const uint64_t valid_from = random() % 60;
        const bool put = (random() & 1U) == 0;
        events.push_back(put
            ? TemporalEvent::Put(key, valid_from, commit_seq, 1,
                                 Value::Binary(""))
            : TemporalEvent::Delete(key, valid_from, commit_seq, 1));
        if (valid_from >= 10 && valid_from < 50) {
          expected.push_back(ExpectedChange{
              key, valid_from, commit_seq,
              put ? TemporalOperation::kPut : TemporalOperation::kDelete});
        }
        ++commit_seq;
      }
    }
    std::shuffle(events.begin(), events.end(), random);
    std::sort(expected.begin(), expected.end(),
              [](const ExpectedChange& left, const ExpectedChange& right) {
                if (left.valid_from != right.valid_from) {
                  return left.valid_from < right.valid_from;
                }
                if (left.commit_seq != right.commit_seq) {
                  return left.commit_seq < right.commit_seq;
                }
                return left.key < right.key;
              });

    CommitTimeline timeline(
        "/tmp/cedar_unused_relationship_change_oracle_" +
        std::to_string(case_index));
    auto stats = std::make_shared<TcypherExecutionStats>();
    TcypherQueryOptions options;
    options.statement_start_valid_time = 50;
    options.batch_capacity = 3;
    options.execution_stats = stats;
    auto stream = ExecuteTcypher(
        "CHANGES FOR VALID_TIME BETWEEN 10 AND 50 "
        "MATCH (a)-[r:KNOWS]->(b) "
        "RETURN r, valid_from(r), commit_seq(r), operation(r);",
        TcypherExecutionContext{
            timeline, commit_seq - 1, options,
            MakeTcypherBinderSchemaSnapshot(), std::move(events)});
    ASSERT_TRUE(stream.ok()) << stream.status().ToString();

    std::vector<ExpectedChange> actual;
    for (;;) {
      ResultBatch result;
      const Status next = stream.ValueOrDie()->Next(&result);
      if (next.IsNotFound()) break;
      ASSERT_TRUE(next.ok()) << next.ToString();
      for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
        const auto relationship = result.batch().StructAt(0, row);
        ASSERT_TRUE(relationship.has_value());
        ASSERT_EQ(relationship->fields.size(), 6U);
        const uint64_t source = static_cast<uint64_t>(
            std::get<int64_t>(relationship->fields[0].value->data()));
        const uint64_t target = static_cast<uint64_t>(
            std::get<int64_t>(relationship->fields[1].value->data()));
        const uint16_t edge_type = static_cast<uint16_t>(
            std::get<int32_t>(relationship->fields[2].value->data()));
        const uint64_t edge_id = static_cast<uint64_t>(
            std::get<int64_t>(relationship->fields[3].value->data()));
        actual.push_back(ExpectedChange{
            LogicalKey::EdgeExistence(source, target, edge_type, edge_id,
                                      EntityType::EdgeOut),
            std::get<uint64_t>(result.batch().ValueAt(1, row)->data()),
            static_cast<uint64_t>(
                std::get<int64_t>(result.batch().ValueAt(2, row)->data())),
            std::get<std::string>(result.batch().ValueAt(3, row)->data()) ==
                    "PUT"
                ? TemporalOperation::kPut
                : TemporalOperation::kDelete});
      }
    }
    ASSERT_EQ(actual.size(), expected.size());
    for (size_t index = 0; index < expected.size(); ++index) {
      EXPECT_EQ(actual[index].key, expected[index].key);
      EXPECT_EQ(actual[index].valid_from, expected[index].valid_from);
      EXPECT_EQ(actual[index].commit_seq, expected[index].commit_seq);
      EXPECT_EQ(actual[index].operation, expected[index].operation);
    }
    EXPECT_EQ(stats->physical_plan_builds, 1U);
    EXPECT_EQ(stats->pipeline_builds, 1U);
    EXPECT_EQ(stats->base_history_materialized_events, 0U);
  }
}

