TEST(TcypherExecutorTest, PhysicalFixedPointExpandResumesTwoHopWorkAcrossMorsels) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_two_hop_morsels_timeline");
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 1;
  options.execution_stats = stats;
  TcypherExecutionContext context{
      timeline, 10, options, MakeTcypherBinderSchemaSnapshot(),
      {TemporalEvent::Put(LogicalKey::VertexExistence(1), 5, 1, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(2), 5, 2, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(3), 5, 3, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(4), 5, 4, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(5), 5, 5, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::VertexExistence(6), 5, 6, 1,
                          Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(1, 2, 9, 77, EntityType::EdgeOut),
                          7, 7, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(3, 4, 9, 78, EntityType::EdgeOut),
                          7, 8, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(2, 5, 9, 79, EntityType::EdgeOut),
                          7, 9, 1, Value::Binary("")),
       TemporalEvent::Put(LogicalKey::EdgeExistence(4, 6, 9, 80, EntityType::EdgeOut),
                          7, 10, 1, Value::Binary(""))}};
  auto stream = ExecuteTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a)-[r1:KNOWS]->(b)-[r2:KNOWS]->(c) "
      "RETURN a, c;",
      std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  std::vector<int64_t> sources;
  std::vector<int64_t> targets;
  for (;;) {
    ResultBatch result;
    const Status next = stream.ValueOrDie()->Next(&result);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
    ASSERT_EQ(result.batch().row_count(), 1U);
    sources.push_back(std::get<int64_t>(result.batch().ValueAt(0, 0)->data()));
    targets.push_back(std::get<int64_t>(result.batch().ValueAt(1, 0)->data()));
  }
  EXPECT_EQ(sources, (std::vector<int64_t>{1, 3}));
  EXPECT_EQ(targets, (std::vector<int64_t>{5, 6}));
  EXPECT_EQ(stats->pipeline_builds, 1U);
  EXPECT_EQ(stats->base_history_materialized_events, 0U);
}

