TEST(TemporalScanCursorTest, ChargesLastPhysicalEventAcrossMorselBoundaries) {
  constexpr size_t kPayloadBytes = 4096;
  auto memtable = std::make_shared<TemporalMemTable>();
  ASSERT_TRUE(memtable->Insert(TemporalEvent::Put(
      LogicalKey::VertexProperty(1, 7), 10, 1, 1,
      Value::String(std::string(kPayloadBytes, 'a')))).ok());
  ASSERT_TRUE(memtable->Insert(TemporalEvent::Put(
      LogicalKey::VertexProperty(2, 7), 10, 1, 1,
      Value::String(std::string(kPayloadBytes, 'b')))).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(64U << 10, 128U << 10);
  PinnedTemporalScanSources sources;
  sources.memtables.push_back(memtable);
  TemporalScanSpec spec{10, 1, 1};
  spec.memory_account = memory;
  auto opened = OpenPinnedTemporalScan(std::move(sources), spec);
  ASSERT_TRUE(opened.ok()) << opened.status().ToString();
  {
    TemporalScanCursor cursor = std::move(opened).ConsumeValueOrDie();
    const uint64_t cursor_baseline = memory->used_bytes();
    const uint64_t retained_charge = sizeof(TemporalEvent) + kPayloadBytes;
    {
      ColumnBatch batch;
      ASSERT_TRUE(cursor.NextMorsel(&batch).ok());
    }
    EXPECT_EQ(memory->used_bytes(), cursor_baseline + retained_charge);
    {
      ColumnBatch batch;
      ASSERT_TRUE(cursor.NextMorsel(&batch).ok());
    }
    EXPECT_EQ(memory->used_bytes(), cursor_baseline + retained_charge);
    ColumnBatch exhausted;
    EXPECT_TRUE(cursor.NextMorsel(&exhausted).IsNotFound());
    EXPECT_EQ(memory->used_bytes(), cursor_baseline);
  }
  EXPECT_EQ(memory->used_bytes(), 0U);
}

