TEST(PropertyGatherTest, ResolvesDemandedPropertiesForSurvivingEntityRows) {
  const std::vector<TemporalEvent> existence_candidates = {
      TemporalEvent::Put(LogicalKey::VertexExistence(1), 1, 1, 1, Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexExistence(2), 1, 1, 1, Value::Binary("")),
  };
  auto scan = OpenTemporalScan(existence_candidates, TemporalScanSpec{10, 3, 2});
  ASSERT_TRUE(scan.ok()) << scan.status().ToString();
  ColumnBatch entities;
  ASSERT_TRUE(scan.ValueOrDie().NextMorsel(&entities).ok());
  ASSERT_TRUE(entities.SetSelection({1, 0}).ok());

  const std::vector<TemporalEvent> property_candidates = {
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 1, 1, 1,
                         Value::String("Ada")),
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 8, 4, 1,
                         Value::String("Grace")),
  };
  ColumnBatch gathered;
  ASSERT_TRUE(BatchGatherProperties(entities, property_candidates,
                                    PropertyGatherSpec{{7}, 10, 3},
                                    &gathered).ok());
  ASSERT_EQ(gathered.column_count(), 11U);
  ASSERT_EQ(gathered.row_count(), 2U);
  EXPECT_FALSE(gathered.ValueAt(10, 0).has_value());
  ASSERT_TRUE(gathered.ValueAt(10, 1).has_value());
  EXPECT_EQ(*gathered.ValueAt(10, 1), Value::String("Ada"));
}

