TEST(PropertyGatherTest, ResumablePinnedGatherHonorsLookupQuantum) {
  std::vector<TemporalEvent> existence;
  auto properties = std::make_shared<TemporalMemTable>();
  for (uint64_t id = 1; id <= 8; ++id) {
    existence.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(id), 10, id, 1, Value::Binary("")));
    ASSERT_TRUE(properties->Insert(TemporalEvent::Put(
        LogicalKey::VertexProperty(id, 7), 10, id, 1,
        Value::String("name-" + std::to_string(id)))).ok());
    ASSERT_TRUE(properties->Insert(TemporalEvent::Put(
        LogicalKey::VertexProperty(id, 8), 10, id, 1,
        Value::Int64(static_cast<int64_t>(id)))).ok());
  }
  auto scan = OpenTemporalScan(existence, TemporalScanSpec{10, 8, 8});
  ASSERT_TRUE(scan.ok()) << scan.status().ToString();
  ColumnBatch entities;
  ASSERT_TRUE(scan.ValueOrDie().NextMorsel(&entities).ok());
  PinnedTemporalScanSources sources;
  sources.memtables.push_back(properties);
  auto gather = OpenPinnedPropertyGather(
      std::move(entities), std::move(sources), TemporalScanSpec{10, 8, 1},
      PropertyGatherSpec{{7, 8}, 10, 8, {1, 1}});
  ASSERT_TRUE(gather.ok()) << gather.status().ToString();
  uint32_t lookups = 0;
  ASSERT_TRUE(gather.ValueOrDie().Advance(3, &lookups).ok());
  EXPECT_EQ(lookups, 3U);
  EXPECT_FALSE(gather.ValueOrDie().done());
  while (!gather.ValueOrDie().done()) {
    ASSERT_TRUE(gather.ValueOrDie().Advance(3, &lookups).ok());
    EXPECT_LE(lookups, 3U);
  }
  ColumnBatch gathered;
  ASSERT_TRUE(gather.ValueOrDie().Finish(&gathered).ok());
  ASSERT_EQ(gathered.row_count(), 8U);
  EXPECT_EQ(*gathered.ValueAt(kValue + 1, 0), Value::String("name-1"));
  EXPECT_EQ(*gathered.ValueAt(kValue + 2, 7), Value::Int64(8));
}

TEST(PropertyGatherTest, ResumablePinnedGatherFinishesAnEmptyInput) {
  ColumnBatch entities(0);
  for (uint32_t column = 0; column <= kValue; ++column) {
    ASSERT_TRUE(entities.AddVector(std::make_shared<FlatVector>(
        std::vector<Value>{}, std::vector<bool>{})).ok());
  }
  auto gather = OpenPinnedPropertyGather(
      std::move(entities), PinnedTemporalScanSources{},
      TemporalScanSpec{10, 1, 1},
      PropertyGatherSpec{{7}, 10, 1, {1}});
  ASSERT_TRUE(gather.ok()) << gather.status().ToString();
  EXPECT_TRUE(gather.ValueOrDie().done());
  ColumnBatch gathered;
  ASSERT_TRUE(gather.ValueOrDie().Finish(&gathered).ok());
  EXPECT_EQ(gathered.row_count(), 0U);
  EXPECT_EQ(gathered.column_count(), kValue + 2);
}

TEST(TcypherExecutorTest, FinalProjectReservesRepeatedBinaryPayloadBeforeCopy) {
  constexpr size_t kPayloadBytes = 32U << 10;
  CommitTimeline timeline("/tmp/cedar_unused_project_payload_timeline");
  auto schemas = std::make_shared<SchemaSnapshot>();
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 7}].push_back(
      ColumnSchema{EntityType::Vertex, 7, 1, "payload", PhysicalType::kBinary,
                   4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4});
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexExistence(1), 10, 1, 1,
                         Value::Binary("")),
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 10, 2, 1,
                         Value::Binary(std::string(kPayloadBytes, 'x'))),
  };
  auto memory = std::make_shared<QueryMemoryAccount>(128U << 10, 144U << 10);
  auto stats = std::make_shared<TcypherExecutionStats>();
  {
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.batch_capacity = 1;
    options.memory_account = memory;
    options.execution_stats = stats;
    auto stream = ExecuteTcypher(
        "MATCH (n) RETURN n.payload, n.payload, n.payload, n.payload;",
        TcypherExecutionContext{timeline, 2, options, schemas, events});
    ASSERT_TRUE(stream.ok()) << stream.status().ToString();
    ResultBatch result;
    const Status projected = stream.ValueOrDie()->Next(&result);
    EXPECT_TRUE(projected.IsQueryMemoryLimit()) << projected.ToString();
    EXPECT_EQ(stats->projection_gather_payload_bytes_copied, kPayloadBytes)
        << "used=" << memory->used_bytes()
        << " property_scans=" << stats->pinned_property_point_scans
        << " status=" << projected.ToString();
    EXPECT_EQ(stats->physical_project_payload_bytes_copied, 0U);
  }
  EXPECT_EQ(memory->used_bytes(), 0U);
}

