TEST(TcypherBinderTest, ResolvesTemporalParametersThroughVisibleTimelinePrefix) {
  const auto parsed = ParseTcypher(
      "FOR SYSTEM_TIME AS OF $cutoff MATCH (n:Person) RETURN n.name;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  CommitTimeline timeline("/tmp/cedar_unused_timeline");
  ASSERT_TRUE(timeline.AddDurableCommit(1, SystemHlc{100, 0}).ok());
  ASSERT_TRUE(timeline.AddDurableCommit(2, SystemHlc{100, 1}).ok());
  const auto schemas = MakeTcypherBinderSchemaSnapshot();
  TcypherBindingContext context{timeline, 1, 55, {{"cutoff", 100}}, schemas};
  const auto bound = BindTcypher(parsed.ValueOrDie(), context);
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  ASSERT_EQ(bound.ValueOrDie().temporal_scopes.size(), 1U);
  EXPECT_EQ(bound.ValueOrDie().temporal_scopes[0].snapshot_seq, 1U);
  EXPECT_EQ(bound.ValueOrDie().temporal_scopes[0].valid_time_start, 55U);

  const auto valid = ParseTcypher(
      "FOR VALID_TIME AS OF $at MATCH (n:Person) RETURN n.name;");
  ASSERT_TRUE(valid.ok());
  const auto valid_bound = BindTcypher(
      valid.ValueOrDie(), TcypherBindingContext{timeline, 2, 55, {{"at", 42}}, schemas});
  ASSERT_TRUE(valid_bound.ok()) << valid_bound.status().ToString();
  EXPECT_EQ(valid_bound.ValueOrDie().temporal_scopes[0].valid_time_start, 42U);
  EXPECT_EQ(valid_bound.ValueOrDie().temporal_scopes[0].snapshot_seq, 2U);
  EXPECT_TRUE(BindTcypher(valid.ValueOrDie(),
      TcypherBindingContext{timeline, 2, 55, {}, schemas}).status().IsBindError());
}

