TEST(TcypherBinderTest, ExposesResolvedPropertyMetadataAndUseSites) {
  CommitTimeline timeline("/tmp/cedar_unused_bound_property_timeline");
  auto schemas = std::make_shared<SchemaSnapshot>();
  const ColumnSchema person{EntityType::Vertex, 0, 2, "Person", PhysicalType::kBinary,
                            4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  const ColumnSchema name{EntityType::Vertex, 7, 3, "name", PhysicalType::kString,
                          4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 0}] = {person};
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 7}] = {name};
  const auto parsed = ParseTcypher(
      "MATCH (n:Person) WHERE n.name = 'Li' RETURN n.name;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();

  const auto bound = BindTcypher(
      parsed.ValueOrDie(), TcypherBindingContext{timeline, 3, 99, {}, schemas});

  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  ASSERT_EQ(bound.ValueOrDie().variables.size(), 1U);
  EXPECT_EQ(bound.ValueOrDie().variables[0].variable, "n");
  EXPECT_EQ(bound.ValueOrDie().variables[0].kind, BoundGraphKind::kNode);
  EXPECT_TRUE(bound.ValueOrDie().variables[0].non_nullable);
  ASSERT_TRUE(bound.ValueOrDie().variables[0].entity_schema.has_value());
  EXPECT_EQ(bound.ValueOrDie().variables[0].entity_schema->schema_epoch, 2U);
  ASSERT_EQ(bound.ValueOrDie().properties.size(), 1U);
  const BoundPropertyReference& property = bound.ValueOrDie().properties[0];
  EXPECT_EQ(property.variable, "n");
  EXPECT_EQ(property.column.column_id, 7U);
  EXPECT_EQ(property.column.schema_epoch, 3U);
  EXPECT_EQ(property.column.physical_type, PhysicalType::kString);
  EXPECT_TRUE(property.nullable);
  EXPECT_TRUE(property.predicate);
  EXPECT_TRUE(property.projection);
  EXPECT_FALSE(property.grouping);
  EXPECT_FALSE(property.ordering);
  EXPECT_FALSE(property.join);
}

TEST(TcypherLogicalPlanTest, DemandsCompleteRelationshipBindingsAndEndpointExistence) {
  CommitTimeline timeline("/tmp/cedar_unused_complete_entity_timeline");
  auto schemas = std::make_shared<SchemaSnapshot>();
  const ColumnSchema knows{EntityType::EdgeOut, 9, 4, "KNOWS", PhysicalType::kBinary,
                           4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  schemas->schemas[{static_cast<uint8_t>(EntityType::EdgeOut), 9}] = {knows};
  const auto parsed = ParseTcypher(
      "MATCH (a)-[r:KNOWS]->(b) RETURN a, r, b;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(), TcypherBindingContext{timeline, 3, 99, {}, schemas});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto plan = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();

  ASSERT_EQ(plan.ValueOrDie().demand.variables.size(), 3U);
  EXPECT_EQ(plan.ValueOrDie().demand.variables[0].variable, "a");
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[0].existence);
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[0].complete_entity);
  EXPECT_EQ(plan.ValueOrDie().demand.variables[0].entity_type, EntityType::Vertex);
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[0].non_nullable);
  EXPECT_FALSE(plan.ValueOrDie().demand.variables[0].entity_schema.has_value());
  EXPECT_EQ(plan.ValueOrDie().demand.variables[1].variable, "b");
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[1].existence);
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[1].complete_entity);
  EXPECT_EQ(plan.ValueOrDie().demand.variables[1].entity_type, EntityType::Vertex);
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[1].non_nullable);
  EXPECT_EQ(plan.ValueOrDie().demand.variables[2].variable, "r");
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[2].existence);
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[2].complete_entity);
  EXPECT_EQ(plan.ValueOrDie().demand.variables[2].entity_type, EntityType::EdgeOut);
  EXPECT_TRUE(plan.ValueOrDie().demand.variables[2].non_nullable);
  ASSERT_TRUE(plan.ValueOrDie().demand.variables[2].entity_schema.has_value());
  EXPECT_EQ(plan.ValueOrDie().demand.variables[2].entity_schema->column_id, 9U);
  EXPECT_EQ(plan.ValueOrDie().demand.variables[2].entity_schema->schema_epoch, 4U);
  EXPECT_EQ(plan.ValueOrDie().demand.variables[2].entity_schema->physical_type,
            PhysicalType::kBinary);
}

