TEST(TcypherLogicalPlanTest, ThreeRootEqualitiesBecomeTypedConnectedJoinGraph) {
  CommitTimeline timeline("/tmp/cedar_unused_three_root_join_graph_timeline");
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name "
      "RETURN a, b, c;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();

  const auto plan = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  ASSERT_EQ(plan.ValueOrDie().join_edges.size(), 2U);
  EXPECT_EQ(plan.ValueOrDie().nodes[0].kind, LogicalOperatorKind::kTemporalScan);
  EXPECT_EQ(plan.ValueOrDie().nodes[1].kind, LogicalOperatorKind::kTemporalScan);
  EXPECT_EQ(plan.ValueOrDie().nodes[2].kind, LogicalOperatorKind::kTemporalScan);
  EXPECT_EQ(plan.ValueOrDie().nodes[3].kind, LogicalOperatorKind::kJoin);
  EXPECT_EQ(plan.ValueOrDie().nodes[4].kind, LogicalOperatorKind::kJoin);
  EXPECT_EQ(std::count_if(plan.ValueOrDie().nodes.begin(), plan.ValueOrDie().nodes.end(),
                          [](const LogicalPlanNode& node) {
                            return node.kind == LogicalOperatorKind::kJoin;
                          }),
            2);

  const auto& first = plan.ValueOrDie().join_edges[0];
  EXPECT_EQ(first.left.binding_id, BindingId{1});
  EXPECT_EQ(first.right.binding_id, BindingId{2});
  EXPECT_EQ(first.left.type, PhysicalType::kString);
  EXPECT_EQ(first.right.type, PhysicalType::kString);
  EXPECT_TRUE(first.left.nullable);
  EXPECT_TRUE(first.right.nullable);
  ASSERT_TRUE(first.left.property_id.has_value());
  ASSERT_TRUE(first.right.property_id.has_value());

  const auto& second = plan.ValueOrDie().join_edges[1];
  EXPECT_EQ(second.left.binding_id, BindingId{2});
  EXPECT_EQ(second.right.binding_id, BindingId{3});
  EXPECT_EQ(second.left.type, PhysicalType::kString);
  EXPECT_EQ(second.right.type, PhysicalType::kString);
  EXPECT_TRUE(second.left.nullable);
  EXPECT_TRUE(second.right.nullable);
  ASSERT_TRUE(second.left.property_id.has_value());
  ASSERT_TRUE(second.right.property_id.has_value());
}

TEST(TcypherLogicalPlanTest,
     ReversedDuplicateEqualitiesCanonicalizeAndSelfEqualityStaysFilter) {
  CommitTimeline timeline("/tmp/cedar_unused_canonical_join_graph_timeline");
  auto schemas = std::make_shared<SchemaSnapshot>();
  const ColumnSchema name{EntityType::Vertex, 7, 1, "name", PhysicalType::kString,
                          4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  const ColumnSchema alias{EntityType::Vertex, 8, 1, "alias", PhysicalType::kString,
                           4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 7}] = {name};
  schemas->schemas[{static_cast<uint8_t>(EntityType::Vertex), 8}] = {alias};

  const auto duplicates = ParseTcypher(
      "MATCH (a) MATCH (b) WHERE a.name = b.name AND b.name = a.name RETURN a, b;");
  ASSERT_TRUE(duplicates.ok()) << duplicates.status().ToString();
  const auto duplicate_bound = BindTcypher(
      duplicates.ValueOrDie(), TcypherBindingContext{timeline, 3, 99, {}, schemas});
  ASSERT_TRUE(duplicate_bound.ok()) << duplicate_bound.status().ToString();
  const auto duplicate_plan = LowerTcypher(duplicate_bound.ValueOrDie());
  ASSERT_TRUE(duplicate_plan.ok()) << duplicate_plan.status().ToString();
  EXPECT_EQ(duplicate_plan.ValueOrDie().join_edges.size(), 1U);
  EXPECT_EQ(std::count_if(duplicate_plan.ValueOrDie().nodes.begin(),
                          duplicate_plan.ValueOrDie().nodes.end(),
                          [](const LogicalPlanNode& node) {
                            return node.kind == LogicalOperatorKind::kJoin;
                          }),
            1);

  const auto self = ParseTcypher("MATCH (a) WHERE a.name = a.alias RETURN a;");
  ASSERT_TRUE(self.ok()) << self.status().ToString();
  const auto self_bound = BindTcypher(
      self.ValueOrDie(), TcypherBindingContext{timeline, 3, 99, {}, schemas});
  ASSERT_TRUE(self_bound.ok()) << self_bound.status().ToString();
  const auto self_plan = LowerTcypher(self_bound.ValueOrDie());
  ASSERT_TRUE(self_plan.ok()) << self_plan.status().ToString();
  EXPECT_TRUE(self_plan.ValueOrDie().join_edges.empty());
  EXPECT_EQ(std::count_if(self_plan.ValueOrDie().nodes.begin(),
                          self_plan.ValueOrDie().nodes.end(),
                          [](const LogicalPlanNode& node) {
                            return node.kind == LogicalOperatorKind::kJoin;
                          }),
            0);
  EXPECT_EQ(std::count_if(self_plan.ValueOrDie().nodes.begin(),
                          self_plan.ValueOrDie().nodes.end(),
                          [](const LogicalPlanNode& node) {
                            return node.kind == LogicalOperatorKind::kFilter;
                          }),
            1);
}

