  EXPECT_EQ(range_plan.ValueOrDie().nodes[1].kind, LogicalOperatorKind::kIntervalDerive);
  EXPECT_EQ(range_plan.ValueOrDie().nodes[2].kind, LogicalOperatorKind::kIntervalAlign);
  EXPECT_EQ(range_plan.ValueOrDie().nodes[3].kind, LogicalOperatorKind::kTemporalCoalesce);

