TEST(TcypherPhysicalPlanTest,
     MixedSegmentsCarryIndependentBoundsAndPathSlots) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_mixed_expand_plan_timeline");
  const auto build = [&](const std::string& query) {
    const auto parsed = ParseTcypher(query);
    EXPECT_TRUE(parsed.ok()) << parsed.status().ToString();
    const auto bound = BindTcypher(
        parsed.ValueOrDie(),
        TcypherBindingContext{timeline, 3, 99, {},
                              MakeTcypherBinderSchemaSnapshot()});
    EXPECT_TRUE(bound.ok()) << bound.status().ToString();
    if (!bound.ok()) {
      return StatusOr<std::shared_ptr<const PhysicalPlan>>(bound.status());
    }
    EXPECT_TRUE(CanPlanPhysicalRootPoint(bound.ValueOrDie()));
    const auto logical = LowerTcypher(bound.ValueOrDie());
    EXPECT_TRUE(logical.ok()) << logical.status().ToString();
    if (!logical.ok()) {
      return StatusOr<std::shared_ptr<const PhysicalPlan>>(logical.status());
    }
    return PlanPhysicalRootPoint(bound.ValueOrDie(), logical.ValueOrDie());
  };

  const auto variable_then_fixed = build(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a)-[p:KNOWS*2..2]->(b)-[r:KNOWS]->(c) "
      "RETURN a, p, b, r, c;");
  ASSERT_TRUE(variable_then_fixed.ok())
      << variable_then_fixed.status().ToString();
  ASSERT_EQ(variable_then_fixed.ValueOrDie()->expand_steps().size(), 2U);
  EXPECT_EQ(variable_then_fixed.ValueOrDie()->expand_steps()[0].min_hops, 2U);
  EXPECT_EQ(variable_then_fixed.ValueOrDie()->expand_steps()[0].max_hops, 2U);
  EXPECT_NE(variable_then_fixed.ValueOrDie()->expand_steps()[0].path_slot.value,
            0U);
  EXPECT_EQ(variable_then_fixed.ValueOrDie()->expand_steps()[1].min_hops, 1U);
  EXPECT_EQ(variable_then_fixed.ValueOrDie()->expand_steps()[1].max_hops, 1U);
  EXPECT_EQ(variable_then_fixed.ValueOrDie()->expand_steps()[1].path_slot.value,
            0U);
  EXPECT_TRUE(ValidatePhysicalPlan(*variable_then_fixed.ValueOrDie()).ok());

  const auto fixed_then_variable = build(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a)-[r:KNOWS]->(b)-[p:KNOWS*2..2]->(c) "
      "RETURN a, r, b, p, c;");
  ASSERT_TRUE(fixed_then_variable.ok())
      << fixed_then_variable.status().ToString();
  ASSERT_EQ(fixed_then_variable.ValueOrDie()->expand_steps().size(), 2U);
  EXPECT_EQ(fixed_then_variable.ValueOrDie()->expand_steps()[0].min_hops, 1U);
  EXPECT_EQ(fixed_then_variable.ValueOrDie()->expand_steps()[0].max_hops, 1U);
  EXPECT_EQ(fixed_then_variable.ValueOrDie()->expand_steps()[0].path_slot.value,
            0U);
  EXPECT_EQ(fixed_then_variable.ValueOrDie()->expand_steps()[1].min_hops, 2U);
  EXPECT_EQ(fixed_then_variable.ValueOrDie()->expand_steps()[1].max_hops, 2U);
  EXPECT_NE(fixed_then_variable.ValueOrDie()->expand_steps()[1].path_slot.value,
            0U);
  EXPECT_TRUE(ValidatePhysicalPlan(*fixed_then_variable.ValueOrDie()).ok());

  const auto changed_bound = build(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a)-[p:KNOWS*1..2]->(b)-[r:KNOWS]->(c) "
      "RETURN a, p, b, r, c;");
  ASSERT_TRUE(changed_bound.ok()) << changed_bound.status().ToString();
  EXPECT_NE(variable_then_fixed.ValueOrDie()->plan_id(),
            changed_bound.ValueOrDie()->plan_id());
}

