TEST(TcypherPhysicalPlanTest, HashJoinPlanPinsStatisticsDrivenBuildSideAndEstimates) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_hash_join_stats_plan_timeline");
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) "
      "WHERE a.name = b.name RETURN a, b;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  PhysicalHashJoinPlanningStats planning_stats;
  planning_stats.statistics_snapshot_id = 77;
  planning_stats.left = PhysicalCardinalityEstimate{4, 900, false};
  planning_stats.right = PhysicalCardinalityEstimate{40, 700, false};

  const auto plan = PlanPhysicalHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, planning_stats);
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  EXPECT_EQ(plan.ValueOrDie()->build_side, PhysicalHashJoinBuildSide::kLeft);
  EXPECT_EQ(plan.ValueOrDie()->left_estimate.rows, 4U);
  EXPECT_EQ(plan.ValueOrDie()->left_estimate.confidence_per_mille, 900U);
  EXPECT_FALSE(plan.ValueOrDie()->left_estimate.conservative);
  EXPECT_EQ(plan.ValueOrDie()->right_estimate.rows, 40U);
  EXPECT_EQ(plan.ValueOrDie()->right_estimate.confidence_per_mille, 700U);
  EXPECT_EQ(plan.ValueOrDie()->statistics_snapshot_id, 77U);
  const std::string explain = FormatPhysicalHashJoinPlan(*plan.ValueOrDie());
  EXPECT_NE(explain.find("build=left"), std::string::npos) << explain;
  EXPECT_NE(explain.find("left_rows=4"), std::string::npos) << explain;
  EXPECT_NE(explain.find("right_rows=40"), std::string::npos) << explain;
  EXPECT_NE(explain.find("left_confidence=900"), std::string::npos) << explain;
  EXPECT_NE(explain.find("right_confidence=700"), std::string::npos) << explain;
  EXPECT_NE(explain.find("statistics=77"), std::string::npos) << explain;
}

TEST(TcypherPhysicalPlanTest, HashJoinPlanUsesDeterministicConservativeFallback) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_hash_join_fallback_timeline");
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) "
      "WHERE a.name = b.name RETURN a, b;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();

  const auto first = PlanPhysicalHashJoin(bound.ValueOrDie(), logical.ValueOrDie());
  const auto second = PlanPhysicalHashJoin(bound.ValueOrDie(), logical.ValueOrDie());
  ASSERT_TRUE(first.ok()) << first.status().ToString();
  ASSERT_TRUE(second.ok()) << second.status().ToString();
  EXPECT_EQ(first.ValueOrDie()->plan_id, second.ValueOrDie()->plan_id);
  EXPECT_EQ(first.ValueOrDie()->build_side, PhysicalHashJoinBuildSide::kRight);
  EXPECT_TRUE(first.ValueOrDie()->left_estimate.conservative);
  EXPECT_TRUE(first.ValueOrDie()->right_estimate.conservative);
  EXPECT_TRUE(ValidatePhysicalHashJoinPlan(*first.ValueOrDie()).ok());
  PhysicalHashJoinPlan invalid_build_side = *first.ValueOrDie();
  invalid_build_side.build_side = static_cast<PhysicalHashJoinBuildSide>(255);
  EXPECT_TRUE(ValidatePhysicalHashJoinPlan(invalid_build_side).IsInvalidArgument());
  const std::string explain = FormatPhysicalHashJoinPlan(*first.ValueOrDie());
  EXPECT_NE(explain.find("left_conservative=1"), std::string::npos) << explain;
  EXPECT_NE(explain.find("right_conservative=1"), std::string::npos) << explain;
}

TEST(TcypherPhysicalPlanTest, ThreeRootConnectedMatchBuildsTypedMultiJoinPlan) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_multi_join_plan_timeline");
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name "
      "RETURN a, b, c;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();

  const std::map<BindingId, PhysicalCardinalityEstimate> estimates{
      {BindingId{1}, PhysicalCardinalityEstimate{100, 900, false}},
      {BindingId{2}, PhysicalCardinalityEstimate{4, 800, false}},
      {BindingId{3}, PhysicalCardinalityEstimate{20, 700, false}}};
  const auto plan = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, estimates, 77);
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  ASSERT_TRUE(CanPlanPhysicalMultiHashJoin(bound.ValueOrDie()));
  ASSERT_NE(plan.ValueOrDie()->plan_id, 0U);
  EXPECT_EQ(plan.ValueOrDie()->statistics_snapshot_id, 77U);
  ASSERT_EQ(plan.ValueOrDie()->inputs.size(), 3U);
  ASSERT_EQ(plan.ValueOrDie()->input_layouts.size(), 3U);
  ASSERT_EQ(plan.ValueOrDie()->steps.size(), 2U);
  ASSERT_EQ(plan.ValueOrDie()->join_order.size(), 3U);
  EXPECT_EQ(plan.ValueOrDie()->output_names,
            (std::vector<std::string>{"a", "b", "c"}));
  ASSERT_EQ(plan.ValueOrDie()->final_output_columns.size(), 3U);
  for (size_t input_index = 0;
       input_index < plan.ValueOrDie()->inputs.size(); ++input_index) {
    const auto& input = plan.ValueOrDie()->inputs[input_index];
    ASSERT_TRUE(input);
    EXPECT_EQ(input->projections().size(), 2U);
    EXPECT_EQ(input->projections().size(),
              plan.ValueOrDie()->input_layouts[input_index].size());
    EXPECT_EQ(input->projections()[1].type, PhysicalType::kString);
    EXPECT_EQ(plan.ValueOrDie()->input_layouts[input_index][0].kind,
              ReturnExpressionKind::kBinding);
    EXPECT_EQ(plan.ValueOrDie()->input_layouts[input_index][1].kind,
              ReturnExpressionKind::kProperty);
    EXPECT_FALSE(input->aggregate_sink().has_value());
    EXPECT_FALSE(input->sort_sink().has_value());
    EXPECT_TRUE(input->post_result_operators().empty());
  }
  EXPECT_EQ(plan.ValueOrDie()->steps[0].join.kind,
            PhysicalOperatorKind::kHashJoin);
  EXPECT_EQ(plan.ValueOrDie()->steps[1].join.kind,
            PhysicalOperatorKind::kHashJoin);
  EXPECT_NE(plan.ValueOrDie()->steps[0].join.id,
            plan.ValueOrDie()->steps[1].join.id);
  const auto& final_layout = plan.ValueOrDie()->steps.back().output_layout;
  ASSERT_EQ(final_layout.size(), 3U);
  for (size_t index = 0; index < plan.ValueOrDie()->output_names.size(); ++index) {
    ASSERT_LT(plan.ValueOrDie()->final_output_columns[index], final_layout.size());
    EXPECT_EQ(final_layout[plan.ValueOrDie()->final_output_columns[index]].name,
              plan.ValueOrDie()->output_names[index]);
  }
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(*plan.ValueOrDie()).ok());

  const auto changed_statistics = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, estimates, 78);
  ASSERT_TRUE(changed_statistics.ok())
      << changed_statistics.status().ToString();
  EXPECT_NE(plan.ValueOrDie()->plan_id, changed_statistics.ValueOrDie()->plan_id);
  const std::string explain = FormatPhysicalMultiHashJoinPlan(*plan.ValueOrDie());
  EXPECT_NE(explain.find("statistics=77"), std::string::npos) << explain;
  EXPECT_NE(explain.find("order=2,3,1"), std::string::npos) << explain;
  EXPECT_NE(explain.find("step0"), std::string::npos) << explain;
  EXPECT_NE(explain.find("accumulated_rows=4"), std::string::npos) << explain;

  const auto duplicate = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = a.name AND b.name = c.name "
      "RETURN a, b, c;");
  ASSERT_TRUE(duplicate.ok()) << duplicate.status().ToString();
  const auto duplicate_bound = BindTcypher(
      duplicate.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(duplicate_bound.ok()) << duplicate_bound.status().ToString();
  const auto duplicate_logical = LowerTcypher(duplicate_bound.ValueOrDie());
  ASSERT_TRUE(duplicate_logical.ok()) << duplicate_logical.status().ToString();
  ASSERT_EQ(duplicate_bound.ValueOrDie().joins.size(), 3U);
  ASSERT_EQ(duplicate_logical.ValueOrDie().join_edges.size(), 2U);
  const auto duplicate_plan = PlanPhysicalMultiHashJoin(
      duplicate_bound.ValueOrDie(), duplicate_logical.ValueOrDie(), nullptr,
      estimates, 77);
  ASSERT_TRUE(duplicate_plan.ok()) << duplicate_plan.status().ToString();
  ASSERT_EQ(duplicate_plan.ValueOrDie()->steps.size(), 2U);
  EXPECT_EQ(duplicate_plan.ValueOrDie()->steps[0].accumulated_key_columns.size(),
            1U);
  EXPECT_EQ(duplicate_plan.ValueOrDie()->steps[1].accumulated_key_columns.size(),
            1U);
}

TEST(TcypherPhysicalPlanTest,
     ThreeRootLocalPredicateBuildsPropertyGatherAndFilterInOwningInput) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_multi_join_local_filter_timeline");
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name AND a.city = 'terminal' "
      "RETURN a, b, c;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {},
                            MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  ASSERT_EQ(bound.ValueOrDie().predicates.size(), 1U);
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  ASSERT_TRUE(CanPlanPhysicalMultiHashJoin(bound.ValueOrDie()));

  const auto plan = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, {}, 81);
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  const BindingId owner = bound.ValueOrDie().predicates.front().binding_id;
  const auto owning_input = std::find_if(
      plan.ValueOrDie()->inputs.begin(), plan.ValueOrDie()->inputs.end(),
      [&](const std::shared_ptr<const PhysicalPlan>& input) {
        return input != nullptr && input->binding_id() == owner;
      });
  ASSERT_NE(owning_input, plan.ValueOrDie()->inputs.end());
  ASSERT_EQ((*owning_input)->predicates().size(), 1U);
  ASSERT_EQ((*owning_input)->predicate_properties().size(), 1U);
  EXPECT_EQ((*owning_input)->predicate_properties().front().column.logical_type,
            "city");
  EXPECT_TRUE(std::any_of(
      (*owning_input)->operators().begin(), (*owning_input)->operators().end(),
      [](const PhysicalOperatorSpec& op) {
        return op.kind == PhysicalOperatorKind::kPropertyGather;
      }));
  EXPECT_TRUE(std::any_of(
      (*owning_input)->operators().begin(), (*owning_input)->operators().end(),
      [](const PhysicalOperatorSpec& op) {
        return op.kind == PhysicalOperatorKind::kFilter;
      }));
  for (const std::shared_ptr<const PhysicalPlan>& input :
       plan.ValueOrDie()->inputs) {
    if (input->binding_id() == owner) continue;
    EXPECT_TRUE(input->predicates().empty());
    EXPECT_TRUE(input->predicate_properties().empty());
  }
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(*plan.ValueOrDie()).ok());
}

TEST(TcypherPhysicalPlanTest,
     DisconnectedComponentBuildsExplicitCrossJoinStep) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_physical_multi_join_disconnected_timeline");
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name RETURN a, b, c;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {},
                            MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  ASSERT_TRUE(CanPlanPhysicalMultiHashJoin(bound.ValueOrDie()));

  const auto plan = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr,
      {{BindingId{1}, PhysicalCardinalityEstimate{8, 900, false}},
       {BindingId{2}, PhysicalCardinalityEstimate{4, 900, false}},
       {BindingId{3}, PhysicalCardinalityEstimate{2, 900, false}}},
      82);
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  ASSERT_EQ(plan.ValueOrDie()->steps.size(), 2U);
  EXPECT_EQ(std::count_if(
                plan.ValueOrDie()->steps.begin(),
                plan.ValueOrDie()->steps.end(),
                [](const PhysicalMultiHashJoinStep& step) {
                  return step.join.kind == PhysicalOperatorKind::kHashJoin;
                }),
            1);
  EXPECT_EQ(std::count_if(
                plan.ValueOrDie()->steps.begin(),
                plan.ValueOrDie()->steps.end(),
                [](const PhysicalMultiHashJoinStep& step) {
                  return step.join.kind == PhysicalOperatorKind::kCrossJoin;
                }),
            1);
  for (const PhysicalMultiHashJoinStep& step : plan.ValueOrDie()->steps) {
    if (step.join.kind == PhysicalOperatorKind::kHashJoin) {
      EXPECT_FALSE(step.accumulated_key_columns.empty());
      EXPECT_EQ(step.accumulated_key_columns.size(),
                step.input_key_columns.size());
    } else if (step.join.kind == PhysicalOperatorKind::kCrossJoin) {
      EXPECT_TRUE(step.accumulated_key_columns.empty());
      EXPECT_TRUE(step.input_key_columns.empty());
    }
  }
  const std::string explain = FormatPhysicalMultiHashJoinPlan(*plan.ValueOrDie());
  EXPECT_NE(explain.find("HashJoin"), std::string::npos) << explain;
  EXPECT_NE(explain.find("CrossJoin"), std::string::npos) << explain;

  const auto hash_step = std::find_if(
      plan.ValueOrDie()->steps.begin(), plan.ValueOrDie()->steps.end(),
      [](const PhysicalMultiHashJoinStep& step) {
        return step.join.kind == PhysicalOperatorKind::kHashJoin;
      });
  const auto cross_step = std::find_if(
      plan.ValueOrDie()->steps.begin(), plan.ValueOrDie()->steps.end(),
      [](const PhysicalMultiHashJoinStep& step) {
        return step.join.kind == PhysicalOperatorKind::kCrossJoin;
      });
  ASSERT_NE(hash_step, plan.ValueOrDie()->steps.end());
  ASSERT_NE(cross_step, plan.ValueOrDie()->steps.end());
  const size_t hash_index = static_cast<size_t>(
      std::distance(plan.ValueOrDie()->steps.begin(), hash_step));
  const size_t cross_index = static_cast<size_t>(
      std::distance(plan.ValueOrDie()->steps.begin(), cross_step));

  PhysicalMultiHashJoinPlan empty_hash_keys = *plan.ValueOrDie();
  empty_hash_keys.steps[hash_index].accumulated_key_columns.clear();
  empty_hash_keys.steps[hash_index].input_key_columns.clear();
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(empty_hash_keys)
                  .IsInvalidArgument());

  PhysicalMultiHashJoinPlan keyed_cross = *plan.ValueOrDie();
  keyed_cross.steps[cross_index].accumulated_key_columns = {0};
  keyed_cross.steps[cross_index].input_key_columns = {0};
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(keyed_cross)
                  .IsInvalidArgument());

  PhysicalMultiHashJoinPlan unknown_kind = *plan.ValueOrDie();
  unknown_kind.steps[cross_index].join.kind =
      static_cast<PhysicalOperatorKind>(255);
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(unknown_kind)
                  .IsInvalidArgument());
}

TEST(TcypherPhysicalPlanTest,
     RelationshipMultiMatchBuildsCompleteExpandInputPlan) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_relationship_multi_join_plan_timeline");
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a)-[r:KNOWS]->(b) MATCH (c) "
      "WHERE b.name = c.name RETURN r, c;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {},
                            MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  const auto binding_for = [&](const std::string& name) {
    const auto found = std::find_if(
        bound.ValueOrDie().variables.begin(), bound.ValueOrDie().variables.end(),
        [&](const BoundVariable& variable) { return variable.variable == name; });
    EXPECT_NE(found, bound.ValueOrDie().variables.end());
    return found == bound.ValueOrDie().variables.end() ? BindingId{} :
        found->binding_id;
  };
  const BindingId relationship_binding = binding_for("r");
  const BindingId target_binding = binding_for("b");

  EXPECT_TRUE(CanPlanPhysicalMultiHashJoin(bound.ValueOrDie()));
  const auto plan = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), &parsed.ValueOrDie(),
      {{BindingId{1}, PhysicalCardinalityEstimate{2, 1000, false}},
       {BindingId{4}, PhysicalCardinalityEstimate{3, 1000, false}}},
      17);
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  ASSERT_EQ(plan.ValueOrDie()->inputs.size(), 2U);
  ASSERT_EQ(plan.ValueOrDie()->steps.size(), 1U);
  EXPECT_EQ(plan.ValueOrDie()->inputs[0]->expand_steps().size(), 1U);
  EXPECT_TRUE(std::any_of(
      plan.ValueOrDie()->input_layouts[0].begin(),
      plan.ValueOrDie()->input_layouts[0].end(),
      [&](const PhysicalMultiJoinColumn& column) {
        return column.binding_id == relationship_binding &&
            column.kind == ReturnExpressionKind::kBinding &&
            column.type == PhysicalType::kBinary;
      }));
  EXPECT_TRUE(std::any_of(
      plan.ValueOrDie()->input_layouts[0].begin(),
      plan.ValueOrDie()->input_layouts[0].end(),
      [&](const PhysicalMultiJoinColumn& column) {
        return column.binding_id == target_binding &&
            column.kind == ReturnExpressionKind::kProperty &&
            column.type == PhysicalType::kString;
      }));
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(*plan.ValueOrDie()).ok());

  PhysicalMultiHashJoinPlan wrong_binding = *plan.ValueOrDie();
  ASSERT_FALSE(wrong_binding.input_layouts[0].empty());
  wrong_binding.input_layouts[0][0].binding_id = target_binding;
  EXPECT_FALSE(ValidatePhysicalMultiHashJoinPlan(wrong_binding).ok());

  PhysicalMultiHashJoinPlan wrong_kind = *plan.ValueOrDie();
  wrong_kind.input_layouts[0][0].kind = ReturnExpressionKind::kSystemTime;
  EXPECT_FALSE(ValidatePhysicalMultiHashJoinPlan(wrong_kind).ok());
}

