TEST(TcypherPhysicalPlanTest, MultiJoinFallbackIsDeterministicWithoutStats) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_multi_join_fallback_timeline");
  const auto parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name "
      "RETURN a, b, c;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();

  const auto first = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, {}, 0);
  const auto second = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, {}, 0);
  ASSERT_TRUE(first.ok()) << first.status().ToString();
  ASSERT_TRUE(second.ok()) << second.status().ToString();
  EXPECT_EQ(first.ValueOrDie()->join_order,
            (std::vector<uint32_t>{0, 1, 2}));
  EXPECT_EQ(first.ValueOrDie()->plan_id, second.ValueOrDie()->plan_id);
  EXPECT_TRUE(first.ValueOrDie()->steps[0].accumulated_estimate.conservative);
  EXPECT_TRUE(first.ValueOrDie()->steps[0].input_estimate.conservative);

  const auto seven_parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) MATCH (d) MATCH (e) MATCH (f) MATCH (g) "
      "WHERE a.name = b.name AND a.name = c.name AND a.name = d.name AND "
      "a.name = e.name AND a.name = f.name AND a.name = g.name "
      "RETURN a, b, c, d, e, f, g;");
  ASSERT_TRUE(seven_parsed.ok()) << seven_parsed.status().ToString();
  const auto seven_bound = BindTcypher(
      seven_parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(seven_bound.ok()) << seven_bound.status().ToString();
  const auto seven_logical = LowerTcypher(seven_bound.ValueOrDie());
  ASSERT_TRUE(seven_logical.ok()) << seven_logical.status().ToString();
  const auto seven_plan = PlanPhysicalMultiHashJoin(
      seven_bound.ValueOrDie(), seven_logical.ValueOrDie(), nullptr, {}, 0);
  ASSERT_TRUE(seven_plan.ok()) << seven_plan.status().ToString();
  EXPECT_EQ(seven_plan.ValueOrDie()->join_order,
            (std::vector<uint32_t>{0, 1, 2, 3, 4, 5, 6}));
  EXPECT_EQ(seven_plan.ValueOrDie()->steps.size(), 6U);

  const auto selective_seven_parsed = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) MATCH (d) MATCH (e) MATCH (f) MATCH (g) "
      "WHERE a.name = 'target' AND a.name = b.name AND a.name = c.name AND "
      "a.name = d.name AND a.name = e.name AND a.name = f.name AND "
      "a.name = g.name RETURN a, b, c, d, e, f, g;");
  ASSERT_TRUE(selective_seven_parsed.ok())
      << selective_seven_parsed.status().ToString();
  const auto selective_seven_bound = BindTcypher(
      selective_seven_parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(selective_seven_bound.ok())
      << selective_seven_bound.status().ToString();
  const auto selective_seven_logical = LowerTcypher(selective_seven_bound.ValueOrDie());
  ASSERT_TRUE(selective_seven_logical.ok())
      << selective_seven_logical.status().ToString();
  std::map<BindingId, PhysicalCardinalityEstimate> selective_estimates;
  selective_estimates.emplace(
      BindingId{1}, PhysicalCardinalityEstimate{100, 900, false, true});
  for (uint32_t binding = 2; binding <= 7; ++binding) {
    selective_estimates.emplace(
        BindingId{binding}, PhysicalCardinalityEstimate{1000000, 900, false});
  }
  const auto selective_seven_plan = PlanPhysicalMultiHashJoin(
      selective_seven_bound.ValueOrDie(), selective_seven_logical.ValueOrDie(), nullptr,
      selective_estimates, 0);
  ASSERT_TRUE(selective_seven_plan.ok()) << selective_seven_plan.status().ToString();
  EXPECT_EQ(selective_seven_plan.ValueOrDie()->graph_order, GraphOrder::kIndexFirst);
  EXPECT_EQ(selective_seven_plan.ValueOrDie()->join_order.front(), 0U);
}

