TEST(TcypherPhysicalPlanTest, MultiJoinCandidateRejectsNonPointTemporalScopes) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_multi_join_scope_timeline");
  const auto can_plan = [&](const std::string& query) {
    const auto parsed = ParseTcypher(query);
    EXPECT_TRUE(parsed.ok()) << parsed.status().ToString();
    if (!parsed.ok()) return true;
    const auto bound = BindTcypher(
        parsed.ValueOrDie(),
        TcypherBindingContext{timeline, 3, 99, {},
                              MakeTcypherBinderSchemaSnapshot()});
    EXPECT_TRUE(bound.ok()) << bound.status().ToString();
    return bound.ok() && CanPlanPhysicalMultiHashJoin(bound.ValueOrDie());
  };

  EXPECT_FALSE(can_plan(
      "FOR VALID_TIME BETWEEN 5 AND 15 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name "
      "RETURN a, b, c;"));
  EXPECT_FALSE(can_plan(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) FOR VALID_TIME BETWEEN 5 AND 15 MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name "
      "RETURN a, b, c;"));
}

