TEST(TcypherPhysicalPlanTest, MultiJoinValidatorAcceptsCrossAndRejectsInvalidLayouts) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_multi_join_validate_timeline");
  const auto disconnected = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name RETURN a, b, c;");
  ASSERT_TRUE(disconnected.ok()) << disconnected.status().ToString();
  const auto disconnected_bound = BindTcypher(
      disconnected.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(disconnected_bound.ok()) << disconnected_bound.status().ToString();
  const auto disconnected_logical = LowerTcypher(disconnected_bound.ValueOrDie());
  ASSERT_TRUE(disconnected_logical.ok()) << disconnected_logical.status().ToString();
  EXPECT_TRUE(CanPlanPhysicalMultiHashJoin(disconnected_bound.ValueOrDie()));
  const auto disconnected_plan = PlanPhysicalMultiHashJoin(
      disconnected_bound.ValueOrDie(), disconnected_logical.ValueOrDie(),
      nullptr, {}, 0);
  ASSERT_TRUE(disconnected_plan.ok())
      << disconnected_plan.status().ToString();
  EXPECT_TRUE(std::any_of(
      disconnected_plan.ValueOrDie()->steps.begin(),
      disconnected_plan.ValueOrDie()->steps.end(),
      [](const PhysicalMultiHashJoinStep& step) {
        return step.join.kind == PhysicalOperatorKind::kCrossJoin;
      }));

  const auto connected = ParseTcypher(
      "FOR VALID_TIME AS OF 10 "
      "MATCH (a) MATCH (b) MATCH (c) "
      "WHERE a.name = b.name AND b.name = c.name "
      "RETURN a, b, c;");
  ASSERT_TRUE(connected.ok()) << connected.status().ToString();
  const auto bound = BindTcypher(
      connected.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  const auto built = PlanPhysicalMultiHashJoin(
      bound.ValueOrDie(), logical.ValueOrDie(), nullptr, {}, 0);
  ASSERT_TRUE(built.ok()) << built.status().ToString();

  PhysicalMultiHashJoinPlan invalid_layout = *built.ValueOrDie();
  invalid_layout.steps.front().output_layout.front().type =
      static_cast<PhysicalType>(255);
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(invalid_layout).IsInvalidArgument());

  PhysicalMultiHashJoinPlan disconnected_step = *built.ValueOrDie();
  disconnected_step.steps.front().input_index =
      disconnected_step.join_order.front();
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(disconnected_step).IsInvalidArgument());

  PhysicalMultiHashJoinPlan invalid_pipeline = *built.ValueOrDie();
  invalid_pipeline.pipelines.back().dependencies.clear();
  EXPECT_TRUE(ValidatePhysicalMultiHashJoinPlan(invalid_pipeline).IsInvalidArgument());

  PhysicalMultiHashJoinPlan duplicate_key_pair = *built.ValueOrDie();
  duplicate_key_pair.steps.front().accumulated_key_columns.push_back(
      duplicate_key_pair.steps.front().accumulated_key_columns.front());
  duplicate_key_pair.steps.front().input_key_columns.push_back(
      duplicate_key_pair.steps.front().input_key_columns.front());
  EXPECT_TRUE(
      ValidatePhysicalMultiHashJoinPlan(duplicate_key_pair).IsInvalidArgument());
}

TEST(TcypherPhysicalPlanTest, BuildsTypedRootRangeAndChangePlans) {
  CommitTimeline timeline("/tmp/cedar_unused_physical_range_change_plan_timeline");
  const auto build = [&](const std::string& query) {
    const auto parsed = ParseTcypher(query);
    EXPECT_TRUE(parsed.ok()) << parsed.status().ToString();
    const auto bound = BindTcypher(
        parsed.ValueOrDie(),
        TcypherBindingContext{timeline, 3, 99, {}, MakeTcypherBinderSchemaSnapshot()});
    EXPECT_TRUE(bound.ok()) << bound.status().ToString();
    const auto logical = LowerTcypher(bound.ValueOrDie());
    EXPECT_TRUE(logical.ok()) << logical.status().ToString();
    return PlanPhysicalRootPoint(bound.ValueOrDie(), logical.ValueOrDie());
  };

  const auto range = build(
      "FOR VALID_TIME BETWEEN 10 AND 20 MATCH (n) RETURN n, valid_from(n), valid_to(n);");
  ASSERT_TRUE(range.ok()) << range.status().ToString();
  EXPECT_EQ(range.ValueOrDie()->temporal_mode(), PhysicalTemporalMode::kValidTimeRange);
  ASSERT_FALSE(range.ValueOrDie()->operators().empty());
  EXPECT_EQ(range.ValueOrDie()->operators().front().kind,
            PhysicalOperatorKind::kTemporalRangeScan);
  EXPECT_EQ(range.ValueOrDie()->operators()[1].kind,
            PhysicalOperatorKind::kIntervalDerive);
  EXPECT_EQ(range.ValueOrDie()->valid_time_range(),
            (std::optional<std::pair<uint64_t, uint64_t>>{{10, 20}}));

  const auto changes = build(
      "CHANGES FOR SYSTEM_TIME BETWEEN 100 AND 200 "
      "FOR VALID_TIME BETWEEN 10 AND 20 MATCH (n) "
      "RETURN n, valid_from(n), commit_seq(n), operation(n), system_time(n);");
  ASSERT_TRUE(changes.ok()) << changes.status().ToString();
  EXPECT_EQ(changes.ValueOrDie()->temporal_mode(), PhysicalTemporalMode::kSystemTimeChanges);
  EXPECT_EQ(changes.ValueOrDie()->operators().front().kind,
            PhysicalOperatorKind::kChangeScan);
  EXPECT_EQ(changes.ValueOrDie()->valid_time_range(),
            (std::optional<std::pair<uint64_t, uint64_t>>{{10, 20}}));
  EXPECT_EQ(changes.ValueOrDie()->system_time_range(),
            (std::optional<std::pair<uint64_t, uint64_t>>{{100, 200}}));
  EXPECT_TRUE(ValidatePhysicalPlan(*changes.ValueOrDie()).ok());

  const auto point_restricted = build(
      "CHANGES FOR SYSTEM_TIME BETWEEN 100 AND 200 "
      "FOR VALID_TIME AS OF 25 MATCH (n) RETURN n;");
  ASSERT_TRUE(point_restricted.ok()) << point_restricted.status().ToString();
  EXPECT_EQ(point_restricted.ValueOrDie()->valid_time_as_of(),
            std::optional<uint64_t>(25));
}

