TEST(TcypherPhysicalPlanTest, PlanningUsesBoundIdsAfterSyntaxNamesAreDiscarded) {
  CommitTimeline timeline("/tmp/cedar_unused_bound_id_plan_timeline");
  const auto parsed = ParseTcypher(
      "MATCH (n) WHERE n.name = 'Ada' RETURN n.name;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{timeline, 3, 99, {},
                            MakeTcypherBinderSchemaSnapshot()});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  const auto original = PlanPhysicalRootPoint(
      bound.ValueOrDie(), logical.ValueOrDie());
  ASSERT_TRUE(original.ok()) << original.status().ToString();
  bound.ValueOrDie().syntax.match.variable = "discarded";
  bound.ValueOrDie().syntax.where->variable = "discarded";
  bound.ValueOrDie().syntax.where->property_name = "discarded";
  bound.ValueOrDie().syntax.returns[0].variable = "discarded";
  bound.ValueOrDie().syntax.returns[0].property_name = "discarded";
  const auto rebound = PlanPhysicalRootPoint(
      bound.ValueOrDie(), logical.ValueOrDie());
  ASSERT_TRUE(rebound.ok()) << rebound.status().ToString();
  EXPECT_EQ(rebound.ValueOrDie()->plan_id(), original.ValueOrDie()->plan_id());
}

