TEST(TcypherExecutorTest, ExplainAnalyzeAttributesBlockingSpillResources) {
  CommitTimeline timeline(
      "/tmp/cedar_unused_explain_analyze_blocking_spill_timeline");
  std::vector<TemporalEvent> events;
  for (uint64_t id = 1; id <= 24; ++id) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(id), 1, 1, 1, Value::Binary("")));
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(id, 7), 1, 1, 1,
        Value::String("value-" + std::to_string(id) + std::string(24, 'x'))));
  }
  const auto profile_for = [&](const std::string& query,
                               const std::string& spill_directory) {
    std::filesystem::remove_all(spill_directory);
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.batch_capacity = 1;
    options.memory_account = std::make_shared<QueryMemoryAccount>(512, 4096);
    options.spill_directory = spill_directory;
    auto stream = ExecuteTcypher(
        query, TcypherExecutionContext{
                   timeline, 1, options, MakeTcypherBinderSchemaSnapshot(),
                   events});
    EXPECT_TRUE(stream.ok()) << stream.status().ToString();
    ResultBatch result;
    EXPECT_TRUE(stream.ValueOrDie()->Next(&result).ok());
    const std::string profile = std::get<std::string>(
        result.batch().ValueAt(0, 0)->data());
    stream = Status::NotFound("test", "release explain stream");
    std::filesystem::remove_all(spill_directory);
    return profile;
  };

  const std::string aggregate_profile = profile_for(
      "EXPLAIN ANALYZE FOR VALID_TIME AS OF 10 MATCH (n) "
      "RETURN n.name, COUNT(n);",
      "/tmp/cedar_explain_analyze_aggregate_spill");
  const std::string distinct_profile = profile_for(
      "EXPLAIN ANALYZE FOR VALID_TIME AS OF 10 MATCH (n) "
      "RETURN DISTINCT n.name;",
      "/tmp/cedar_explain_analyze_distinct_spill");
  const std::string sort_profile = profile_for(
      "EXPLAIN ANALYZE FOR VALID_TIME AS OF 10 MATCH (n) "
      "RETURN n.name ORDER BY n.name;",
      "/tmp/cedar_explain_analyze_sort_spill");

  for (const auto& [profile, kind] :
       std::array<std::pair<std::string, std::string>, 3>{{
           {aggregate_profile, "AggregateSink"},
           {distinct_profile, "DistinctSink"},
           {sort_profile, "SortSink"}}}) {
    const std::string counters = ExplainOperatorCounters(profile, kind);
    EXPECT_EQ(counters.find("\"memory_peak_bytes\":0"), std::string::npos)
        << counters;
    EXPECT_EQ(counters.find("\"spill_bytes\":0"), std::string::npos)
        << counters;
    EXPECT_EQ(counters.find("\"spill_starts\":0"), std::string::npos)
        << counters;
  }
}

