TEST(IndexSidecarTest, RoundTripsEveryPhysicalPostingEncoding) {
  IndexDefinition definition;
  definition.index_id = 17;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 3;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality | kIndexOrderedRange | kIndexPrefix;
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexProperty(4, 3), 40, 1, 1,
                          Value::String("charlie")),
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 3), 10, 2, 1,
                          Value::String("alpha")),
      TemporalEvent::Put(LogicalKey::VertexProperty(2, 3), 20, 3, 1,
                          Value::String("alpha")),
      TemporalEvent::Put(LogicalKey::VertexProperty(3, 3), 30, 4, 1,
                          Value::String("bravo")),
  };
  const std::vector<uint32_t> encodings = {
      kIndexCanonicalEncoding,
      kIndexCanonicalEncodingDictionary,
      kIndexCanonicalEncodingBitmap,
      kIndexCanonicalEncodingSortedDelta,
  };
  std::string raw_bytes;
  for (const uint32_t encoding : encodings) {
    definition.canonical_encoding_id = encoding;
    const auto sidecar = BuildIndexCandidateSidecar(91, definition, events);
    ASSERT_TRUE(sidecar.ok()) << sidecar.status().ToString();
    const auto encoded = BuildIndexSidecar(definition, 91, sidecar.ValueOrDie().postings);
    ASSERT_TRUE(encoded.ok()) << encoded.status().ToString();
    if (raw_bytes.empty()) raw_bytes = encoded.ValueOrDie();
    else EXPECT_NE(encoded.ValueOrDie(), raw_bytes);
    const auto decoded = ReadIndexSidecar(encoded.ValueOrDie(), definition, 91);
    ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
    ASSERT_EQ(decoded.ValueOrDie().postings.size(), 4U);
    const auto equality = LookupIndexEquality(decoded.ValueOrDie(), Value::String("alpha"));
    ASSERT_TRUE(equality.ok()) << equality.status().ToString();
    EXPECT_EQ(equality.ValueOrDie().size(), 2U);
    const auto range = LookupIndexRange(decoded.ValueOrDie(), Value::String("bravo"),
                                        true, Value::String("charlie"), true);
    ASSERT_TRUE(range.ok()) << range.status().ToString();
    EXPECT_EQ(range.ValueOrDie().size(), 2U);
    const auto prefix = LookupIndexPrefix(decoded.ValueOrDie(), Value::String("al"));
    ASSERT_TRUE(prefix.ok()) << prefix.status().ToString();
    EXPECT_EQ(prefix.ValueOrDie().size(), 2U);
  }
  definition.canonical_encoding_id = kIndexCanonicalEncodingDictionary;
  const auto sidecar = BuildIndexCandidateSidecar(91, definition, events);
  ASSERT_TRUE(sidecar.ok()) << sidecar.status().ToString();
  const auto encoded = BuildIndexSidecar(definition, 91, sidecar.ValueOrDie().postings);
  ASSERT_TRUE(encoded.ok()) << encoded.status().ToString();
  definition.canonical_encoding_id = kIndexCanonicalEncodingBitmap;
  EXPECT_TRUE(ReadIndexSidecar(encoded.ValueOrDie(), definition, 91)
                  .status()
                  .IsCorruption());
}

