TEST(IndexSidecarTest, RunningCancellationStopsAtThe64EventQuantum) {
  IndexDefinition definition;
  definition.index_id = 7;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 3;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kActive;
  std::vector<TemporalEvent> events;
  for (uint64_t ordinal = 0; ordinal < 128; ++ordinal) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(ordinal + 1, 3), 10, ordinal + 1, 1,
        Value::Int64(static_cast<int64_t>(ordinal))));
  }
  uint64_t checkpoints = 0;
  auto cancellation = std::make_shared<WorkCancellation>();
  cancellation->SetCheckpointObserverForTesting(
      [&](WorkCancellation* token, const std::string& owner,
          uint64_t checkpoint) {
        EXPECT_EQ(owner, "index sidecar build");
        checkpoints = checkpoint;
        if (checkpoint == 2) token->Cancel();
      });
  const auto sidecar =
      BuildIndexCandidateSidecar(99, definition, events, cancellation);
  EXPECT_TRUE(sidecar.status().IsQueryCancelled())
      << sidecar.status().ToString();
  EXPECT_EQ(checkpoints, 2U);
}

TEST(IndexSidecarTest, BlobEqualityUsesHashWithoutRangeOrPrefixExposure) {
  IndexDefinition definition;
  definition.index_id = 19;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 3;
  definition.schema_epoch = 1;
  definition.capabilities =
      kIndexEquality | kIndexOrderedRange | kIndexPrefix;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kActive;
  const std::string payload(128, 'h');
  const BlobRef reference{
      Blake3Hash(payload), payload.size(), BlobLocation{0, 1, 0}};
  const std::vector<TemporalEvent> events = {
      TemporalEvent::PutBlob(LogicalKey::VertexProperty(1, 3), 10, 1, 1,
                             reference),
      TemporalEvent::Put(LogicalKey::VertexProperty(2, 3), 10, 2, 1,
                         Value::String(payload)),
  };
  const auto sidecar = BuildIndexCandidateSidecar(99, definition, events);
  ASSERT_TRUE(sidecar.ok()) << sidecar.status().ToString();
  ASSERT_EQ(sidecar.ValueOrDie().postings.size(), 2U);
  const auto equality =
      LookupIndexEquality(sidecar.ValueOrDie(), Value::String(payload));
  ASSERT_TRUE(equality.ok()) << equality.status().ToString();
  ASSERT_EQ(equality.ValueOrDie().size(), 2U);
  EXPECT_EQ(equality.ValueOrDie()[0].source_row_ordinal, 1U);
  EXPECT_EQ(equality.ValueOrDie()[1].source_row_ordinal, 0U);
  const auto range = LookupIndexRange(
      sidecar.ValueOrDie(), Value::String(payload), true,
      Value::String(payload), true);
  ASSERT_TRUE(range.ok()) << range.status().ToString();
  ASSERT_EQ(range.ValueOrDie().size(), 1U);
  EXPECT_EQ(range.ValueOrDie()[0].source_row_ordinal, 1U);
  const auto prefix =
      LookupIndexPrefix(sidecar.ValueOrDie(), Value::String("hhhh"));
  ASSERT_TRUE(prefix.ok()) << prefix.status().ToString();
  ASSERT_EQ(prefix.ValueOrDie().size(), 1U);
  EXPECT_EQ(prefix.ValueOrDie()[0].source_row_ordinal, 1U);
}

TEST(HybridIndexScanTest, FallsBackToBaseCandidatesForIncompleteCoverage) {
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 3), 10, 1, 1, Value::String("x")),
      TemporalEvent::Put(LogicalKey::VertexProperty(2, 3), 10, 2, 1, Value::String("x")),
  };
  const auto canonical = EncodeIndexCanonicalValue(Value::String("x"));
  ASSERT_TRUE(canonical.ok());
  IndexSidecar incomplete{44, {IndexPosting{canonical.ValueOrDie(), 0, 10, 1}}};
  const auto fallback = SelectHybridIndexCandidates(
      events, IndexCoverage{44, false, incomplete}, Value::String("x"));
  ASSERT_TRUE(fallback.ok()) << fallback.status().ToString();
  EXPECT_EQ(fallback.ValueOrDie(), (std::vector<uint64_t>{0, 1}));

  const auto covered = SelectHybridIndexCandidates(
      events, IndexCoverage{44, true, incomplete}, Value::String("x"));
  ASSERT_TRUE(covered.ok()) << covered.status().ToString();
  EXPECT_EQ(covered.ValueOrDie(), (std::vector<uint64_t>{0}));
}

