TEST(MemtableDeltaIndexTest, RangeCursorNeverReturnsBlobHashPostings) {
  IndexDefinition definition;
  definition.index_id = 8;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 3;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality | kIndexOrderedRange;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  const std::string blob_payload(128, 'z');
  std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 3), 10, 1, 1,
                         Value::String("bravo")),
  };
  for (uint64_t entity_id = 2; entity_id <= 131; ++entity_id) {
    const std::string payload =
        blob_payload + std::to_string(entity_id);
    events.push_back(TemporalEvent::PutBlob(
        LogicalKey::VertexProperty(entity_id, 3), 10, entity_id, 1,
        BlobRef{Blake3Hash(payload), payload.size(),
                BlobLocation{0, entity_id, 0}}));
  }
  MemtableDeltaIndex delta;
  ASSERT_TRUE(delta.Rebuild(definition, 7, events).ok());
  const auto lower = EncodeIndexCanonicalValue(Value::String("alpha"));
  ASSERT_TRUE(lower.ok()) << lower.status().ToString();
  auto opened = delta.OpenLookupCursor(
      7, MemtableDeltaIndex::LookupKind::kRange, nullptr,
      &lower.ValueOrDie(), true, nullptr, true);
  ASSERT_TRUE(opened.ok()) << opened.status().ToString();
  std::vector<uint64_t> all_ordinals;
  uint64_t total_processed = 0;
  while (!opened.ValueOrDie().done()) {
    std::vector<uint64_t> ordinals;
    uint32_t processed = 0;
    ASSERT_TRUE(opened.ValueOrDie()
                    .Advance(1, nullptr, &ordinals, &processed)
                    .ok());
    all_ordinals.insert(all_ordinals.end(), ordinals.begin(), ordinals.end());
    total_processed += processed;
  }
  EXPECT_EQ(all_ordinals, (std::vector<uint64_t>{0}));
  EXPECT_LE(total_processed, 2U);
}

