TEST(WorkExecutionServiceTest, RejectedAdmissionNeverEntersScheduler) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  ResourceGovernor governor(ResourceProfile{2, 2, 2, 2, 2, 2, 2, 2, 2},
                            ResourceProfile{1, 1, 1, 1, 1, 1, 1, 1, 1});
  ASSERT_TRUE(service.ConfigureResourceGovernor(&governor).ok());
  ASSERT_TRUE(service.Start().ok());

  std::mutex blocker_mutex;
  std::condition_variable blocker_entered;
  std::condition_variable unblock_worker;
  bool worker_is_blocked = false;
  bool release_worker = false;
  std::atomic<uint32_t> executions{0};
  const ResourceProfile one_unit{1, 1, 1, 1, 1, 1, 1, 1, 1};
  const auto at_non_critical_cap = service.Submit(
      WorkTaskRequest{WorkClass::kStatsMerge, one_unit, false, 0}, [&] {
        std::unique_lock<std::mutex> lock(blocker_mutex);
        worker_is_blocked = true;
        blocker_entered.notify_one();
        unblock_worker.wait(lock, [&] { return release_worker; });
        return Status::OK();
      });
  ASSERT_TRUE(at_non_critical_cap.ok()) << at_non_critical_cap.status().ToString();
  {
    std::unique_lock<std::mutex> lock(blocker_mutex);
    blocker_entered.wait(lock, [&] { return worker_is_blocked; });
  }

  const auto rejected = service.Submit(
      WorkTaskRequest{WorkClass::kStatsMerge, one_unit, false, 0}, [&] {
        executions.fetch_add(1, std::memory_order_relaxed);
        return Status::OK();
      });
  EXPECT_TRUE(rejected.status().IsQueryMemoryLimit());
  EXPECT_FALSE(scheduler.NextExecutableWork().has_value());
  EXPECT_EQ(executions.load(std::memory_order_relaxed), 0U);
  EXPECT_EQ(governor.used().memory_bytes, 1U);

  const WorkTaskRequest critical{WorkClass::kCommitCritical, one_unit, true, 0};
  const auto admitted = service.Submit(critical, [&] {
    executions.fetch_add(1, std::memory_order_relaxed);
    return Status::OK();
  });
  ASSERT_TRUE(admitted.ok()) << admitted.status().ToString();
  EXPECT_EQ(governor.used().memory_bytes, 2U);

  {
    std::lock_guard<std::mutex> lock(blocker_mutex);
    release_worker = true;
  }
  unblock_worker.notify_one();
  EXPECT_TRUE(at_non_critical_cap.ValueOrDie().Wait().ok());
  EXPECT_TRUE(admitted.ValueOrDie().Wait().ok());
  EXPECT_EQ(executions.load(std::memory_order_relaxed), 1U);
  EXPECT_EQ(governor.used().memory_bytes, 0U);
  EXPECT_TRUE(service.Stop().ok());
}

TEST(WorkExecutionServiceTest, ExposesBoundedPerClassTelemetry) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  MetricRegistry metrics(13);
  ASSERT_TRUE(service.ExportMetrics(&metrics).ok());

  const auto metric = [&](const std::string& name) -> MetricPoint {
    for (const MetricPoint& point : metrics.Snapshot()) {
      if (point.definition.name == name) return point;
    }
    return MetricPoint{};
  };
  for (const char* name : {
           "cedar_scheduler_tasks_submitted_total",
           "cedar_scheduler_tasks_admitted_total",
           "cedar_scheduler_tasks_rejected_total",
           "cedar_scheduler_tasks_cancelled_total",
           "cedar_scheduler_tasks_completed_total"}) {
    const MetricPoint point = metric(name);
    EXPECT_EQ(point.definition.type, MetricType::kCounter);
    EXPECT_EQ(point.values.size(), 13U);
  }

  ASSERT_TRUE(service.Start().ok());
  const auto completed = service.Submit(
      WorkClass::kStatsMerge, [] { return Status::OK(); });
  ASSERT_TRUE(completed.ok()) << completed.status().ToString();
  ASSERT_TRUE(completed.ValueOrDie().Wait().ok());
  ASSERT_TRUE(service.Stop().ok());
  EXPECT_TRUE(service.Submit(
      WorkClass::kStatsMerge, [] { return Status::OK(); }).status().IsInvalidArgument());

  ASSERT_TRUE(service.ExportMetrics(&metrics).ok());
  EXPECT_EQ(metrics.Counter("cedar_scheduler_tasks_submitted_total", "stats_merge"), 2U);
  EXPECT_EQ(metrics.Counter("cedar_scheduler_tasks_admitted_total", "stats_merge"), 1U);
  EXPECT_EQ(metrics.Counter("cedar_scheduler_tasks_rejected_total", "stats_merge"), 1U);
  EXPECT_EQ(metrics.Counter("cedar_scheduler_tasks_cancelled_total", "stats_merge"), 0U);
  EXPECT_EQ(metrics.Counter("cedar_scheduler_tasks_completed_total", "stats_merge"), 1U);
  ASSERT_TRUE(service.ExportMetrics(&metrics).ok());
  EXPECT_EQ(metrics.Counter("cedar_scheduler_tasks_submitted_total", "stats_merge"), 2U);
  EXPECT_EQ(metrics.Counter("cedar_scheduler_tasks_completed_total", "stats_merge"), 1U);
}

