TEST(MaintenanceExecutorTest, AdmitsSelectedTaskBeforeRunningItsCallback) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  ASSERT_TRUE(service.Start().ok());
  ResourceGovernor resources(ResourceProfile{0, 0, 2, 0, 2});
  IoGovernor io(IoGovernorLimits{
      IoTokenBudget{0, 0}, IoTokenBudget{0, 0},
      IoTokenBudget{0, 0}, IoTokenBudget{4, 0}});
  MaintenanceExecutor executor;
  ASSERT_TRUE(executor.Configure(&service, &resources, &io).ok());
  uint32_t executions = 0;
  uint64_t descriptors_during_callback = 0;
  uint64_t cpu_slots_during_callback = 0;
  const Status status = executor.SubmitAndRun(MaintenanceTaskSpec{
      WorkClass::kStatsMerge, ResourceProfile{0, 0, 1, 0, 1},
      IoTokenRequest{0, 0, 0, 1, false}, false, false,
      [&](const std::shared_ptr<WorkCancellation>&) {
        const ResourceProfile used = resources.used();
        descriptors_during_callback = used.descriptors;
        cpu_slots_during_callback = used.cpu_slots;
        ++executions;
        return Status::OK();
      }});
  EXPECT_TRUE(status.ok()) << status.ToString();
  EXPECT_EQ(executions, 1U);
  EXPECT_EQ(descriptors_during_callback, 1U);
  EXPECT_EQ(cpu_slots_during_callback, 1U);
  EXPECT_EQ(resources.used().descriptors, 0U);
  EXPECT_TRUE(service.Stop().ok());
}

TEST(MaintenanceExecutorTest, PropagatesRunningCancellation) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  ASSERT_TRUE(service.Start().ok());
  MaintenanceExecutor executor;
  ASSERT_TRUE(executor.Configure(&service, nullptr, nullptr).ok());

  std::mutex mutex;
  std::condition_variable entered;
  std::condition_variable cancelled;
  std::shared_ptr<WorkCancellation> observed;
  Status terminal = Status::InvalidArgument("test", "maintenance did not run");
  std::thread submitter([&] {
    terminal = executor.SubmitAndRun(MaintenanceTaskSpec{
        WorkClass::kStatsMerge, {}, {}, false, true,
        [&](const std::shared_ptr<WorkCancellation>& cancellation) {
          std::unique_lock<std::mutex> lock(mutex);
          observed = cancellation;
          entered.notify_one();
          cancelled.wait(lock, [&] { return cancellation->IsCancelled(); });
          return cancellation->Checkpoint("test maintenance executor");
        }});
  });
  {
    std::unique_lock<std::mutex> lock(mutex);
    entered.wait(lock, [&] { return observed != nullptr; });
  }
  EXPECT_EQ(service.CancelPreemptible(WorkClass::kStatsMerge), 1U);
  cancelled.notify_one();
  submitter.join();
  EXPECT_TRUE(terminal.IsQueryCancelled()) << terminal.ToString();
  EXPECT_TRUE(observed->IsCancelled());
  EXPECT_TRUE(service.Stop().ok());
}

TEST(MaintenanceExecutorTest, NestedProgressPropagatesCancellation) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  ASSERT_TRUE(service.Start().ok());
  MaintenanceExecutor executor;
  ASSERT_TRUE(executor.Configure(&service, nullptr, nullptr).ok());
  std::vector<TemporalEvent> events;
  for (uint64_t ordinal = 0; ordinal < 128; ++ordinal) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(ordinal + 1, 3), 10, ordinal + 1, 1,
        Value::Int64(static_cast<int64_t>(ordinal))));
  }
  Status nested = Status::InvalidArgument("test", "nested task did not run");
  uint64_t stats_checkpoints = 0;
  executor.SetCancellationObserverForTesting(
      [&](WorkCancellation*, const std::string& owner, uint64_t) {
        if (owner != "stats fragment build") return;
        ++stats_checkpoints;
        if (stats_checkpoints == 2) {
          EXPECT_EQ(service.CancelPreemptible(WorkClass::kStatsMerge), 1U);
        }
      });

  const auto outer = service.Submit(WorkClass::kPointRead, [&] {
    nested = executor.SubmitAndRun(MaintenanceTaskSpec{
        WorkClass::kStatsMerge, {}, {}, false, true,
        [&](const std::shared_ptr<WorkCancellation>& cancellation) {
          return BuildStatsFragment(
                     44, EntityType::Vertex, 3, events, cancellation)
              .status();
        }});
    return nested;
  });
  ASSERT_TRUE(outer.ok()) << outer.status().ToString();
  EXPECT_TRUE(outer.ValueOrDie().Wait().IsQueryCancelled())
      << nested.ToString();
  EXPECT_TRUE(nested.IsQueryCancelled()) << nested.ToString();
  EXPECT_EQ(stats_checkpoints, 2U);
  EXPECT_EQ(service.stats().cancelled[11], 1U);
  EXPECT_EQ(service.stats().completed[11], 1U);
  EXPECT_TRUE(service.Stop().ok());
}

TEST(MaintenanceExecutorTest,
     ReentrantWaitPreservesSchedulerSelectionOrder) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  ASSERT_TRUE(service.Start().ok());
  MaintenanceExecutor executor;
  ASSERT_TRUE(executor.Configure(&service, nullptr, nullptr).ok());
  bool higher_priority_ran = false;
  Status nested = Status::InvalidArgument("test", "nested task did not run");

  const auto outer = service.Submit(WorkClass::kPointRead, [&] {
    const auto higher_priority = service.Submit(
        WorkClass::kCommitCritical, [&] {
          higher_priority_ran = true;
          return Status::OK();
        });
    if (!higher_priority.ok()) return higher_priority.status();
    nested = executor.SubmitAndRun(MaintenanceTaskSpec{
        WorkClass::kBlobGc, {}, {}, false, true,
        [&](const std::shared_ptr<WorkCancellation>&) {
          return higher_priority_ran
              ? Status::OK()
              : Status::Corruption(
                    "test", "nested maintenance bypassed scheduler order");
        }});
    return nested;
  });
  ASSERT_TRUE(outer.ok()) << outer.status().ToString();
  EXPECT_TRUE(outer.ValueOrDie().Wait().ok()) << nested.ToString();
  EXPECT_TRUE(higher_priority_ran);
  EXPECT_TRUE(nested.ok()) << nested.ToString();
  EXPECT_TRUE(service.Stop().ok());
}

TEST_F(DurableLogTest, FlushWaitsOnlyForItsOwnExecutableTask) {
  TransactionCoordinator coordinator(path_, 1, 11);
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  ASSERT_TRUE(service.Start().ok());
  ASSERT_TRUE(coordinator.SetWorkExecutionService(&service).ok());
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary,
                         4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(existence, &registered).ok());
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexExistence(1), 0,
                        registered.schema_epoch, Value::Binary("")),
  }, &commit_seq).ok());
  const auto critical = service.Submit(
      WorkClass::kCommitCritical,
      [] { return Status::IOError("unrelated", "critical task failure"); });
  ASSERT_TRUE(critical.ok()) << critical.status().ToString();
  const Status flushed = coordinator.Flush();
  EXPECT_TRUE(flushed.ok()) << flushed.ToString();
  EXPECT_TRUE(critical.ValueOrDie().Wait().IsIOError());
  EXPECT_FALSE(scheduler.NextExecutableWork().has_value());
  EXPECT_TRUE(service.Stop().ok());
}

TEST(PressureControllerTest, ProducesTypedStatesAndActions) {
  struct Case {
    PressureSignals signals;
    PressureState state;
    PressureCause cause;
    bool admit_writes;
    bool admit_analytical;
    bool admit_optional_maintenance;
    bool cancel_queued_analytical;
    bool require_flush;
    bool require_urgent_compaction;
    bool require_blob_gc;
  };
  const std::vector<Case> cases{
      {PressureSignals{}, PressureState::kNormal, PressureCause::kNone,
       true, true, true, false, false, false, false},
      {PressureSignals{60, 0, 0, 0, 0}, PressureState::kSoftPressure,
       PressureCause::kMemtable, true, true, false, false, true, false, false},
      {PressureSignals{0, 0, 80, 0, 0}, PressureState::kHardPressure,
       PressureCause::kCompaction, true, false, false, true, false, true, false},
      {PressureSignals{0, 80, 0, 0, 0}, PressureState::kWriteStall,
       PressureCause::kWal, false, false, false, true, true, false, false},
      {PressureSignals{0, 0, 0, 0, 160}, PressureState::kDiskEmergency,
       PressureCause::kDisk, false, false, false, true, false, true, true},
  };
  for (const Case& test : cases) {
    PressureController controller(80, 50, 150);
    const PressureDecision decision = controller.Update(test.signals);
    EXPECT_EQ(decision.state, test.state);
    EXPECT_EQ(decision.cause, test.cause);
    EXPECT_EQ(decision.admit_writes, test.admit_writes);
    EXPECT_EQ(decision.admit_analytical, test.admit_analytical);
    EXPECT_EQ(decision.admit_optional_maintenance,
              test.admit_optional_maintenance);
    EXPECT_EQ(decision.cancel_queued_analytical,
              test.cancel_queued_analytical);
    EXPECT_EQ(decision.require_flush, test.require_flush);
    EXPECT_EQ(decision.require_urgent_compaction,
              test.require_urgent_compaction);
    EXPECT_EQ(decision.require_blob_gc, test.require_blob_gc);
  }

  PressureController recovery(80, 50, 150);
  const PressureDecision recovery_decision = recovery.EnterRecovery();
  EXPECT_EQ(recovery_decision.state, PressureState::kRecovery);
  EXPECT_EQ(recovery_decision.cause, PressureCause::kNone);
  EXPECT_FALSE(recovery_decision.admit_writes);
  EXPECT_FALSE(recovery_decision.admit_analytical);
  EXPECT_FALSE(recovery_decision.admit_optional_maintenance);
  EXPECT_TRUE(recovery_decision.cancel_queued_analytical);

  PressureController shutdown(80, 50, 150);
  const PressureDecision shutdown_decision = shutdown.EnterShutdown();
  EXPECT_EQ(shutdown_decision.state, PressureState::kShutdown);
  EXPECT_EQ(shutdown_decision.cause, PressureCause::kNone);
  EXPECT_FALSE(shutdown_decision.admit_writes);
  EXPECT_FALSE(shutdown_decision.admit_analytical);
  EXPECT_FALSE(shutdown_decision.admit_optional_maintenance);
  EXPECT_TRUE(shutdown_decision.cancel_queued_analytical);
}

TEST(PressureControllerTest, NormalizesOverflowAndThresholdOrder) {
  constexpr uint64_t maximum = std::numeric_limits<uint64_t>::max();
  PressureController overflow(maximum - 1, maximum - 2);
  EXPECT_EQ(overflow.Update(
                PressureSignals{0, 0, 0, 0, maximum - 1}).state,
            PressureState::kHardPressure);

  PressureController inverted_low(80, 100, 160);
  EXPECT_EQ(inverted_low.Update(
                PressureSignals{0, 0, 90, 0, 0}).state,
            PressureState::kHardPressure);
  PressureController equal_after_normalization(80, 100, 160);
  EXPECT_EQ(equal_after_normalization.Update(
                PressureSignals{0, 0, 80, 0, 0}).state,
            PressureState::kHardPressure);

  PressureController zero_thresholds(0, 0, 0);
  EXPECT_EQ(zero_thresholds.Update(
                PressureSignals{0, 0, 0, 0, 0}).state,
            PressureState::kDiskEmergency);

  PressureController inverted_emergency(80, 50, 20);
  EXPECT_EQ(inverted_emergency.Update(
                PressureSignals{0, 0, 0, 0, 80}).state,
            PressureState::kDiskEmergency);
}

TEST(PressureControllerTest, SelectsCauseWithDeterministicSafetyTies) {
  PressureController controller(80, 50, 150);
  PressureSignals tied{80, 80, 80, 80, 80};
  EXPECT_EQ(controller.Update(tied).cause, PressureCause::kDisk);

  PressureController without_disk(80, 50, 150);
  tied.disk_pressure_bytes = 0;
  EXPECT_EQ(without_disk.Update(tied).cause, PressureCause::kWal);

  const std::vector<std::pair<PressureSignals, PressureCause>> causes{
      {PressureSignals{80, 0, 0, 0, 0}, PressureCause::kMemtable},
      {PressureSignals{0, 80, 0, 0, 0}, PressureCause::kWal},
      {PressureSignals{0, 0, 80, 0, 0}, PressureCause::kCompaction},
      {PressureSignals{0, 0, 0, 80, 0}, PressureCause::kCache},
      {PressureSignals{0, 0, 0, 0, 80}, PressureCause::kDisk},
  };
  for (const auto& test : causes) {
    PressureController one_cause(80, 50, 150);
    EXPECT_EQ(one_cause.Update(test.first).cause, test.second);
  }
}

TEST(PressureControllerTest, RetainsSafetyStateAndCauseUntilLowWatermark) {
  PressureController controller(80, 50, 150);
  EXPECT_EQ(controller.Update(PressureSignals{0, 0, 0, 0, 160}).state,
            PressureState::kDiskEmergency);
  const PressureDecision retained =
      controller.Update(PressureSignals{60, 0, 0, 0, 0});
  EXPECT_EQ(retained.state, PressureState::kDiskEmergency);
  EXPECT_EQ(retained.cause, PressureCause::kDisk);
  const PressureDecision recovered =
      controller.Update(PressureSignals{50, 0, 0, 0, 0});
  EXPECT_EQ(recovered.state, PressureState::kNormal);
  EXPECT_EQ(recovered.cause, PressureCause::kNone);

  PressureController write_stall(80, 50, 150);
  EXPECT_EQ(write_stall.Update(PressureSignals{0, 80, 0, 0, 0}).state,
            PressureState::kWriteStall);
  const PressureDecision held =
      write_stall.Update(PressureSignals{0, 0, 60, 0, 0});
  EXPECT_EQ(held.state, PressureState::kWriteStall);
  EXPECT_EQ(held.cause, PressureCause::kWal);
  EXPECT_TRUE(write_stall.Update(50));
}

TEST(PressureControllerTest, EscalatesSafetyWhenAggregatePressureFalls) {
  PressureController disk_emergency(80, 50, 150);
  EXPECT_EQ(
      disk_emergency.Update(PressureSignals{0, 0, 200, 0, 0}).state,
      PressureState::kHardPressure);
  const PressureDecision disk_escalation =
      disk_emergency.Update(PressureSignals{0, 0, 0, 0, 160});
  EXPECT_EQ(disk_escalation.state, PressureState::kDiskEmergency);
  EXPECT_EQ(disk_escalation.cause, PressureCause::kDisk);
  EXPECT_FALSE(disk_escalation.admit_writes);

  PressureController write_stall(80, 50, 150);
  EXPECT_EQ(write_stall.Update(PressureSignals{0, 0, 100, 0, 0}).state,
            PressureState::kHardPressure);
  const PressureDecision wal_escalation =
      write_stall.Update(PressureSignals{0, 90, 0, 0, 0});
  EXPECT_EQ(wal_escalation.state, PressureState::kWriteStall);
  EXPECT_EQ(wal_escalation.cause, PressureCause::kWal);
  EXPECT_FALSE(wal_escalation.admit_writes);
}

TEST(PressureControllerTest, SafetyThresholdsOverrideHigherDiagnosticSignals) {
  PressureController wal_safety(80, 50, 150);
  const PressureDecision wal_decision =
      wal_safety.Update(PressureSignals{0, 80, 90, 0, 0});
  EXPECT_EQ(wal_decision.state, PressureState::kWriteStall);
  EXPECT_EQ(wal_decision.cause, PressureCause::kCompaction);
  EXPECT_FALSE(wal_decision.admit_writes);
  EXPECT_TRUE(wal_decision.require_flush);
  EXPECT_TRUE(wal_decision.require_urgent_compaction);

  PressureController disk_safety(80, 50, 150);
  const PressureDecision disk_decision =
      disk_safety.Update(PressureSignals{0, 0, 0, 160, 150});
  EXPECT_EQ(disk_decision.state, PressureState::kDiskEmergency);
  EXPECT_EQ(disk_decision.cause, PressureCause::kCache);
  EXPECT_FALSE(disk_decision.admit_writes);
  EXPECT_TRUE(disk_decision.require_urgent_compaction);
  EXPECT_TRUE(disk_decision.require_blob_gc);
}

TEST(PressureControllerTest, RecordsCauseAndTransitionTelemetry) {
  PressureController controller(80, 50, 150);
  MetricRegistry metrics(13);
  ASSERT_TRUE(controller.ExportMetrics(&metrics).ok());
  EXPECT_EQ(metrics.Counter("cedar_pressure_state", "normal"), 1U);
  EXPECT_EQ(metrics.Counter("cedar_pressure_transitions_total", "memtable"), 0U);

  controller.Update(PressureSignals{60, 0, 0, 0, 0});
  controller.Update(PressureSignals{0, 0, 80, 0, 0});
  controller.Update(PressureSignals{0, 0, 60, 0, 0});
  controller.Update(PressureSignals{0, 0, 50, 0, 0});
  ASSERT_TRUE(controller.ExportMetrics(&metrics).ok());
  EXPECT_EQ(metrics.Counter("cedar_pressure_transitions_total", "memtable"), 1U);
  EXPECT_EQ(metrics.Counter("cedar_pressure_transitions_total", "compaction"), 1U);
  EXPECT_EQ(metrics.Counter("cedar_pressure_transitions_total", "none"), 1U);
  EXPECT_EQ(metrics.Counter("cedar_pressure_state", "normal"), 1U);
  EXPECT_EQ(metrics.Counter("cedar_pressure_state", "soft_pressure"), 0U);
  EXPECT_EQ(metrics.Counter("cedar_pressure_state", "hard_pressure"), 0U);

  const auto before = metrics.Counter(
      "cedar_pressure_transitions_total", "compaction");
  ASSERT_TRUE(controller.ExportMetrics(&metrics).ok());
  EXPECT_EQ(metrics.Counter("cedar_pressure_transitions_total", "compaction"), before);
  for (const MetricPoint& point : metrics.Snapshot()) {
    if (point.definition.name == "cedar_pressure_transitions_total") {
      EXPECT_EQ(point.values.size(), 6U);
    }
    if (point.definition.name == "cedar_pressure_state") {
      EXPECT_EQ(point.definition.type, MetricType::kGauge);
      EXPECT_EQ(point.values.size(), 7U);
    }
  }
}

TEST(StorageShardTest, ReportsActiveAndFrozenMemtableUsageSeparately) {
  StorageShard shard(0);
  const PendingEvent event = PendingEvent::Put(
      LogicalKey::VertexProperty(17, 3), 10, 1, Value::String("memtable accounting"));
  ASSERT_TRUE(shard.InstallCommitted(1, 1, {event}).ok());
  const MemtableUsage active = shard.memtable_usage();
  EXPECT_EQ(active.active_event_count, 1U);
  EXPECT_EQ(active.frozen_event_count, 0U);
  EXPECT_GT(active.active_bytes, 0U);
  EXPECT_EQ(active.total_bytes(), active.active_bytes);

  ASSERT_EQ(shard.FreezeForFlush().size(), 1U);
  const MemtableUsage frozen = shard.memtable_usage();
  EXPECT_EQ(frozen.active_event_count, 0U);
  EXPECT_EQ(frozen.frozen_event_count, 1U);
  EXPECT_EQ(frozen.total_bytes(), frozen.frozen_bytes);
}

