    CacheManager cache(4, &governor);
    const CacheKey key{CacheKind::kPage, "page-a"};
    ASSERT_TRUE(cache.Insert(key, std::make_shared<const std::string>("old!"),
                             CacheAdmission::kPointRead)
                    .ok());
