TEST_F(DurableLogTest, DatabasePointReadMakesNestedSchedulerProgress) {
  CedarDatabase database(path_, 1, 11);
  ASSERT_TRUE(database.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 26, 0, "score", PhysicalType::kInt64,
                      4096, EncodingPolicy::kAdaptive,
                      CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(database.RegisterColumn(schema, &registered).ok());
  const LogicalKey key = LogicalKey::VertexProperty(8, 26);
  ASSERT_TRUE(database.Put(
      key, 10, registered.schema_epoch, Value::Int64(84)).ok());

  WorkExecutionService* service =
      CedarDatabaseTestAccess::work_execution_service(&database);
  ASSERT_NE(service, nullptr);
  std::mutex gate_mutex;
  std::condition_variable gate_cv;
  uint32_t blockers_entered = 0;
  bool release_blockers = false;
  std::vector<WorkTaskHandle> blockers;
  for (uint32_t index = 0; index < 3; ++index) {
    const auto submitted = service->Submit(
        WorkClass::kAnalyticalQuery, [&] {
          std::unique_lock<std::mutex> lock(gate_mutex);
          ++blockers_entered;
          gate_cv.notify_all();
          gate_cv.wait(lock, [&] { return release_blockers; });
          return Status::OK();
        });
    ASSERT_TRUE(submitted.ok()) << submitted.status().ToString();
    blockers.push_back(submitted.ValueOrDie());
  }
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    ASSERT_TRUE(gate_cv.wait_for(
        lock, std::chrono::seconds(2), [&] { return blockers_entered == 3; }));
  }

  bool outer_entered = false;
  bool point_read_completed = false;
  Status point_read_status =
      Status::InvalidArgument("test", "nested point read did not run");
  std::optional<Value> point_read_value;
  const auto outer = service->Submit(
      WorkClass::kInteractiveQuery, [&] {
        {
          std::lock_guard<std::mutex> lock(gate_mutex);
          outer_entered = true;
          gate_cv.notify_all();
        }
        const auto value = database.Get(key, 10);
        {
          std::lock_guard<std::mutex> lock(gate_mutex);
          point_read_status = value.ok() ? Status::OK() : value.status();
          if (value.ok()) point_read_value = value.ValueOrDie();
          point_read_completed = true;
        }
        gate_cv.notify_all();
        return point_read_status;
      });
  ASSERT_TRUE(outer.ok()) << outer.status().ToString();
  bool completed_without_releasing_workers = false;
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    completed_without_releasing_workers = gate_cv.wait_for(
        lock, std::chrono::seconds(2), [&] { return point_read_completed; });
    release_blockers = true;
  }
  gate_cv.notify_all();
  for (const WorkTaskHandle& blocker : blockers) {
    EXPECT_TRUE(blocker.Wait().ok());
  }
  EXPECT_TRUE(outer.ValueOrDie().Wait().ok()) << point_read_status.ToString();

  EXPECT_TRUE(outer_entered);
  EXPECT_TRUE(completed_without_releasing_workers);
  EXPECT_TRUE(point_read_status.ok()) << point_read_status.ToString();
  ASSERT_TRUE(point_read_value.has_value());
  EXPECT_EQ(*point_read_value, Value::Int64(84));
}

