TEST_F(DurableLogTest, PressureStallsNewWritesWhenFailedFlushRetainsFrozenMemtable) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 24, 0, "name", PhysicalType::kString,
                      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());

  // The first commit gets through pre-prepare admission. Its pressure-driven
  // flush cannot reserve temporary output bytes, so the frozen generation is
  // deliberately retained and becomes the input to the next admission check.
  ResourceGovernor no_flush_space(ResourceProfile{1024, 1024, 1024, 0,
                                                    1, 0, 0, 1024, 4});
  PressureController pressure(128, 64, 192);
  coordinator.SetResourceGovernor(&no_flush_space);
  coordinator.SetPressureController(&pressure);
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexProperty(9, 24), 10, registered.schema_epoch,
                        Value::String(std::string(256, 'x'))),
  }, &commit_seq).ok());
  EXPECT_EQ(coordinator.pressure_state(), PressureState::kWriteStall);
  EXPECT_GT(coordinator.pressure_signals().memtable_bytes, 192U);
  EXPECT_TRUE(coordinator.AdmitQuery(true).IsResourceExhausted());
  EXPECT_TRUE(coordinator.AdmitQuery(false).ok());

  EXPECT_TRUE(coordinator.Commit(coordinator.visible_seq(), {
      PendingEvent::Put(LogicalKey::VertexProperty(10, 24), 10, registered.schema_epoch,
                        Value::String("must not prepare")),
  }, &commit_seq).IsWriteStalled());
  EXPECT_EQ(coordinator.visible_seq(), 1U);
}

