TEST_F(DurableLogTest, PressureRefreshCancelsQueuedAnalyticalWork) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(service.Start().ok());
  ASSERT_TRUE(coordinator.SetWorkExecutionService(&service).ok());
  ASSERT_TRUE(coordinator.Open().ok());

  std::mutex blocker_mutex;
  std::condition_variable blocker_ready;
  std::condition_variable unblock_worker;
  bool entered = false;
  bool release_worker = false;
  auto blocker = service.Submit(WorkClass::kCommitCritical, [&] {
    std::unique_lock<std::mutex> lock(blocker_mutex);
    entered = true;
    blocker_ready.notify_one();
    unblock_worker.wait(lock, [&] { return release_worker; });
    return Status::OK();
  });
  ASSERT_TRUE(blocker.ok());
  {
    std::unique_lock<std::mutex> lock(blocker_mutex);
    blocker_ready.wait(lock, [&] { return entered; });
  }
  auto analytical = service.Submit(
      WorkClass::kAnalyticalQuery, [] { return Status::OK(); });
  ASSERT_TRUE(analytical.ok());

  coordinator.SetDiskAvailableBytesProviderForTesting([] { return 0; });
  PressureController pressure(80, 50, 150);
  coordinator.SetPressureController(&pressure);
  Status admission = Status::InvalidArgument("test", "admission did not run");
  std::thread admit_thread([&] { admission = coordinator.AdmitQuery(false); });
  EXPECT_TRUE(analytical.ValueOrDie().Wait().IsQueryCancelled());
  EXPECT_EQ(service.stats().cancelled[8], 1U);

  {
    std::lock_guard<std::mutex> lock(blocker_mutex);
    release_worker = true;
  }
  unblock_worker.notify_one();
  admit_thread.join();
  EXPECT_TRUE(admission.ok());
  EXPECT_TRUE(blocker.ValueOrDie().Wait().ok());
  EXPECT_TRUE(service.Stop().ok());
}

TEST_F(DurableLogTest, PressureActionsCompleteWhenTriggeredFromOnlyWorker) {
  struct CompletionState {
    std::mutex mutex;
    std::condition_variable ready;
    bool completed = false;
    Status status = Status::InvalidArgument("test", "worker did not run");
  };
  auto state = std::make_shared<CompletionState>();
  auto* scheduler = new WorkScheduler();
  auto* service = new WorkExecutionService(scheduler, 1);
  auto* coordinator = new TransactionCoordinator(path_, 1, 11);
  auto* pressure = new PressureController(80, 50, 150);
  ASSERT_TRUE(service->Start().ok());
  ASSERT_TRUE(coordinator->SetWorkExecutionService(service).ok());
  ASSERT_TRUE(coordinator->Open().ok());
  coordinator->SetDiskAvailableBytesProviderForTesting([] { return 0; });
  coordinator->SetPressureController(pressure);

  const auto trigger = service->Submit(WorkClass::kPointRead,
                                       [coordinator, state] {
    const Status status = coordinator->AdmitQuery(false);
    {
      std::lock_guard<std::mutex> lock(state->mutex);
      state->status = status;
      state->completed = true;
    }
    state->ready.notify_one();
    return status;
  });
  ASSERT_TRUE(trigger.ok()) << trigger.status().ToString();
  {
    std::unique_lock<std::mutex> lock(state->mutex);
    if (!state->ready.wait_for(lock, std::chrono::seconds(2),
                               [&] { return state->completed; })) {
      ADD_FAILURE() << "pressure action deadlocked the only execution worker";
      return;
    }
  }

  EXPECT_TRUE(state->status.ok()) << state->status.ToString();
  EXPECT_TRUE(trigger.ValueOrDie().Wait().ok());
  const WorkExecutionStats stats = service->stats();
  EXPECT_EQ(stats.submitted[7], 1U);
  EXPECT_EQ(stats.completed[7], 1U);
  EXPECT_EQ(stats.submitted[12], 1U);
  EXPECT_EQ(stats.completed[12], 1U);
  EXPECT_TRUE(service->Stop().ok());
  delete coordinator;
  delete pressure;
  delete service;
  delete scheduler;
}

