TEST_F(DurableLogTest, DatabaseExportsSchedulerResourceAndPressureMetrics) {
  CedarDatabase database(path_, 1, 11);
  ASSERT_TRUE(database.Open().ok());
  const auto find_metric = [&](const std::string& name) -> MetricPoint {
    for (const MetricPoint& point : database.metrics().Snapshot()) {
      if (point.definition.name == name) return point;
    }
    return MetricPoint{};
  };

  EXPECT_EQ(find_metric("cedar_scheduler_tasks_submitted_total").values.size(), 13U);
  EXPECT_EQ(find_metric("cedar_pressure_state").values.size(), 7U);
  const MetricPoint resource_bytes = find_metric("cedar_resource_used_bytes");
  const MetricPoint resource_units = find_metric("cedar_resource_used_units");
  EXPECT_EQ(resource_bytes.definition.type, MetricType::kGauge);
  EXPECT_EQ(resource_units.definition.type, MetricType::kGauge);
  EXPECT_EQ(resource_bytes.values.size() + resource_units.values.size(), 9U);

  ColumnSchema schema{EntityType::Vertex, 25, 0, "name", PhysicalType::kString,
                      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(database.RegisterColumn(schema, &registered).ok());
  ASSERT_TRUE(database.Put(LogicalKey::VertexProperty(1, 25), 10,
                           registered.schema_epoch, Value::String("telemetry")).ok());
  ASSERT_TRUE(database.Flush().ok());
  const uint64_t submitted = database.metrics().Counter(
      "cedar_scheduler_tasks_submitted_total", "flush").value_or(0);
  EXPECT_GE(submitted, 1U);
  EXPECT_GE(database.metrics().Counter(
      "cedar_scheduler_tasks_admitted_total", "flush").value_or(0), 1U);
  EXPECT_GE(database.metrics().Counter(
      "cedar_scheduler_tasks_completed_total", "flush").value_or(0), 1U);
  EXPECT_EQ(database.metrics().Counter("cedar_pressure_state", "normal"), 1U);
  EXPECT_EQ(database.metrics().Counter(
      "cedar_scheduler_tasks_submitted_total", "flush"), submitted);

  const std::string exported = database.ExportMetricsJson();
  EXPECT_NE(exported.find("cedar_scheduler_tasks_submitted_total"), std::string::npos);
  EXPECT_NE(exported.find("cedar_resource_used_bytes"), std::string::npos);
  EXPECT_NE(exported.find("cedar_pressure_transitions_total"), std::string::npos);
}

