TEST_F(DurableLogTest, BlobRotationUsesTypedMaintenanceAdmission) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(service.Start().ok());
  ASSERT_TRUE(coordinator.SetWorkExecutionService(&service).ok());
  ASSERT_TRUE(coordinator.Open().ok());

  std::mutex hook_mutex;
  std::condition_variable hook_ready;
  std::condition_variable hook_release;
  bool entered = false;
  bool release = false;
  std::thread::id callback_thread;
  coordinator.SetBlobRotationExecutionHookForTesting([&] {
    {
      std::lock_guard<std::mutex> lock(hook_mutex);
      entered = true;
      callback_thread = std::this_thread::get_id();
    }
    hook_ready.notify_one();
    std::unique_lock<std::mutex> lock(hook_mutex);
    hook_release.wait(lock, [&] { return release; });
  });

  const std::thread::id caller_thread = std::this_thread::get_id();
  Status rotation_status = Status::InvalidArgument("test", "rotation did not finish");
  std::thread rotation_thread([&] {
    rotation_status = coordinator.RotateBlobSegments();
  });
  {
    std::unique_lock<std::mutex> lock(hook_mutex);
    ASSERT_TRUE(hook_ready.wait_for(lock, std::chrono::seconds(2),
                                    [&] { return entered; }));
  }
  EXPECT_NE(callback_thread, caller_thread);
  EXPECT_EQ(service.stats().submitted[3], 1U);
  EXPECT_EQ(service.stats().admitted[3], 1U);
  {
    std::lock_guard<std::mutex> lock(hook_mutex);
    release = true;
  }
  hook_release.notify_one();
  rotation_thread.join();
  EXPECT_TRUE(rotation_status.ok()) << rotation_status.ToString();
  EXPECT_EQ(service.stats().completed[3], 1U);
  EXPECT_TRUE(service.Stop().ok());
}

