TEST_F(DurableLogTest, BlobRotationFaultRequiresReopenWithoutLosingManifestState) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  coordinator.SetVersionSetFaultInjectorForTesting(
      [](VersionSetFaultPoint point) {
        return point == VersionSetFaultPoint::kAfterManifestRename
                   ? Status::IOError("test", "rotation manifest fault")
                   : Status::OK();
      });
  const Status failed = coordinator.RotateBlobSegments();
  EXPECT_TRUE(failed.IsIndeterminate()) << failed.ToString();
  EXPECT_TRUE(coordinator.recovery_required());
  coordinator.SetVersionSetFaultInjectorForTesting({});
  ASSERT_TRUE(coordinator.Open().ok());
  EXPECT_FALSE(coordinator.recovery_required());
  ASSERT_EQ(coordinator.version_snapshot()->blob_segments.size(), 1U);
  EXPECT_TRUE(coordinator.version_snapshot()->blob_segments[0].active);
}

