TEST_F(DurableLogTest, ConcurrentDatabaseOpenDoesNotRunRecoveryTwice) {
  CedarDatabase db(path_, 1, 11);
  std::mutex hook_mutex;
  std::condition_variable hook_cv;
  bool entered = false;
  bool release = false;
  uint32_t recovery_calls = 0;
  CedarDatabaseTestAccess::SetRecoveryExecutionHook(&db, [&] {
    std::unique_lock<std::mutex> lock(hook_mutex);
    ++recovery_calls;
    entered = true;
    hook_cv.notify_all();
    hook_cv.wait(lock, [&] { return release; });
  });

  Status first = Status::InvalidArgument("test", "first open did not run");
  std::thread opener([&] { first = db.Open(); });
  {
    std::unique_lock<std::mutex> lock(hook_mutex);
    ASSERT_TRUE(hook_cv.wait_for(lock, std::chrono::seconds(2),
                                 [&] { return entered; }));
  }
  const Status second = db.Open();
  EXPECT_TRUE(second.IsInvalidArgument()) << second.ToString();
  EXPECT_NE(second.ToString().find("already attempted"), std::string::npos);
  {
    std::lock_guard<std::mutex> lock(hook_mutex);
    release = true;
  }
  hook_cv.notify_all();
  opener.join();
  EXPECT_TRUE(first.ok()) << first.ToString();
  EXPECT_EQ(recovery_calls, 1U);
}

TEST_F(DurableLogTest,
       DatabaseExportsRealColumnarBlobCompactionAndGcMetrics) {
  CedarDatabase database(path_, 1, 11);
  ASSERT_TRUE(database.Open().ok());

  ColumnSchema existence;
  ASSERT_TRUE(database.RegisterColumn(
      ColumnSchema{EntityType::Vertex, 0, 0, "existence",
                   PhysicalType::kBinary, 4096, EncodingPolicy::kAdaptive,
                   CompressionPolicy::kLz4},
      &existence).ok());
  ColumnSchema property;
  ASSERT_TRUE(database.RegisterColumn(
      ColumnSchema{EntityType::Vertex, 37, 0, "payload",
                   PhysicalType::kString, 8, EncodingPolicy::kAdaptive,
                   CompressionPolicy::kLz4},
      &property).ok());

  const std::string first_payload(8192, 'a');
  const std::string second_payload(8192, 'b');
  for (uint64_t vertex_id : {1ULL, 2ULL}) {
    ASSERT_TRUE(database.Put(LogicalKey::VertexExistence(vertex_id), 10,
                             existence.schema_epoch, Value::Binary("")).ok());
    ASSERT_TRUE(database.Put(LogicalKey::VertexProperty(vertex_id, 37), 10,
                             property.schema_epoch,
                             Value::String(first_payload)).ok());
  }
  ASSERT_TRUE(database.Flush().ok());
  for (uint64_t vertex_id : {1ULL, 2ULL}) {
    ASSERT_TRUE(database.Put(LogicalKey::VertexExistence(vertex_id), 20,
                             existence.schema_epoch, Value::Binary("")).ok());
    ASSERT_TRUE(database.Put(LogicalKey::VertexProperty(vertex_id, 37), 20,
                             property.schema_epoch,
                             Value::String(second_payload)).ok());
  }
  ASSERT_TRUE(database.Flush().ok());

  const auto value = database.Get(LogicalKey::VertexProperty(1, 37), 20);
  ASSERT_TRUE(value.ok()) << value.status().ToString();
  ASSERT_TRUE(value.ValueOrDie().has_value());
  EXPECT_EQ(*value.ValueOrDie(), Value::String(second_payload));
  const auto cached_value =
      database.Get(LogicalKey::VertexProperty(1, 37), 20);
  ASSERT_TRUE(cached_value.ok()) << cached_value.status().ToString();
  EXPECT_EQ(cached_value.ValueOrDie(), value.ValueOrDie());

  auto query = database.ExecuteTcypher("MATCH (n) RETURN n;");
  ASSERT_TRUE(query.ok()) << query.status().ToString();
  for (;;) {
    ResultBatch batch;
    const Status next = query.ValueOrDie()->Next(&batch);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
  }

  ASSERT_TRUE(database.Compact().ok());
  ASSERT_TRUE(database.RotateBlobSegments().ok());
  ASSERT_TRUE(database.CollectBlobGarbage().ok());

  const auto metric = [&](const std::string& name,
                          const std::string& label) -> uint64_t {
    return database.metrics().Counter(name, label).value_or(0);
  };
  EXPECT_GT(metric("cedar_storage_bytes", "page_decoded"), 0U);
  EXPECT_GT(metric("cedar_storage_bytes", "sst_physical_read"), 0U);
  EXPECT_GT(metric("cedar_storage_bytes", "blob_payload_read"), 0U);
  EXPECT_GT(metric("cedar_storage_bytes", "blob_payload_written"), 0U);
  EXPECT_GT(metric("cedar_storage_bytes", "blob_payload_deduplicated"), 0U);
  EXPECT_GT(metric("cedar_storage_bytes", "compaction_input"), 0U);
  EXPECT_GT(metric("cedar_storage_bytes", "compaction_output"), 0U);
  EXPECT_EQ(metric("cedar_storage_bytes", "compaction_blob_payload_read"),
            0U);
  EXPECT_GT(metric("cedar_storage_bytes", "blob_gc_live"), 0U);
  EXPECT_GT(metric("cedar_storage_bytes", "blob_gc_rewritten"), 0U);
  EXPECT_GT(metric("cedar_storage_operations", "page_decode"), 0U);
  EXPECT_GT(metric("cedar_storage_operations", "blob_lookup"), 0U);
  EXPECT_GT(metric("cedar_storage_latency_ns", "page_decode"), 0U);
  EXPECT_GT(metric("cedar_storage_latency_ns", "blob_lookup"), 0U);
  EXPECT_GT(metric("cedar_cache_hit_total", "page"), 0U);
  EXPECT_GT(metric("cedar_cache_miss_total", "page"), 0U);
  EXPECT_GT(metric("cedar_cache_hit_total", "metadata"), 0U);
  EXPECT_GT(metric("cedar_cache_miss_total", "metadata"), 0U);
  EXPECT_GT(metric("cedar_cache_hit_total", "blob_value"), 0U);
  EXPECT_GT(metric("cedar_cache_miss_total", "blob_value"), 0U);
  for (const std::string& page_type :
       {"entity_id", "operation", "typed_value"}) {
    EXPECT_GT(metric("cedar_page_uncompressed_bytes_total", page_type), 0U)
        << page_type;
    EXPECT_GT(metric("cedar_page_stored_bytes_total", page_type), 0U)
        << page_type;
  }

  const std::string exported = database.ExportMetricsJson();
  EXPECT_NE(exported.find("cedar_storage_bytes"), std::string::npos);
  EXPECT_NE(exported.find("cedar_storage_operations"), std::string::npos);
  EXPECT_NE(exported.find("cedar_storage_latency_ns"), std::string::npos);
  EXPECT_NE(exported.find("cedar_page_uncompressed_bytes_total"),
            std::string::npos);
  EXPECT_NE(exported.find("cedar_page_stored_bytes_total"),
            std::string::npos);
  EXPECT_NE(exported.find("cedar_cache_hit_total"), std::string::npos);
  EXPECT_NE(exported.find("cedar_cache_miss_total"), std::string::npos);
}

TEST_F(DurableLogTest, DatabaseExportsSampledOperationAndCompletedQueryTraces) {
  TelemetryAggregatorConfig trace_config;
  trace_config.input_capacity = 64;
  trace_config.correctness_reserve = 8;
  trace_config.retained_capacity = 64;
  trace_config.base_sampling_per_mille = 1000;
  CedarDatabase database(path_, 1, 31, trace_config);
  ASSERT_TRUE(database.Open().ok());
  ColumnSchema registered;
  ASSERT_TRUE(database.RegisterColumn(
      ColumnSchema{EntityType::Vertex, 0, 0, "existence",
                   PhysicalType::kBinary, 4096, EncodingPolicy::kAdaptive,
                   CompressionPolicy::kLz4},
      &registered).ok());
  ASSERT_TRUE(database.Put(LogicalKey::VertexExistence(1), 0,
                           registered.schema_epoch, Value::Binary("")).ok());
  const auto value = database.Get(LogicalKey::VertexExistence(1), 0);
  ASSERT_TRUE(value.ok());
  ASSERT_TRUE(value.ValueOrDie().has_value());
  auto opened = database.ExecuteTcypher("MATCH (n) RETURN n;");
  ASSERT_TRUE(opened.ok()) << opened.status().ToString();
  for (;;) {
    ResultBatch batch;
    const Status next = opened.ValueOrDie()->Next(&batch);
    if (next.IsNotFound()) break;
    ASSERT_TRUE(next.ok()) << next.ToString();
  }
  ASSERT_TRUE(database.Flush().ok());

  const std::string traces = database.ExportTracesJson(false);
  EXPECT_NE(traces.find("\"trace_schema_version\":1"), std::string::npos);
  EXPECT_NE(traces.find("\"category\":\"transaction\""), std::string::npos);
  EXPECT_NE(traces.find("\"name\":\"put\""), std::string::npos);
  EXPECT_NE(traces.find("\"category\":\"point_read\""), std::string::npos);
  EXPECT_NE(traces.find("\"category\":\"query\""), std::string::npos);
  EXPECT_NE(traces.find("\"name\":\"interactive_execute\""),
            std::string::npos);
  EXPECT_NE(traces.find("\"category\":\"maintenance\""),
            std::string::npos);
  EXPECT_NE(traces.find("\"name\":\"flush\""), std::string::npos);
  EXPECT_EQ(traces.find("MATCH (n) RETURN n"), std::string::npos);

  const std::string metrics = database.ExportMetricsJson();
  EXPECT_NE(metrics.find("cedar_trace_sampling_per_mille"), std::string::npos);
  EXPECT_NE(metrics.find("cedar_trace_retained_events"), std::string::npos);
  EXPECT_NE(metrics.find("cedar_trace_dropped_events"), std::string::npos);
}

