TEST_F(DurableLogTest, CompactionPublishesOneOutputAndReclaimsReleasedInputs) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 25, 0, "score", PhysicalType::kInt64,
                      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
  uint64_t commit_seq = 0;
  const LogicalKey first = LogicalKey::VertexProperty(100, 25);
  const LogicalKey second = LogicalKey::VertexProperty(101, 25);
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(first, 10, registered.schema_epoch, Value::Int64(10)),
  }, &commit_seq).ok());
  ASSERT_TRUE(coordinator.Flush().ok());
  ASSERT_TRUE(coordinator.Commit(coordinator.visible_seq(), {
      PendingEvent::Put(second, 10, registered.schema_epoch, Value::Int64(20)),
  }, &commit_seq).ok());
  ASSERT_TRUE(coordinator.Flush().ok());
  auto inputs = coordinator.version_snapshot();
  ASSERT_EQ(inputs->files.size(), 2U);
  std::vector<std::string> input_paths;
  for (const SstFileMeta& file : inputs->files) input_paths.push_back(path_ + "/" + file.relative_path);

  ASSERT_TRUE(coordinator.Compact().ok());
  EXPECT_EQ(coordinator.version_snapshot()->files.size(), 1U);
  const auto first_value = coordinator.GetChecked(first, 10);
  const auto second_value = coordinator.GetChecked(second, 10);
  ASSERT_TRUE(first_value.ok()) << first_value.status().ToString();
  ASSERT_TRUE(second_value.ok()) << second_value.status().ToString();
  EXPECT_EQ(*first_value.ValueOrDie(), Value::Int64(10));
  EXPECT_EQ(*second_value.ValueOrDie(), Value::Int64(20));

  inputs.reset();
  ASSERT_TRUE(coordinator.Compact().ok());
  for (const std::string& input_path : input_paths) EXPECT_FALSE(std::filesystem::exists(input_path));
}

TEST_F(DurableLogTest, CompactionStreamsSortedSstBlocksWithBoundedEventBuffering) {
  VersionSet versions(path_ + "/manifest/MANIFEST");
  ASSERT_TRUE(versions.Open().ok());
  const BlockPartition partition{EntityType::Vertex, 25, 1, PhysicalType::kInt64};
  std::vector<SstFileMeta> inputs;
  constexpr uint64_t kEventsPerInput = 20000;
  for (uint64_t input = 0; input < 2; ++input) {
    std::vector<TemporalEvent> events;
    events.reserve(kEventsPerInput);
    for (uint64_t row = 0; row < kEventsPerInput; ++row) {
      const uint64_t entity_id = input * kEventsPerInput + row;
      events.push_back(TemporalEvent::Put(
          LogicalKey::VertexProperty(entity_id, 25), 10, entity_id + 1, 1,
          Value::Int64(static_cast<int64_t>(entity_id))));
    }
    const uint64_t file_number = input + 1;
    const std::string relative = "shards/0/sst/" +
        std::to_string(file_number) + ".sst";
    SstFile written;
    ASSERT_TRUE(WriteSstFile(path_ + "/" + relative, partition, events,
                               &written).ok());
    inputs.push_back(SstFileMeta{
        file_number, relative, partition,
        std::filesystem::file_size(path_ + "/" + relative),
        std::move(written.blob_refs), written.metadata.format,
        written.metadata.identity, written.metadata.statistics,
        written.metadata.statistics_crc32c});
  }
  VersionEdit bootstrap;
  bootstrap.adds = inputs;
  bootstrap.schema_adds = TestSchemasForPartition(partition);
  ASSERT_TRUE(versions.ApplyEdit(bootstrap).ok());

  const auto compacted = CompactSstPartition(path_, inputs, 3, &versions);
  ASSERT_TRUE(compacted.ok()) << compacted.status().ToString();
  EXPECT_LT(compacted.ValueOrDie().peak_buffered_events,
            2 * kEventsPerInput);
  EXPECT_EQ(compacted.ValueOrDie().output_bytes_written,
            std::filesystem::file_size(
                path_ + "/" + compacted.ValueOrDie().output.relative_path));
  const auto restored = ReadSstFile(
      path_ + "/" + compacted.ValueOrDie().output.relative_path);
  ASSERT_TRUE(restored.ok()) << restored.status().ToString();
  EXPECT_EQ(restored.ValueOrDie().size(), 2 * kEventsPerInput);
}

TEST_F(DurableLogTest, SstOrdinalReadDecodesOnlyPostingBlocks) {
  const BlockPartition partition{EntityType::Vertex, 25, 1,
                                 PhysicalType::kString};
  std::vector<TemporalEvent> events;
  for (uint64_t ordinal = 0; ordinal < 30; ++ordinal) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(ordinal + 1, 25), 10, ordinal + 1, 1,
        Value::String(std::string(150 * 1024,
                                  static_cast<char>('a' + ordinal % 20)))));
  }
  const std::string sst_path = path_ + "/shards/0/sst/ordinal.sst";
  SstFile written;
  ASSERT_TRUE(WriteSstFile(sst_path, partition, events, &written).ok());
  ASSERT_GT(written.block_count, 2U);
  SstReadStats stats;
  const auto selected = ReadSstEventsAtOrdinals(
      sst_path, partition, {0, 29}, nullptr, nullptr, &stats);
  ASSERT_TRUE(selected.ok()) << selected.status().ToString();
  EXPECT_EQ(selected.ValueOrDie().total_row_count, events.size());
  ASSERT_EQ(selected.ValueOrDie().events.size(), 2U);
  EXPECT_EQ(selected.ValueOrDie().events[0].first, 0U);
  EXPECT_EQ(selected.ValueOrDie().events[0].second.logical_key().entity_id(), 1U);
  EXPECT_EQ(selected.ValueOrDie().events[1].first, 29U);
  EXPECT_EQ(selected.ValueOrDie().events[1].second.logical_key().entity_id(), 30U);
  EXPECT_LT(stats.blocks_read, written.block_count);
}

TEST_F(DurableLogTest, SstOrdinalReadReservesDecodedBlockBeforeBlockIo) {
  const BlockPartition partition{EntityType::Vertex, 25, 1,
                                 PhysicalType::kString};
  std::vector<TemporalEvent> events;
  for (uint64_t ordinal = 0; ordinal < 8; ++ordinal) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(ordinal + 1, 25), 10, ordinal + 1, 1,
        Value::String(std::string(150 * 1024, 'x'))));
  }
  const std::string sst_path = path_ + "/shards/0/sst/ordinal-memory.sst";
  ASSERT_TRUE(WriteSstFile(sst_path, partition, events).ok());
  const uint64_t encoded_budget = 2 * std::filesystem::file_size(sst_path);
  auto memory = std::make_shared<QueryMemoryAccount>(
      encoded_budget / 2, encoded_budget);
  SstReadStats stats;
  const auto selected = ReadSstEventsAtOrdinals(
      sst_path, partition, {0}, nullptr, memory, &stats);
  EXPECT_TRUE(selected.status().IsQueryMemoryLimit())
      << selected.status().ToString();
  EXPECT_EQ(stats.blocks_read, 0U);
  EXPECT_EQ(memory->used_bytes(), 0U);
}

TEST_F(DurableLogTest, CompactionPreservesVersionChainAcrossContinuationBlocks) {
  VersionSet versions(path_ + "/manifest/MANIFEST");
  ASSERT_TRUE(versions.Open().ok());
  const BlockPartition partition{EntityType::Vertex, 25, 1, PhysicalType::kInt64};
  const LogicalKey key = LogicalKey::VertexProperty(7, 25);
  std::vector<SstFileMeta> inputs;
  constexpr uint64_t kVersionsPerInput = 9000;
  for (uint64_t input = 0; input < 2; ++input) {
    std::vector<TemporalEvent> events;
    events.reserve(kVersionsPerInput);
    for (uint64_t row = 1; row <= kVersionsPerInput; ++row) {
      const uint64_t version = input * kVersionsPerInput + row;
      events.push_back(TemporalEvent::Put(
          key, version, version, 1, Value::Int64(static_cast<int64_t>(version))));
    }
    const uint64_t file_number = input + 1;
    const std::string relative = "shards/0/sst/" +
        std::to_string(file_number) + ".sst";
    SstFile written;
    ASSERT_TRUE(WriteSstFile(path_ + "/" + relative, partition, events,
                               &written).ok());
    inputs.push_back(SstFileMeta{
        file_number, relative, partition,
        std::filesystem::file_size(path_ + "/" + relative),
        std::move(written.blob_refs), written.metadata.format,
        written.metadata.identity, written.metadata.statistics,
        written.metadata.statistics_crc32c});
  }
  VersionEdit bootstrap;
  bootstrap.adds = inputs;
  bootstrap.schema_adds = TestSchemasForPartition(partition);
  ASSERT_TRUE(versions.ApplyEdit(bootstrap).ok());
  const auto compacted = CompactSstPartition(path_, inputs, 3, &versions);
  ASSERT_TRUE(compacted.ok()) << compacted.status().ToString();
  const auto restored = ReadSstFile(
      path_ + "/" + compacted.ValueOrDie().output.relative_path);
  ASSERT_TRUE(restored.ok()) << restored.status().ToString();
  ASSERT_EQ(restored.ValueOrDie().size(), 2 * kVersionsPerInput);
  EXPECT_EQ(restored.ValueOrDie().front().valid_from(), 2 * kVersionsPerInput);
  EXPECT_EQ(restored.ValueOrDie().back().valid_from(), 1U);
}

