TEST_F(DurableLogTest,
       RunningNormalCompactionCancellationAtOutputBoundaryCleansOutput) {
  VersionSet versions(path_ + "/manifest/MANIFEST");
  ASSERT_TRUE(versions.Open().ok());
  const BlockPartition partition{EntityType::Vertex, 25, 1,
                                 PhysicalType::kInt64};
  std::vector<SstFileMeta> inputs;
  for (uint64_t file_number = 1; file_number <= 2; ++file_number) {
    const std::string relative = "shards/0/sst/" +
        std::to_string(file_number) + ".sst";
    SstFile written;
    ASSERT_TRUE(WriteSstFile(path_ + "/" + relative, partition, {
        TemporalEvent::Put(LogicalKey::VertexProperty(file_number, 25), 10,
                           file_number, 1, Value::Int64(file_number)),
    }, &written).ok());
    inputs.push_back(SstFileMeta{
        file_number, relative, partition,
        std::filesystem::file_size(path_ + "/" + relative),
        written.metadata.blob_refs, written.metadata.format,
        written.metadata.identity, written.metadata.statistics,
        written.metadata.statistics_crc32c});
  }
  VersionEdit bootstrap;
  bootstrap.adds = inputs;
  bootstrap.schema_adds = TestSchemasForPartition(partition);
  ASSERT_TRUE(versions.ApplyEdit(bootstrap).ok());
  const uint64_t generation = versions.Snapshot()->generation;
  uint64_t streaming_checkpoints = 0;
  auto cancellation = std::make_shared<WorkCancellation>();
  cancellation->SetCheckpointObserverForTesting(
      [&](WorkCancellation* token, const std::string& owner,
          uint64_t checkpoint) {
        if (owner != "sst streaming merge") return;
        streaming_checkpoints = checkpoint;
        if (checkpoint == 3) token->Cancel();
      });

  const auto compacted = CompactSstPartition(
      path_, inputs, 3, &versions, cancellation);
  EXPECT_TRUE(compacted.status().IsQueryCancelled())
      << compacted.status().ToString();
  EXPECT_EQ(versions.Snapshot()->generation, generation);
  EXPECT_EQ(streaming_checkpoints, 3U);
  EXPECT_FALSE(std::filesystem::exists(path_ + "/shards/0/sst/3.sst"));
  EXPECT_FALSE(std::filesystem::exists(path_ + "/shards/0/sst/3.sst.tmp"));
}

TEST_F(DurableLogTest, CompactionRetainsPossiblyPublishedOutputAfterManifestRename) {
  VersionSet versions(path_ + "/manifest/MANIFEST");
  ASSERT_TRUE(versions.Open().ok());
  const BlockPartition partition{EntityType::Vertex, 25, 1, PhysicalType::kInt64};
  std::vector<SstFileMeta> inputs;
  for (uint64_t file_number = 1; file_number <= 2; ++file_number) {
    const std::string relative = "shards/0/sst/" +
        std::to_string(file_number) + ".sst";
    SstFile written;
    ASSERT_TRUE(WriteSstFile(path_ + "/" + relative, partition, {
        TemporalEvent::Put(LogicalKey::VertexProperty(file_number, 25), 10,
                           file_number, 1, Value::Int64(file_number)),
    }, &written).ok());
    inputs.push_back(SstFileMeta{
        file_number, relative, partition,
        std::filesystem::file_size(path_ + "/" + relative),
        written.metadata.blob_refs, written.metadata.format,
        written.metadata.identity, written.metadata.statistics,
        written.metadata.statistics_crc32c});
  }
  VersionEdit bootstrap;
  bootstrap.adds = inputs;
  bootstrap.schema_adds = TestSchemasForPartition(partition);
  ASSERT_TRUE(versions.ApplyEdit(bootstrap).ok());
  auto cancellation = std::make_shared<WorkCancellation>();
  versions.SetFaultInjectorForTesting([&](VersionSetFaultPoint point) {
    if (point != VersionSetFaultPoint::kAfterManifestRename) {
      return Status::OK();
    }
    cancellation->Cancel();
    return Status::IOError("test", "post-rename failure");
  });

  const auto compacted = CompactSstPartition(
      path_, inputs, 3, &versions, cancellation);
  EXPECT_TRUE(compacted.status().IsIndeterminate())
      << compacted.status().ToString();
  EXPECT_TRUE(cancellation->IsCancelled());
  EXPECT_TRUE(std::filesystem::exists(path_ + "/shards/0/sst/3.sst"));
  EXPECT_TRUE(versions.ApplyEdit(VersionEdit{}).IsRecoveryRequired());

  VersionSet reopened(path_ + "/manifest/MANIFEST");
  ASSERT_TRUE(reopened.Open().ok());
  ASSERT_EQ(reopened.Snapshot()->files.size(), 1U);
  EXPECT_EQ(reopened.Snapshot()->files.front().file_number, 3U);
}

TEST_F(DurableLogTest, PointReadChargesSelectiveSstIoToTheDatabaseGovernor) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 25, 0, "score", PhysicalType::kInt64,
                      4096, EncodingPolicy::kAdaptive,
                      CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
  const LogicalKey key = LogicalKey::VertexProperty(9, 25);
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(key, 10, registered.schema_epoch, Value::Int64(42)),
  }, &commit_seq).ok());
  IoGovernor flush_io(IoGovernorLimits{
      IoTokenBudget{1U << 20, 0}, IoTokenBudget{16, 0},
      IoTokenBudget{1U << 20, 0}, IoTokenBudget{16, 0}});
  coordinator.SetIoGovernor(&flush_io);
  ASSERT_TRUE(coordinator.Flush().ok());

  IoGovernor no_random_reads(IoGovernorLimits{
      IoTokenBudget{1U << 20, 0}, IoTokenBudget{0, 0},
      IoTokenBudget{1U << 20, 0}, IoTokenBudget{16, 0}});
  coordinator.SetIoGovernor(&no_random_reads);
  const auto blocked = coordinator.GetChecked(key, 10, commit_seq);
  EXPECT_TRUE(blocked.status().IsQueryMemoryLimit())
      << blocked.status().ToString();
}

TEST_F(DurableLogTest, CommitRejectsBlobBeforeAnyDurableBlobWriteWhenCriticalIoIsExhausted) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 21, 0, "payload", PhysicalType::kBinary,
                      1, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
  IoGovernor exhausted(IoGovernorLimits{
      IoTokenBudget{0, 0}, IoTokenBudget{0, 0}, IoTokenBudget{0, 0},
      IoTokenBudget{16, 16}});
  coordinator.SetIoGovernor(&exhausted);

  uint64_t commit_seq = 0;
  EXPECT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexProperty(9, 21), 10, registered.schema_epoch,
                        Value::Binary("not durable")),
  }, &commit_seq).IsQueryMemoryLimit());
  EXPECT_FALSE(std::filesystem::exists(path_ + "/blobs"));
}

