TEST(EventRingTest, ReservesCapacityForCorrectnessEventsAndDropsSpansUnderPressure) {
  EventRing ring(3, 1);
  EXPECT_TRUE(ring.Push(TelemetryEvent{TelemetryEventKind::kSpan, {}, 1, "query", 1}));
  EXPECT_TRUE(ring.Push(TelemetryEvent{TelemetryEventKind::kSpan, {}, 2, "query", 2}));
  EXPECT_FALSE(ring.Push(TelemetryEvent{TelemetryEventKind::kSpan, {}, 3, "query", 3}));
  EXPECT_TRUE(ring.Push(TelemetryEvent{TelemetryEventKind::kCorrectness, {}, 4, "commit", 1}));
  EXPECT_FALSE(ring.Push(TelemetryEvent{TelemetryEventKind::kCorrectness, {}, 5, "commit", 2}));
  const EventRingStats stats = ring.stats();
  EXPECT_EQ(stats.accepted_spans, 2U);
  EXPECT_EQ(stats.accepted_correctness, 1U);
  EXPECT_EQ(stats.dropped_spans, 1U);
  EXPECT_EQ(stats.dropped_correctness, 1U);
}

TEST(TelemetryAggregatorTest, ExportsSampledParentedSpansAsStructuredJson) {
  TelemetryAggregatorConfig config;
  config.input_capacity = 8;
  config.correctness_reserve = 2;
  config.retained_capacity = 8;
  config.base_sampling_per_mille = 1000;
  TelemetryAggregator telemetry(config);
  ASSERT_TRUE(telemetry.Start().ok());
  const TraceContext root = telemetry.NewTrace(TracePriority::kNormal);
  const TraceContext child = telemetry.NewChild(root);
  ASSERT_TRUE(root.sampled);
  ASSERT_TRUE(telemetry.RecordSpan(
      root, TracePriority::kNormal, "query", "execute", 100, 40, "OK"));
  ASSERT_TRUE(telemetry.RecordSpan(
      child, TracePriority::kVerbose, "storage", "page_read", 110, 5, "OK"));
  ASSERT_TRUE(telemetry.Flush().ok());
  const TelemetryAggregatorStats stats = telemetry.stats();
  EXPECT_EQ(stats.accepted_spans, 2U);
  EXPECT_EQ(stats.retained_events, 2U);
  EXPECT_EQ(stats.current_sampling_per_mille, 1000U);
  const std::string json = telemetry.ExportTracesJson(false);
  EXPECT_NE(json.find("\"trace_schema_version\":1"), std::string::npos);
  EXPECT_NE(json.find("\"sampling_per_mille\":1000"), std::string::npos);
  EXPECT_NE(json.find("\"category\":\"query\""), std::string::npos);
  EXPECT_NE(json.find("\"name\":\"execute\""), std::string::npos);
  EXPECT_NE(json.find("\"category\":\"storage\""), std::string::npos);
  EXPECT_NE(json.find("\"parent_span_id\":" +
                      std::to_string(root.span_id)), std::string::npos);
  EXPECT_EQ(json.find("MATCH (n)"), std::string::npos);
  ASSERT_TRUE(telemetry.Stop().ok());
}

TEST(TelemetryAggregatorTest, DropsVerboseBeforeCorrectnessAndReducesSampling) {
  TelemetryAggregatorConfig config;
  config.input_capacity = 8;
  config.correctness_reserve = 2;
  config.retained_capacity = 3;
  config.base_sampling_per_mille = 1000;
  config.minimum_sampling_per_mille = 10;
  config.high_watermark_per_mille = 600;
  config.low_watermark_per_mille = 300;
  TelemetryAggregator telemetry(config);
  ASSERT_TRUE(telemetry.Start().ok());
  const TraceContext trace = telemetry.NewTrace(TracePriority::kNormal);
  for (uint64_t index = 0; index < 3; ++index) {
    ASSERT_TRUE(telemetry.RecordSpan(
        trace, TracePriority::kNormal, "query", "batch", index, 1, "OK"));
  }
  ASSERT_TRUE(telemetry.Flush().ok());
  EXPECT_EQ(telemetry.stats().current_sampling_per_mille, 10U);

  ASSERT_TRUE(telemetry.RecordSpan(
      trace, TracePriority::kVerbose, "storage", "page_read", 4, 1, "OK"));
  ASSERT_TRUE(telemetry.RecordCorrectness("commit_failure", 1));
  ASSERT_TRUE(telemetry.Flush().ok());
  const TelemetryAggregatorStats pressured = telemetry.stats();
  EXPECT_GE(pressured.dropped_verbose_spans, 1U);
  EXPECT_EQ(pressured.accepted_correctness, 1U);
  EXPECT_EQ(pressured.retained_events, 3U);
  EXPECT_EQ(pressured.current_sampling_per_mille, 10U);
  const std::string json = telemetry.ExportTracesJson(true);
  EXPECT_NE(json.find("\"category\":\"commit_failure\""),
            std::string::npos);
  EXPECT_NE(json.find("\"dropped_verbose_spans\":1"),
            std::string::npos);
  EXPECT_EQ(telemetry.stats().retained_events, 0U);
  EXPECT_EQ(telemetry.stats().current_sampling_per_mille, 1000U);
  ASSERT_TRUE(telemetry.Stop().ok());
}

