TEST(BenchmarkArrivalSchedulerTest, PreservesOpenLoopArrivalsWhileServiceQueues) {
  OpenLoopScheduleConfig config;
  config.operation_count = 4;
  config.arrival_interval_ns = 1000;
  config.worker_count = 1;
  config.queue_capacity = 4;
  std::vector<uint64_t> executed;
  const auto run = RunOpenLoopSchedule(config, [&](uint64_t operation_id) {
    executed.push_back(operation_id);
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
    return Status::OK();
  });
  ASSERT_TRUE(run.ok()) << run.status().ToString();
  ASSERT_EQ(run.ValueOrDie().samples.size(), 4U);
  EXPECT_EQ(executed, (std::vector<uint64_t>{0, 1, 2, 3}));
  for (size_t index = 0; index < run.ValueOrDie().samples.size(); ++index) {
    const BenchmarkOperationSample& sample = run.ValueOrDie().samples[index];
    EXPECT_EQ(sample.requested_arrival_ns, index * 1000U);
    EXPECT_GE(sample.admitted_ns, sample.requested_arrival_ns);
    EXPECT_GE(sample.started_ns, sample.admitted_ns);
    EXPECT_GE(sample.completed_ns, sample.started_ns);
    EXPECT_EQ(sample.terminal_status, "PASS");
  }
  EXPECT_GT(run.ValueOrDie().samples.back().started_ns,
            run.ValueOrDie().samples.back().requested_arrival_ns);
}

TEST(BenchmarkArrivalSchedulerTest, RetainsOperationFailuresWithoutDroppingLaterArrivals) {
  OpenLoopScheduleConfig config;
  config.operation_count = 3;
  config.arrival_interval_ns = 0;
  config.worker_count = 2;
  config.queue_capacity = 3;
  const auto run = RunOpenLoopSchedule(config, [](uint64_t operation_id) {
    return operation_id == 1 ? Status::Corruption("benchmark", "injected")
                             : Status::OK();
  });
  ASSERT_TRUE(run.ok()) << run.status().ToString();
  ASSERT_EQ(run.ValueOrDie().samples.size(), 3U);
  EXPECT_EQ(run.ValueOrDie().samples[0].terminal_status, "PASS");
  EXPECT_NE(run.ValueOrDie().samples[1].terminal_status.find("injected"),
            std::string::npos);
  EXPECT_EQ(run.ValueOrDie().samples[2].terminal_status, "PASS");
  EXPECT_TRUE(run.ValueOrDie().terminal_status.IsCorruption());
}

TEST(BenchmarkProfileTest, ResolvesAllNamedScaleProfilesWithoutSilentShrink) {
  const std::vector<std::string> names = {
      "ci", "workstation", "paper", "stress"};
  uint64_t previous_vertices = 0;
  for (const std::string& name : names) {
    const auto parsed = ParseBenchmarkScaleProfile(name);
    ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
    const BenchmarkProfile profile = ResolveBenchmarkProfile(
        parsed.ValueOrDie(), 73);
    EXPECT_EQ(profile.name, name);
    EXPECT_EQ(profile.dataset.seed, 73U);
    EXPECT_GT(profile.dataset.vertex_count, 0U);
    EXPECT_GT(profile.dataset.valid_time_span, 0U);
    EXPECT_GT(profile.dataset.property_events_per_vertex, 0U);
    EXPECT_GT(profile.dataset.vertex_count, previous_vertices);
    EXPECT_GT(profile.worker_count, 0U);
    EXPECT_GT(profile.queue_capacity, 0U);
    EXPECT_FALSE(profile.resource_profile_id.empty());
    previous_vertices = profile.dataset.vertex_count;
  }
  EXPECT_TRUE(ParseBenchmarkScaleProfile("CI").status().IsInvalidArgument());
  EXPECT_TRUE(ParseBenchmarkScaleProfile("unknown").status().IsInvalidArgument());
}

TEST(BenchmarkProfileTest, NamesEveryCacheModeAndRejectsUnsupportedDurability) {
  const std::vector<std::string> names = {
      "cold_process_and_database",
      "cold_database_warm_process",
      "warm_metadata_only",
      "warm_full_working_set",
      "steady_state_with_background_maintenance"};
  for (const std::string& name : names) {
    const auto parsed = ParseBenchmarkCacheMode(name);
    ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
    EXPECT_EQ(BenchmarkCacheModeName(parsed.ValueOrDie()), name);
    EXPECT_FALSE(BenchmarkCachePreparationDescription(
        parsed.ValueOrDie()).empty());
    const BenchmarkCachePlan plan = ResolveBenchmarkCachePlan(
        parsed.ValueOrDie());
    if (name == "warm_metadata_only") {
      EXPECT_TRUE(plan.reopen_before_measurement);
      EXPECT_FALSE(plan.read_full_working_set);
    }
    if (name == "warm_full_working_set") {
      EXPECT_TRUE(plan.reopen_before_measurement);
      EXPECT_TRUE(plan.read_full_working_set);
      EXPECT_FALSE(plan.run_background_maintenance);
    }
    if (name == "steady_state_with_background_maintenance") {
      EXPECT_TRUE(plan.reopen_before_measurement);
      EXPECT_TRUE(plan.read_full_working_set);
      EXPECT_TRUE(plan.run_background_maintenance);
    }
  }
  EXPECT_TRUE(ParseBenchmarkCacheMode("warm").status().IsInvalidArgument());
  EXPECT_TRUE(ValidateBenchmarkDurabilityMode("durable").ok());
  EXPECT_TRUE(ValidateBenchmarkDurabilityMode("NON_DURABLE")
                  .IsNotSupportedError());
  EXPECT_TRUE(ValidateBenchmarkDurabilityMode("relaxed")
                  .IsInvalidArgument());
}

