TEST(BenchmarkFaultCampaignTest, ParsesPublicationFaultScenarioNames) {
  for (const std::string& name : {
           std::string("sst_after_rename"),
           std::string("sidecar_after_rename"),
           std::string("blob_gc_after_manifest_rename"),
           std::string("accepted_work_shutdown")}) {
    const auto parsed = ParseBenchmarkFaultScenario(name);
    ASSERT_TRUE(parsed.ok()) << name << ": " << parsed.status().ToString();
    EXPECT_EQ(BenchmarkFaultScenarioName(parsed.ValueOrDie()), name);
  }
}

TEST_F(DurableLogTest,
       BenchmarkFaultCampaignReopensAndVerifiesCommitDurabilityBoundary) {
  CedarTgConfig dataset_config;
  dataset_config.seed = 91;
  dataset_config.vertex_count = 2;
  dataset_config.edge_count = 1;
  dataset_config.valid_time_span = 100;
  const auto generated = GenerateCedarTg(dataset_config);
  ASSERT_TRUE(generated.ok()) << generated.status().ToString();

  const std::vector<BenchmarkFaultScenario> scenarios = {
      BenchmarkFaultScenario::kCommitAfterPrepareDurable,
      BenchmarkFaultScenario::kCommitAfterDecisionDurable,
      BenchmarkFaultScenario::kManifestAfterRename,
      BenchmarkFaultScenario::kBlobIndexPartialWrite,
      BenchmarkFaultScenario::kSstAfterRename,
      BenchmarkFaultScenario::kSidecarAfterRename,
      BenchmarkFaultScenario::kBlobGcAfterManifestRename,
      BenchmarkFaultScenario::kAcceptedWorkShutdown,
  };
  for (const BenchmarkFaultScenario scenario : scenarios) {
    EXPECT_NE(BenchmarkFaultVerificationDetail(scenario).find(
                  BenchmarkFaultScenarioName(scenario)),
              std::string::npos);
    const std::string case_path = path_ + "/benchmark-fault-" +
        BenchmarkFaultScenarioName(scenario);
    auto database = std::make_unique<CedarDatabase>(
        case_path, 1, dataset_config.seed);
    ASSERT_TRUE(database->Open().ok());
    ColumnSchema registered;
    ASSERT_TRUE(database->RegisterColumn(
        ColumnSchema{EntityType::Vertex, 1, 0, "value",
                     PhysicalType::kString, 4096,
                     EncodingPolicy::kAdaptive, CompressionPolicy::kLz4},
        &registered).ok());
    ASSERT_TRUE(database->Put(
        LogicalKey::VertexProperty(dataset_config.vertex_count, 1), 1,
        registered.schema_epoch, Value::String("before-fault")).ok());
    if (scenario == BenchmarkFaultScenario::kAcceptedWorkShutdown) {
      ASSERT_TRUE(database->Flush().ok());
      const auto warmed = database->Get(
          LogicalKey::VertexProperty(dataset_config.vertex_count, 1), 1);
      ASSERT_TRUE(warmed.ok()) << warmed.status().ToString();
      ASSERT_TRUE(warmed.ValueOrDie().has_value());
      EXPECT_GT(database->cache_stats().ValueOrDie().resident_bytes, 0U);
    }

    BenchmarkFaultCampaignConfig config;
    config.scenario = scenario;
    config.vertex_property_schema_epoch = registered.schema_epoch;
    config.valid_time = dataset_config.valid_time_span + 10;
    config.reopen_database = [case_path, dataset_config] {
      return std::make_unique<CedarDatabase>(
          case_path, 1, dataset_config.seed);
    };
    const auto result = RunBenchmarkFaultCampaign(
        &database, generated.ValueOrDie(), config);
    ASSERT_TRUE(result.ok()) << result.status().ToString();
    EXPECT_TRUE(result.ValueOrDie().terminal_status.ok())
        << result.ValueOrDie().terminal_status.ToString();
    EXPECT_TRUE(result.ValueOrDie().verified);
    EXPECT_EQ(result.ValueOrDie().logical_work_units, 1U);
    EXPECT_EQ(result.ValueOrDie().measurement_mode, "fault_recovery");
    ASSERT_NE(database, nullptr);

    const auto recovered = database->Get(
        LogicalKey::VertexProperty(dataset_config.vertex_count, 1),
        config.valid_time);
    ASSERT_TRUE(recovered.ok()) << recovered.status().ToString();
    if (scenario == BenchmarkFaultScenario::kCommitAfterDecisionDurable ||
        scenario == BenchmarkFaultScenario::kManifestAfterRename ||
        scenario == BenchmarkFaultScenario::kSstAfterRename ||
        scenario == BenchmarkFaultScenario::kSidecarAfterRename ||
        scenario == BenchmarkFaultScenario::kBlobGcAfterManifestRename ||
        scenario == BenchmarkFaultScenario::kAcceptedWorkShutdown) {
      EXPECT_EQ(recovered.ValueOrDie(), std::optional<Value>(Value::String(
          BenchmarkFaultValue(generated.ValueOrDie(),
                              dataset_config.vertex_count) +
          (scenario == BenchmarkFaultScenario::kBlobGcAfterManifestRename
               ? std::string(8192, 'b')
               : std::string()))));
    } else {
      EXPECT_EQ(recovered.ValueOrDie(),
                std::optional<Value>(Value::String("before-fault")));
    }
  }
}

TEST_F(DurableLogTest, BenchmarkWorkloadDriverRunsVerifiedPublicApiFamilies) {
  CedarTgConfig dataset_config;
  dataset_config.seed = 9;
  // Keep the end-to-end index workload above the production CBO crossover:
  // this test verifies an executed index benchmark, not a forced access path.
  dataset_config.vertex_count = 64;
  dataset_config.edge_count = 2;
  dataset_config.valid_time_span = 10;
  const auto generated = GenerateCedarTg(dataset_config);
  ASSERT_TRUE(generated.ok()) << generated.status().ToString();

  CedarDatabase database(path_ + "/workload-db", 2, dataset_config.seed);
  ASSERT_TRUE(database.Open().ok());
  ColumnSchema vertex_existence;
  ColumnSchema vertex_property;
  ColumnSchema edge_existence;
  ASSERT_TRUE(database.RegisterColumn(
      ColumnSchema{EntityType::Vertex, 0, 0, "existence",
                   PhysicalType::kBinary, 4096, EncodingPolicy::kAdaptive,
                   CompressionPolicy::kLz4},
      &vertex_existence).ok());
  ASSERT_TRUE(database.RegisterColumn(
      ColumnSchema{EntityType::Vertex, 1, 0, "value",
                   PhysicalType::kString, 4096, EncodingPolicy::kAdaptive,
                   CompressionPolicy::kLz4},
      &vertex_property).ok());
  ASSERT_TRUE(database.RegisterColumn(
      ColumnSchema{EntityType::EdgeOut, 1, 0, "existence",
                   PhysicalType::kBinary, 4096, EncodingPolicy::kAdaptive,
                   CompressionPolicy::kLz4},
      &edge_existence).ok());
  for (const TemporalEvent& event : generated.ValueOrDie().events) {
    const ColumnSchema* schema = event.logical_key().entity_type() == EntityType::EdgeOut
        ? &edge_existence
        : (event.logical_key().IsExistence() ? &vertex_existence
                                             : &vertex_property);
    ASSERT_TRUE(database.Put(event.logical_key(), event.valid_from(),
                             schema->schema_epoch, event.value()).ok());
  }
  ASSERT_TRUE(database.Flush().ok());
  const uint64_t reads_before_warm =
      database.storage_stats().ValueOrDie().sst_physical_bytes_read;
  ASSERT_TRUE(WarmBenchmarkWorkingSet(
      &database, generated.ValueOrDie()).ok());
  EXPECT_GT(database.storage_stats().ValueOrDie().sst_physical_bytes_read,
            reads_before_warm);

  const std::vector<std::pair<BenchmarkWorkloadFamily, uint64_t>> cases = {
      {BenchmarkWorkloadFamily::kPointRead, dataset_config.vertex_count},
      {BenchmarkWorkloadFamily::kBitemporalPointRead,
       dataset_config.vertex_count},
      {BenchmarkWorkloadFamily::kAnalyticalVertexCount,
       dataset_config.vertex_count},
      {BenchmarkWorkloadFamily::kValidTimeRange,
       dataset_config.vertex_count},
      {BenchmarkWorkloadFamily::kGraphOneHop, dataset_config.edge_count},
      {BenchmarkWorkloadFamily::kBlobProjection, 1},
      {BenchmarkWorkloadFamily::kDurableIngestion,
       dataset_config.vertex_count},
      {BenchmarkWorkloadFamily::kIndexEquality, 1},
      {BenchmarkWorkloadFamily::kMaintenanceCycle, 5},
      {BenchmarkWorkloadFamily::kHtapBalanced,
       2 * dataset_config.vertex_count + 3},
      {BenchmarkWorkloadFamily::kRecovery, 2},
  };
  for (const auto& item : cases) {
    BenchmarkWorkloadConfig workload;
    workload.family = item.first;
    workload.arrival_interval_ns = 0;
    workload.worker_count = 1;
    workload.vertex_property_schema_epoch = vertex_property.schema_epoch;
    ASSERT_TRUE(PrepareBenchmarkWorkload(
        &database, generated.ValueOrDie(), workload).ok());
    const auto run = RunBenchmarkWorkload(
        &database, generated.ValueOrDie(), workload);
    ASSERT_TRUE(run.ok()) << BenchmarkWorkloadFamilyName(item.first) << ": "
                          << run.status().ToString();
    std::string sample_failures;
    for (size_t sample_index = 0;
         sample_index < run.ValueOrDie().samples.size(); ++sample_index) {
      const std::string& terminal =
          run.ValueOrDie().samples[sample_index].terminal_status;
      if (terminal == "PASS") continue;
      sample_failures.append(" sample[")
          .append(std::to_string(sample_index))
          .append("]=")
          .append(terminal);
    }
    EXPECT_TRUE(run.ValueOrDie().terminal_status.ok())
        << BenchmarkWorkloadFamilyName(item.first) << ": "
        << run.ValueOrDie().terminal_status.ToString() << sample_failures;
    EXPECT_TRUE(run.ValueOrDie().verified);
    EXPECT_EQ(run.ValueOrDie().logical_work_units, item.second);
    EXPECT_FALSE(run.ValueOrDie().result_checksum.empty());
    EXPECT_FALSE(run.ValueOrDie().samples.empty());
    if (item.first == BenchmarkWorkloadFamily::kAnalyticalVertexCount ||
        item.first == BenchmarkWorkloadFamily::kGraphOneHop ||
        item.first == BenchmarkWorkloadFamily::kBlobProjection) {
      EXPECT_TRUE(run.ValueOrDie().physical_read_bytes_available);
      EXPECT_GT(run.ValueOrDie().physical_read_bytes, 0U);
    }
    if (item.first == BenchmarkWorkloadFamily::kDurableIngestion) {
      EXPECT_TRUE(run.ValueOrDie().physical_write_bytes_available);
      EXPECT_GT(run.ValueOrDie().physical_write_bytes, 0U);
      EXPECT_TRUE(run.ValueOrDie().transaction_measurements.available);
      EXPECT_EQ(run.ValueOrDie().transaction_measurements.started,
                dataset_config.vertex_count);
      EXPECT_EQ(run.ValueOrDie().transaction_measurements.committed,
                dataset_config.vertex_count);
      EXPECT_EQ(run.ValueOrDie().transaction_measurements.commit_latency.sample_count,
                dataset_config.vertex_count);
    }
    if (item.first == BenchmarkWorkloadFamily::kAnalyticalVertexCount ||
        item.first == BenchmarkWorkloadFamily::kGraphOneHop) {
      EXPECT_GT(run.ValueOrDie().derived_metrics.read_amplification.denominator,
                0U);
      EXPECT_NE(run.ValueOrDie().derived_metrics.read_amplification.denominator,
                run.ValueOrDie().logical_work_units);
    }
    if (item.first == BenchmarkWorkloadFamily::kValidTimeRange) {
      EXPECT_GT(run.ValueOrDie().derived_metrics.read_amplification.numerator,
                0U);
      EXPECT_GT(run.ValueOrDie().derived_metrics.interval_survival.numerator,
                0U);
      EXPECT_GT(run.ValueOrDie().derived_metrics.interval_survival.denominator,
                0U);
    }
    if (item.first == BenchmarkWorkloadFamily::kBlobProjection) {
      EXPECT_EQ(run.ValueOrDie().derived_metrics.blob_materialization.numerator,
                1U);
      EXPECT_EQ(run.ValueOrDie().derived_metrics.blob_materialization.denominator,
                1U);
      EXPECT_GT(run.ValueOrDie().derived_metrics.read_amplification.numerator,
                0U);
    }
    if (item.first == BenchmarkWorkloadFamily::kIndexEquality) {
      EXPECT_EQ(run.ValueOrDie().derived_metrics.index_survival.numerator,
                item.second);
      EXPECT_GT(run.ValueOrDie().derived_metrics.index_survival.denominator,
                0U);
      EXPECT_GT(run.ValueOrDie().derived_metrics.cache_admission.denominator,
                0U);
      EXPECT_LE(run.ValueOrDie().derived_metrics.cache_admission.numerator,
                run.ValueOrDie().derived_metrics.cache_admission.denominator);
    }
    if (item.first == BenchmarkWorkloadFamily::kMaintenanceCycle) {
      EXPECT_GT(run.ValueOrDie().derived_metrics.maintenance_share.numerator,
                0U);
      EXPECT_GE(run.ValueOrDie().derived_metrics.maintenance_share.denominator,
                run.ValueOrDie().derived_metrics.maintenance_share.numerator);
    }
    if (item.first == BenchmarkWorkloadFamily::kDurableIngestion) {
      EXPECT_GT(run.ValueOrDie().derived_metrics.write_amplification.numerator,
                0U);
      EXPECT_GT(run.ValueOrDie().derived_metrics.write_amplification.denominator,
                0U);
      EXPECT_NE(run.ValueOrDie().derived_metrics.write_amplification.denominator,
                run.ValueOrDie().logical_work_units);
      EXPECT_GT(run.ValueOrDie().durable_write_bytes.wal, 0U);
      EXPECT_GT(run.ValueOrDie().durable_write_bytes.decision_log, 0U);
    }
    EXPECT_GT(run.ValueOrDie().derived_metrics.space_amplification.numerator,
              0U);
    EXPECT_GT(run.ValueOrDie().derived_metrics.space_amplification.denominator,
              0U);
  }
}

TEST(BenchmarkRegressionGateTest, PersistsFailingPairedReleaseGate) {
  char pattern[] = "/tmp/cedar_regression_gate_XXXXXX";
  ASSERT_NE(mkdtemp(pattern), nullptr);
  const std::string path = std::string(pattern) + "/regression.json";
  BenchmarkBaselineKey key;
  key.hardware_profile = "ci-host";
  key.dataset_hash = "dataset";
  key.workload_hash = "workload";
  key.durability_mode = "durable";
  key.resource_profile_id = "default";
  std::vector<BenchmarkRegressionSample> baseline(7);
  std::vector<BenchmarkRegressionSample> candidate(7);
  for (size_t index = 0; index < baseline.size(); ++index) {
    baseline[index] = BenchmarkRegressionSample{true, 100.0, 1000.0, 100.0, 2.0};
    candidate[index] = BenchmarkRegressionSample{true, 90.0, 1000.0, 100.0, 2.0};
  }
  const auto artifact = WriteBenchmarkRegressionGate(
      path, key, key, baseline, candidate);
  ASSERT_TRUE(artifact.ok()) << artifact.status().ToString();
  EXPECT_EQ(artifact.ValueOrDie().result.status,
            BenchmarkRegressionStatus::kFail);
  EXPECT_FALSE(artifact.ValueOrDie().release_gate_passed);
  std::ifstream input(path);
  const std::string json((std::istreambuf_iterator<char>(input)),
                         std::istreambuf_iterator<char>());
  EXPECT_NE(json.find("\"regression_schema_version\":1"), std::string::npos);
  EXPECT_NE(json.find("\"status\":\"FAIL\""), std::string::npos);
  EXPECT_NE(json.find("\"release_gate_passed\":false"), std::string::npos);
  EXPECT_NE(json.find("\"pair_count\":7"), std::string::npos);
  std::filesystem::remove_all(pattern);
}

