TEST(BenchmarkRegressionGateTest,
     InstrumentationOverheadUsesMedianTwoAndFivePercentLimits) {
  BenchmarkBaselineKey key;
  key.hardware_profile = "ci-host";
  key.dataset_hash = "dataset";
  key.workload_hash = "workload";
  key.durability_mode = "durable";
  key.resource_profile_id = "default";
  std::vector<BenchmarkRegressionSample> minimal(
      5, BenchmarkRegressionSample{true, 100.0, 1000.0, 0.0, 0.0});
  std::vector<BenchmarkRegressionSample> within(
      5, BenchmarkRegressionSample{true, 98.1, 1049.0, 0.0, 0.0});
  EXPECT_EQ(CompareInstrumentationOverheadRuns(
                key, key, kInstrumentationProfileTier0Minimal,
                kInstrumentationProfileTier0Tier1, minimal, within)
                .status,
            BenchmarkRegressionStatus::kPass);

  std::vector<BenchmarkRegressionSample> throughput_over(
      5, BenchmarkRegressionSample{true, 97.9, 1000.0, 0.0, 0.0});
  EXPECT_EQ(CompareInstrumentationOverheadRuns(
                key, key, kInstrumentationProfileTier0Minimal,
                kInstrumentationProfileTier0Tier1, minimal,
                throughput_over)
                .status,
            BenchmarkRegressionStatus::kFail);

  std::vector<BenchmarkRegressionSample> p99_over(
      5, BenchmarkRegressionSample{true, 100.0, 1051.0, 0.0, 0.0});
  EXPECT_EQ(CompareInstrumentationOverheadRuns(
                key, key, kInstrumentationProfileTier0Minimal,
                kInstrumentationProfileTier0Tier1, minimal, p99_over)
                .status,
            BenchmarkRegressionStatus::kFail);

  minimal.resize(4);
  within.resize(4);
  const BenchmarkRegressionResult too_few =
      CompareInstrumentationOverheadRuns(
          key, key, kInstrumentationProfileTier0Minimal,
          kInstrumentationProfileTier0Tier1, minimal, within);
  EXPECT_EQ(too_few.status, BenchmarkRegressionStatus::kInvalid);
  EXPECT_NE(too_few.detail.find("at least 5"), std::string::npos);
  EXPECT_EQ(CompareInstrumentationOverheadRuns(
                key, key, kInstrumentationProfileTier0Tier1,
                kInstrumentationProfileTier0Minimal, minimal, within)
                .status,
            BenchmarkRegressionStatus::kIncompatible);
}

