TEST(BenchmarkArtifactTest,
     DerivedMetricsRetainNumeratorsAndDoNotHideMissingDenominators) {
  BenchmarkRunManifest manifest;
  manifest.dataset_id = "cedar-tg";
  manifest.dataset_hash = "dataset";
  manifest.workload_id = "range-index";
  manifest.workload_hash = "workload";
  manifest.execution_nonce = "derived";
  BenchmarkArtifactSummary summary;
  summary.physical_read_bytes = 50;
  summary.physical_write_bytes = 300;
  summary.durable_write_bytes =
      BenchmarkDurableWriteBytes{120, 40, 60, 30, 20, 30};
  summary.derived_metrics.write_amplification = BenchmarkRatio{300, 100};
  summary.derived_metrics.read_amplification = BenchmarkRatio{50, 0};
  summary.derived_metrics.index_survival = BenchmarkRatio{7, 10};
  summary.derived_metrics.visible_prefix_lag = BenchmarkLag{true, 12, 10};
  const std::string serialized = SerializeBenchmarkArtifactSummary(summary);
  EXPECT_NE(serialized.find(
                "\"write_amplification\":{\"defined\":true,"
                "\"numerator\":300,\"denominator\":100,\"value\":3"),
            std::string::npos)
      << serialized;
  EXPECT_NE(serialized.find(
                "\"read_amplification\":{\"defined\":false,"
                "\"numerator\":50,\"denominator\":0,\"value\":null}"),
            std::string::npos)
      << serialized;
  EXPECT_NE(serialized.find("\"physical_read_bytes_available\":false"),
            std::string::npos)
      << serialized;
  EXPECT_NE(serialized.find("\"physical_write_bytes_available\":false"),
            std::string::npos)
      << serialized;
  EXPECT_NE(serialized.find(
                "\"durable_write_bytes\":{\"wal\":120,"
                "\"decision_log\":40,\"sst_flush\":60,"
                "\"compaction\":30,\"blob\":20,\"manifest\":30}"),
            std::string::npos)
      << serialized;
  EXPECT_NE(serialized.find(
                "\"visible_prefix_lag\":{\"defined\":true,"
                "\"committed_seq\":12,\"visible_seq\":10,\"value\":2}"),
            std::string::npos)
      << serialized;

  BenchmarkVerification verification;
  verification.load_passed = true;
  verification.result_passed = true;
  verification.reopen_passed = true;
  const std::string report =
      BuildBenchmarkReport(manifest, summary, verification, true);
  EXPECT_NE(report.find("| Write amplification | 300 / 100 = 3.0000 |"),
            std::string::npos)
      << report;
  EXPECT_NE(report.find("| WAL durable bytes | 120 |"), std::string::npos)
      << report;
  EXPECT_NE(report.find("| DecisionLog durable bytes | 40 |"),
            std::string::npos)
      << report;
  EXPECT_NE(report.find("| Read amplification | undefined (50 / 0) |"),
            std::string::npos)
      << report;
  EXPECT_NE(report.find("| Index survival | 7 / 10 = 0.7000 |"),
            std::string::npos)
      << report;
  EXPECT_NE(report.find("| Visible prefix lag | 12 - 10 = 2 |"),
            std::string::npos)
      << report;
  EXPECT_NE(report.find("| Physical read bytes | undefined |"),
            std::string::npos)
      << report;
  EXPECT_NE(report.find("| Physical write bytes | undefined |"),
            std::string::npos)
      << report;
}

TEST(BenchmarkArtifactTest, RegeneratesReportFromArchivedJsonWithoutDatabase) {
  char pattern[] = "/tmp/cedar_benchmark_regenerate_XXXXXX";
  ASSERT_NE(mkdtemp(pattern), nullptr);
  const std::string root = pattern;
  BenchmarkRunManifest manifest;
  manifest.source_commit = "abc123";
  manifest.dataset_id = "ci-\"archive\"";
  manifest.dataset_hash = "dataset-hash";
  manifest.workload_id = "point-read";
  manifest.workload_hash = "workload-hash";
  manifest.resource_profile_id = "default";
  manifest.execution_nonce = "offline";
  BenchmarkArtifactSummary summary;
  summary.cache_preparation = "fresh\nprocess";
  summary.measurement_elapsed_ns = 1000;
  summary.measured_work_units = 1;
  summary.measurement_throughput = 1000000.0;
  summary.latency_p50_ns = 20;
  summary.latency_p95_ns = 20;
  summary.latency_p99_ns = 20;
  summary.latency_p999_ns = 20;
  summary.logical_work_units = 1;
  summary.derived_metrics.index_survival = BenchmarkRatio{1, 2};
  summary.derived_metrics.visible_prefix_lag = BenchmarkLag{true, 9, 7};
  summary.measured_samples = {
      BenchmarkOperationSample{0, 0, 10, 20, "PASS"},
  };
  summary.phases.resize(11);
  for (size_t index = 0; index < summary.phases.size(); ++index) {
    summary.phases[index].phase = static_cast<BenchmarkPhase>(index);
    summary.phases[index].elapsed_ns = index + 1;
  }
  BenchmarkVerification verification;
  verification.load_passed = true;
  verification.result_passed = true;
  verification.reopen_passed = true;
  verification.result_checksum = "checksum";
  verification.detail = "verified \"offline\"\narchive";
  const auto written = WriteBenchmarkArtifacts(
      root, manifest, ProbeBenchmarkEnvironment(), summary, verification);
  ASSERT_TRUE(written.ok()) << written.status().ToString();
  const BenchmarkArtifactPaths& paths = written.ValueOrDie();
  std::ifstream original_input(paths.report_path);
  const std::string original((std::istreambuf_iterator<char>(original_input)),
                             std::istreambuf_iterator<char>());
  ASSERT_FALSE(original.empty());
  ASSERT_TRUE(std::filesystem::remove(paths.report_path));

  const Status regenerated = RegenerateBenchmarkReport(paths.run_directory);
  ASSERT_TRUE(regenerated.ok()) << regenerated.ToString();
  std::ifstream regenerated_input(paths.report_path);
  const std::string rebuilt((std::istreambuf_iterator<char>(regenerated_input)),
                            std::istreambuf_iterator<char>());
  EXPECT_EQ(rebuilt, original);
  std::filesystem::remove_all(root);
}

