TEST(RuntimeFeedbackStoreTest, RequiresTwoMatchingObservationsBeforeCorrection) {
  RuntimeFeedbackStore store(4);
  const RuntimeFeedbackKey key{
      11, 22, 33, 44, SelectivityBucket::kVerySelective};
  ScanCostEstimate estimate;
  estimate.base_rows = 1000;
  estimate.index_candidate_rows = 800;
  estimate.uncovered_base_rows = 7;

  store.Observe(key, RuntimeFeedbackObservation{10, 4, 2, 3, 1});
  const ScanCostEstimate diagnostic = store.ApplyToEstimate(key, estimate);
  EXPECT_EQ(diagnostic.index_candidate_rows, 800U);
  EXPECT_FALSE(diagnostic.feedback_applied);

  store.Observe(key, RuntimeFeedbackObservation{14, 6, 4, 5, 3});
  const ScanCostEstimate corrected = store.ApplyToEstimate(key, estimate);
  EXPECT_EQ(corrected.index_candidate_rows, 12U);
  EXPECT_EQ(corrected.uncovered_base_rows, 7U);
  EXPECT_TRUE(corrected.feedback_applied);
  const auto aggregate = store.Lookup(key);
  ASSERT_TRUE(aggregate.has_value());
  EXPECT_EQ(aggregate->observations, 2U);
  EXPECT_EQ(aggregate->candidate_rows, 24U);
  EXPECT_EQ(aggregate->survivor_rows, 10U);
  EXPECT_EQ(aggregate->interval_splits, 6U);
  EXPECT_EQ(aggregate->pages_read, 8U);
  EXPECT_EQ(aggregate->blob_reads, 4U);
}

TEST(RuntimeFeedbackStoreTest, IsolatesKeysAndEvictsLeastRecentlyUsed) {
  RuntimeFeedbackStore store(2);
  const RuntimeFeedbackKey first{
      1, 2, 3, 4, SelectivityBucket::kVerySelective};
  const RuntimeFeedbackKey second{
      1, 2, 4, 4, SelectivityBucket::kVerySelective};
  const RuntimeFeedbackKey third{
      1, 2, 3, 4, SelectivityBucket::kModerate};
  store.Observe(first, RuntimeFeedbackObservation{1, 1, 0, 0, 0});
  store.Observe(second, RuntimeFeedbackObservation{2, 1, 0, 0, 0});
  ASSERT_TRUE(store.Lookup(first).has_value());
  store.Observe(third, RuntimeFeedbackObservation{3, 1, 0, 0, 0});
  EXPECT_TRUE(store.Lookup(first).has_value());
  EXPECT_FALSE(store.Lookup(second).has_value());
  EXPECT_TRUE(store.Lookup(third).has_value());
  EXPECT_EQ(store.size(), 2U);
}

TEST(RuntimeFeedbackStoreTest, SaturatesCountersAndClassifiesSelectivity) {
  RuntimeFeedbackStore store(1);
  const RuntimeFeedbackKey key{
      7, 8, 9, 10, SelectivityBucket::kNonSelective};
  store.Observe(key, RuntimeFeedbackObservation{
      std::numeric_limits<uint64_t>::max(),
      std::numeric_limits<uint64_t>::max(), 1, 2, 3});
  store.Observe(key, RuntimeFeedbackObservation{1, 1, 1, 2, 3});
  const auto aggregate = store.Lookup(key);
  ASSERT_TRUE(aggregate.has_value());
  EXPECT_EQ(aggregate->candidate_rows, std::numeric_limits<uint64_t>::max());
  EXPECT_EQ(aggregate->survivor_rows, std::numeric_limits<uint64_t>::max());
  EXPECT_EQ(ClassifySelectivity(1, 100), SelectivityBucket::kVerySelective);
  EXPECT_EQ(ClassifySelectivity(20, 100), SelectivityBucket::kModerate);
  EXPECT_EQ(ClassifySelectivity(21, 100), SelectivityBucket::kNonSelective);
}

TEST(RuntimeFeedbackStoreTest, DecaysConfidenceAndBlendsWithStaticEstimate) {
  RuntimeFeedbackPolicy policy;
  policy.minimum_observations = 2;
  policy.decay_interval_epochs = 2;
  policy.expiry_epochs = 8;
  RuntimeFeedbackStore store(4, policy);
  const RuntimeFeedbackKey key{
      31, 32, 33, 34, SelectivityBucket::kVerySelective};
  ScanCostEstimate estimate;
  estimate.base_rows = 1000;
  estimate.index_candidate_rows = 100;

  store.Observe(key, RuntimeFeedbackObservation{20, 10, 0, 0, 0});
  store.Observe(key, RuntimeFeedbackObservation{20, 10, 0, 0, 0});
  const ScanCostEstimate fresh = store.ApplyToEstimate(key, estimate);
  EXPECT_TRUE(fresh.feedback_applied);
  EXPECT_EQ(fresh.index_candidate_rows, 20U);

  const ScanCostEstimate half_confidence =
      store.ApplyToEstimate(key, estimate);
  EXPECT_TRUE(half_confidence.feedback_applied);
  EXPECT_EQ(half_confidence.index_candidate_rows, 60U);
  const auto decayed = store.Lookup(key);
  ASSERT_TRUE(decayed.has_value());
  EXPECT_EQ(decayed->confidence_per_mille, 500U);

  store.Observe(key, RuntimeFeedbackObservation{20, 10, 0, 0, 0});
  const ScanCostEstimate refreshed = store.ApplyToEstimate(key, estimate);
  EXPECT_TRUE(refreshed.feedback_applied);
  EXPECT_EQ(refreshed.index_candidate_rows, 20U);
  const auto current = store.Lookup(key);
  ASSERT_TRUE(current.has_value());
  EXPECT_EQ(current->observations, 3U);
  EXPECT_EQ(current->confidence_per_mille, 1000U);
}

TEST(RuntimeFeedbackStoreTest, ExpiresByFreshnessWithoutConflatingLruReads) {
  RuntimeFeedbackPolicy policy;
  policy.minimum_observations = 2;
  policy.decay_interval_epochs = 2;
  policy.expiry_epochs = 4;
  RuntimeFeedbackStore store(2, policy);
  const RuntimeFeedbackKey key{
      41, 42, 43, 44, SelectivityBucket::kModerate};
  const RuntimeFeedbackKey other{
      51, 52, 53, 54, SelectivityBucket::kModerate};
  ScanCostEstimate estimate;
  estimate.base_rows = 1000;
  estimate.index_candidate_rows = 100;

  store.Observe(key, RuntimeFeedbackObservation{20, 10, 0, 0, 0});
  store.Observe(key, RuntimeFeedbackObservation{20, 10, 0, 0, 0});
  for (uint32_t read = 0; read < 8; ++read) {
    ASSERT_TRUE(store.Lookup(key).has_value());
  }
  const ScanCostEstimate fresh = store.ApplyToEstimate(key, estimate);
  EXPECT_EQ(fresh.index_candidate_rows, 20U);

  store.ApplyToEstimate(other, estimate);
  store.ApplyToEstimate(other, estimate);
  store.ApplyToEstimate(other, estimate);
  EXPECT_FALSE(store.Lookup(key).has_value());
  EXPECT_EQ(store.size(), 0U);

  store.Observe(key, RuntimeFeedbackObservation{30, 15, 0, 0, 0});
  const auto restarted = store.Lookup(key);
  ASSERT_TRUE(restarted.has_value());
  EXPECT_EQ(restarted->observations, 1U);
  EXPECT_EQ(restarted->confidence_per_mille, 0U);
  const ScanCostEstimate diagnostic = store.ApplyToEstimate(key, estimate);
  EXPECT_FALSE(diagnostic.feedback_applied);
  EXPECT_EQ(diagnostic.index_candidate_rows, 100U);
}

TEST(CostModelTest, ConfidentRuntimeFeedbackCorrectsCostButNotLegality) {
  ScanCostEstimate stale;
  stale.base_rows = 1000;
  stale.index_candidate_rows = 800;
  const AccessPathDecision before = ChooseAccessPathDecision(
      stale, OptimizerBudget{4, false});
  EXPECT_EQ(before.source, CandidateSource::kBase);

  RuntimeFeedbackStore store(4);
  const RuntimeFeedbackKey key{
      101, 202, 303, 404, SelectivityBucket::kVerySelective};
  store.Observe(key, RuntimeFeedbackObservation{10, 4, 0, 2, 0});
  store.Observe(key, RuntimeFeedbackObservation{12, 5, 0, 3, 0});
  const ScanCostEstimate corrected = store.ApplyToEstimate(key, stale);
  const AccessPathDecision after = ChooseAccessPathDecision(
      corrected, OptimizerBudget{4, false});
  EXPECT_EQ(after.source, CandidateSource::kIndex);
  EXPECT_NE(after.rationale.find("runtime feedback"), std::string::npos)
      << after.rationale;

  RuntimeFeedbackKey incompatible = key;
  incompatible.catalog_generation = 304;
  const ScanCostEstimate unchanged = store.ApplyToEstimate(incompatible, stale);
  EXPECT_FALSE(unchanged.feedback_applied);
  EXPECT_EQ(ChooseAccessPathDecision(unchanged, OptimizerBudget{4, false}).source,
            CandidateSource::kBase);

  ScanCostEstimate illegal = corrected;
  illegal.base_rows = 0;
  EXPECT_EQ(ChooseAccessPathDecision(illegal, OptimizerBudget{4, false}).source,
            CandidateSource::kBase);
}

TEST_F(DurableLogTest, ActivatingIndexBuildsManifestOwnedSidecarsForExistingSsts) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence", PhysicalType::kBinary,
                         4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema name{EntityType::Vertex, 7, 0, "name", PhysicalType::kString,
                    4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered_existence;
  ColumnSchema registered_name;
  ASSERT_TRUE(coordinator.RegisterColumn(existence, &registered_existence).ok());
  ASSERT_TRUE(coordinator.RegisterColumn(name, &registered_name).ok());
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexExistence(1), 0,
                        registered_existence.schema_epoch, Value::Binary("")),
      PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 0,
                        registered_name.schema_epoch, Value::String("Ada")),
  }, &commit_seq).ok());
  ASSERT_TRUE(coordinator.Flush().ok());

  IndexDefinition definition;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = registered_name.schema_epoch;
  definition.capabilities = kIndexEquality | kIndexOrderedRange;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kDeclared;
  uint64_t index_id = 0;
  ASSERT_TRUE(coordinator.RegisterIndex(definition, &index_id).ok());
  ASSERT_TRUE(coordinator.SetIndexState(index_id, IndexState::kBuilding).ok());
  ASSERT_TRUE(coordinator.SetIndexState(index_id, IndexState::kActive).ok());

  const auto snapshot = coordinator.version_snapshot();
  ASSERT_EQ(snapshot->index_fragments.size(), 1U);
  const IndexFragment& fragment = snapshot->index_fragments.front();
  EXPECT_EQ(fragment.index_id, index_id);
  EXPECT_TRUE(fragment.usable);
  EXPECT_EQ(fragment.source_row_count, 1U);
  EXPECT_EQ(fragment.indexed_put_count, 1U);
  EXPECT_TRUE(std::filesystem::exists(path_ + "/" + fragment.relative_path));
  const auto definition_it = std::find_if(snapshot->index_definitions.begin(),
                                          snapshot->index_definitions.end(),
      [index_id](const IndexDefinition& candidate) { return candidate.index_id == index_id; });
  ASSERT_NE(definition_it, snapshot->index_definitions.end());
  const auto sidecar = ReadIndexSidecarFile(path_ + "/" + fragment.relative_path,
                                             *definition_it, fragment.source_sst_id);
  ASSERT_TRUE(sidecar.ok()) << sidecar.status().ToString();
  const auto candidates = LookupIndexEquality(sidecar.ValueOrDie(), Value::String("Ada"));
  ASSERT_TRUE(candidates.ok());

  const std::string orphan = path_ + "/indexes/999/999.idx";
  std::filesystem::create_directories(std::filesystem::path(orphan).parent_path());
  std::filesystem::copy_file(path_ + "/" + fragment.relative_path, orphan,
                             std::filesystem::copy_options::overwrite_existing);
  ASSERT_TRUE(std::filesystem::exists(orphan));
  TransactionCoordinator reopened(path_, 1, 11);
  ASSERT_TRUE(reopened.Open().ok());
  EXPECT_TRUE(std::filesystem::exists(path_ + "/" + fragment.relative_path));
  EXPECT_FALSE(std::filesystem::exists(orphan));
  ASSERT_EQ(candidates.ValueOrDie().size(), 1U);
  EXPECT_EQ(candidates.ValueOrDie().front().source_row_ordinal, 0U);

  TcypherExecutionContext query_context{coordinator.commit_timeline(), 0, {}, nullptr, {}};
  ASSERT_TRUE(coordinator.PopulateTcypherContext(&query_context).ok());
  ASSERT_TRUE(query_context.version_snapshot);
  ASSERT_TRUE(query_context.index_catalog_snapshot);
  EXPECT_TRUE(query_context.committed_events.empty());
  ASSERT_EQ(query_context.sst_event_sources.size(), 2U);
  ASSERT_EQ(query_context.version_snapshot->generation,
            query_context.index_catalog_snapshot->catalog_generation);
  EXPECT_EQ(query_context.index_sources.size(), 1U);
  EXPECT_TRUE(query_context.delta_index_sources.empty());
  ASSERT_EQ(query_context.version_snapshot->index_fragments.size(), 1U);
  EXPECT_EQ(query_context.version_snapshot->index_fragments.front().source_sst_id,
            fragment.source_sst_id);
}

TEST_F(DurableLogTest,
       IndexRepairRetainsPossiblyPublishedSidecarAfterManifestRename) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema property{EntityType::Vertex, 7, 0, "name",
                        PhysicalType::kString, 4096,
                        EncodingPolicy::kAdaptive,
                        CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 0,
                        registered.schema_epoch, Value::String("Ada")),
  }, &commit_seq).ok());
  ASSERT_TRUE(coordinator.Flush().ok());

  IndexDefinition definition;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = registered.schema_epoch;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kDeclared;
  uint64_t index_id = 0;
  ASSERT_TRUE(coordinator.RegisterIndex(definition, &index_id).ok());
  ASSERT_TRUE(coordinator.SetIndexState(index_id, IndexState::kBuilding).ok());
  ASSERT_TRUE(coordinator.SetIndexState(index_id, IndexState::kActive).ok());
  ASSERT_EQ(coordinator.version_snapshot()->index_fragments.size(), 1U);
  const std::string relative =
      coordinator.version_snapshot()->index_fragments.front().relative_path;
  const std::string sidecar_path = path_ + "/" + relative;
  std::ofstream(sidecar_path, std::ios::binary | std::ios::trunc)
      << "corrupt-sidecar";

  WorkCancellation* index_cancellation = nullptr;
  bool index_cancellation_signalled = false;
  coordinator.SetMaintenanceCancellationObserverForTesting(
      [&](WorkCancellation* token, const std::string& owner, uint64_t) {
        if (owner == "index build") index_cancellation = token;
      });
  uint32_t manifest_renames = 0;
  coordinator.SetVersionSetFaultInjectorForTesting(
      [&](VersionSetFaultPoint point) {
        if (point != VersionSetFaultPoint::kAfterManifestRename) {
          return Status::OK();
        }
        ++manifest_renames;
        if (manifest_renames != 1) return Status::OK();
        if (index_cancellation == nullptr) {
          return Status::Corruption(
              "index repair", "missing running cancellation token");
        }
        index_cancellation_signalled = index_cancellation->Cancel();
        return Status::IOError("index repair", "post-rename attach fault");
      });
  const Status repaired = coordinator.RepairIndexes();
  EXPECT_TRUE(repaired.IsIndeterminate()) << repaired.ToString();
  ASSERT_NE(index_cancellation, nullptr);
  EXPECT_TRUE(index_cancellation_signalled);
  EXPECT_TRUE(std::filesystem::exists(sidecar_path));

  TransactionCoordinator reopened(path_, 1, 11);
  ASSERT_TRUE(reopened.Open().ok());
  const auto snapshot = reopened.version_snapshot();
  const auto fragment = std::find_if(
      snapshot->index_fragments.begin(), snapshot->index_fragments.end(),
      [index_id](const IndexFragment& candidate) {
        return candidate.index_id == index_id;
      });
  ASSERT_NE(fragment, snapshot->index_fragments.end());
  EXPECT_TRUE(std::filesystem::exists(path_ + "/" + fragment->relative_path));
}

