  ASSERT_TRUE(coordinator.RegisterColumn(property, &registered).ok());
  uint64_t commit_seq = 0;
  for (uint64_t vertex = 1; vertex <= 2; ++vertex) {
    ASSERT_TRUE(coordinator.Commit(
        coordinator.visible_seq(),
        {PendingEvent::Put(LogicalKey::VertexProperty(vertex, 7), vertex,
                           registered.schema_epoch,
                           Value::String("value-" +
                                         std::to_string(vertex)))},
        &commit_seq).ok());
    ASSERT_TRUE(coordinator.Flush().ok());
  }
  const uint64_t limit = 1ULL << 30;
  ResourceGovernor resources(ResourceProfile{
      limit, limit, limit, limit, limit, limit, limit, limit, limit});
  coordinator.SetResourceGovernor(&resources);
  std::vector<ResourceProfile> admitted;
  coordinator.SetMaintenanceCancellationObserverForTesting(
      [&](WorkCancellation*, const std::string& owner, uint64_t checkpoint) {
        if (owner == "maintenance" && checkpoint == 1) {
          admitted.push_back(resources.used());
        }
      });
  IndexDefinition definition;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = registered.schema_epoch;
  definition.capabilities = kIndexEquality;
