TEST_F(DurableLogTest, ScheduledPhysicalStreamCancelsBeforeTheNextSstBlock) {
  const BlockPartition partition{
      EntityType::Vertex, 0, 1, PhysicalType::kBinary, 0,
      CompressionId::kLz4, LogicalKeyKind::kExistence};
  std::vector<TemporalEvent> events;
  for (uint64_t id = 1; id <= 8; ++id) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexExistence(id), 10, id, 1,
        Value::Binary(std::string(150 * 1024, static_cast<char>('a' + id)))));
  }
  const std::string sst_path = path_ + "/shards/0/sst/scheduled-cancel.sst";
  SstFile written;
  ASSERT_TRUE(WriteSstFile(sst_path, partition, events, &written).ok());
  ASSERT_GT(written.block_count, 1U);

  CommitTimeline timeline(path_ + "/scheduled-cancel-timeline");
  auto cancellation = std::make_shared<QueryCancellation>();
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 6;
  options.cancellation = cancellation;
  options.execution_stats = stats;
  options.memory_account =
      std::make_shared<QueryMemoryAccount>(32U << 20, 64U << 20);
  TcypherExecutionContext context{
      timeline, 8, options, MakeTcypherBinderSchemaSnapshot(), {}};
  context.sst_event_sources.push_back(PinnedSstSource{
      SstFileMeta{1, "scheduled-cancel.sst", partition,
                    std::filesystem::file_size(sst_path), written.blob_refs},
      sst_path});
  auto stream = OpenPhysicalRootForTest("MATCH (n) RETURN n;", std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 6U);
  ASSERT_EQ(stats->root_sst_blocks_read, 1U);
  const uint64_t scheduled_before_cancel = stats->morsels_scheduled;
  cancellation->Cancel();
  const Status cancelled = stream.ValueOrDie()->Next(&result);
  EXPECT_TRUE(cancelled.IsQueryCancelled()) << cancelled.ToString();
  EXPECT_TRUE(stream.ValueOrDie()->terminal_status().IsQueryCancelled());
  EXPECT_EQ(stats->root_sst_blocks_read, 1U);
  EXPECT_EQ(stats->morsels_scheduled, scheduled_before_cancel);
}

