TEST_F(DurableLogTest, PointTemporalMetadataProjectionsUseLazyPinnedRootScan) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence",
                         PhysicalType::kBinary, 4096,
                         EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(existence, &registered).ok());
  std::vector<PendingEvent> events;
  events.reserve(9000);
  for (uint64_t id = 1; id <= 9000; ++id) {
    events.push_back(PendingEvent::Put(
        LogicalKey::VertexExistence(id), 10, registered.schema_epoch,
        Value::Binary("")));
  }
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, events, &commit_seq).ok());
  ASSERT_TRUE(coordinator.Flush().ok());

  const auto execute_first = [&](const std::string& query,
                                 std::shared_ptr<TcypherExecutionStats> stats) {
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.batch_capacity = 1;
    options.execution_stats = stats;
    TcypherExecutionContext context{
        coordinator.commit_timeline(), 0, options, nullptr, {}};
    EXPECT_TRUE(coordinator.PopulateTcypherContext(&context).ok());
    auto stream = ExecuteTcypher(query, std::move(context));
    EXPECT_TRUE(stream.ok()) << stream.status().ToString();
    ResultBatch first;
    if (stream.ok()) EXPECT_TRUE(stream.ValueOrDie()->Next(&first).ok());
    return first;
  };

  auto valid_stats = std::make_shared<TcypherExecutionStats>();
  ResultBatch valid_to = execute_first(
      "MATCH (n) RETURN n, valid_to(n);", valid_stats);
  ASSERT_EQ(valid_to.batch().row_count(), 1U);
  EXPECT_EQ(valid_stats->pinned_root_scan_opens, 1U);
  EXPECT_EQ(valid_stats->vector_materialized_root_events, 0U);
  EXPECT_EQ(valid_stats->root_sst_blocks_read, 1U);
  EXPECT_GT(valid_stats->pinned_boundary_point_scans, 0U);

  auto system_stats = std::make_shared<TcypherExecutionStats>();
  ResultBatch system_time = execute_first(
      "MATCH (n) RETURN n, system_time(n);", system_stats);
  ASSERT_EQ(system_time.batch().row_count(), 1U);
  EXPECT_EQ(system_stats->pinned_root_scan_opens, 1U);
  EXPECT_EQ(system_stats->vector_materialized_root_events, 0U);
  EXPECT_EQ(system_stats->root_sst_blocks_read, 1U);
  EXPECT_EQ(system_stats->pinned_boundary_point_scans, 0U);
}

