  for (uint64_t index = 0; index < 1000; ++index, ++commit_seq) {
    ASSERT_TRUE(memtable->Insert(TemporalEvent::Put(
        LogicalKey::VertexProperty(1, 7), 10, commit_seq, 1,
        Value::String("other-" + std::to_string(index)))).ok());
  }
  for (uint64_t index = 0; index < 130; ++index, ++commit_seq) {
    ASSERT_TRUE(memtable->Insert(TemporalEvent::Put(
        LogicalKey::VertexProperty(1, 7), 10, commit_seq, 1,
        Value::String("target"))).ok());
  }
  IndexDefinition definition;
  definition.index_id = 1;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kActive;
  auto catalog = std::make_shared<IndexCatalogSnapshot>();
  catalog->definitions.push_back(definition);
  TcypherDeltaIndexSource delta;
  delta.index_id = definition.index_id;
  delta.source_generation = commit_seq - 1;
  delta.pinned_memtable = memtable;
  delta.definition = definition;
  auto stats = std::make_shared<TcypherExecutionStats>();
  TcypherQueryOptions options;
  options.statement_start_valid_time = 10;
  options.batch_capacity = 1;
  options.execution_stats = stats;
