  context.index_catalog_snapshot = catalog;
  context.index_sources.push_back(std::move(source));
  auto stream = OpenPhysicalRootForTest(query, std::move(context));
  ASSERT_TRUE(stream.ok()) << stream.status().ToString();
  ResultBatch result;
  ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 1U);
  EXPECT_EQ(stats->index_predicate_literals_canonicalized, kLiteralCount);
  EXPECT_GE(stats->index_predicate_canonicalization_yields,
            kLiteralCount / 64);
