TEST(TcypherExecutorTest, AdvisoryDeltaAdmissionIncludesCanonicalPayloadCopies) {
  CommitTimeline timeline("/tmp/cedar_unused_advisory_canonical_memory_timeline");
  auto memtable = std::make_shared<TemporalMemTable>();
  ASSERT_TRUE(memtable->Insert(TemporalEvent::Put(
      LogicalKey::VertexExistence(1), 10, 1, 1, Value::Binary(""))).ok());
  std::string target;
  for (uint64_t commit_seq = 2; commit_seq <= 81; ++commit_seq) {
    std::string value = "value-" + std::to_string(commit_seq) + "-";
    value.append(1024 - value.size(), static_cast<char>('a' + commit_seq % 26));
    if (commit_seq == 81) target = value;
    ASSERT_TRUE(memtable->Insert(TemporalEvent::Put(
        LogicalKey::VertexProperty(1, 7), 10, commit_seq, 1,
        Value::String(std::move(value)))).ok());
  }
  IndexDefinition definition;
  definition.index_id = 1;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kActive;
  auto catalog = std::make_shared<IndexCatalogSnapshot>();
  catalog->definitions.push_back(definition);
  TcypherDeltaIndexSource delta;
  delta.index_id = definition.index_id;
  delta.source_generation = 81;
  delta.pinned_memtable = memtable;
  delta.definition = definition;

  auto memory = std::make_shared<QueryMemoryAccount>(112U << 10, 128U << 10);
  auto stats = std::make_shared<TcypherExecutionStats>();
  {
    TcypherQueryOptions options;
    options.statement_start_valid_time = 10;
    options.batch_capacity = 1;
    options.memory_account = memory;
    options.execution_stats = stats;
    TcypherExecutionContext context{
        timeline, 81, options, MakeTcypherBinderSchemaSnapshot(), {}};
    context.index_catalog_snapshot = catalog;
    context.delta_index_sources.push_back(std::move(delta));
    context.memtable_event_sources.push_back(memtable);
    auto stream = OpenPhysicalRootForTest(
        "MATCH (n {id: 1}) WHERE n.name = '" + target + "' RETURN n;",
        std::move(context));
    ASSERT_TRUE(stream.ok()) << stream.status().ToString();
    ResultBatch result;
    ASSERT_TRUE(stream.ValueOrDie()->Next(&result).ok());
    ASSERT_EQ(result.batch().row_count(), 1U);
    EXPECT_EQ(*result.batch().ValueAt(0, 0), Value::Int64(1));
    EXPECT_EQ(stats->index_advisory_fallbacks, 1U);
  }
  EXPECT_EQ(memory->used_bytes(), 0U);
}

