TEST_F(DurableLogTest, PhysicalRuntimeRejectsSourcesFromAnotherSnapshotEnvelope) {
  TransactionCoordinator coordinator(path_, 1, 11);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema existence{EntityType::Vertex, 0, 0, "existence",
                         PhysicalType::kBinary, 4096,
                         EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(existence, &registered).ok());
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(LogicalKey::VertexExistence(1), 10,
                        registered.schema_epoch, Value::Binary("")),
  }, &commit_seq).ok());
  ASSERT_TRUE(coordinator.Flush().ok());
  TcypherExecutionContext context{
      coordinator.commit_timeline(), 0, {}, nullptr, {}};
  context.options.statement_start_valid_time = 10;
  ASSERT_TRUE(coordinator.PopulateTcypherContext(&context).ok());
  ASSERT_EQ(context.sst_event_sources.size(), 1U);

  const auto parsed = ParseTcypher("MATCH (n) RETURN n;");
  ASSERT_TRUE(parsed.ok()) << parsed.status().ToString();
  const auto bound = BindTcypher(
      parsed.ValueOrDie(),
      TcypherBindingContext{context.commit_timeline,
                            context.visible_seq_ceiling,
                            context.options.statement_start_valid_time,
                            context.options.timestamp_parameters,
                            context.schema_snapshot});
  ASSERT_TRUE(bound.ok()) << bound.status().ToString();
  const auto logical = LowerTcypher(bound.ValueOrDie());
  ASSERT_TRUE(logical.ok()) << logical.status().ToString();
  const auto plan = PlanPhysicalRootPoint(
      bound.ValueOrDie(), logical.ValueOrDie());
  ASSERT_TRUE(plan.ok()) << plan.status().ToString();
  const auto snapshot = BuildPhysicalQuerySnapshot(bound.ValueOrDie(), context);
  ASSERT_TRUE(snapshot.ok()) << snapshot.status().ToString();

  TcypherExecutionContext wrong_schema = context;
  wrong_schema.schema_snapshot =
      std::make_shared<SchemaSnapshot>(*context.schema_snapshot);
  EXPECT_TRUE(OpenPhysicalRootPointRuntime(
      plan.ValueOrDie(), snapshot.ValueOrDie(),
      std::move(wrong_schema)).status().IsCorruption());

  TcypherExecutionContext wrong_version = context;
  auto replacement_version =
      std::make_shared<VersionSnapshot>(*context.version_snapshot);
  ++replacement_version->generation;
  wrong_version.version_snapshot = replacement_version;
  wrong_version.blob_reader_epoch = replacement_version->generation;
  EXPECT_TRUE(OpenPhysicalRootPointRuntime(
      plan.ValueOrDie(), snapshot.ValueOrDie(),
      std::move(wrong_version)).status().IsCorruption());

  TcypherExecutionContext wrong_descriptor = context;
  BlobHash unexpected{};
  unexpected.bytes[0] = 1;
  wrong_descriptor.sst_event_sources[0].metadata.blob_refs.push_back(unexpected);
  EXPECT_TRUE(OpenPhysicalRootPointRuntime(
      plan.ValueOrDie(), snapshot.ValueOrDie(),
      std::move(wrong_descriptor)).status().IsCorruption());
}

TEST_F(DurableLogTest, BlobStoreDeduplicatesDurableContentAndRejectsUnknownHashes) {
  BlobStore store(path_ + "/blobs", 4);
  ASSERT_TRUE(store.Open().ok());
  const auto first = store.Put("large value payload");
  ASSERT_TRUE(first.ok()) << first.status().ToString();
  const auto duplicate = store.Put("large value payload");
  ASSERT_TRUE(duplicate.ok()) << duplicate.status().ToString();
  EXPECT_EQ(first.ValueOrDie().content_hash, duplicate.ValueOrDie().content_hash);
  const auto distinct = store.Put("different large value payload");
  ASSERT_TRUE(distinct.ok()) << distinct.status().ToString();
  EXPECT_NE(first.ValueOrDie().content_hash, distinct.ValueOrDie().content_hash);
  EXPECT_EQ(store.stored_blob_count(), 2U);
  const auto read = store.Get(first.ValueOrDie());
  ASSERT_TRUE(read.ok()) << read.status().ToString();
  EXPECT_EQ(read.ValueOrDie(), "large value payload");

  BlobStore reopened(path_ + "/blobs", 4);
  ASSERT_TRUE(reopened.Open().ok());
  EXPECT_EQ(reopened.Get(first.ValueOrDie()).ValueOrDie(), "large value payload");
  EXPECT_EQ(reopened.Get(distinct.ValueOrDie()).ValueOrDie(),
            "different large value payload");
  BlobRef missing = first.ValueOrDie();
  missing.content_hash.bytes[0] ^= 1;
  EXPECT_TRUE(reopened.Get(missing).status().IsBlobCorruption());
  BlobRef wrong_length = first.ValueOrDie();
  ++wrong_length.raw_length;
  EXPECT_TRUE(reopened.Get(wrong_length).status().IsBlobCorruption());
}

TEST_F(DurableLogTest, BlobStoreWritesIndexedBlobBlockAndReopensIt) {
  const std::string blob_root = path_ + "/blob-block";
  BlobStore store(blob_root, 1);
  ASSERT_TRUE(store.Open().ok());
  const auto reference = store.Put("block framed payload");
  ASSERT_TRUE(reference.ok()) << reference.status().ToString();
  EXPECT_EQ(reference.ValueOrDie().hint.offset, 0U);

  const std::string segment_path =
      blob_root + "/shard-0/segment-1.blob";
  std::ifstream segment(segment_path, std::ios::binary);
  ASSERT_TRUE(segment.good());
  const std::string bytes{std::istreambuf_iterator<char>(segment),
                          std::istreambuf_iterator<char>()};
  ASSERT_GE(bytes.size(), 88U);
  EXPECT_EQ(bytes.substr(0, 4), "CBB1");
  const auto little_endian_u64 = [&bytes](size_t offset) {
    uint64_t value = 0;
    for (uint32_t byte = 0; byte < 8; ++byte) {
      value |= static_cast<uint64_t>(
                   static_cast<uint8_t>(bytes[offset + byte]))
               << (byte * 8);
    }
    return value;
  };
  EXPECT_EQ(little_endian_u64(16), bytes.size());
  EXPECT_EQ(little_endian_u64(24), 1U);

  BlobStore reopened(blob_root, 1);
  ASSERT_TRUE(reopened.Open().ok());
  const auto restored = reopened.Get(reference.ValueOrDie());
  ASSERT_TRUE(restored.ok()) << restored.status().ToString();
  EXPECT_EQ(restored.ValueOrDie(), "block framed payload");
}

TEST_F(DurableLogTest, CommitPacksMultipleSmallBlobsIntoOneBlobBlock) {
  TransactionCoordinator coordinator(path_ + "/packed-commit", 1, 19);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 41, 0, "payload",
                      PhysicalType::kString, 1,
                      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(
      0,
      {PendingEvent::Put(LogicalKey::VertexProperty(1, 41), 1,
                         registered.schema_epoch,
                         Value::String("first block payload")),
       PendingEvent::Put(LogicalKey::VertexProperty(2, 41), 1,
                         registered.schema_epoch,
                         Value::String("second block payload"))},
      &commit_seq).ok());

  const auto committed = coordinator.SnapshotCommittedEvents();
  ASSERT_TRUE(committed.ok()) << committed.status().ToString();
  std::vector<BlobRef> references;
  for (const TemporalEvent& event : committed.ValueOrDie()) {
    if (event.blob_ref().has_value()) references.push_back(*event.blob_ref());
  }
  ASSERT_EQ(references.size(), 2U);
  EXPECT_EQ(references[0].hint.segment_id, references[1].hint.segment_id);
  EXPECT_EQ(references[0].hint.offset, references[1].hint.offset);

  const std::string segment_path =
      path_ + "/packed-commit/blobs/shard-0/segment-1.blob";
  std::ifstream segment(segment_path, std::ios::binary);
  ASSERT_TRUE(segment.good());
  const std::string bytes{std::istreambuf_iterator<char>(segment),
                          std::istreambuf_iterator<char>()};
  ASSERT_GE(bytes.size(), 88U);
  EXPECT_EQ(bytes.substr(0, 4), "CBB1");
  uint64_t record_count = 0;
  for (uint32_t byte = 0; byte < 8; ++byte) {
    record_count |= static_cast<uint64_t>(
                        static_cast<uint8_t>(bytes[24 + byte]))
                    << (byte * 8);
  }
  EXPECT_EQ(record_count, 2U);
}

TEST_F(DurableLogTest, BlobLargerThanBlockTargetUsesOversizedBlock) {
  const std::string blob_root = path_ + "/oversized-block";
  BlobStore store(blob_root, 1);
  ASSERT_TRUE(store.Open().ok());
  const std::string payload((1U << 20) + 1, 'o');
  const auto reference = store.Put(payload);
  ASSERT_TRUE(reference.ok()) << reference.status().ToString();

  std::ifstream segment(blob_root + "/shard-0/segment-1.blob",
                        std::ios::binary);
  ASSERT_TRUE(segment.good());
  std::array<char, 16> header{};
  segment.read(header.data(), static_cast<std::streamsize>(header.size()));
  ASSERT_EQ(segment.gcount(), static_cast<std::streamsize>(header.size()));
  EXPECT_EQ(std::string(header.data(), 4), "CBB1");
  uint32_t flags = 0;
  for (uint32_t byte = 0; byte < 4; ++byte) {
    flags |= static_cast<uint32_t>(
                 static_cast<uint8_t>(header[12 + byte]))
             << (byte * 8);
  }
  EXPECT_EQ(flags & 1U, 1U);
  EXPECT_EQ(store.Get(reference.ValueOrDie()).ValueOrDie(), payload);
}

TEST_F(DurableLogTest, BlobBatchStartsANewBlockAtTheOneMiBTarget) {
  const auto incompressible = [](uint64_t seed) {
    std::string payload(450 * 1024, '\0');
    uint64_t state = seed;
    for (char& byte : payload) {
      state ^= state << 13;
      state ^= state >> 7;
      state ^= state << 17;
      byte = static_cast<char>(state);
    }
    return payload;
  };
  const std::vector<std::string> payloads = {
      incompressible(0x123456789abcdef0ULL),
      incompressible(0x0fedcba987654321ULL),
      incompressible(0x3141592653589793ULL)};
  const std::string blob_root = path_ + "/block-target";
  BlobStore store(blob_root, 1);
  ASSERT_TRUE(store.Open().ok());
  const auto references = store.PutBatch(payloads);
  ASSERT_TRUE(references.ok()) << references.status().ToString();
  ASSERT_EQ(references.ValueOrDie().size(), payloads.size());
  EXPECT_EQ(references.ValueOrDie()[0].hint.offset,
            references.ValueOrDie()[1].hint.offset);
  EXPECT_NE(references.ValueOrDie()[1].hint.offset,
            references.ValueOrDie()[2].hint.offset);

  BlobStore reopened(blob_root, 1);
  ASSERT_TRUE(reopened.Open().ok());
  for (size_t index = 0; index < payloads.size(); ++index) {
    const auto restored = reopened.Get(references.ValueOrDie()[index]);
    ASSERT_TRUE(restored.ok()) << restored.status().ToString();
    EXPECT_EQ(restored.ValueOrDie(), payloads[index]);
  }
}

