TEST_F(DurableLogTest, ConcurrentEqualBlobPutsPublishOnePhysicalRecord) {
  const std::string payload(64 * 1024, 'd');
  BlobStore baseline(path_ + "/baseline-blobs", 1);
  ASSERT_TRUE(baseline.Open().ok());
  ASSERT_TRUE(baseline.Put(payload).ok());
  const uint64_t baseline_segment_bytes = std::filesystem::file_size(
      path_ + "/baseline-blobs/shard-0/segment-1.blob");
  const uint64_t baseline_index_bytes = std::filesystem::file_size(
      path_ + "/baseline-blobs/shard-0/INDEX");

  BlobStore concurrent(path_ + "/concurrent-blobs", 1);
  ASSERT_TRUE(concurrent.Open().ok());
  constexpr size_t kThreads = 16;
  std::mutex gate_mutex;
  std::condition_variable gate;
  size_t ready = 0;
  bool start = false;
  std::vector<Status> statuses(
      kThreads, Status::InvalidArgument("test", "worker did not run"));
  std::vector<BlobRef> references(kThreads);
  std::vector<std::thread> workers;
  for (size_t worker = 0; worker < kThreads; ++worker) {
    workers.emplace_back([&, worker] {
      {
        std::unique_lock<std::mutex> lock(gate_mutex);
        ++ready;
        gate.notify_all();
        gate.wait(lock, [&] { return start; });
      }
      const auto stored = concurrent.Put(payload);
      statuses[worker] = stored.status();
      if (stored.ok()) references[worker] = stored.ValueOrDie();
    });
  }
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    gate.wait(lock, [&] { return ready == kThreads; });
    start = true;
  }
  gate.notify_all();
  for (std::thread& worker : workers) worker.join();

  for (size_t worker = 0; worker < kThreads; ++worker) {
    ASSERT_TRUE(statuses[worker].ok())
        << "worker=" << worker << " " << statuses[worker].ToString();
    EXPECT_EQ(references[worker].content_hash, references[0].content_hash);
    EXPECT_EQ(references[worker].hint.segment_id,
              references[0].hint.segment_id);
    EXPECT_EQ(references[worker].hint.offset, references[0].hint.offset);
  }
  EXPECT_EQ(concurrent.stored_blob_count(), 1U);
  EXPECT_EQ(std::filesystem::file_size(
                path_ + "/concurrent-blobs/shard-0/segment-1.blob"),
            baseline_segment_bytes);
  EXPECT_EQ(std::filesystem::file_size(
                path_ + "/concurrent-blobs/shard-0/INDEX"),
            baseline_index_bytes);

  BlobStore reopened(path_ + "/concurrent-blobs", 1);
  ASSERT_TRUE(reopened.Open().ok());
  const auto restored = reopened.Get(references[0]);
  ASSERT_TRUE(restored.ok()) << restored.status().ToString();
  EXPECT_EQ(restored.ValueOrDie(), payload);
}

TEST_F(DurableLogTest,
       BlobRecordFaultBoundariesLeaveOnlyReclaimableUnindexedOrphans) {
  for (uint8_t boundary = 0; boundary < 2; ++boundary) {
    const std::string blob_root =
        path_ + "/record-fault-" + std::to_string(boundary);
    BlobStore store(blob_root, 1);
    ASSERT_TRUE(store.Open().ok());
    const BlobStoreFaultPoint selected = boundary == 0
        ? BlobStoreFaultPoint::kAfterPartialRecordWrite
        : BlobStoreFaultPoint::kAfterRecordFsync;
    store.SetFaultInjectorForTesting(
        [selected](BlobStoreFaultPoint point) {
          return point == selected
              ? Status::IOError("test", "Blob record publication fault")
              : Status::OK();
        });
    const std::string payload =
        "record fault payload " + std::to_string(boundary);
    const auto failed = store.Put(payload);
    EXPECT_TRUE(failed.status().IsIOError())
        << "boundary=" << static_cast<uint32_t>(boundary) << " "
        << failed.status().ToString();

    store.SetFaultInjectorForTesting({});
    const auto retried = store.Put(payload);
    ASSERT_TRUE(retried.ok()) << retried.status().ToString();
    EXPECT_EQ(store.stored_blob_count(), 1U);
    ASSERT_TRUE(store.RotateActiveSegments().ok());
    const std::string retired = blob_root + "/shard-0/segment-1.blob";
    ASSERT_TRUE(std::filesystem::exists(retired));
    BlobReferenceCatalog catalog;
    catalog.ReplaceSource("sst:1", {retried.ValueOrDie().content_hash});
    BlobGarbageCollector collector(&store);
    ASSERT_TRUE(collector.Collect(catalog).ok());
    EXPECT_FALSE(std::filesystem::exists(retired));
    const auto restored = store.Get(retried.ValueOrDie());
    ASSERT_TRUE(restored.ok()) << restored.status().ToString();
    EXPECT_EQ(restored.ValueOrDie(), payload);
  }
}

TEST_F(DurableLogTest, BlobPayloadDetectsCrcAndBlake3Corruption) {
  const auto corrupt = [&](const std::string& root, bool preserve_crc) {
    BlobStore store(root, 1);
    ASSERT_TRUE(store.Open().ok());
    const std::string payload = "blob-verification-payload-0123456789";
    const auto reference = store.Put(payload);
    ASSERT_TRUE(reference.ok()) << reference.status().ToString();
    std::string corrupted = payload;
    corrupted[5] ^= 0x40;
    const std::string segment_path = root + "/shard-0/segment-1.blob";
    std::ifstream input(segment_path, std::ios::binary);
    ASSERT_TRUE(input.good());
    std::string segment{std::istreambuf_iterator<char>(input),
                        std::istreambuf_iterator<char>()};
    const size_t block_offset =
        static_cast<size_t>(reference.ValueOrDie().hint.offset);
    ASSERT_GE(segment.size(), block_offset + 88 + 57 + payload.size());
    const auto read_u64 = [&segment](size_t offset) {
      uint64_t value = 0;
      for (uint32_t byte = 0; byte < 8; ++byte) {
        value |= static_cast<uint64_t>(
                     static_cast<uint8_t>(segment[offset + byte]))
                 << (byte * 8);
      }
      return value;
    };
    const auto put_u32 = [&segment](size_t offset, uint32_t value) {
      for (uint32_t byte = 0; byte < 4; ++byte) {
        segment[offset + byte] = static_cast<char>(value >> (byte * 8));
      }
    };
    const size_t payload_offset = block_offset + 88 + 57;
    segment.replace(payload_offset, corrupted.size(), corrupted);
    if (preserve_crc) {
      const uint32_t checksum =
          crc32c::Value(corrupted.data(), corrupted.size());
      put_u32(block_offset + 88 + 53, checksum);
      const size_t directory_offset =
          block_offset + static_cast<size_t>(read_u64(block_offset + 32));
      put_u32(directory_offset + 68, checksum);
      const uint64_t directory_length = read_u64(block_offset + 40);
      const std::string directory = segment.substr(
          directory_offset, static_cast<size_t>(directory_length));
      put_u32(block_offset + 48,
              crc32c::Value(directory.data(), directory.size()));
      const BlobHash block_identity = Blake3Hash(
          segment.substr(block_offset, 52) + directory);
      std::memcpy(segment.data() + block_offset + 52,
                  block_identity.bytes.data(), block_identity.bytes.size());
      put_u32(block_offset + 84,
              crc32c::Value(segment.data() + block_offset, 84));
    }
    std::fstream file(segment_path,
                      std::ios::binary | std::ios::in | std::ios::out);
    ASSERT_TRUE(file.good());
    file.write(segment.data(), static_cast<std::streamsize>(segment.size()));
    file.close();
    EXPECT_TRUE(store.Get(reference.ValueOrDie()).status().IsBlobCorruption());
  };

  corrupt(path_ + "/crc-corruption", false);
  corrupt(path_ + "/hash-corruption", true);
}

TEST_F(DurableLogTest,
       BlobGcConcurrentWriterRespectsLongSnapshotPinAndStaleReferences) {
  TransactionCoordinator coordinator(path_, 1, 17);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 6, 0, "payload",
                      PhysicalType::kString, 1,
                      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
  const LogicalKey old_key = LogicalKey::VertexProperty(1, 6);
  const LogicalKey new_key = LogicalKey::VertexProperty(2, 6);
  const std::string old_payload(32 * 1024, 'o');
  const std::string new_payload(32 * 1024, 'n');
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(0, {
      PendingEvent::Put(old_key, 1, registered.schema_epoch,
                        Value::String(old_payload)),
  }, &commit_seq).ok());
  ASSERT_TRUE(coordinator.Flush().ok());
  const auto committed = coordinator.SnapshotCommittedEvents();
  ASSERT_TRUE(committed.ok()) << committed.status().ToString();
  const auto old_event = std::find_if(
      committed.ValueOrDie().begin(), committed.ValueOrDie().end(),
      [&old_key](const TemporalEvent& event) {
        return event.logical_key() == old_key && event.is_blob_reference();
      });
  ASSERT_NE(old_event, committed.ValueOrDie().end());
  const TemporalEvent stale_reference = *old_event;
  ASSERT_EQ(stale_reference.blob_ref()->hint.segment_id, 1U);

  ASSERT_TRUE(coordinator.RotateBlobSegments().ok());
  std::shared_ptr<const VersionSnapshot> pinned =
      coordinator.version_snapshot();
  ASSERT_EQ(pinned->blob_segments.size(), 2U);
  const std::string sealed = path_ + "/blobs/shard-0/segment-1.blob";
  ASSERT_TRUE(std::filesystem::exists(sealed));

  std::mutex gate_mutex;
  std::condition_variable gate;
  size_t ready = 0;
  bool start = false;
  Status writer_status =
      Status::InvalidArgument("test", "writer did not run");
  Status gc_status = Status::InvalidArgument("test", "gc did not run");
  std::thread writer([&] {
    {
      std::unique_lock<std::mutex> lock(gate_mutex);
      ++ready;
      gate.notify_all();
      gate.wait(lock, [&] { return start; });
    }
    uint64_t written_seq = 0;
    writer_status = coordinator.Commit(0, {
        PendingEvent::Put(new_key, 1, registered.schema_epoch,
                          Value::String(new_payload)),
    }, &written_seq);
  });
  std::thread collector([&] {
    {
      std::unique_lock<std::mutex> lock(gate_mutex);
      ++ready;
      gate.notify_all();
      gate.wait(lock, [&] { return start; });
    }
    gc_status = coordinator.CollectBlobGarbage();
  });
  {
    std::unique_lock<std::mutex> lock(gate_mutex);
    gate.wait(lock, [&] { return ready == 2; });
    start = true;
  }
  gate.notify_all();
  writer.join();
  collector.join();
  ASSERT_TRUE(writer_status.ok()) << writer_status.ToString();
  if (gc_status.IsConflict()) {
    EXPECT_TRUE(std::filesystem::exists(sealed))
        << "conflicting GC deleted the sealed segment";
    gc_status = coordinator.CollectBlobGarbage();
  }
  ASSERT_TRUE(gc_status.ok()) << gc_status.ToString();

  EXPECT_TRUE(std::filesystem::exists(sealed))
      << "pinned_generation=" << pinned->generation
      << " pinned_use_count=" << pinned.use_count();
  const auto old_while_pinned =
      coordinator.MaterializeBlobValue(stale_reference);
  ASSERT_TRUE(old_while_pinned.ok())
      << old_while_pinned.status().ToString();
  ASSERT_TRUE(old_while_pinned.ValueOrDie().has_value());
  EXPECT_EQ(*old_while_pinned.ValueOrDie(), Value::String(old_payload));
  const auto new_value = coordinator.GetChecked(new_key, 1);
  ASSERT_TRUE(new_value.ok()) << new_value.status().ToString();
  ASSERT_TRUE(new_value.ValueOrDie().has_value());
  EXPECT_EQ(*new_value.ValueOrDie(), Value::String(new_payload));

  pinned.reset();
  ASSERT_TRUE(coordinator.CollectBlobGarbage().ok());
  EXPECT_FALSE(std::filesystem::exists(sealed));
  const auto old_after_reclaim =
      coordinator.MaterializeBlobValue(stale_reference);
  ASSERT_TRUE(old_after_reclaim.ok())
      << old_after_reclaim.status().ToString();
  ASSERT_TRUE(old_after_reclaim.ValueOrDie().has_value());
  EXPECT_EQ(*old_after_reclaim.ValueOrDie(), Value::String(old_payload));
}

TEST_F(DurableLogTest, PartialBlobIndexWriteRequiresReopenAndTruncatesTornTail) {
  const std::string blob_root = path_ + "/blobs";
  const std::string index_path = blob_root + "/shard-0/INDEX";
  BlobStore store(blob_root, 1);
  ASSERT_TRUE(store.Open().ok());
  store.SetIndexFaultInjectorForTesting([](BlobStoreFaultPoint point) {
    return point == BlobStoreFaultPoint::kAfterPartialIndexWrite
        ? Status::IOError("test", "partial Blob INDEX")
        : Status::OK();
  });
  const auto partial = store.Put("partial index payload");
  EXPECT_TRUE(partial.status().IsIOError()) << partial.status().ToString();
  EXPECT_TRUE(store.requires_reopen());
  ASSERT_TRUE(std::filesystem::exists(index_path));
  EXPECT_GT(std::filesystem::file_size(index_path), 0U);
  EXPECT_TRUE(store.Put("blocked payload").status().IsRecoveryRequired());

  store.SetIndexFaultInjectorForTesting({});
  ASSERT_TRUE(store.Open().ok());
  EXPECT_FALSE(store.requires_reopen());
  EXPECT_EQ(std::filesystem::file_size(index_path), 0U);
  const auto clean = store.Put("clean index payload");
  ASSERT_TRUE(clean.ok()) << clean.status().ToString();
  EXPECT_EQ(store.Get(clean.ValueOrDie()).ValueOrDie(), "clean index payload");
  const uint64_t clean_index_bytes = std::filesystem::file_size(index_path);
  {
    std::ofstream index(index_path, std::ios::binary | std::ios::app);
    ASSERT_TRUE(index.good());
    index.write("tail", 4);
  }
  BlobStore header_reopened(blob_root, 1);
  ASSERT_TRUE(header_reopened.Open().ok());
  EXPECT_EQ(std::filesystem::file_size(index_path), clean_index_bytes);
  EXPECT_EQ(header_reopened.Get(clean.ValueOrDie()).ValueOrDie(),
            "clean index payload");
}

TEST_F(DurableLogTest, RecreatedBlobStoreSyncsIndexDirectoryBeforeReuse) {
  const std::string blob_root = path_ + "/blobs";
  {
    BlobStore failed_writer(blob_root, 1);
    ASSERT_TRUE(failed_writer.Open().ok());
    failed_writer.SetIndexFaultInjectorForTesting([](BlobStoreFaultPoint point) {
      return point == BlobStoreFaultPoint::kAfterIndexFsync
          ? Status::IOError("test", "post-fsync Blob INDEX failure")
          : Status::OK();
    });
    const auto failed = failed_writer.Put("durable index payload");
    EXPECT_TRUE(failed.status().IsIOError()) << failed.status().ToString();
    EXPECT_TRUE(failed_writer.requires_reopen());
  }

  BlobStore recreated(blob_root, 1);
  recreated.SetIndexFaultInjectorForTesting([](BlobStoreFaultPoint point) {
    return point == BlobStoreFaultPoint::kBeforeRecoveryDirectoryFsync
        ? Status::IOError("test", "Blob INDEX recovery directory fsync")
        : Status::OK();
  });
  EXPECT_TRUE(recreated.Open().IsIOError());
  EXPECT_TRUE(recreated.requires_reopen());
  EXPECT_TRUE(recreated.Put("blocked").status().IsRecoveryRequired());

  recreated.SetIndexFaultInjectorForTesting({});
  ASSERT_TRUE(recreated.Open().ok());
  EXPECT_FALSE(recreated.requires_reopen());
  const auto recovered = recreated.Put("durable index payload");
  ASSERT_TRUE(recovered.ok()) << recovered.status().ToString();
  EXPECT_EQ(recreated.Get(recovered.ValueOrDie()).ValueOrDie(),
            "durable index payload");
  EXPECT_TRUE(recreated.Put("safe reuse").ok());
}

