TEST_F(DurableLogTest, BlobStoreRotatesActiveSegmentsWithoutBreakingOldReferences) {
  BlobStore store(path_ + "/blobs", 1);
  ASSERT_TRUE(store.Open().ok());
  const auto old_reference = store.Put("sealed content");
  ASSERT_TRUE(old_reference.ok()) << old_reference.status().ToString();
  ASSERT_TRUE(store.RotateActiveSegments().ok());
  const auto new_reference = store.Put("active content");
  ASSERT_TRUE(new_reference.ok()) << new_reference.status().ToString();
  EXPECT_NE(old_reference.ValueOrDie().hint.segment_id,
            new_reference.ValueOrDie().hint.segment_id);

  BlobStore reopened(path_ + "/blobs", 1);
  ASSERT_TRUE(reopened.Open().ok());
  EXPECT_EQ(reopened.Get(old_reference.ValueOrDie()).ValueOrDie(), "sealed content");
  EXPECT_EQ(reopened.Get(new_reference.ValueOrDie()).ValueOrDie(), "active content");
}

