TEST_F(DurableLogTest, RunningBlobGcCancellationStopsAtThe64HashBatch) {
  BlobStore store(path_ + "/blobs", 1);
  ASSERT_TRUE(store.Open().ok());
  std::vector<std::string> payloads;
  for (uint64_t ordinal = 0; ordinal < 65; ++ordinal) {
    payloads.push_back("keep sealed payload " + std::to_string(ordinal));
  }
  const auto old_references = store.PutBatch(payloads);
  ASSERT_TRUE(old_references.ok()) << old_references.status().ToString();
  ASSERT_TRUE(store.RotateActiveSegments().ok());
  uint64_t checkpoints = 0;
  auto cancellation = std::make_shared<WorkCancellation>();
  cancellation->SetCheckpointObserverForTesting(
      [&](WorkCancellation* token, const std::string& owner,
          uint64_t checkpoint) {
        EXPECT_EQ(owner, "blob gc relocation");
        checkpoints = checkpoint;
        if (checkpoint == 4) token->Cancel();
      });
  std::vector<BlobHash> hashes;
  for (const BlobRef& reference : old_references.ValueOrDie()) {
    hashes.push_back(reference.content_hash);
  }

  const Status relocated = store.RelocateLiveHashes(hashes, cancellation);
  EXPECT_TRUE(relocated.IsQueryCancelled()) << relocated.ToString();
  EXPECT_EQ(checkpoints, 4U);
  const auto relocated_reference = store.Put(payloads.front());
  const auto unvisited_reference = store.Put(payloads.back());
  ASSERT_TRUE(relocated_reference.ok())
      << relocated_reference.status().ToString();
  ASSERT_TRUE(unvisited_reference.ok())
      << unvisited_reference.status().ToString();
  EXPECT_NE(relocated_reference.ValueOrDie().hint.segment_id,
            old_references.ValueOrDie().front().hint.segment_id);
  EXPECT_EQ(unvisited_reference.ValueOrDie().hint.segment_id,
            old_references.ValueOrDie().back().hint.segment_id);

  BlobStore reopened(path_ + "/blobs", 1);
  ASSERT_TRUE(reopened.Open().ok());
  for (size_t index = 0; index < payloads.size(); ++index) {
    EXPECT_EQ(reopened.Get(old_references.ValueOrDie()[index]).ValueOrDie(),
              payloads[index]);
  }
}

TEST_F(DurableLogTest, BlobGcRelocationUsesTheSamePackedBlockWriterAsPut) {
  const std::string blob_root = path_ + "/packed-gc";
  BlobStore store(blob_root, 1);
  ASSERT_TRUE(store.Open().ok());
  const std::vector<std::string> payloads = {
      "first relocation payload", "second relocation payload"};
  const auto original = store.PutBatch(payloads);
  ASSERT_TRUE(original.ok()) << original.status().ToString();
  ASSERT_TRUE(store.RotateActiveSegments().ok());
  ASSERT_TRUE(store.RelocateLiveHashes(
      {original.ValueOrDie()[0].content_hash,
       original.ValueOrDie()[1].content_hash}).ok());

  const auto first = store.Put(payloads[0]);
  const auto second = store.Put(payloads[1]);
  ASSERT_TRUE(first.ok()) << first.status().ToString();
  ASSERT_TRUE(second.ok()) << second.status().ToString();
  EXPECT_EQ(first.ValueOrDie().hint.segment_id, 2U);
  EXPECT_EQ(second.ValueOrDie().hint.segment_id, 2U);
  EXPECT_EQ(first.ValueOrDie().hint.offset,
            second.ValueOrDie().hint.offset);

  std::ifstream segment(blob_root + "/shard-0/segment-2.blob",
                        std::ios::binary);
  ASSERT_TRUE(segment.good());
  std::array<char, 32> header{};
  segment.read(header.data(), static_cast<std::streamsize>(header.size()));
  ASSERT_EQ(segment.gcount(), static_cast<std::streamsize>(header.size()));
  EXPECT_EQ(std::string(header.data(), 4), "CBB1");
  uint64_t record_count = 0;
  for (uint32_t byte = 0; byte < 8; ++byte) {
    record_count |= static_cast<uint64_t>(
                        static_cast<uint8_t>(header[24 + byte]))
                    << (byte * 8);
  }
  EXPECT_EQ(record_count, 2U);
}

