TEST_F(DurableLogTest, BlobGcReleasesRelocationGrantAfterFailure) {
  const auto prepare_live_blob = [](TransactionCoordinator* coordinator,
                                    uint16_t column_id,
                                    const std::string& payload) {
    ColumnSchema schema{EntityType::Vertex, column_id, 0, "payload",
                        PhysicalType::kString, 1,
                        EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
    ColumnSchema registered;
    Status status = coordinator->RegisterColumn(schema, &registered);
    if (!status.ok()) return status;
    uint64_t commit_seq = 0;
    status = coordinator->Commit(
        0, {PendingEvent::Put(LogicalKey::VertexProperty(1, column_id), 1,
                              registered.schema_epoch,
                              Value::String(payload))},
        &commit_seq);
    if (!status.ok()) return status;
    return coordinator->RotateBlobSegments();
  };

  const std::string exact_root = path_ + "/exact";
  TransactionCoordinator exact(exact_root, 1, 13);
  ASSERT_TRUE(exact.Open().ok());
  ASSERT_TRUE(prepare_live_blob(&exact, 32, "exact relocation payload").ok());
  const std::string exact_sealed =
      exact_root + "/blobs/shard-0/segment-1.blob";
  const std::string exact_active =
      exact_root + "/blobs/shard-0/segment-2.blob";
  const uint64_t exact_bytes = std::filesystem::file_size(exact_sealed);
  const uint64_t exact_active_before =
      std::filesystem::file_size(exact_active);
  const auto exact_estimate =
      exact.EstimateBlobGarbageCollectionResources();
  ASSERT_TRUE(exact_estimate.ok()) << exact_estimate.status().ToString();
  ResourceGovernor exact_resources(exact_estimate.ValueOrDie());
  exact.SetResourceGovernor(&exact_resources);
  ASSERT_TRUE(exact.CollectBlobGarbage().ok());
  EXPECT_EQ(std::filesystem::file_size(exact_active),
            exact_active_before + exact_bytes);
  EXPECT_EQ(exact_resources.used().descriptors, 0U);
  EXPECT_EQ(exact_resources.used().temporary_bytes, 0U);
  EXPECT_EQ(exact_resources.used().write_bytes, 0U);

  const std::string failure_root = path_ + "/failure";
  TransactionCoordinator failing(failure_root, 1, 17);
  ASSERT_TRUE(failing.Open().ok());
  ASSERT_TRUE(prepare_live_blob(&failing, 33, "failed relocation payload").ok());
  const std::string failure_index = failure_root + "/blobs/shard-0/INDEX";
  ASSERT_TRUE(std::filesystem::remove(failure_index));
  ASSERT_TRUE(std::filesystem::create_directory(failure_index));
  const auto failure_estimate =
      failing.EstimateBlobGarbageCollectionResources();
  ASSERT_TRUE(failure_estimate.ok()) << failure_estimate.status().ToString();
  ResourceGovernor failure_resources(failure_estimate.ValueOrDie());
  failing.SetResourceGovernor(&failure_resources);
  EXPECT_TRUE(failing.CollectBlobGarbage().IsIOError());
  EXPECT_EQ(failure_resources.used().descriptors, 0U);
  EXPECT_EQ(failure_resources.used().temporary_bytes, 0U);
  EXPECT_EQ(failure_resources.used().write_bytes, 0U);
}

TEST_F(DurableLogTest, BlobGcBudgetsEveryPhysicalWriteBeforeMutation) {
  TransactionCoordinator coordinator(path_, 1, 23);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 35, 0, "payload",
                      PhysicalType::kString, 1,
                      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(
      0, {PendingEvent::Put(LogicalKey::VertexProperty(1, 35), 1,
                            registered.schema_epoch,
                            Value::String("complete gc write estimate"))},
      &commit_seq).ok());
  ASSERT_TRUE(coordinator.RotateBlobSegments().ok());

  const std::string sealed = path_ + "/blobs/shard-0/segment-1.blob";
  const std::string active = path_ + "/blobs/shard-0/segment-2.blob";
  const std::string index = path_ + "/blobs/shard-0/INDEX";
  const std::string manifest = path_ + "/manifest/MANIFEST";
  const auto exact = coordinator.EstimateBlobGarbageCollectionResources();
  ASSERT_TRUE(exact.ok()) << exact.status().ToString();
  ASSERT_GT(exact.ValueOrDie().write_bytes,
            std::filesystem::file_size(sealed));
  ASSERT_GT(exact.ValueOrDie().descriptors, 0U);
  ASSERT_GT(exact.ValueOrDie().metadata_ops, 0U);

  ResourceProfile insufficient_limit = exact.ValueOrDie();
  ASSERT_GT(insufficient_limit.write_bytes, 0U);
  --insufficient_limit.write_bytes;
  ResourceGovernor insufficient(insufficient_limit);
  coordinator.SetResourceGovernor(&insufficient);
  const uint64_t active_before = std::filesystem::file_size(active);
  const uint64_t index_before = std::filesystem::file_size(index);
  const uint64_t manifest_before = std::filesystem::file_size(manifest);
  EXPECT_TRUE(coordinator.CollectBlobGarbage().IsQueryMemoryLimit());
  EXPECT_EQ(std::filesystem::file_size(active), active_before);
  EXPECT_EQ(std::filesystem::file_size(index), index_before);
  EXPECT_EQ(std::filesystem::file_size(manifest), manifest_before);
  EXPECT_EQ(insufficient.used().write_bytes, 0U);

  ResourceGovernor sufficient(exact.ValueOrDie());
  coordinator.SetResourceGovernor(&sufficient);
  ASSERT_TRUE(coordinator.CollectBlobGarbage().ok());
  EXPECT_GT(std::filesystem::file_size(active), active_before);
  EXPECT_GT(std::filesystem::file_size(index), index_before);
  EXPECT_EQ(sufficient.used().descriptors, 0U);
  EXPECT_EQ(sufficient.used().temporary_bytes, 0U);
  EXPECT_EQ(sufficient.used().write_bytes, 0U);
  EXPECT_EQ(sufficient.used().metadata_ops, 0U);
}

