TEST_F(DurableLogTest, BlobGcRejectsQueuedRelocationGrowthBeforeCopy) {
  WorkScheduler scheduler;
  WorkExecutionService service(&scheduler, 1);
  ASSERT_TRUE(service.Start().ok());
  ResourceGovernor resources(ResourceProfile{
      0, 0, 16, 1024 * 1024, 4, 1024 * 1024, 0,
      1024 * 1024, 32});
  TransactionCoordinator coordinator(path_, 1, 19);
  coordinator.SetResourceGovernor(&resources);
  ASSERT_TRUE(coordinator.SetWorkExecutionService(&service).ok());
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema schema{EntityType::Vertex, 34, 0, "payload",
                      PhysicalType::kString, 1,
                      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(
      0, {PendingEvent::Put(LogicalKey::VertexProperty(1, 34), 1,
                            registered.schema_epoch,
                            Value::String("queued rotation payload"))},
      &commit_seq).ok());

  std::mutex blocker_mutex;
  std::condition_variable blocker_entered;
  std::condition_variable unblock_worker;
  bool worker_is_blocked = false;
  bool release_worker = false;
  const auto blocker = service.Submit(
      WorkClass::kCommitCritical,
      [&] {
        std::unique_lock<std::mutex> lock(blocker_mutex);
        worker_is_blocked = true;
        blocker_entered.notify_one();
        unblock_worker.wait(lock, [&] { return release_worker; });
        return Status::OK();
      });
  ASSERT_TRUE(blocker.ok()) << blocker.status().ToString();
  {
    std::unique_lock<std::mutex> lock(blocker_mutex);
    blocker_entered.wait(lock, [&] { return worker_is_blocked; });
  }

  Status gc_status = Status::OK();
  std::atomic<bool> gc_finished{false};
  std::thread gc([&] {
    gc_status = coordinator.CollectBlobGarbage();
    gc_finished.store(true, std::memory_order_release);
  });
  const auto queue_deadline =
      std::chrono::steady_clock::now() + std::chrono::seconds(5);
  while (scheduler.queued_executable(WorkClass::kBlobGc) == 0 &&
         !gc_finished.load(std::memory_order_acquire) &&
         std::chrono::steady_clock::now() < queue_deadline) {
    std::this_thread::yield();
  }
  const bool gc_queued =
      scheduler.queued_executable(WorkClass::kBlobGc) != 0;
  const auto release_blocker_and_wait = [&] {
    {
      std::lock_guard<std::mutex> lock(blocker_mutex);
      release_worker = true;
    }
    unblock_worker.notify_one();
    return blocker.ValueOrDie().Wait();
  };
  if (!gc_queued) {
    const Status blocker_status = release_blocker_and_wait();
    gc.join();
    const Status stopped = service.Stop();
    EXPECT_TRUE(blocker_status.ok()) << blocker_status.ToString();
    EXPECT_TRUE(stopped.ok()) << stopped.ToString();
    FAIL() << "Blob GC task did not queue before the bounded wait; status: "
           << gc_status.ToString();
  }
  EXPECT_EQ(resources.used().descriptors, 0U);
  EXPECT_EQ(resources.used().cpu_slots, 1U);
  EXPECT_EQ(resources.used().temporary_bytes, 0U);
  EXPECT_EQ(resources.used().write_bytes, 0U);

  const std::string index = path_ + "/blobs/shard-0/INDEX";
  const uint64_t index_before = std::filesystem::file_size(index);
  Status rotated = Status::InvalidArgument("test", "rotation did not run");
  std::thread rotation([&] {
    rotated = coordinator.RotateBlobSegments();
  });
  const auto rotation_deadline =
      std::chrono::steady_clock::now() + std::chrono::seconds(5);
  while (scheduler.queued_executable(WorkClass::kForegroundWrite) == 0 &&
         std::chrono::steady_clock::now() < rotation_deadline) {
    std::this_thread::yield();
  }
  EXPECT_NE(scheduler.queued_executable(WorkClass::kForegroundWrite), 0U);
  EXPECT_TRUE(release_blocker_and_wait().ok());
  rotation.join();
  gc.join();

  const std::string active = path_ + "/blobs/shard-0/segment-2.blob";
  EXPECT_TRUE(rotated.ok()) << rotated.ToString();
  EXPECT_TRUE(gc_status.IsQueryMemoryLimit()) << gc_status.ToString();
  EXPECT_EQ(std::filesystem::file_size(active), 0U);
  EXPECT_EQ(std::filesystem::file_size(index), index_before);
  EXPECT_EQ(resources.used().descriptors, 0U);
  EXPECT_EQ(resources.used().temporary_bytes, 0U);
  EXPECT_EQ(resources.used().write_bytes, 0U);
  EXPECT_TRUE(service.Stop().ok());
}

