TEST_F(DurableLogTest, SchemaPublicationIndeterminateRequiresReopen) {
  TransactionCoordinator coordinator(path_, 1, 31);
  ASSERT_TRUE(coordinator.Open().ok());
  coordinator.SetVersionSetFaultInjectorForTesting(
      [](VersionSetFaultPoint point) {
        return point == VersionSetFaultPoint::kAfterManifestRename
            ? Status::IOError("test", "post-rename schema fault")
            : Status::OK();
      });
  ColumnSchema schema{EntityType::Vertex, 7, 0, "name",
                      PhysicalType::kString, 4096,
                      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  const Status uncertain = coordinator.RegisterColumn(schema, &registered);
  EXPECT_TRUE(uncertain.IsIndeterminate()) << uncertain.ToString();
  EXPECT_TRUE(coordinator.recovery_required());
  EXPECT_TRUE(coordinator.RegisterColumn(schema, &registered).IsRecoveryRequired());
  uint64_t commit_seq = 0;
  EXPECT_TRUE(coordinator.Commit(
      0, {PendingEvent::Put(LogicalKey::VertexProperty(1, 7), 1, 1,
                            Value::String("blocked"))},
      &commit_seq).IsRecoveryRequired());
  IndexDefinition definition;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  uint64_t index_id = 0;
  EXPECT_TRUE(coordinator.RegisterIndex(definition, &index_id).IsRecoveryRequired());
  EXPECT_TRUE(coordinator.AllocateVertexId().status().IsRecoveryRequired());
  EXPECT_TRUE(coordinator.Flush().IsRecoveryRequired());
  EXPECT_TRUE(coordinator.Compact().IsRecoveryRequired());
  EXPECT_TRUE(coordinator.RotateBlobSegments().IsRecoveryRequired());
  EXPECT_TRUE(coordinator.CollectBlobGarbage().IsRecoveryRequired());
  EXPECT_TRUE(coordinator.CheckpointDurableLogs().IsRecoveryRequired());

  coordinator.SetVersionSetFaultInjectorForTesting({});
  ASSERT_TRUE(coordinator.Open().ok());
  EXPECT_FALSE(coordinator.recovery_required());
  const auto epoch_one = coordinator.schema_snapshot()->Lookup(
      EntityType::Vertex, 7, 1);
  ASSERT_TRUE(epoch_one.has_value());
  schema.blob_threshold = 8192;
  ASSERT_TRUE(coordinator.RegisterColumn(schema, &registered).ok());
  EXPECT_EQ(registered.schema_epoch, 2U);
  ASSERT_EQ(coordinator.version_snapshot()->schemas.size(), 2U);
}

