TEST_F(DurableLogTest, VersionSetRejectsInvalidSchemaCatalogEdits) {
  VersionSet versions(path_ + "/manifest/MANIFEST");
  ASSERT_TRUE(versions.Open().ok());
  const ColumnSchema epoch_one{EntityType::Vertex, 7, 1, "name",
                               PhysicalType::kString, 4096,
                               EncodingPolicy::kAdaptive,
                               CompressionPolicy::kLz4};
  ColumnSchema invalid = epoch_one;
  invalid.schema_epoch = 2;
  VersionEdit non_contiguous;
  non_contiguous.schema_adds.push_back(invalid);
  EXPECT_TRUE(versions.ApplyEdit(non_contiguous).IsInvalidArgument());

  invalid = epoch_one;
  invalid.entity_type = static_cast<EntityType>(255);
  VersionEdit invalid_enum;
  invalid_enum.schema_adds.push_back(invalid);
  EXPECT_TRUE(versions.ApplyEdit(invalid_enum).IsInvalidArgument());

  invalid = epoch_one;
  invalid.logical_type.assign(kMaxSchemaLogicalTypeBytes + 1, 'x');
  VersionEdit oversized;
  oversized.schema_adds.push_back(invalid);
  EXPECT_TRUE(versions.ApplyEdit(oversized).IsInvalidArgument());

  VersionEdit duplicate;
  duplicate.schema_adds = {epoch_one, epoch_one};
  EXPECT_TRUE(versions.ApplyEdit(duplicate).IsInvalidArgument());
  EXPECT_TRUE(versions.Snapshot()->schemas.empty());
}

