TEST_F(DurableLogTest,
       VersionSetRejectsInvalidIndexStructureBeforeSchemaLookup) {
  VersionSet versions(path_ + "/manifest/MANIFEST");
  ASSERT_TRUE(versions.Open().ok());
  VersionEdit schema_edit;
  schema_edit.schema_adds.push_back(ColumnSchema{
      EntityType::Vertex, 7, 1, "name", PhysicalType::kString, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4});
  ASSERT_TRUE(versions.ApplyEdit(schema_edit).ok());

  const auto apply = [&](IndexDefinition definition) {
    VersionEdit edit;
    edit.index_adds.push_back(definition);
    return versions.ApplyEdit(edit);
  };
  IndexDefinition definition;
  definition.index_id = 1;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kDeclared;

  IndexDefinition invalid = definition;
  invalid.entity_type = static_cast<EntityType>(255);
  EXPECT_TRUE(apply(invalid).IsInvalidArgument());
  invalid = definition;
  invalid.state = static_cast<IndexState>(255);
  EXPECT_TRUE(apply(invalid).IsInvalidArgument());
  invalid = definition;
  invalid.schema_epoch = 0;
  EXPECT_TRUE(apply(invalid).IsInvalidArgument());

  IndexDefinition unknown = definition;
  unknown.column_id = 8;
  EXPECT_TRUE(apply(unknown).IsSchemaMismatch());
}

TEST_F(DurableLogTest, ManifestRejectsCorruptSchemaEnumAndOldMagic) {
  const std::string manifest = path_ + "/manifest/MANIFEST";
  VersionSet versions(manifest);
  ASSERT_TRUE(versions.Open().ok());
  VersionEdit edit;
  edit.schema_adds.push_back(ColumnSchema{
      EntityType::Vertex, 7, 1, "name", PhysicalType::kString, 4096,
      EncodingPolicy::kAdaptive, CompressionPolicy::kLz4});
  ASSERT_TRUE(versions.ApplyEdit(edit).ok());

  const auto rewrite = [&](size_t byte_offset, uint8_t value) {
    std::ifstream input(manifest, std::ios::binary);
    std::string bytes((std::istreambuf_iterator<char>(input)),
                      std::istreambuf_iterator<char>());
    ASSERT_GT(bytes.size(), byte_offset);
    bytes[byte_offset] = static_cast<char>(value);
    const uint32_t checksum = crc32c::Value(bytes.data() + 8, bytes.size() - 8);
    for (uint32_t shift = 0; shift < 32; shift += 8) {
      bytes[4 + shift / 8] = static_cast<char>(checksum >> shift);
    }
    std::ofstream output(manifest, std::ios::binary | std::ios::trunc);
    output.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
  };

  rewrite(32, 255);
  VersionSet corrupt_schema(manifest);
  EXPECT_TRUE(corrupt_schema.Open().IsCorruption());

  ASSERT_TRUE(versions.ApplyEdit(VersionEdit{}).ok());
  rewrite(8, 'M');
  rewrite(9, 'V');
  rewrite(10, '1');
  rewrite(11, '0');
  VersionSet old_manifest(manifest);
  EXPECT_TRUE(old_manifest.Open().IsCorruption());
}

