TEST(BlobReferenceCatalogTest, RetainsReferencesAcrossFlushTransferWithoutGap) {
  const BlobHash first = Blake3Hash("first");
  const BlobHash second = Blake3Hash("second");
  BlobReferenceCatalog catalog;
  catalog.ReplaceSource("memtable:0", {first});
  EXPECT_TRUE(catalog.IsLive(first));
  catalog.ReplaceSource("sst:17", {first, second});
  catalog.RemoveSource("memtable:0");
  EXPECT_TRUE(catalog.IsLive(first));
  EXPECT_TRUE(catalog.IsLive(second));
  catalog.RemoveSource("sst:17");
  EXPECT_FALSE(catalog.IsLive(first));
  EXPECT_FALSE(catalog.IsLive(second));
}

TEST(BlobReferenceCatalogTest, RebuildsLiveSstSourcesWithoutDroppingMemtableProtection) {
  const BlobHash memtable = Blake3Hash("memtable");
  const BlobHash sst = Blake3Hash("sst");
  BlobReferenceCatalog catalog;
  catalog.ReplaceSource("memtable:0", {memtable});
  VersionSnapshot snapshot{1, {SstFileMeta{
      9, "shards/0/sst/9.sst",
      BlockPartition{EntityType::Vertex, 2, 1, PhysicalType::kBinary}, 20, {sst}}}};
  catalog.RebuildLiveSstSources(snapshot);
  EXPECT_TRUE(catalog.IsLive(memtable));
  EXPECT_TRUE(catalog.IsLive(sst));
  catalog.RebuildLiveSstSources(VersionSnapshot{2, {}});
  EXPECT_TRUE(catalog.IsLive(memtable));
  EXPECT_FALSE(catalog.IsLive(sst));
}

