TEST_F(DurableLogTest, MediumAndLargeValuesUseSeparateSstAndBlobPlacementTiers) {
  TransactionCoordinator coordinator(path_, 1, 7);
  ASSERT_TRUE(coordinator.Open().ok());
  ColumnSchema registered;
  ASSERT_TRUE(coordinator.RegisterColumn(
      ColumnSchema{EntityType::Vertex, 13, 0, "payload",
                   PhysicalType::kBinary, 8, EncodingPolicy::kAdaptive,
                   CompressionPolicy::kLz4},
      &registered).ok());
  const LogicalKey medium_key = LogicalKey::VertexProperty(1, 13);
  const LogicalKey large_key = LogicalKey::VertexProperty(2, 13);
  uint64_t commit_seq = 0;
  ASSERT_TRUE(coordinator.Commit(
      0, {PendingEvent::Put(medium_key, 1, registered.schema_epoch,
                            Value::Binary("12345678")),
          PendingEvent::Put(large_key, 1, registered.schema_epoch,
                            Value::Binary("123456789"))},
      &commit_seq).ok());

  const auto committed = coordinator.SnapshotCommittedEvents();
  ASSERT_TRUE(committed.ok()) << committed.status().ToString();
  const auto medium = std::find_if(
      committed.ValueOrDie().begin(), committed.ValueOrDie().end(),
      [&](const TemporalEvent& event) {
        return event.logical_key() == medium_key;
      });
  const auto large = std::find_if(
      committed.ValueOrDie().begin(), committed.ValueOrDie().end(),
      [&](const TemporalEvent& event) {
        return event.logical_key() == large_key;
      });
  ASSERT_NE(medium, committed.ValueOrDie().end());
  ASSERT_NE(large, committed.ValueOrDie().end());
  EXPECT_FALSE(medium->is_blob_reference());
  EXPECT_TRUE(large->is_blob_reference());

  ASSERT_TRUE(coordinator.Flush().ok());
  ASSERT_EQ(coordinator.version_snapshot()->files.size(), 1U);
  EXPECT_EQ(coordinator.version_snapshot()->files[0].blob_refs.size(), 1U);
  EXPECT_EQ(coordinator.GetChecked(medium_key, 1).ValueOrDie(),
            std::optional<Value>(Value::Binary("12345678")));
  EXPECT_EQ(coordinator.GetChecked(large_key, 1).ValueOrDie(),
            std::optional<Value>(Value::Binary("123456789")));
}

