TEST(PageFormatTest, RoundTripsRleAndDeltaEncodedStoredPayloads) {
  const std::string repeated(256, '\x03');
  const auto rle_bytes = EncodePageChecked(
      PageHeader{PageType::kValueClass, PhysicalType::kInt64, EncodingId::kRle,
                 CompressionId::kNone, 0, 256, 256, 0}, repeated);
  ASSERT_TRUE(rle_bytes.ok()) << rle_bytes.status().ToString();
  const auto rle = DecodePage(rle_bytes.ValueOrDie());
  ASSERT_TRUE(rle.ok()) << rle.status().ToString();
  EXPECT_EQ(rle.ValueOrDie().header.encoding_id, EncodingId::kRle);
  EXPECT_EQ(rle.ValueOrDie().payload, repeated);

  std::string values;
  for (uint64_t value = 1000; value < 1128; ++value) {
    for (uint32_t shift = 0; shift < 64; shift += 8) {
      values.push_back(static_cast<char>(value >> shift));
    }
  }
  const auto delta_bytes = EncodePageChecked(
      PageHeader{PageType::kCommitSeq, PhysicalType::kInt64, EncodingId::kDelta,
                 CompressionId::kNone, 0, 128, 128, 0}, values);
  ASSERT_TRUE(delta_bytes.ok()) << delta_bytes.status().ToString();
  const auto delta = DecodePage(delta_bytes.ValueOrDie());
  ASSERT_TRUE(delta.ok()) << delta.status().ToString();
  EXPECT_EQ(delta.ValueOrDie().header.encoding_id, EncodingId::kDelta);
  EXPECT_EQ(delta.ValueOrDie().payload, values);
}

