std::string HexBytes(const std::string& bytes) {
  static constexpr char kHex[] = "0123456789abcdef";
  std::string result;
  result.reserve(bytes.size() * 2);
  for (unsigned char byte : bytes) {
    result.push_back(kHex[byte >> 4]);
    result.push_back(kHex[byte & 0x0f]);
  }
  return result;
}

StatusOr<SstFileMeta> BuildTestSstFileMeta(
    uint64_t file_number, std::string relative_path,
    const BlockPartition& partition, int64_t value) {
  const auto built = BuildSst(partition, {
      TemporalEvent::Put(
          LogicalKey::VertexProperty(file_number, partition.column_id),
          10, file_number, partition.schema_epoch, Value::String(
              std::to_string(value))),
  });
  if (!built.ok()) return built.status();
  const SstMetadata& metadata = built.ValueOrDie().metadata;
  return SstFileMeta{file_number, std::move(relative_path), partition,
                     built.ValueOrDie().bytes.size(), metadata.blob_refs,
                     metadata.format, metadata.identity, metadata.statistics,
                     metadata.statistics_crc32c};
}

void PutTestU64(std::string* bytes, uint64_t value) {
  for (uint32_t shift = 0; shift < 64; shift += 8) {
    bytes->push_back(static_cast<char>(value >> shift));
  }
}

std::string CodecMatrixPayload(EncodingId encoding) {
  if (encoding == EncodingId::kPlain) {
    return std::string(4096, 'p');
  }
  if (encoding == EncodingId::kRle) {
    std::string payload;
    for (uint32_t run = 0; run < 256; ++run) {
      payload.append(16, static_cast<char>(run & 0x0f));
    }
    return payload;
  }
  std::string payload;
  if (encoding == EncodingId::kDelta) {
    for (uint64_t value = 1000; value < 1512; ++value) {
      PutTestU64(&payload, value);
    }
    return payload;
  }
  if (encoding == EncodingId::kFrameOfReference) {
    for (uint64_t value = 0; value < 512; ++value) {
      PutTestU64(&payload, 1000000 + (value % 8));
    }
    return payload;
  }
  if (encoding == EncodingId::kBitmap) {
    for (uint32_t value = 0; value < 512; ++value) {
      payload.push_back(static_cast<char>((value % 3) == 0));
    }
    return payload;
  }
  if (encoding == EncodingId::kBitPacking) {
    for (uint32_t value = 0; value < 512; ++value) {
      PutTestU64(&payload, 700000 + (value % 31));
    }
    return payload;
  }
  if (encoding == EncodingId::kDeltaOfDelta) {
    for (uint64_t value = 0; value < 512; ++value) {
      PutTestU64(&payload, 900000 + value * 1000);
    }
    return payload;
  }
  if (encoding == EncodingId::kXor) {
    for (uint64_t value = 0; value < 512; ++value) {
      PutTestU64(&payload, 0x3ff0000000000000ULL + (value % 8));
    }
    return payload;
  }
  for (uint32_t value = 0; value < 512; ++value) {
    const std::string record = "dictionary-" + std::to_string(value % 4);
    payload.push_back(static_cast<char>(record.size()));
    payload.append(3, '\0');
    payload.append(record);
  }
  return payload;
}

std::string GoldenCodecPayload(EncodingId encoding, CompressionId compression) {
  if (encoding == EncodingId::kPlain) {
    return compression == CompressionId::kLz4 ? std::string(256, 'p') : "abc";
  }
  if (encoding == EncodingId::kRle) {
    std::string payload;
    const uint32_t runs = compression == CompressionId::kLz4 ? 32 : 4;
    for (uint32_t run = 0; run < runs; ++run) {
      payload.append(8, static_cast<char>(run & 0x03));
    }
    return payload;
  }
  std::string payload;
  if (encoding == EncodingId::kDelta) {
    const uint64_t count = compression == CompressionId::kLz4 ? 64 : 2;
    for (uint64_t value = 1000; value < 1000 + count; ++value) {
      PutTestU64(&payload, value);
    }
    return payload;
  }
  const uint32_t count = compression == CompressionId::kLz4 ? 32 : 8;
  for (uint32_t value = 0; value < count; ++value) {
    const std::string record = value % 2 == 0 ? "alpha" : "beta";
    payload.push_back(static_cast<char>(record.size()));
    payload.append(3, '\0');
    payload.append(record);
  }
  return payload;
}

TEST(PageFormatTest, GoldenBytesAreStableForHeaderDirectoryAndCodecs) {
  const auto header_page = EncodePageChecked(
      PageHeader{PageType::kTypedValue, PhysicalType::kInt32,
                 EncodingId::kPlain, CompressionId::kNone,
                 0x0102030405060708ULL, 0x11223344U, 0x55667788U, 0},
      "abc");
  ASSERT_TRUE(header_page.ok()) << header_page.status().ToString();
  EXPECT_EQ(HexBytes(header_page.ValueOrDie().substr(0, kPageFormatHeaderSize)),
            "4350473203003c000702010108070605040302014433221188776655030000000000000003000000000000000300000000000000b73f4b3600000000");

  PageDirectoryEntry directory_entry{
      PageType::kEntityId, 7, 0x0102030405060708ULL,
      0x1112131415161718ULL};
  for (uint8_t byte = 0; byte < directory_entry.content_hash.size(); ++byte) {
    directory_entry.content_hash[byte] = byte;
  }
  const std::vector<PageDirectoryEntry> entries = {directory_entry};
  EXPECT_EQ(HexBytes(EncodePageDirectory(entries)),
            "5044523301000000010700000008070605040302011817161514131211"
            "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");

  const std::vector<std::pair<EncodingId, CompressionId>> codecs = {
      {EncodingId::kPlain, CompressionId::kNone},
      {EncodingId::kPlain, CompressionId::kLz4},
      {EncodingId::kRle, CompressionId::kNone},
      {EncodingId::kRle, CompressionId::kLz4},
      {EncodingId::kDelta, CompressionId::kNone},
      {EncodingId::kDelta, CompressionId::kLz4},
      {EncodingId::kDictionary, CompressionId::kNone},
      {EncodingId::kDictionary, CompressionId::kLz4},
  };
  for (const auto& codec : codecs) {
    const std::string payload = GoldenCodecPayload(codec.first, codec.second);
    const uint32_t value_count =
        codec.first == EncodingId::kDictionary
            ? (codec.second == CompressionId::kLz4 ? 32U : 8U)
            : 1U;
    const auto page = EncodePageChecked(
        PageHeader{PageType::kTypedValue, PhysicalType::kInt64,
                   codec.first, codec.second, 0, value_count, value_count, 0},
        payload);
    ASSERT_TRUE(page.ok()) << page.status().ToString();
    SCOPED_TRACE("encoding=" + std::to_string(static_cast<int>(codec.first)) +
                 " compression=" +
                 std::to_string(static_cast<int>(codec.second)));
    const std::string expected =
        codec == std::make_pair(EncodingId::kPlain, CompressionId::kNone)
            ? "4350473203003c000703010100000000000000000100000001000000030000000000000003000000000000000300000000000000b73f4b3600000000616263"
        : codec == std::make_pair(EncodingId::kPlain, CompressionId::kLz4)
            ? "4350473203003c000703010200000000000000000100000001000000000100000000000000010000000000000b00000000000000dfce0c24000000001f700100e7507070707070"
        : codec == std::make_pair(EncodingId::kRle, CompressionId::kNone)
            ? "4350473203003c00070302010000000000000000010000000100000020000000000000000800000000000000080000000000000044c06ba1000000000800080108020803"
        : codec == std::make_pair(EncodingId::kRle, CompressionId::kLz4)
            ? "4350473203003c000703020200000000000000000100000001000000000100000000000040000000000000001200000000000000225824f0000000008f0800080108020803080020500108020803"
        : codec == std::make_pair(EncodingId::kDelta, CompressionId::kNone)
            ? "4350473203003c000703030100000000000000000100000001000000100000000000000009000000000000000900000000000000868504b700000000e80300000000000001"
        : codec == std::make_pair(EncodingId::kDelta, CompressionId::kLz4)
            ? "4350473203003c00070303020000000000000000010000000100000000020000000000004700000000000000110000000000000018075a630000000031e8030001001f01010026500101010101"
        : codec == std::make_pair(EncodingId::kDictionary, CompressionId::kNone)
            ? "4350473203003c00070304010000000000000000080000000800000044000000000000003500000000000000350000000000000012fd2140000000000200000005000000616c70686104000000626574610000000001000000000000000100000000000000010000000000000001000000"
            : "4350473203003c0007030402000000000000000020000000200000001001000000000000950000000000000028000000000000000d84fa0100000000f00b0200000005000000616c7068610400000062657461000000000105000f08005f500001000000";
    EXPECT_EQ(HexBytes(page.ValueOrDie()), expected);
  }
}

TEST(SstTest, GoldenBytesAreStableForFileBlockAndFooterHeaders) {
  const BlockPartition partition{EntityType::Vertex, 4, 3,
                                 PhysicalType::kInt32, 0,
                                 CompressionId::kNone,
                                 LogicalKeyKind::kProperty};
  const auto sst = BuildSst(partition, {
      TemporalEvent::Put(LogicalKey::VertexProperty(7, 4), 10, 11, 3,
                         Value::Int32(42)),
  });
  ASSERT_TRUE(sst.ok()) << sst.status().ToString();
  constexpr size_t kSstHeaderBytes = 80;
  constexpr size_t kBlockHeaderBytes = 28;
  constexpr size_t kSstFooterBytes = 136;
  ASSERT_GE(sst.ValueOrDie().bytes.size(),
            kSstHeaderBytes + kBlockHeaderBytes + kSstFooterBytes);
  EXPECT_EQ(HexBytes(sst.ValueOrDie().bytes.substr(0, kSstHeaderBytes)),
            "435353540a005000000000000000000000000000000104000300000001000200"
            "00010101010101010000001aa653559d081c92abf406a4f69420e55545442039"
            "ad7247d595c6a19303763b00e79995a8");
  EXPECT_EQ(HexBytes(sst.ValueOrDie().bytes.substr(kSstHeaderBytes,
                                                   kBlockHeaderBytes)),
            "47424b3505001c0001000000e5020000000000004f02000000000000");
  EXPECT_EQ(HexBytes(sst.ValueOrDie().bytes.substr(
                sst.ValueOrDie().bytes.size() - kSstFooterBytes)),
            "435346540a0088007f060000000000009a000000000000008405000000000000"
            "040000000000000088050000000000004900000000000000d105000000000000"
            "ae00000000000000571f9f38c74b67488060ca479b7e1a5d0100000000000000"
            "010000001aa653559d081c92abf406a4f69420e55545442039ad7247d595c6a19"
            "303763b3ff4a748");
}

TEST(SstTest, ExposesCompleteFormatIdentityAndFileStatistics) {
  const BlockPartition partition{EntityType::Vertex, 4, 3,
                                 PhysicalType::kInt32, 0,
                                 CompressionId::kLz4,
                                 LogicalKeyKind::kProperty};
  const auto sst = BuildSst(partition, {
      TemporalEvent::Put(LogicalKey::VertexProperty(7, 4), 10, 11, 3,
                         Value::Int32(42)),
      TemporalEvent::Delete(LogicalKey::VertexProperty(8, 4), 20, 12, 3),
      TemporalEvent::Put(LogicalKey::VertexProperty(9, 4), 30, 13, 3,
                         Value::Int32(10)),
  });
  ASSERT_TRUE(sst.ok()) << sst.status().ToString();
  const SstMetadata& metadata = sst.ValueOrDie().metadata;
  EXPECT_EQ(metadata.format.sort_order_id,
            SstSortOrderId::kLogicalKeyValidFromCommitSeq);
  EXPECT_EQ(metadata.format.hash_algorithm_id,
            SstHashAlgorithmId::kBlake3_256);
  EXPECT_EQ(metadata.format.encoding_registry_id,
            SstEncodingRegistryId::kCedarPageCodecs);
  EXPECT_EQ(metadata.format.compression_registry_id,
            SstCompressionRegistryId::kCedarPageCompression);
  EXPECT_EQ(metadata.format.checksum_algorithm_id,
            SstChecksumAlgorithmId::kCrc32c);
  EXPECT_TRUE(std::any_of(metadata.identity.bytes.begin(),
                          metadata.identity.bytes.end(),
                          [](uint8_t byte) { return byte != 0; }));
  EXPECT_EQ(metadata.statistics.row_count, 3U);
  EXPECT_EQ(metadata.statistics.put_count, 2U);
  EXPECT_EQ(metadata.statistics.delete_count, 1U);
  EXPECT_EQ(metadata.statistics.inline_value_count, 2U);
  EXPECT_EQ(metadata.statistics.blob_reference_count, 0U);
  EXPECT_EQ(metadata.statistics.first_key,
            LogicalKey::VertexProperty(7, 4));
  EXPECT_EQ(metadata.statistics.last_key,
            LogicalKey::VertexProperty(9, 4));
  EXPECT_EQ(metadata.statistics.min_valid_from, 10U);
  EXPECT_EQ(metadata.statistics.max_valid_from, 30U);
  EXPECT_EQ(metadata.statistics.min_commit_seq, 11U);
  EXPECT_EQ(metadata.statistics.max_commit_seq, 13U);
  ASSERT_TRUE(metadata.statistics.typed_min.has_value());
  ASSERT_TRUE(metadata.statistics.typed_max.has_value());
  EXPECT_EQ(*metadata.statistics.typed_min, Value::Int32(10));
  EXPECT_EQ(*metadata.statistics.typed_max, Value::Int32(42));
  EXPECT_NE(metadata.statistics_crc32c, 0U);
}

