TEST(PageFormatTest, CoversEveryPhysicalCodecAndCompressionCombination) {
  constexpr uint64_t kSeed = 0xCEDA20260721ULL;
  const std::vector<PhysicalType> physical_types = {
      PhysicalType::kBool, PhysicalType::kInt32, PhysicalType::kInt64,
      PhysicalType::kFloat32, PhysicalType::kFloat64,
      PhysicalType::kTimestamp64, PhysicalType::kString, PhysicalType::kBinary};
  const std::vector<EncodingId> encodings = {
      EncodingId::kPlain, EncodingId::kRle, EncodingId::kDelta,
      EncodingId::kDictionary};
  const std::vector<CompressionId> compressions = {
      CompressionId::kNone, CompressionId::kLz4};
  size_t case_index = 0;
  for (PhysicalType physical : physical_types) {
    for (EncodingId encoding : encodings) {
      for (CompressionId compression : compressions) {
        SCOPED_TRACE("seed=" + std::to_string(kSeed) +
                     " case=" + std::to_string(case_index++) +
                     " physical=" +
                     std::to_string(static_cast<int>(physical)) +
                     " encoding=" +
                     std::to_string(static_cast<int>(encoding)) +
                     " compression=" +
                     std::to_string(static_cast<int>(compression)));
        const std::string payload = CodecMatrixPayload(encoding);
        const auto encoded = EncodePageChecked(
            PageHeader{PageType::kTypedValue, physical, encoding, compression,
                       0, 512, 512, 0}, payload);
        ASSERT_TRUE(encoded.ok()) << encoded.status().ToString();
        const auto decoded = DecodePage(encoded.ValueOrDie());
        ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
        EXPECT_EQ(decoded.ValueOrDie().header.physical_type, physical);
        EXPECT_EQ(decoded.ValueOrDie().header.encoding_id, encoding);
        EXPECT_EQ(decoded.ValueOrDie().header.compression_id, compression);
        EXPECT_EQ(decoded.ValueOrDie().payload, payload);
      }
    }
  }
  for (PhysicalType physical : {PhysicalType::kInt64,
                                PhysicalType::kTimestamp64}) {
    for (EncodingId encoding : {EncodingId::kFrameOfReference,
                                EncodingId::kBitPacking,
                                EncodingId::kDeltaOfDelta}) {
      for (CompressionId compression : compressions) {
        const std::string payload = CodecMatrixPayload(encoding);
        const auto encoded = EncodePageChecked(
            PageHeader{PageType::kCommitSeq, physical, encoding, compression,
                       0, 512, 512, 0}, payload);
        ASSERT_TRUE(encoded.ok()) << encoded.status().ToString();
        const auto decoded = DecodePage(encoded.ValueOrDie());
        ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
        EXPECT_EQ(decoded.ValueOrDie().header.encoding_id, encoding);
        EXPECT_EQ(decoded.ValueOrDie().payload, payload);
      }
    }
  }
  for (PhysicalType physical : {PhysicalType::kFloat64}) {
    for (CompressionId compression : compressions) {
      const std::string payload = CodecMatrixPayload(EncodingId::kXor);
      const auto encoded = EncodePageChecked(
          PageHeader{PageType::kTypedValue, physical, EncodingId::kXor,
                     compression, 0, 512, 512, 0}, payload);
      ASSERT_TRUE(encoded.ok()) << encoded.status().ToString();
      const auto decoded = DecodePage(encoded.ValueOrDie());
      ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
      EXPECT_EQ(decoded.ValueOrDie().header.encoding_id, EncodingId::kXor);
      EXPECT_EQ(decoded.ValueOrDie().payload, payload);
    }
  }
  for (CompressionId compression : compressions) {
    const std::string payload = CodecMatrixPayload(EncodingId::kBitmap);
    const auto encoded = EncodePageChecked(
        PageHeader{PageType::kOperation, PhysicalType::kBool,
                   EncodingId::kBitmap, compression,
                   0, 512, 512, 0}, payload);
    ASSERT_TRUE(encoded.ok()) << encoded.status().ToString();
    const auto decoded = DecodePage(encoded.ValueOrDie());
    ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
    EXPECT_EQ(decoded.ValueOrDie().header.encoding_id, EncodingId::kBitmap);
    EXPECT_EQ(decoded.ValueOrDie().payload, payload);
  }
}

TEST(PageFormatTest, DeterministicRandomPhysicalCodecRoundTrips) {
  constexpr uint64_t kSeed = 0x5EEDC0DEC0DEULL;
  std::mt19937_64 random(kSeed);
  size_t case_index = 0;
  for (uint32_t physical_id = 1; physical_id <= 8; ++physical_id) {
    const PhysicalType physical = static_cast<PhysicalType>(physical_id);
    for (uint32_t encoding_id = 1; encoding_id <= 4; ++encoding_id) {
      const EncodingId encoding = static_cast<EncodingId>(encoding_id);
      for (uint32_t compression_id = 1; compression_id <= 2; ++compression_id) {
        const CompressionId compression = static_cast<CompressionId>(compression_id);
        for (uint32_t iteration = 0; iteration < 4; ++iteration) {
          SCOPED_TRACE("seed=" + std::to_string(kSeed) +
                       " case=" + std::to_string(case_index++) +
                       " physical=" + std::to_string(physical_id) +
                       " encoding=" + std::to_string(encoding_id) +
                       " compression=" + std::to_string(compression_id) +
                       " iteration=" + std::to_string(iteration));
          uint32_t value_count = 1;
          std::string payload;
          if (encoding == EncodingId::kDictionary) {
            value_count = 16;
            std::vector<std::string> records;
            for (uint32_t record = 0; record < 4; ++record) {
              const size_t length = 4 + static_cast<size_t>(random() % 12);
              std::string bytes(length, '\0');
              for (char& byte : bytes) byte = static_cast<char>(random() & 0xff);
              records.push_back(std::move(bytes));
            }
            for (uint32_t value = 0; value < value_count; ++value) {
              const std::string& record = records[random() % records.size()];
              payload.push_back(static_cast<char>(record.size()));
              payload.append(3, '\0');
              payload.append(record);
            }
          } else {
            size_t length = 64 + static_cast<size_t>(random() % 256);
            if (encoding == EncodingId::kDelta) {
              length = (length / sizeof(uint64_t)) * sizeof(uint64_t);
            }
            if (length == 0) length = sizeof(uint64_t);
            payload.assign(length, '\0');
            for (char& byte : payload) byte = static_cast<char>(random() & 0xff);
          }
          const auto encoded = EncodePageChecked(
              PageHeader{PageType::kTypedValue, physical, encoding, compression,
                         0, value_count, value_count, 0}, payload);
          ASSERT_TRUE(encoded.ok()) << encoded.status().ToString();
          const auto decoded = DecodePage(encoded.ValueOrDie());
          ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
          EXPECT_EQ(decoded.ValueOrDie().header.physical_type, physical);
          EXPECT_EQ(decoded.ValueOrDie().payload, payload);
        }
      }
    }
  }
}

TEST(PageFormatTest, RejectsCorruptPayloadSizesAndDirectoryOffsets) {
  const auto page = EncodePageChecked(
      PageHeader{PageType::kTypedValue, PhysicalType::kBinary,
                 EncodingId::kPlain, CompressionId::kNone, 0, 1, 1, 0},
      "payload");
  ASSERT_TRUE(page.ok()) << page.status().ToString();
  const std::string encoded = page.ValueOrDie();

  EXPECT_TRUE(DecodePage(encoded.substr(0, encoded.size() - 1))
                  .status()
                  .IsCorruption());
  std::string bit_flip = encoded;
  bit_flip.back() ^= 1;
  EXPECT_TRUE(DecodePage(bit_flip).status().IsCorruption());

  std::string bad_crc = encoded;
  bad_crc[52] ^= 1;
  EXPECT_TRUE(DecodePage(bad_crc).status().IsCorruption());

  std::string bad_decoded_size = encoded;
  bad_decoded_size[28] = static_cast<char>(bad_decoded_size[28] + 1);
  EXPECT_TRUE(DecodePage(bad_decoded_size).status().IsCorruption());

  std::string bomb = encoded;
  const uint64_t oversized = kHardMaxPageBytes + 1;
  for (uint32_t shift = 0; shift < 64; shift += 8) {
    bomb[36 + shift / 8] = static_cast<char>(oversized >> shift);
  }
  EXPECT_TRUE(DecodePage(bomb).status().IsCorruption());

  std::string unknown_compression = encoded;
  unknown_compression[11] = static_cast<char>(255);
  EXPECT_TRUE(DecodePage(unknown_compression).status().IsNotSupportedError());

  std::string directory = EncodePageDirectory(
      {{PageType::kEntityId, 0, 1, 8}});
  directory.resize(8 + 1 + 4 + 8 + 8);
  for (size_t i = 21; i < 29; ++i) directory[i] = 0;
  EXPECT_TRUE(DecodePageDirectory(directory).status().IsCorruption());
}

TEST(PageFormatTest, RejectsMalformedRleRuns) {
  const auto page = EncodePageChecked(
      PageHeader{PageType::kValueClass, PhysicalType::kInt64,
                 EncodingId::kRle, CompressionId::kNone, 0, 1, 1, 0},
      std::string(64, '\x01'));
  ASSERT_TRUE(page.ok()) << page.status().ToString();
  std::string malformed = page.ValueOrDie();
  malformed[kPageFormatHeaderSize] = 0;
  const uint32_t crc = crc32c::Value(
      malformed.data() + kPageFormatHeaderSize,
      malformed.size() - kPageFormatHeaderSize);
  for (uint32_t shift = 0; shift < 32; shift += 8) {
    malformed[52 + shift / 8] = static_cast<char>(crc >> shift);
  }
  EXPECT_TRUE(DecodePage(malformed).status().IsCorruption());
}

TEST(PageFormatTest, DictionaryEncodingRoundTripsAndRejectsBadIndex) {
  std::string payload;
  const std::vector<std::string> records = {"alpha", "beta", "alpha", "beta",
                                             "alpha", "beta", "alpha", "beta"};
  for (const std::string& record : records) {
    payload.push_back(static_cast<char>(record.size()));
    payload.append(3, '\0');
    payload.append(record);
  }
  const auto encoded = EncodePageChecked(
      PageHeader{PageType::kTypedValue, PhysicalType::kString,
                 EncodingId::kDictionary, CompressionId::kNone,
                 0, static_cast<uint32_t>(records.size()),
                 static_cast<uint32_t>(records.size()), 0},
      payload);
  ASSERT_TRUE(encoded.ok()) << encoded.status().ToString();
  const auto decoded = DecodePage(encoded.ValueOrDie());
  ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
  EXPECT_EQ(decoded.ValueOrDie().header.encoding_id, EncodingId::kDictionary);
  EXPECT_EQ(decoded.ValueOrDie().payload, payload);

  std::string bad_index = encoded.ValueOrDie();
  ASSERT_GE(bad_index.size(), kPageFormatHeaderSize + sizeof(uint32_t));
  bad_index.back() = static_cast<char>(records.size());
  const uint32_t crc = crc32c::Value(
      bad_index.data() + kPageFormatHeaderSize,
      bad_index.size() - kPageFormatHeaderSize);
  for (uint32_t shift = 0; shift < 32; shift += 8) {
    bad_index[52 + shift / 8] = static_cast<char>(crc >> shift);
  }
  EXPECT_TRUE(DecodePage(bad_index).status().IsCorruption());

  std::string bad_dictionary_length = encoded.ValueOrDie();
  for (size_t byte = 0; byte < sizeof(uint32_t); ++byte) {
    bad_dictionary_length[kPageFormatHeaderSize + sizeof(uint32_t) + byte] =
        static_cast<char>(0xff);
  }
  const uint32_t length_crc = crc32c::Value(
      bad_dictionary_length.data() + kPageFormatHeaderSize,
      bad_dictionary_length.size() - kPageFormatHeaderSize);
  for (uint32_t shift = 0; shift < 32; shift += 8) {
    bad_dictionary_length[52 + shift / 8] =
        static_cast<char>(length_crc >> shift);
  }
  EXPECT_TRUE(DecodePage(bad_dictionary_length).status().IsCorruption());
}

TEST(GranuleBlockTest, PreservesTemporalEventsAndDeleteValueSparsity) {
  const LogicalKey key = LogicalKey::VertexProperty(9, 3);
  const BlockPartition partition{EntityType::Vertex, 3, 1, PhysicalType::kString};
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(key, 20, 2, 1, Value::String("later")),
      TemporalEvent::Delete(key, 10, 3, 1),
      TemporalEvent::Put(key, 5, 1, 1, Value::String("early")),
  };
  const auto block = BuildGranuleBlock(partition, events);
  ASSERT_TRUE(block.ok()) << block.status().ToString();
  const auto decoded = DecodeGranuleBlock(block.ValueOrDie().bytes, partition);
  ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
  ASSERT_EQ(decoded.ValueOrDie().size(), events.size());
  EXPECT_EQ(decoded.ValueOrDie()[0].value(), Value::String("later"));
  EXPECT_TRUE(decoded.ValueOrDie()[1].is_delete());
  EXPECT_EQ(decoded.ValueOrDie()[2].value(), Value::String("early"));
}

TEST(GranuleBlockTest, PersistsPresenceBitmapsAndUsesRankForDenseValues) {
  const BlockPartition partition{EntityType::Vertex, 3, 1,
                                 PhysicalType::kString};
  BlobRef reference;
  reference.content_hash = Blake3Hash("blob-value");
  reference.raw_length = 10;
  reference.hint = BlobLocation{2, 7, 4096};
  const std::vector<TemporalEvent> events = {
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 3), 1, 1, 1,
                         Value::String("first")),
      TemporalEvent::Delete(LogicalKey::VertexProperty(2, 3), 2, 2, 1),
      TemporalEvent::PutBlob(LogicalKey::VertexProperty(3, 3), 3, 3, 1,
                             reference),
      TemporalEvent::Put(LogicalKey::VertexProperty(4, 3), 4, 4, 1,
                         Value::String("second")),
  };
  const auto block = BuildGranuleBlock(partition, events);
  ASSERT_TRUE(block.ok()) << block.status().ToString();
  const auto read_u64 = [](const std::string& bytes, size_t offset) {
    uint64_t value = 0;
    for (uint32_t shift = 0; shift < 64; shift += 8) {
      value |= static_cast<uint64_t>(static_cast<uint8_t>(bytes[offset++]))
          << shift;
    }
    return value;
  };
  const uint64_t directory_offset = read_u64(block.ValueOrDie().bytes, 12);
  const uint64_t directory_length = read_u64(block.ValueOrDie().bytes, 20);
  const auto directory = DecodePageDirectory(block.ValueOrDie().bytes.substr(
      directory_offset, directory_length));
  ASSERT_TRUE(directory.ok()) << directory.status().ToString();
  std::map<PageType, std::string> presence;
  for (const PageDirectoryEntry& entry : directory.ValueOrDie()) {
    if (entry.page_type != PageType::kInlinePresence &&
        entry.page_type != PageType::kBlobPresence) {
      continue;
    }
    const auto page = DecodePage(block.ValueOrDie().bytes.substr(
        entry.offset, entry.length));
    ASSERT_TRUE(page.ok()) << page.status().ToString();
    EXPECT_EQ(page.ValueOrDie().header.encoding_id, EncodingId::kBitmap);
    presence.emplace(entry.page_type, page.ValueOrDie().payload);
  }
  EXPECT_EQ(presence[PageType::kInlinePresence], std::string("\1\0\0\1", 4));
  EXPECT_EQ(presence[PageType::kBlobPresence], std::string("\0\0\1\0", 4));

  const auto decoded = DecodeGranuleBlock(block.ValueOrDie().bytes, partition);
  ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
  ASSERT_EQ(decoded.ValueOrDie().size(), events.size());
  EXPECT_EQ(decoded.ValueOrDie()[0].value(), Value::String("first"));
  EXPECT_TRUE(decoded.ValueOrDie()[1].is_delete());
  ASSERT_TRUE(decoded.ValueOrDie()[2].is_blob_reference());
  EXPECT_EQ(decoded.ValueOrDie()[2].blob_ref()->content_hash,
            reference.content_hash);
  EXPECT_EQ(decoded.ValueOrDie()[3].value(), Value::String("second"));

  std::string corrupted = block.ValueOrDie().bytes;
  for (const PageDirectoryEntry& entry : directory.ValueOrDie()) {
    if (entry.page_type != PageType::kInlinePresence) continue;
    const auto page = DecodePage(corrupted.substr(entry.offset, entry.length));
    ASSERT_TRUE(page.ok()) << page.status().ToString();
    std::string bad_payload = page.ValueOrDie().payload;
    bad_payload[1] = 1;
    const auto replacement = EncodePageChecked(page.ValueOrDie().header,
                                               bad_payload);
    ASSERT_TRUE(replacement.ok()) << replacement.status().ToString();
    ASSERT_EQ(replacement.ValueOrDie().size(), entry.length);
    corrupted.replace(entry.offset, entry.length, replacement.ValueOrDie());
    break;
  }
  EXPECT_TRUE(DecodeGranuleBlock(corrupted, partition).status().IsCorruption());
}

TEST(GranuleBlockTest, EncodesSystemPagesWithFixedPhysicalTypes) {
  const BlockPartition partition{EntityType::Vertex, 3, 1, PhysicalType::kString};
  const auto block = BuildGranuleBlock(partition, {
      TemporalEvent::Put(LogicalKey::VertexProperty(9, 3), 20, 2, 1,
                         Value::String("value")),
  });
  ASSERT_TRUE(block.ok()) << block.status().ToString();
  const auto read_u64 = [](const std::string& bytes, size_t offset) {
    uint64_t value = 0;
    for (uint32_t shift = 0; shift < 64; shift += 8) {
      value |= static_cast<uint64_t>(
          static_cast<uint8_t>(bytes[offset++])) << shift;
    }
    return value;
  };
  const uint64_t directory_offset = read_u64(block.ValueOrDie().bytes, 12);
  const uint64_t directory_length = read_u64(block.ValueOrDie().bytes, 20);
  const auto directory = DecodePageDirectory(block.ValueOrDie().bytes.substr(
      directory_offset, directory_length));
  ASSERT_TRUE(directory.ok()) << directory.status().ToString();
  std::map<PageType, PhysicalType> physical_types;
  for (const PageDirectoryEntry& entry : directory.ValueOrDie()) {
    if (physical_types.count(entry.page_type) != 0) continue;
    const auto page = DecodePage(block.ValueOrDie().bytes.substr(
        entry.offset, entry.length));
    ASSERT_TRUE(page.ok()) << page.status().ToString();
    physical_types.emplace(entry.page_type, page.ValueOrDie().header.physical_type);
  }
  EXPECT_EQ(physical_types[PageType::kEntityId], PhysicalType::kInt64);
  EXPECT_EQ(physical_types[PageType::kTargetId], PhysicalType::kInt64);
  EXPECT_EQ(physical_types[PageType::kEdgeId], PhysicalType::kInt64);
  EXPECT_EQ(physical_types[PageType::kValidFrom], PhysicalType::kTimestamp64);
  EXPECT_EQ(physical_types[PageType::kCommitSeq], PhysicalType::kInt64);
  EXPECT_EQ(physical_types[PageType::kOperation], PhysicalType::kBool);
  EXPECT_EQ(physical_types[PageType::kValueClass], PhysicalType::kInt32);
  EXPECT_EQ(physical_types[PageType::kTypedValue], PhysicalType::kString);
  EXPECT_EQ(physical_types[PageType::kBlobRef], PhysicalType::kBinary);
}

TEST(GranuleBlockTest, UsesDictionaryEncodingForRepeatedTypedValues) {
  const BlockPartition partition{EntityType::Vertex, 3, 1,
                                 PhysicalType::kString};
  std::vector<TemporalEvent> events;
  for (uint64_t row = 0; row < 64; ++row) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(row, 3), 100 + row, row + 1, 1,
        Value::String(row % 2 == 0 ? "alpha" : "beta")));
  }
  const auto block = BuildGranuleBlock(partition, events);
  ASSERT_TRUE(block.ok()) << block.status().ToString();
  const auto read_u64 = [](const std::string& bytes, size_t offset) {
    uint64_t value = 0;
    for (uint32_t shift = 0; shift < 64; shift += 8) {
      value |= static_cast<uint64_t>(
          static_cast<uint8_t>(bytes[offset++])) << shift;
    }
    return value;
  };
  const uint64_t directory_offset = read_u64(block.ValueOrDie().bytes, 12);
  const uint64_t directory_length = read_u64(block.ValueOrDie().bytes, 20);
  const auto directory = DecodePageDirectory(block.ValueOrDie().bytes.substr(
      directory_offset, directory_length));
  ASSERT_TRUE(directory.ok()) << directory.status().ToString();
  bool found_typed_values = false;
  for (const PageDirectoryEntry& entry : directory.ValueOrDie()) {
    if (entry.page_type != PageType::kTypedValue) continue;
    const auto page = DecodePage(block.ValueOrDie().bytes.substr(
        entry.offset, entry.length));
    ASSERT_TRUE(page.ok()) << page.status().ToString();
    EXPECT_EQ(page.ValueOrDie().header.encoding_id, EncodingId::kDictionary);
    found_typed_values = true;
  }
  EXPECT_TRUE(found_typed_values);

  const auto decoded = DecodeGranuleBlock(block.ValueOrDie().bytes, partition);
  ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
  ASSERT_EQ(decoded.ValueOrDie().size(), events.size());
  for (size_t row = 0; row < events.size(); ++row) {
    EXPECT_EQ(decoded.ValueOrDie()[row].logical_key(), events[row].logical_key());
    EXPECT_EQ(decoded.ValueOrDie()[row].valid_from(), events[row].valid_from());
    EXPECT_EQ(decoded.ValueOrDie()[row].commit_seq(), events[row].commit_seq());
    EXPECT_EQ(decoded.ValueOrDie()[row].value(), events[row].value());
  }
}

TEST(GranuleBlockTest, UsesZstdWhenConfiguredAndBeneficial) {
  const BlockPartition partition{EntityType::Vertex, 3, 1,
                                 PhysicalType::kString, 0,
                                 CompressionId::kZstd};
  std::vector<TemporalEvent> events;
  const std::string repeated_value(2048, 'z');
  for (uint64_t row = 0; row < 64; ++row) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(row, 3), 100 + row, row + 1, 1,
        Value::String(repeated_value)));
  }
  const auto block = BuildGranuleBlock(partition, events);
#if CEDAR_HAS_ZSTD
  ASSERT_TRUE(block.ok()) << block.status().ToString();
  uint64_t directory_offset = 0;
  uint64_t directory_length = 0;
  for (uint32_t byte = 0; byte < 8; ++byte) {
    directory_offset |= static_cast<uint64_t>(static_cast<uint8_t>(
        block.ValueOrDie().bytes[12 + byte])) << (byte * 8);
    directory_length |= static_cast<uint64_t>(static_cast<uint8_t>(
        block.ValueOrDie().bytes[20 + byte])) << (byte * 8);
  }
  const auto directory = DecodePageDirectory(block.ValueOrDie().bytes.substr(
      directory_offset, directory_length));
  ASSERT_TRUE(directory.ok()) << directory.status().ToString();
  bool saw_zstd = false;
  for (const PageDirectoryEntry& entry : directory.ValueOrDie()) {
    if (entry.page_type != PageType::kTypedValue) continue;
    const auto header = DecodePageHeader(block.ValueOrDie().bytes.substr(
        entry.offset, kPageFormatHeaderSize));
    ASSERT_TRUE(header.ok()) << header.status().ToString();
    saw_zstd = saw_zstd ||
        header.ValueOrDie().compression_id == CompressionId::kZstd;
  }
  EXPECT_TRUE(saw_zstd);
  const auto decoded = DecodeGranuleBlock(block.ValueOrDie().bytes, partition);
  ASSERT_TRUE(decoded.ok()) << decoded.status().ToString();
  EXPECT_EQ(decoded.ValueOrDie().size(), events.size());
#else
  ASSERT_FALSE(block.ok());
  EXPECT_TRUE(block.status().IsNotSupportedError());
#endif
}

