TEST(GranuleBlockTest, UsesCurrentFormatIdentityForFixedWidthFloatLayout) {
  const BlockPartition partition{EntityType::Vertex, 7, 1,
                                 PhysicalType::kFloat64};
  const auto built = BuildGranuleBlock(
      partition,
      {TemporalEvent::Put(LogicalKey::VertexProperty(1, 7), 10, 1, 1,
                          Value::Float64(1.0))});
  ASSERT_TRUE(built.ok()) << built.status().ToString();
  ASSERT_GE(built.ValueOrDie().bytes.size(), 6U);
  const uint32_t magic =
      static_cast<uint32_t>(static_cast<uint8_t>(built.ValueOrDie().bytes[0])) |
      (static_cast<uint32_t>(static_cast<uint8_t>(built.ValueOrDie().bytes[1]))
       << 8) |
      (static_cast<uint32_t>(static_cast<uint8_t>(built.ValueOrDie().bytes[2]))
       << 16) |
      (static_cast<uint32_t>(static_cast<uint8_t>(built.ValueOrDie().bytes[3]))
       << 24);
  const uint16_t version =
      static_cast<uint16_t>(static_cast<uint8_t>(built.ValueOrDie().bytes[4])) |
      (static_cast<uint16_t>(static_cast<uint8_t>(built.ValueOrDie().bytes[5]))
       << 8);
  EXPECT_EQ(magic, 0x354b4247U);  // GBK5
  EXPECT_EQ(version, 5U);
}

TEST(GranuleBlockTest, RejectsInvalidInlineLengthAndPageDirectoryOffset) {
  const BlockPartition partition{EntityType::Vertex, 3, 1,
                                 PhysicalType::kString};
  const auto block = BuildGranuleBlock(partition, {
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 3), 10, 1, 1,
                         Value::String("value")),
  });
  ASSERT_TRUE(block.ok()) << block.status().ToString();
  const auto read_u64 = [](const std::string& bytes, size_t offset) {
    uint64_t value = 0;
    for (uint32_t shift = 0; shift < 64; shift += 8) {
      value |= static_cast<uint64_t>(
          static_cast<uint8_t>(bytes[offset++])) << shift;
    }
    return value;
  };
  const uint64_t directory_offset = read_u64(block.ValueOrDie().bytes, 12);
  const uint64_t directory_length = read_u64(block.ValueOrDie().bytes, 20);
  const auto directory = DecodePageDirectory(block.ValueOrDie().bytes.substr(
      directory_offset, directory_length));
  ASSERT_TRUE(directory.ok()) << directory.status().ToString();
  const auto typed = std::find_if(
      directory.ValueOrDie().begin(), directory.ValueOrDie().end(),
      [](const PageDirectoryEntry& entry) {
        return entry.page_type == PageType::kTypedValue;
      });
  ASSERT_NE(typed, directory.ValueOrDie().end());

  std::string bad_length = block.ValueOrDie().bytes;
  const size_t typed_payload =
      static_cast<size_t>(typed->offset + kPageFormatHeaderSize);
  bad_length[typed_payload] = static_cast<char>(0xff);
  const uint32_t crc = crc32c::Value(
      bad_length.data() + typed_payload,
      static_cast<size_t>(typed->length - kPageFormatHeaderSize));
  for (uint32_t shift = 0; shift < 32; shift += 8) {
    bad_length[static_cast<size_t>(typed->offset) + 52 + shift / 8] =
        static_cast<char>(crc >> shift);
  }
  EXPECT_TRUE(DecodeGranuleBlock(bad_length, partition).status().IsCorruption());

  std::string bad_offset = block.ValueOrDie().bytes;
  constexpr size_t kFirstDirectoryOffsetField = 8 + 1 + sizeof(uint32_t);
  for (size_t byte = 0; byte < sizeof(uint64_t); ++byte) {
    bad_offset[static_cast<size_t>(directory_offset) +
               kFirstDirectoryOffsetField + byte] = 0;
  }
  EXPECT_TRUE(DecodeGranuleBlock(bad_offset, partition).status().IsCorruption());
}

