TEST_F(DurableLogTest, SstCursorChargesRealBlockReadsToTheIoGovernor) {
  const BlockPartition partition{EntityType::Vertex, 31, 1,
                                 PhysicalType::kInt64};
  const std::string path = path_ + "/shards/0/sst/governed-cursor.sst";
  ASSERT_TRUE(WriteSstFile(path, partition, {
      TemporalEvent::Put(LogicalKey::VertexProperty(1, 31), 10, 1, 1,
                         Value::Int64(1)),
  }).ok());

  IoGovernor exhausted(IoGovernorLimits{
      IoTokenBudget{0, 0}, IoTokenBudget{0, 0}, IoTokenBudget{0, 0},
      IoTokenBudget{16, 16}});
  SstCursorOptions blocked_options{partition, std::nullopt, nullptr, nullptr};
  blocked_options.io_governor = &exhausted;
  const auto blocked = OpenSstEventCursor(path, std::move(blocked_options));
  EXPECT_TRUE(blocked.status().IsQueryMemoryLimit())
      << blocked.status().ToString();

  IoGovernor available(IoGovernorLimits{
      IoTokenBudget{1U << 20, 0}, IoTokenBudget{16, 0},
      IoTokenBudget{0, 0}, IoTokenBudget{16, 0}});
  const uint64_t before = available.available().sequential_read_bytes;
  SstCursorOptions admitted_options{partition, std::nullopt, nullptr, nullptr};
  admitted_options.io_governor = &available;
  auto admitted = OpenSstEventCursor(path, std::move(admitted_options));
  ASSERT_TRUE(admitted.ok()) << admitted.status().ToString();
  EXPECT_TRUE(admitted.ValueOrDie().valid());
  EXPECT_EQ(admitted.ValueOrDie().current().logical_key(),
            LogicalKey::VertexProperty(1, 31));
  EXPECT_LT(available.available().sequential_read_bytes, before);
}

TEST_F(DurableLogTest, SstCursorCoalescesAdjacentBlockPrefetchWithinGrantedBudgets) {
  const BlockPartition partition{EntityType::Vertex, 31, 1,
                                 PhysicalType::kInt64};
  std::vector<TemporalEvent> events;
  events.reserve(8193);
  for (uint64_t id = 0; id < 8193; ++id) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(id, 31), 10, id + 1, 1,
        Value::Int64(static_cast<int64_t>(id))));
  }
  const std::string path = path_ + "/shards/0/sst/coalesced-prefetch.sst";
  ASSERT_TRUE(WriteSstFile(path, partition, events).ok());
  const uint64_t file_size = std::filesystem::file_size(path);
  IoGovernor io(IoGovernorLimits{
      IoTokenBudget{2 * file_size, 0}, IoTokenBudget{16, 0},
      IoTokenBudget{0, 0}, IoTokenBudget{16, 0}});
  auto memory = std::make_shared<QueryMemoryAccount>(64U << 20, 128U << 20);
  SstCursorOptions options{partition, std::nullopt, nullptr, memory};
  options.io_governor = &io;
  options.prefetch_next_block = true;
  auto opened = OpenSstEventCursor(path, std::move(options));
  ASSERT_TRUE(opened.ok()) << opened.status().ToString();
  SstEventCursor cursor = std::move(opened).ConsumeValueOrDie();
  EXPECT_EQ(cursor.stats().coalesced_read_ops, 1U);
  EXPECT_EQ(cursor.stats().prefetched_blocks, 1U);
  EXPECT_GT(cursor.stats().prefetched_bytes, 0U);
  const uint64_t tokens_after_open = io.available().sequential_read_bytes;
  while (cursor.valid() && cursor.current().logical_key().entity_id() < 8192) {
    ASSERT_TRUE(cursor.Advance().ok());
  }
  ASSERT_TRUE(cursor.valid());
  EXPECT_EQ(cursor.current().logical_key().entity_id(), 8192U);
  EXPECT_EQ(io.available().sequential_read_bytes, tokens_after_open);
}

