TEST_F(DurableLogTest, ExactSstCursorReportsBloomFalsePositiveBlockAttempt) {
  const BlockPartition partition{EntityType::Vertex, 31, 1,
                                 PhysicalType::kInt64};
  const std::string path =
      path_ + "/shards/0/sst/exact-bloom-false-positive.sst";
  std::vector<TemporalEvent> events;
  events.reserve(1024);
  for (uint64_t ordinal = 0; ordinal < 1024; ++ordinal) {
    const uint64_t entity_id = ordinal * 2;
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(entity_id, 31), 10, ordinal + 1, 1,
        Value::Int64(static_cast<int64_t>(entity_id))));
  }
  ASSERT_TRUE(WriteSstFile(path, partition, events).ok());

  constexpr uint64_t kFirstSeed = 0x9e3779b97f4a7c15ULL;
  constexpr uint64_t kSecondSeed = 0xd6e8feb86659fd93ULL;
  constexpr uint8_t kHashCount = 7;
  const uint32_t bit_count = 10240;
  std::string bloom_bits(bit_count / 8, '\0');
  const auto add_to_bloom = [&](const LogicalKey& key) {
    const uint64_t first = key.StableHash(kFirstSeed);
    uint64_t second = key.StableHash(kSecondSeed);
    if (second == 0) second = 0x94d049bb133111ebULL;
    for (uint8_t hash = 0; hash < kHashCount; ++hash) {
      const uint32_t bit =
          static_cast<uint32_t>((first + hash * second) % bit_count);
      bloom_bits[bit / 8] = static_cast<char>(
          static_cast<uint8_t>(bloom_bits[bit / 8]) |
          (uint8_t{1} << (bit % 8)));
    }
  };
  for (const TemporalEvent& event : events) add_to_bloom(event.logical_key());
  const auto may_contain = [&](const LogicalKey& key) {
    const uint64_t first = key.StableHash(kFirstSeed);
    uint64_t second = key.StableHash(kSecondSeed);
    if (second == 0) second = 0x94d049bb133111ebULL;
    for (uint8_t hash = 0; hash < kHashCount; ++hash) {
      const uint32_t bit =
          static_cast<uint32_t>((first + hash * second) % bit_count);
      if ((static_cast<uint8_t>(bloom_bits[bit / 8]) &
           (uint8_t{1} << (bit % 8))) == 0) {
        return false;
      }
    }
    return true;
  };
  std::optional<LogicalKey> false_positive;
  for (uint64_t entity_id = 1;
       entity_id < 2047 && !false_positive.has_value(); entity_id += 2) {
    for (uint32_t column = 0; column <= UINT16_MAX; ++column) {
      const LogicalKey candidate = LogicalKey::VertexProperty(
          entity_id, static_cast<uint16_t>(column));
      if (may_contain(candidate)) {
        false_positive = candidate;
        break;
      }
    }
  }
  ASSERT_TRUE(false_positive.has_value());
  auto opened = OpenSstEventCursor(
      path, SstCursorOptions{partition, *false_positive, nullptr, nullptr});
  ASSERT_TRUE(opened.ok()) << opened.status().ToString();
  SstEventCursor cursor = std::move(opened).ConsumeValueOrDie();
  EXPECT_FALSE(cursor.valid());
  EXPECT_TRUE(cursor.terminal_status().ok());
  EXPECT_EQ(cursor.stats().blocks_read, 1U);
  EXPECT_GT(cursor.stats().peak_buffered_bytes, 0U);
}

