TEST_F(DurableLogTest, FailedSstBlockReadCountsAttemptAndReleasesReservation) {
  const BlockPartition partition{EntityType::Vertex, 7, 1,
                                 PhysicalType::kString};
  std::vector<TemporalEvent> events;
  for (uint64_t id = 1; id <= 8; ++id) {
    events.push_back(TemporalEvent::Put(
        LogicalKey::VertexProperty(id, 7), 10, id, 1,
        Value::String(std::string(150 * 1024, static_cast<char>('a' + id)))));
  }
  const std::string path = path_ + "/shards/0/sst/failed-block-accounting.sst";
  ASSERT_TRUE(WriteSstFile(path, partition, events).ok());
  const auto first_block = BuildGranuleBlock(
      partition, std::vector<TemporalEvent>(events.begin(), events.begin() + 6));
  ASSERT_TRUE(first_block.ok()) << first_block.status().ToString();
  {
    std::fstream file(path, std::ios::in | std::ios::out | std::ios::binary);
    ASSERT_TRUE(file.is_open());
    const std::streamoff corrupt_at = static_cast<std::streamoff>(
        80 + first_block.ValueOrDie().bytes.size() + 100);
    file.seekg(corrupt_at);
    char byte = 0;
    file.get(byte);
    ASSERT_TRUE(file.good());
    file.seekp(corrupt_at);
    file.put(static_cast<char>(byte ^ 0x5a));
  }
  auto memory = std::make_shared<QueryMemoryAccount>(32U << 20, 64U << 20);
  auto opened = OpenSstEventCursor(
      path, SstCursorOptions{partition, std::nullopt, nullptr, memory});
  ASSERT_TRUE(opened.ok()) << opened.status().ToString();
  SstEventCursor cursor = std::move(opened).ConsumeValueOrDie();
  Status status = Status::OK();
  for (uint32_t row = 0; row < 6 && status.ok(); ++row) {
    status = cursor.Advance();
  }
  EXPECT_TRUE(status.IsCorruption()) << status.ToString();
  EXPECT_TRUE(cursor.terminal_status().IsCorruption());
  EXPECT_EQ(cursor.stats().blocks_read, 2U);
  EXPECT_GT(cursor.stats().peak_buffered_bytes, 0U);
  EXPECT_EQ(memory->used_bytes(), 0U);
}

