  ASSERT_TRUE(versions.ApplyEdit(edit).ok());
  ASSERT_EQ(versions.Snapshot()->index_definitions.size(), 1U);
  EXPECT_EQ(versions.Snapshot()->index_definitions[0].index_id, 17U);
  EXPECT_EQ(versions.Snapshot()->next_index_id, 18U);

