TEST_F(DurableLogTest,
       ReopenRejectsChecksummedIndexFragmentBoundToAnotherPartition) {
  const std::string manifest = path_ + "/manifest/MANIFEST";
  VersionSet versions(manifest);
  ASSERT_TRUE(versions.Open().ok());
  const BlockPartition indexed_partition{
      EntityType::Vertex, 7, 1, PhysicalType::kString};
  const BlockPartition other_partition{
      EntityType::Vertex, 8, 1, PhysicalType::kString};
  const auto indexed_source = BuildTestSstFileMeta(
      101, "shards/0/sst/101.sst", indexed_partition, 101);
  const auto other_source = BuildTestSstFileMeta(
      202, "shards/0/sst/202.sst", other_partition, 202);
  ASSERT_TRUE(indexed_source.ok()) << indexed_source.status().ToString();
  ASSERT_TRUE(other_source.ok()) << other_source.status().ToString();
  IndexDefinition definition;
  definition.index_id = 17;
  definition.entity_type = EntityType::Vertex;
  definition.column_id = 7;
  definition.schema_epoch = 1;
  definition.capabilities = kIndexEquality;
  definition.canonical_encoding_id = kIndexCanonicalEncoding;
  definition.state = IndexState::kActive;
  VersionEdit edit;
  edit.schema_adds = TestSchemasForPartition(indexed_partition);
  const auto other_schemas = TestSchemasForPartition(other_partition);
  edit.schema_adds.insert(edit.schema_adds.end(), other_schemas.begin(),
                          other_schemas.end());
  edit.adds = {indexed_source.ValueOrDie(), other_source.ValueOrDie()};
  edit.index_adds.push_back(definition);
  edit.index_fragment_adds.push_back(IndexFragment{
      17, 101, "indexes/17/101.idx", 1, 1, 1, 1, true, {}});
  ASSERT_TRUE(versions.ApplyEdit(edit).ok());

  std::ifstream input(manifest, std::ios::binary);
  std::string bytes((std::istreambuf_iterator<char>(input)),
                    std::istreambuf_iterator<char>());
  const std::string fragment_path = "indexes/17/101.idx";
  const size_t path_offset = bytes.find(fragment_path);
  ASSERT_NE(path_offset, std::string::npos);
  ASSERT_GE(path_offset, 12U);
  const size_t source_id_offset = path_offset - 12;
  for (uint32_t shift = 0; shift < 64; shift += 8) {
    bytes[source_id_offset + shift / 8] =
        static_cast<char>(uint64_t{202} >> shift);
  }
  const uint32_t checksum = crc32c::Value(bytes.data() + 8, bytes.size() - 8);
  for (uint32_t shift = 0; shift < 32; shift += 8) {
    bytes[4 + shift / 8] = static_cast<char>(checksum >> shift);
  }
  std::ofstream output(manifest, std::ios::binary | std::ios::trunc);
  output.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
  output.close();

  VersionSet reopened(manifest);
  const Status status = reopened.Open();
  EXPECT_TRUE(status.IsCorruption()) << status.ToString();
}

TEST_F(DurableLogTest, VersionSetRejectsManifestGenerationOverflow) {
  const std::string manifest = path_ + "/manifest/MANIFEST";
  VersionSet versions(manifest);
  ASSERT_TRUE(versions.Open().ok());
  ASSERT_TRUE(versions.ApplyEdit(VersionEdit{}).ok());

  std::ifstream input(manifest, std::ios::binary);
  std::string bytes((std::istreambuf_iterator<char>(input)),
                    std::istreambuf_iterator<char>());
  ASSERT_GE(bytes.size(), 20U);
  std::fill(bytes.begin() + 12, bytes.begin() + 20,
            static_cast<char>(0xff));
  const uint32_t checksum = crc32c::Value(bytes.data() + 8, bytes.size() - 8);
  for (uint32_t shift = 0; shift < 32; shift += 8) {
    bytes[4 + shift / 8] = static_cast<char>(checksum >> shift);
  }
  std::ofstream output(manifest, std::ios::binary | std::ios::trunc);
  output.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
  output.close();

  VersionSet reopened(manifest);
  ASSERT_TRUE(reopened.Open().ok());
  ASSERT_EQ(reopened.Snapshot()->generation,
            std::numeric_limits<uint64_t>::max());
  const Status rejected = reopened.ApplyEdit(VersionEdit{});
  EXPECT_TRUE(rejected.IsResourceExhausted() || rejected.IsCorruption())
      << rejected.ToString();
  EXPECT_EQ(reopened.Snapshot()->generation,
            std::numeric_limits<uint64_t>::max());
}

