TEST_F(DurableLogTest,
       VersionSetRejectsImpossibleDeclaredEntryCountWithoutLargeReserve) {
  const auto append_u32 = [](std::string* output, uint32_t value) {
    for (uint32_t shift = 0; shift < 32; shift += 8) {
      output->push_back(static_cast<char>(value >> shift));
    }
  };
  const auto append_u64 = [](std::string* output, uint64_t value) {
    for (uint32_t shift = 0; shift < 64; shift += 8) {
      output->push_back(static_cast<char>(value >> shift));
    }
  };
  std::string body;
  append_u32(&body, 0x3143534dU);
  append_u64(&body, 0);
  append_u32(&body, 1000000);
  std::string framed;
  append_u32(&framed, static_cast<uint32_t>(body.size()));
  append_u32(&framed, crc32c::Value(body.data(), body.size()));
  framed.append(body);

  const std::string manifest = path_ + "/manifest/MANIFEST";
  std::filesystem::create_directories(
      std::filesystem::path(manifest).parent_path());
  std::ofstream output(manifest, std::ios::binary | std::ios::trunc);
  output.write(framed.data(), static_cast<std::streamsize>(framed.size()));
  output.close();
  VersionSet declared_count(manifest);
  const Status status = declared_count.Open();
  EXPECT_TRUE(status.IsCorruption()) << status.ToString();
}

TEST_F(DurableLogTest, FlushesCommittedShardEventsIntoPartitionedSstFiles) {
  StorageShard shard(0);
  const LogicalKey name = LogicalKey::VertexProperty(1, 1);
  const LogicalKey age = LogicalKey::VertexProperty(1, 2);
  ASSERT_TRUE(shard.InstallCommitted(1, 1, {
      PendingEvent::Put(name, 1, 1, Value::String("Ada")),
      PendingEvent::Put(age, 1, 1, Value::Int32(37)),
      PendingEvent{name, 2, 1, TemporalOperation::kDelete, Value::Binary("", 0)},
  }).ok());
  VersionSet versions(path_ + "/manifest/MANIFEST");
  ASSERT_TRUE(versions.Open().ok());
  SchemaRegistry schemas;
  ColumnSchema schema{EntityType::Vertex, 1, 0, "name", PhysicalType::kString,
                      4096, EncodingPolicy::kAdaptive, CompressionPolicy::kLz4};
  ColumnSchema registered;
  ASSERT_TRUE(PublishSchemaForTest(&versions, &schemas, schema, &registered).ok());
  schema.column_id = 2;
  schema.logical_type = "age";
  schema.physical_type = PhysicalType::kInt32;
  ASSERT_TRUE(PublishSchemaForTest(&versions, &schemas, schema, &registered).ok());
  const auto flushed = FlushShardToSst(path_, shard, 10, schemas, &versions);
  ASSERT_TRUE(flushed.ok()) << flushed.status().ToString();
  EXPECT_EQ(flushed.ValueOrDie().next_file_number, 12U);
  ASSERT_EQ(versions.Snapshot()->files.size(), 2U);
  size_t event_count = 0;
  bool saw_delete = false;
  for (const SstFileMeta& file : versions.Snapshot()->files) {
    EXPECT_TRUE(std::filesystem::exists(path_ + "/" + file.relative_path));
    const auto events = ReadSstFile(path_ + "/" + file.relative_path);
    ASSERT_TRUE(events.ok()) << events.status().ToString();
    event_count += events.ValueOrDie().size();
    for (const TemporalEvent& event : events.ValueOrDie()) saw_delete = saw_delete || event.is_delete();
  }
  EXPECT_EQ(event_count, 3U);
  EXPECT_TRUE(saw_delete);

  const auto from_sst = MergeTemporalRead(path_, *versions.Snapshot(), {}, name, 1, 1);
  ASSERT_TRUE(from_sst.ok()) << from_sst.status().ToString();
  ASSERT_TRUE(from_sst.ValueOrDie().has_value());
  EXPECT_EQ(*from_sst.ValueOrDie(), Value::String("Ada"));
}

TEST_F(DurableLogTest, QuerySpillRoundTripsStructuredAndListResultColumns) {
  StructValue relationship;
  relationship.fields = {
      {"source_id", Value::Int64(10)},
      {"target_id", Value::Int64(20)},
      {"edge_type", Value::Int64(7)},
  };
  ListValue names;
  names.elements = {Value::String("Ada"), std::nullopt, Value::String("Lin")};
  ListValue path;
  path.element_kind = ListElementKind::kStruct;
  path.structured_elements = {
      StructValue{{{"source_id", Value::Int64(10)},
                   {"target_id", Value::Int64(20)},
                   {"edge_type", Value::Int64(7)},
                   {"edge_id", Value::Int64(71)},
                   {"valid_from", Value::Timestamp(5)},
                   {"commit_seq", Value::Int64(3)}}},
      StructValue{{{"source_id", Value::Int64(20)},
                   {"target_id", Value::Int64(30)},
                   {"edge_type", Value::Int64(7)},
                   {"edge_id", Value::Int64(72)},
                   {"valid_from", Value::Timestamp(7)},
                   {"commit_seq", Value::Int64(4)}}},
  };
  ListValue empty_path;
  empty_path.element_kind = ListElementKind::kStruct;

  ColumnBatch values(2);
  ASSERT_TRUE(values.AddVector(std::make_shared<StructVector>(
      std::vector<StructValue>{relationship, StructValue{}}, std::vector<bool>{true, false})).ok());
  ASSERT_TRUE(values.AddVector(std::make_shared<ListVector>(
      std::vector<ListValue>{names, ListValue{}}, std::vector<bool>{true, false})).ok());
  ASSERT_TRUE(values.AddVector(std::make_shared<ListVector>(
      std::vector<ListValue>{path, ListValue{}}, std::vector<bool>{true, false})).ok());
  ASSERT_TRUE(values.AddVector(std::make_shared<ListVector>(
      std::vector<ListValue>{empty_path, ListValue{}},
      std::vector<bool>{true, false})).ok());
  ResultBatch source({"r", "names", "path", "empty_path"}, std::move(values),
                     ResultTemporalMetadata{11, true, true});

  QuerySpillFile spill(path_ + "/spill");
  ASSERT_TRUE(spill.Open().ok());
  ASSERT_TRUE(spill.Append(source).ok());
  ASSERT_TRUE(spill.Rewind().ok());
  ResultBatch decoded;
  ASSERT_TRUE(spill.Next(&decoded).ok());
  EXPECT_TRUE(decoded.batch().IsStructured(0));
  EXPECT_TRUE(decoded.batch().IsList(1));
  ASSERT_TRUE(decoded.batch().StructAt(0, 0).has_value());
  ASSERT_EQ(decoded.batch().StructAt(0, 0)->fields.size(), 3U);
  EXPECT_EQ(decoded.batch().StructAt(0, 0)->fields[1].value, Value::Int64(20));
  EXPECT_FALSE(decoded.batch().StructAt(0, 1).has_value());
  ASSERT_TRUE(decoded.batch().ListAt(1, 0).has_value());
  ASSERT_EQ(decoded.batch().ListAt(1, 0)->elements.size(), 3U);
  EXPECT_FALSE(decoded.batch().ListAt(1, 0)->elements[1].has_value());
  EXPECT_FALSE(decoded.batch().ListAt(1, 1).has_value());
  ASSERT_TRUE(decoded.batch().IsList(2));
  ASSERT_TRUE(decoded.batch().ListAt(2, 0).has_value());
  EXPECT_TRUE(decoded.batch().ListAt(2, 0)->elements.empty());
  ASSERT_EQ(decoded.batch().ListAt(2, 0)->structured_elements.size(), 2U);
  EXPECT_EQ(decoded.batch().ListAt(2, 0)->structured_elements[0].fields[3].value,
            Value::Int64(71));
  EXPECT_EQ(decoded.batch().ListAt(2, 0)->structured_elements[1].fields[3].value,
            Value::Int64(72));
  EXPECT_EQ(decoded.batch().ListAt(2, 0)->element_kind,
            ListElementKind::kStruct);
  EXPECT_FALSE(decoded.batch().ListAt(2, 1).has_value());
  ASSERT_TRUE(decoded.batch().ListAt(3, 0).has_value());
  EXPECT_EQ(decoded.batch().ListAt(3, 0)->element_kind,
            ListElementKind::kStruct);
  EXPECT_TRUE(decoded.batch().ListAt(3, 0)->structured_elements.empty());
  EXPECT_EQ(decoded.temporal_metadata().snapshot_seq, 11U);
  EXPECT_TRUE(decoded.temporal_metadata().includes_valid_time);
  EXPECT_TRUE(decoded.temporal_metadata().includes_system_time);
  EXPECT_TRUE(spill.Close().ok());
}

