TEST(TcypherResultStreamTest, DistinctSpillsRemainingRowsAtSoftLimit) {
  const std::string spill_directory =
      "/tmp/cedar_distinct_partition_spill";
  std::filesystem::remove_all(spill_directory);
  constexpr uint32_t kUnique = 24;
  std::vector<Value> values;
  for (uint32_t pass = 0; pass < 2; ++pass) {
    for (uint32_t value = 0; value < kUnique; ++value) {
      values.push_back(Value::String(
          "value-" + std::to_string(value) + std::string(24, 'x')));
    }
  }
  ColumnBatch input_batch(kUnique * 2);
  ASSERT_TRUE(input_batch.AddVector(std::make_shared<FlatVector>(
      std::move(values), std::vector<bool>{})).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(512, 2048);
  std::set<std::string> actual;
  {
    DistinctResultStream distinct(
        std::make_unique<InMemoryResultStream>(
            std::vector<ResultBatch>{ResultBatch(
                {"value"}, std::move(input_batch))}, Status::OK()),
        nullptr, memory, spill_directory);
    for (;;) {
      ResultBatch result;
      const Status next = distinct.Next(&result);
      if (next.IsNotFound()) break;
      ASSERT_TRUE(next.ok()) << next.ToString();
      for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
        actual.insert(std::get<std::string>(
            result.batch().ValueAt(0, row)->data()));
      }
    }
    ASSERT_TRUE(std::filesystem::exists(spill_directory));
    EXPECT_FALSE(std::filesystem::is_empty(spill_directory));
  }
  EXPECT_EQ(actual.size(), kUnique);
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

TEST(TcypherResultStreamTest, GroupsScalarValuesIntoListVectors) {
  ColumnBatch values(3);
  ASSERT_TRUE(values.AddVector(std::make_shared<FlatVector>(
      std::vector<Value>{Value::String("a"), Value::String("a"), Value::String("b")},
      std::vector<bool>{})).ok());
  ASSERT_TRUE(values.AddVector(std::make_shared<FlatVector>(
      std::vector<Value>{Value::Int64(1), Value::Binary(""), Value::Int64(3)},
      std::vector<bool>{true, false, true})).ok());
  auto input = std::make_unique<InMemoryResultStream>(
      std::vector<ResultBatch>{ResultBatch({"group", "value"}, std::move(values))}, Status::OK());
  GroupedCollectResultStream collect(std::move(input), {0}, 1, "collect(value)",
                                     {{false, 0}, {true, 0}}, 8);
  ResultBatch result;
  ASSERT_TRUE(collect.Next(&result).ok());
  ASSERT_EQ(result.batch().row_count(), 2U);
  EXPECT_EQ(result.batch().ValueAt(0, 0), Value::String("a"));
  ASSERT_TRUE(result.batch().ListAt(1, 0).has_value());
  ASSERT_EQ(result.batch().ListAt(1, 0)->elements.size(), 1U);
  EXPECT_EQ(result.batch().ListAt(1, 0)->elements[0], Value::Int64(1));
  EXPECT_EQ(result.batch().ValueAt(0, 1), Value::String("b"));
  ASSERT_TRUE(result.batch().ListAt(1, 1).has_value());
  EXPECT_EQ(result.batch().ListAt(1, 1)->elements[0], Value::Int64(3));
}

TEST(TcypherResultStreamTest,
     CollectsStructuredValuesIntoTypedListAndOmitsNulls) {
  const StructValue first{{
      {"edge_id", Value::Int64(71)},
      {"payload", Value::String("first")}}};
  const StructValue omitted{{
      {"edge_id", Value::Int64(0)},
      {"payload", Value::String("null")}}};
  const StructValue second{{
      {"edge_id", Value::Int64(72)},
      {"payload", Value::String("second")}}};
  ColumnBatch values(3);
  ASSERT_TRUE(values.AddVector(std::make_shared<StructVector>(
      std::vector<StructValue>{first, omitted, second},
      std::vector<bool>{true, false, true})).ok());
  CollectResultStream collect(
      std::make_unique<InMemoryResultStream>(
          std::vector<ResultBatch>{ResultBatch(
              {"relationship"}, std::move(values))}, Status::OK()),
      "collect(relationship)");
  ResultBatch result;
  ASSERT_TRUE(collect.Next(&result).ok());
  ASSERT_TRUE(result.batch().IsList(0));
  const auto collected = result.batch().ListAt(0, 0);
  ASSERT_TRUE(collected.has_value());
  EXPECT_TRUE(collected->elements.empty());
  ASSERT_EQ(collected->structured_elements.size(), 2U);
  EXPECT_EQ(collected->structured_elements[0].fields[0].value,
            Value::Int64(71));
  EXPECT_EQ(collected->structured_elements[0].fields[1].value,
            Value::String("first"));
  EXPECT_EQ(collected->structured_elements[1].fields[0].value,
            Value::Int64(72));
  EXPECT_EQ(collected->structured_elements[1].fields[1].value,
            Value::String("second"));
}

