TEST(TcypherResultStreamTest,
     GroupedCollectSpillsStructuredKeysAndCollectedValues) {
  const std::string spill_directory =
      "/tmp/cedar_grouped_collect_structured_value_spill";
  std::filesystem::remove_all(spill_directory);
  constexpr uint32_t kGroups = 12;
  std::vector<StructValue> keys;
  std::vector<StructValue> collected;
  for (uint32_t pass = 0; pass < 2; ++pass) {
    for (uint32_t group = 0; group < kGroups; ++group) {
      keys.push_back(StructValue{{
          {"source_id", Value::Int64(group)},
          {"edge_id", Value::Int64(100 + group)},
          {"padding", Value::String(std::string(24, 'k'))}}});
      collected.push_back(StructValue{{
          {"source_id", Value::Int64(group)},
          {"edge_id", Value::Int64(group + pass * 1000)},
          {"padding", Value::String(std::string(24, 'v'))}}});
    }
  }
  ColumnBatch values(kGroups * 2);
  ASSERT_TRUE(values.AddVector(std::make_shared<StructVector>(
      std::move(keys), std::vector<bool>{})).ok());
  ASSERT_TRUE(values.AddVector(std::make_shared<StructVector>(
      std::move(collected), std::vector<bool>{})).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(512, 16U << 10);
  std::map<int64_t, ListValue> actual;
  {
    GroupedCollectResultStream collect(
        std::make_unique<InMemoryResultStream>(
            std::vector<ResultBatch>{ResultBatch(
                {"relationship", "collected_relationship"},
                std::move(values))}, Status::OK()),
        {0}, 1, "collect(collected_relationship)",
        {{false, 0}, {true, 0}}, 4, nullptr, memory, spill_directory);
    for (;;) {
      ResultBatch result;
      const Status next = collect.Next(&result);
      if (next.IsNotFound()) break;
      ASSERT_TRUE(next.ok()) << next.ToString();
      ASSERT_TRUE(result.batch().IsStructured(0));
      ASSERT_TRUE(result.batch().IsList(1));
      for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
        const auto key = result.batch().StructAt(0, row);
        ASSERT_TRUE(key.has_value());
        ASSERT_EQ(key->fields.size(), 3U);
        const int64_t group =
            std::get<int64_t>(key->fields[0].value->data());
        EXPECT_EQ(key->fields[0].name, "source_id");
        EXPECT_EQ(key->fields[0].value, Value::Int64(group));
        EXPECT_EQ(key->fields[1].name, "edge_id");
        EXPECT_EQ(key->fields[1].value, Value::Int64(100 + group));
        EXPECT_EQ(key->fields[2].name, "padding");
        EXPECT_EQ(key->fields[2].value,
                  Value::String(std::string(24, 'k')));
        actual.emplace(
            group,
            *result.batch().ListAt(1, row));
      }
    }
    EXPECT_TRUE(collect.operator_resource_stats().spill_started);
  }
  ASSERT_EQ(actual.size(), kGroups);
  for (uint32_t group = 0; group < kGroups; ++group) {
    const ListValue& values_for_group = actual.at(group);
    EXPECT_TRUE(values_for_group.elements.empty());
    ASSERT_EQ(values_for_group.structured_elements.size(), 2U);
    EXPECT_EQ(values_for_group.structured_elements[0].fields[1].value,
              Value::Int64(group));
    EXPECT_EQ(values_for_group.structured_elements[1].fields[1].value,
              Value::Int64(group + 1000));
  }
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

TEST(TcypherResultStreamTest,
     GroupedCollectSpillPreservesAllNullStructElementKind) {
  const std::string spill_directory =
      "/tmp/cedar_grouped_collect_empty_struct_spill";
  std::filesystem::remove_all(spill_directory);
  constexpr uint32_t kGroups = 12;
  std::vector<StructValue> keys;
  std::vector<StructValue> null_values;
  keys.reserve(kGroups);
  null_values.reserve(kGroups);
  for (uint32_t group = 0; group < kGroups; ++group) {
    keys.push_back(StructValue{{
        {"source_id", Value::Int64(group)},
        {"edge_id", Value::Int64(100 + group)}}});
    null_values.push_back(StructValue{});
  }
  ColumnBatch values(kGroups);
  ASSERT_TRUE(values.AddVector(std::make_shared<StructVector>(
      std::move(keys), std::vector<bool>{})).ok());
  ASSERT_TRUE(values.AddVector(std::make_shared<StructVector>(
      std::move(null_values), std::vector<bool>(kGroups, false))).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(256, 16U << 10);
  uint32_t rows = 0;
  {
    GroupedCollectResultStream collect(
        std::make_unique<InMemoryResultStream>(
            std::vector<ResultBatch>{ResultBatch(
                {"relationship", "collected_relationship"},
                std::move(values))}, Status::OK()),
        {0}, 1, "collect(collected_relationship)",
        {{false, 0}, {true, 0}}, 4, nullptr, memory, spill_directory);
    for (;;) {
      ResultBatch result;
      const Status next = collect.Next(&result);
      if (next.IsNotFound()) break;
      ASSERT_TRUE(next.ok()) << next.ToString();
      for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
        const auto collected = result.batch().ListAt(1, row);
        ASSERT_TRUE(collected.has_value());
        EXPECT_EQ(collected->element_kind, ListElementKind::kStruct);
        EXPECT_TRUE(collected->elements.empty());
        EXPECT_TRUE(collected->structured_elements.empty());
        ++rows;
      }
    }
    EXPECT_TRUE(collect.operator_resource_stats().spill_started);
  }
  EXPECT_EQ(rows, kGroups);
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

