TEST(TcypherResultStreamTest, GroupedAggregateMergesAllPartialStatesAfterSpill) {
  const std::string spill_directory =
      "/tmp/cedar_grouped_multi_aggregate_partition_spill";
  std::filesystem::remove_all(spill_directory);
  constexpr uint32_t kGroups = 12;
  std::vector<Value> group_values;
  std::vector<Value> amounts;
  for (uint32_t pass = 0; pass < 2; ++pass) {
    for (uint32_t group = 0; group < kGroups; ++group) {
      group_values.push_back(Value::String(
          "g-" + std::to_string(group) + std::string(20, 'x')));
      amounts.push_back(Value::Int64(group + pass * 100));
    }
  }
  ColumnBatch values(kGroups * 2);
  ASSERT_TRUE(values.AddVector(std::make_shared<FlatVector>(
      std::move(group_values), std::vector<bool>{})).ok());
  ASSERT_TRUE(values.AddVector(std::make_shared<FlatVector>(
      std::move(amounts), std::vector<bool>{})).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(512, 2048);
  std::map<std::string, std::vector<Value>> actual;
  {
    GroupedMultiAggregateResultStream aggregate(
        std::make_unique<InMemoryResultStream>(
            std::vector<ResultBatch>{ResultBatch(
                {"group", "amount"}, std::move(values))}, Status::OK()),
        {0},
        {{ResultAggregateKind::kCount, 1, "count(amount)"},
         {ResultAggregateKind::kSum, 1, "sum(amount)"},
         {ResultAggregateKind::kAvg, 1, "avg(amount)"},
         {ResultAggregateKind::kMin, 1, "min(amount)"},
         {ResultAggregateKind::kMax, 1, "max(amount)"}},
        {{false, 0}, {true, 0}, {true, 1}, {true, 2}, {true, 3}, {true, 4}},
        4, nullptr, memory, spill_directory);
    for (;;) {
      ResultBatch result;
      const Status next = aggregate.Next(&result);
      if (next.IsNotFound()) break;
      ASSERT_TRUE(next.ok()) << next.ToString();
      for (uint32_t row = 0; row < result.batch().row_count(); ++row) {
        std::vector<Value> aggregates;
        for (uint32_t column = 1; column < result.batch().column_count(); ++column) {
          aggregates.push_back(*result.batch().ValueAt(column, row));
        }
        actual.emplace(
            std::get<std::string>(result.batch().ValueAt(0, row)->data()),
            std::move(aggregates));
      }
    }
  }
  ASSERT_EQ(actual.size(), kGroups);
  for (uint32_t group = 0; group < kGroups; ++group) {
    const auto& aggregates = actual.at(
        "g-" + std::to_string(group) + std::string(20, 'x'));
    ASSERT_EQ(aggregates.size(), 5U);
    EXPECT_EQ(aggregates[0], Value::Int64(2));
    EXPECT_EQ(aggregates[1], Value::Int64(group * 2 + 100));
    EXPECT_EQ(aggregates[2], Value::Float64(group + 50.0));
    EXPECT_EQ(aggregates[3], Value::Int64(group));
    EXPECT_EQ(aggregates[4], Value::Int64(group + 100));
  }
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

