TEST(TcypherResultStreamTest,
     CollectStructuredOutputMoveAccountsOnlyOuterTransient) {
  std::string payload(1024, 'x');
  const uint64_t one_copy_upper_bound =
      sizeof(ListValue) + sizeof(StructValue) + sizeof(StructField) +
      std::string("payload").capacity() + payload.capacity();
  const uint64_t old_deep_copy_peak = one_copy_upper_bound +
      sizeof(StructValue) + sizeof(StructField) +
      std::string("payload").capacity() + payload.capacity();
  constexpr uint64_t kHardLimit = 1800;
  ASSERT_LT(one_copy_upper_bound + sizeof(ListValue), kHardLimit);
  ASSERT_GT(old_deep_copy_peak, kHardLimit);
  ColumnBatch values(1);
  ASSERT_TRUE(values.AddVector(std::make_shared<StructVector>(
      std::vector<StructValue>{StructValue{{
          {"payload", Value::String(std::move(payload))}}}},
      std::vector<bool>{})).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(4096, kHardLimit);
  ResultBatch result;
  {
    CollectResultStream collect(
        std::make_unique<InMemoryResultStream>(
            std::vector<ResultBatch>{ResultBatch(
                {"relationship"}, std::move(values))}, Status::OK()),
        "collect(relationship)", nullptr, memory,
        ResultValueKind::kStruct);
    ASSERT_TRUE(collect.Next(&result).ok());
    EXPECT_GT(memory->peak_bytes(), memory->used_bytes());
  }
  result = ResultBatch();
  EXPECT_EQ(memory->used_bytes(), 0U);
}

