TEST_F(DurableLogTest, QuerySpillStructuredListDecodeAccountsValueCopyPeak) {
  const std::string spill_directory =
      "/tmp/cedar_query_spill_struct_list_decode_copy_peak";
  std::filesystem::remove_all(spill_directory);
  ListValue list;
  list.element_kind = ListElementKind::kStruct;
  list.structured_elements.push_back(StructValue{{
      {"payload", Value::String(std::string(1024, 'x'))}}});
  ColumnBatch values(1);
  ASSERT_TRUE(values.AddVector(std::make_shared<ListVector>(
      std::vector<ListValue>{std::move(list)}, std::vector<bool>{})).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(4096, 4300);
  {
    QuerySpillFile spill(spill_directory, nullptr, nullptr, memory);
    ASSERT_TRUE(spill.Open().ok());
    ASSERT_TRUE(spill.Append(ResultBatch(
        {"relationship_path"}, std::move(values))).ok());
    ASSERT_TRUE(spill.Seal().ok());
    ASSERT_TRUE(spill.Rewind().ok());
    ResultBatch decoded;
    const Status status = spill.Next(&decoded);
    EXPECT_TRUE(status.IsQueryMemoryLimit())
        << status.ToString() << " peak=" << memory->peak_bytes();
  }
  EXPECT_EQ(memory->used_bytes(), 0U);
  EXPECT_TRUE(!std::filesystem::exists(spill_directory) ||
              std::filesystem::is_empty(spill_directory));
  std::filesystem::remove_all(spill_directory);
}

TEST(TcypherResultStreamTest,
     CollectStructuredFailureIsTerminalStickyAndDoesNotReaccount) {
  ColumnBatch values(2);
  ASSERT_TRUE(values.AddVector(std::make_shared<StructVector>(
      std::vector<StructValue>{
          StructValue{{{"edge_id", Value::Int64(71)}}},
          StructValue{{{"payload", Value::String(std::string(512, 'x'))}}}},
      std::vector<bool>{})).ok());
  auto memory = std::make_shared<QueryMemoryAccount>(4096, 256);
  {
    CollectResultStream collect(
        std::make_unique<InMemoryResultStream>(
            std::vector<ResultBatch>{ResultBatch(
                {"relationship"}, std::move(values))}, Status::OK()),
        "collect(relationship)", nullptr, memory,
        ResultValueKind::kStruct);
    ResultBatch first_batch;
    const Status first = collect.Next(&first_batch);
    ASSERT_TRUE(first.IsQueryMemoryLimit()) << first.ToString();
    const uint64_t used_after_first = memory->used_bytes();
    ASSERT_GT(used_after_first, 0U);
    EXPECT_EQ(first_batch.batch().column_count(), 0U);

    ResultBatch second_batch;
    const Status second = collect.Next(&second_batch);
    EXPECT_EQ(second.ToString(), first.ToString());
    EXPECT_EQ(second_batch.batch().column_count(), 0U);
    EXPECT_EQ(memory->used_bytes(), used_after_first);
  }
  EXPECT_EQ(memory->used_bytes(), 0U);
}

